        'Os dias do período saem do plano, de amanhã em diante (os escolhidos à mão, os sorteados e os livres), e o modo de rodízio monta esses dias de novo. Pode deixar um lado vazio: só o começo apaga dele até o fim do plano; só o fim apaga de amanhã até ele.' => 'Les jours de la période quittent le plan, à partir de demain (ceux choisis à la main, ceux tirés au sort et les libres), et le mode de rotation refait ces jours. Vous pouvez laisser un côté vide : seulement le début supprime de lui jusqu\'à la fin du plan ; seulement la fin supprime de demain jusqu\'à elle.',
        'Apagar toda a programação, de hoje em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo, e hoje pode sair outro relógio, que passa a ser o do pulso a partir de agora.' => 'Effacer toute la programmation, à partir d\'aujourd\'hui (choisis à la main, tirés au sort et jours libres) ? Le mode de rotation refait le plan, et aujourd\'hui une autre montre peut sortir ; elle devient celle du poignet dès maintenant.',
        'Apagar toda a programação, de amanhã em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo; hoje continua como está.' => 'Effacer toute la programmation, à partir de demain (choisis à la main, tirés au sort et jours libres) ? Le mode de rotation refait le plan ; aujourd\'hui reste tel quel.',
        'Apagar tudo' => 'Tout effacer',
        '{1} Excluindo hoje (apaga também o dia de hoje)' => '{1} Y compris aujourd\'hui (efface aussi la journée d\'aujourd\'hui)',
        'Limpa toda a programação, de amanhã em diante: os dias escolhidos à mão, os sorteados e os livres. Marcando "Excluindo hoje", apaga de hoje em diante (se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora). Depois, o modo de rodízio monta o plano de novo, do zero.' => 'Efface toute la programmation, à partir de demain : les jours choisis à la main, les tirés au sort et les libres. En cochant « Y compris aujourd\'hui », efface à partir d\'aujourd\'hui (si une autre montre sort pour aujourd\'hui, elle devient celle du poignet dès maintenant). Ensuite, le mode de rotation refait le plan, depuis zéro.',
