        'Como pedir acesso (e por que pelo código)' => 'Comment demander l\'accès (et pourquoi par le code)',
        'Por que o código: para proteger quem usa o sistema, nenhuma página mostra a lista de contas nem de coleções. O login é metade do que alguém precisa para tentar entrar numa conta alheia, e o nome de uma coleção costuma levar o login do dono. Por isso o pedido é feito pelo código que o próprio dono passa: quem não recebeu o código não tem como saber de quem ele é.' => 'Pourquoi le code : pour protéger ceux qui utilisent le système, aucune page ne montre la liste des comptes ni des collections. L\'identifiant est la moitié de ce qu\'il faut pour tenter d\'entrer dans le compte d\'un autre, et le nom d\'une collection contient souvent l\'identifiant du propriétaire. C\'est pourquoi la demande se fait avec le code que donne le propriétaire lui-même : qui n\'a pas reçu le code ne peut pas savoir à qui il est.',
        'Peça o código ao dono (por mensagem, e-mail ou pessoalmente). Ele o encontra em Minha conta: o código dele, em Seus dados, dá acesso a todas as coleções dele, também às que ele criar depois; o código de uma coleção só fica na coluna Código da tabela Coleções.' => 'Demandez le code au propriétaire (par message, e-mail ou en personne). Il le trouve dans Mon compte : son code, dans Vos données, donne accès à toutes ses collections, aussi à celles qu\'il créera ensuite ; le code d\'une seule collection est dans la colonne Code du tableau Collections.',
        'Aqui, escolha se o código é de uma coleção ou do dono, digite o número e deixe um recado dizendo quem você é: o dono vê só o seu login.' => 'Ici, choisissez si le code est celui d\'une collection ou du propriétaire, tapez le numéro et laissez un mot disant qui vous êtes : le propriétaire ne voit que votre identifiant.',
        'O dono recebe um e-mail e aprova ou recusa em Aprovações. Até lá, o seu pedido mostra só o código. Aprovado, você recebe um e-mail e a coleção aparece no seletor do menu.' => 'Le propriétaire reçoit un e-mail et approuve ou refuse dans Approbations. D\'ici là, votre demande ne montre que le code. Une fois approuvée, vous recevez un e-mail et la collection apparaît dans le sélecteur du menu.',
