        'Lembretes' => 'Rappels',
        'Para onde vão' => 'Où elles vont',
        'Tudo o que o sistema lembra: os avisos dos relógios, que ele calcula sozinho pelos dados de cada um (dar corda, carregar, trocar a pilha...); os lembretes, que você marca com hora e repetição; e para onde vão os dois (os destinos das mensagens e as agendas).' => 'Tout ce que le système rappelle : les alertes des montres, qu\'il calcule tout seul avec les données de chacune (remonter, charger, changer la pile...) ; les rappels, que vous fixez avec une heure et une répétition ; et où vont les deux (les destinations des messages et les agendas).',
        'não' => 'non',
        'no relógio do dia' => 'sur la montre du jour',
        'sempre' => 'toujours',
        'só dentro da antecedência da agenda' => 'seulement dans l\'anticipation de l\'agenda',
        'qualquer data' => 'n\'importe quelle date',
        'Cada aviso tem uma fórmula da data prevista; entra "em breve" dentro da antecedência e "atrasado" quando a data passa. O "vale quando" (uma fórmula) diz para quais relógios o aviso vale (ex.: corda_manual = 0, só para o automático sem corda); vazio, vale para todos do grupo. O texto é o motivo nas mensagens ({motivo}): "Dar corda: San Martin (a reserva acaba em 3h, 28/09/2026 10:53)"; nele: {relogio}, {data}, {quando} e {limite} (o limite de carga do relógio). O tipo que resolve vira o botão na tela Hoje. Como as fórmulas, pode ter uma versão por ponto da árvore. Na escala inteligente: "no relógio do dia" é conferido no escolhido, do começo ao fim do bloco dele; "sempre", também nos guardados, todo dia. O que vence vira o lembrete do dia, e o lançamento que resolve é simulado com o valor (leitura) ou as horas (sessão) do aviso. Se o aviso vai para cada destino e cada agenda (e com que texto) se escolhe neles, em Para onde vão, embaixo; aqui fica a data que ele usa na agenda. "Na hora": além do alerta da manhã, o Telegram recebe o aviso no minuto em que ele vence (uma vez, até ele ser resolvido), como o "Tirar do carregador" quando a bateria enche.' => 'Chaque alerte a une formule de la date prévue ; elle passe à « bientôt » dans l\'anticipation et à « en retard » quand la date est passée. Le « vaut quand » (une formule) dit pour quelles montres l\'alerte vaut (ex. : corda_manual = 0, seulement pour l\'automatique sans remontage) ; vide, elle vaut pour toutes celles du groupe. Le texte est le motif dans les messages ({motivo}) : « Remonter : San Martin (la réserve s\'épuise dans 3h, 28/09/2026 10:53) » ; on y trouve : {relogio}, {data}, {quando} et {limite} (la limite de charge de la montre). Le type qui la résout devient le bouton sur l\'écran Aujourd\'hui. Comme les formules, elle peut avoir une version par point de l\'arbre. Dans le planning intelligent : « sur la montre du jour » est vérifié sur la montre choisie, du début à la fin de son bloc ; « toujours », aussi sur celles rangées, chaque jour. Ce qui arrive à échéance devient le rappel du jour, et la saisie qui la résout est simulée avec la valeur (lecture) ou les heures (session) de l\'alerte. Si l\'alerte va vers chaque destination et chaque agenda (et avec quel texte) se choisit dans ceux-ci, dans Où elles vont, en bas ; ici se trouve la date qu\'elle utilise dans l\'agenda. « Immédiate » : en plus de l\'alerte du matin, Telegram reçoit l\'alerte à la minute où elle arrive à échéance (une fois, jusqu\'à ce qu\'elle soit résolue), comme le « Retirer du chargeur » quand la batterie est pleine.',
