        'Evento novo já vai por todos os destinos da coleção. Em cada destino e cada agenda (páginas Destinos e Agendas), escolha se ele vai e com que texto.' => 'Un nouvel événement part déjà vers toutes les destinations de la collection. Dans chaque destination et chaque agenda (pages Destinations et Agendas), choisissez s\'il part et avec quel texte.',
        'Salvar alterações' => 'Enregistrer les modifications',
        'Criar evento' => 'Créer l\'événement',
        'cancelar' => 'annuler',
        'Lembretes (eventos personalizados)' => 'Rappels (événements personnalisés)',
        'Um aviso seu, com horário e repetição próprios: todo dia, em dias da semana, todo mês, a cada N dias ou uma vez só.' => 'Un rappel à vous, avec son horaire et sa répétition : tous les jours, certains jours de la semaine, tous les mois, tous les N jours ou une seule fois.',
        'Editar o evento {1}' => 'Modifier l\'événement {1}',
        'Novo evento' => 'Nouvel événement',
        'desligado' => 'désactivé',
        'Para onde vão: destinos e agendas' => 'Où elles vont : destinations et agendas',
        'Destinos das mensagens' => 'Destinations des messages',
        'Nenhum ainda: as mensagens da manhã, da noite e os avisos não saem para lugar nenhum.' => 'Aucune pour l\'instant : les messages du matin, du soir et les alertes ne partent nulle part.',
        'Nenhuma ainda.' => 'Aucun pour l\'instant.',
        'Um destino é um webhook (Telegram, n8n...), um e-mail ou o Web Push do navegador; uma agenda é o Google, um CalDAV (Nextcloud, iCloud, Fastmail), o Outlook ou um link ICS para assinar em qualquer app. Cada um escolhe o que recebe e tem a sua mensagem.' => 'Une destination est un webhook (Telegram, n8n...), un e-mail ou le Web Push du navigateur ; un agenda est Google, un CalDAV (Nextcloud, iCloud, Fastmail), Outlook ou un lien ICS à suivre dans n\'importe quelle app. Chacun choisit ce qu\'il reçoit et a son message.',
        'Não consegui ler os avisos: {1}' => 'Impossible de lire les alertes : {1}',
        'Pronto' => 'C\'est fait',
        'Entrar' => 'Se connecter',
        'Esqueci a senha' => 'Mot de passe oublié',
        'o e-mail ou o login' => 'l\'e-mail ou l\'identifiant',
        'E-mail ou login' => 'E-mail ou identifiant',
        'Mandar o link' => 'Envoyer le lien',
        'O servidor não envia e-mail: peça ao administrador para trocar a sua senha.' => 'Le serveur n\'envoie pas d\'e-mail : demandez à l\'administrateur de changer votre mot de passe.',
        'Criar também uma coleção minha, com o conjunto inicial' => 'Créer aussi une collection à moi, avec l\'ensemble initial',
        'Para começar' => 'Pour commencer',
        'Uma coleção minha, com o conjunto inicial (grupos, campos, fórmulas, avisos e critérios prontos)' => 'Une collection à moi, avec l\'ensemble initial (groupes, champs, formules, alertes et critères prêts)',
        'Uma coleção minha, vazia (eu monto tudo)' => 'Une collection à moi, vide (je monte tout)',
        'Pedir acesso à coleção de alguém' => 'Demander l\'accès à la collection de quelqu\'un',
        'Recado para o dono (opcional)' => 'Message au propriétaire (facultatif)',
        'Login' => 'Compte',
        'sem dois-pontos' => 'sans deux-points',
        'Senha (pelo menos 6 caracteres)' => 'Mot de passe (au moins 6 caractères)',
        'A conta nova é de demonstração por {1} dias: depois disso ela é apagada, a menos que o administrador a torne oficial. Você recebe um aviso por e-mail antes.' => 'Le nouveau compte est en démonstration pendant {1} jours : ensuite il est supprimé, sauf si l\'administrateur le rend officiel. Vous recevez un avertissement par e-mail avant.',
        'Criar conta' => 'Créer un compte',
        'Senha nova' => 'Nouveau mot de passe',
        'Senha nova (pelo menos 6 caracteres)' => 'Nouveau mot de passe (au moins 6 caractères)',
        'Trocar a senha' => 'Changer le mot de passe',
        'Convite' => 'Invitation',
        'Este convite não vale mais (vencido, já usado ou cancelado). Peça outro a quem convidou.' => 'Cette invitation n\'est plus valable (expirée, déjà utilisée ou annulée). Demandez-en une autre à qui vous a invité.',
        'Você foi convidado para ver {1}.' => 'Vous avez été invité à voir {1}.',
        'Já tem conta? {1}' => 'Vous avez déjà un compte ? {1}',
        'Entre e aceite o convite' => 'Connectez-vous et acceptez l\'invitation',
        'Ou crie a sua conta' => 'Ou créez votre compte',
        'O cadastro está fechado: só entra quem tem um convite. Fale com o administrador.' => 'L\'inscription est fermée : seuls ceux qui ont une invitation entrent. Parlez à l\'administrateur.',
        'Não consegui abrir o cadastro: {1}' => 'Impossible d\'ouvrir l\'inscription : {1}',
        'Campos' => 'Champs',
        'Tipos de lançamento' => 'Types de saisie',
        'Fórmulas' => 'Formules',
        'Categorias de documentos' => 'Catégories de documents',
        'vídeos' => 'vidéos',
        'áudios' => 'audios',
        'PDF' => 'PDF',
        'XML' => 'XML',
        'Cadastros' => 'Définitions',
        'Campos do cadastro dos relógios' => 'Champs de la fiche des montres',
        'Cada campo vale para o ponto da árvore escolhido e tudo abaixo dele (os de cada nível somam) e aparece no cadastro desses relógios. O identificador é o nome do campo nas fórmulas. Marcado "só nos desejados", o campo aparece só nos relógios da lista de desejos.' => 'Chaque champ vaut pour le point de l\'arbre choisi et tout ce qui est en dessous (ceux de chaque niveau s\'additionnent) et apparaît dans la fiche de ces montres. L\'identifiant est le nom du champ dans les formules. Coché « seulement pour les envies », le champ n\'apparaît que pour les montres de la liste d\'envies.',
        'Campo' => 'Champ',
        'Identificador' => 'Identifiant',
        'Vale para' => 'Vaut pour',
        'Padrão' => 'Par défaut',
        ' · só nos desejados' => ' · seulement pour les envies',
        'Excluir o campo {1} e os valores dele?' => 'Supprimer le champ {1} et ses valeurs ?',
        'Alterar o campo {1}' => 'Modifier le champ {1}',
        'Novo campo' => 'Nouveau champ',
        'Unidade {1}' => 'Unité {1}',
        'Valor padrão {1}' => 'Valeur par défaut {1}',
        'Vale para {1}' => 'Vaut pour {1}',
        'Opções (lista: uma por linha) {1}' => 'Options (liste : une par ligne) {1}',
        ' só nos desejados (a lista de desejos: o preço-alvo, a prioridade)' => ' seulement pour les envies (la liste d\'envies : le prix cible, la priorité)',
        'O que se registra num relógio: instantâneo (corda), com valor (leitura de carga) ou sessão com início e fim (pulso, winder, sol). O identificador é o nome nas funções das fórmulas: HORAS("pulso"; 30). Sessão exclusiva: o relógio fica num lugar só. Mede o gasto: cada leitura desse tipo mede quanto caiu por dia de uso ou guardado (a função MEDIDO das fórmulas). Vale quando: uma fórmula que diz para quais relógios o tipo vale (ex.: corda_manual, só para quem aceita corda); vazia, vale para todos do grupo.' => 'Ce qu\'on enregistre sur une montre : instantané (remontage), avec une valeur (lecture de charge) ou une session avec début et fin (poignet, remontoir, soleil). L\'identifiant est le nom dans les fonctions des formules : HORAS("pulso"; 30). Session exclusive : la montre n\'est qu\'à un seul endroit. Mesure la consommation : chaque lecture de ce type mesure combien elle a baissé par jour d\'usage ou de rangement (la fonction MEDIDO des formules). Vaut quand : une formule qui dit pour quelles montres le type vaut (ex. : corda_manual, seulement pour celles qui acceptent le remontage) ; vide, il vaut pour toutes celles du groupe.',
        'Formato' => 'Format',
        'Fecha sozinho às' => 'Se ferme seule à',
        'Exclusiva' => 'Exclusive',
        'Mede o gasto' => 'Mesure la consommation',
        'Lançamentos' => 'Saisies',
        'Excluir o tipo {1}?' => 'Supprimer le type {1} ?',
        'Novo tipo de lançamento' => 'Nouveau type de saisie',
        'Formato {1}' => 'Format {1}',
        'Unidade (com valor) {1}' => 'Unité (avec valeur) {1}',
        'Fecha sozinho às (sessão; vazio: não fecha) {1}' => 'Se ferme seule à (session ; vide : ne se ferme pas) {1}',
        'Vale quando (fórmula: 1 vale, 0 não; vazio: sempre) {1}' => 'Vaut quand (formule : 1 vaut, 0 non ; vide : toujours) {1}',
        'ex.: corda_manual' => 'ex. : corda_manual',
        ' sessão exclusiva (o relógio num lugar só)' => ' session exclusive (la montre à un seul endroit)',
        ' mede o gasto (com valor: cada leitura mede o gasto em uso ou guardado, comparando com a anterior)' => ' mesure la consommation (avec valeur : chaque lecture mesure la consommation en usage ou rangée, en comparant avec la précédente)',
        'Uma fórmula pode ter uma versão em cada ponto da árvore: vale para o relógio a do ponto mais perto dele. Números com vírgula ou ponto, argumentos separados por ponto e vírgula, textos entre aspas. Variáveis: os identificadores dos campos e das fórmulas.' => 'Une formule peut avoir une version à chaque point de l\'arbre : pour la montre, c\'est celle du point le plus proche. Nombres avec virgule ou point, arguments séparés par des points-virgules, textes entre guillemets. Variables : les identifiants des champs et des formules.',
        'Fórmula' => 'Formule',
        'Cálculo' => 'Calcul',
        'Excluir esta versão de {1}?' => 'Supprimer cette version de {1} ?',
        'Alterar {1} ({2})' => 'Modifier {1} ({2})',
        'Nova fórmula (ou nova versão de uma que existe)' => 'Nouvelle formule (ou nouvelle version d\'une formule existante)',
        'Cálculo {1}' => 'Calcul {1}',
        'Testar uma fórmula (sem gravar)' => 'Tester une formule (sans enregistrer)',
        'Testar em todos os relógios' => 'Tester sur toutes les montres',
        'Resultado' => 'Résultat',
        'As partes da conta' => 'Les parties du calcul',
        'As funções do motor' => 'Les fonctions du moteur',
        'Os documentos de cada relógio (a página Documentos, aberta pela ficha) ficam numa categoria. "Aceita" limita os arquivos da categoria; nada marcado, ela aceita qualquer arquivo. O jeito de abrir cada arquivo vem do tipo dele, não da categoria: as fotos na galeria, os vídeos no player, o PDF no visualizador, o XML da nota com o resumo, o resto para baixar. Uma categoria com documentos não se exclui: passe os documentos para outra antes.' => 'Les documents de chaque montre (la page Documents, ouverte depuis la fiche) sont classés dans une catégorie. « Accepte » limite les fichiers de la catégorie ; rien de coché, elle accepte n\'importe quel fichier. La façon d\'ouvrir chaque fichier dépend de son type, pas de la catégorie : les photos dans la galerie, les vidéos dans le lecteur, le PDF dans la visionneuse, le XML de la facture avec son résumé, le reste en téléchargement. Une catégorie qui a des documents ne se supprime pas : déplacez d\'abord les documents vers une autre.',
        'Categoria' => 'Catégorie',
        'Aceita' => 'Accepte',
        'Ordem' => 'Ordre',
        'Documentos' => 'Documents',
        'qualquer arquivo' => 'n\'importe quel fichier',
        'Excluir a categoria {1}?' => 'Supprimer la catégorie {1} ?',
        'Alterar a categoria {1}' => 'Modifier la catégorie {1}',
        'Nova categoria' => 'Nouvelle catégorie',
        'Ordem {1}' => 'Ordre {1}',
        'vazio: no fim' => 'vide : à la fin',
        'Aceita (nada marcado: qualquer arquivo)' => 'Accepte (rien de coché : n\'importe quel fichier)',
        'Não consegui ler os cadastros: {1}' => 'Impossible de lire les définitions : {1}',
        'Atualização do banco' => 'Mise à jour de la base de données',
        'O banco está desatualizado' => 'La base de données n\'est pas à jour',
        'Esta versão do sistema precisa de migrações que ainda não foram aplicadas no banco. Até lá, as páginas, a API e o cron ficam parados, para não gravar nada pela metade.' => 'Cette version du système a besoin de migrations qui n\'ont pas encore été appliquées à la base de données. En attendant, les pages, l\'API et le cron sont arrêtés, pour ne rien enregistrer à moitié.',
        'Aplicar agora' => 'Appliquer maintenant',
        'Aplica na ordem e para na primeira que falhar. Se o usuário do banco do sistema não tiver permissão de alterar tabelas, rode na mão, na ordem: {1}' => 'Les applique dans l\'ordre et s\'arrête à la première qui échoue. Si l\'utilisateur de la base de données du système n\'a pas le droit de modifier les tables, exécutez-les à la main, dans l\'ordre : {1}',
        'Continuar para a Configuração' => 'Continuer vers la Configuration',
        'O cron está com erro' => 'Le cron est en erreur',
        'Some sozinho na primeira execução sem erro.' => 'Disparaît tout seul à la première exécution sans erreur.',
        '{1}, com filtro de datas e busca.' => '{1}, avec filtre de dates et recherche.',
        'Ver todas as execuções do cron' => 'Voir toutes les exécutions du cron',
        'Registro da última rodada' => 'Journal de la dernière exécution',
        'Rotina do dia' => 'Routine du jour',
        'Manhã: relógio do dia e avisos' => 'Matin : montre du jour et alertes',
        'Noite: preparar o de amanhã' => 'Soir : préparer celle de demain',
        'No pulso a partir de' => 'Au poignet à partir de',
        'Pôr no pulso sozinho' => 'Mettre au poignet tout seul',
        'No pulso até' => 'Au poignet jusqu\'à',
        'Tirar do pulso sozinho' => 'Retirer du poignet tout seul',
        'Sessão no sol esquecida fecha às' => 'Une session au soleil oubliée se ferme à',
        'Sem <strong>pôr sozinho</strong>, o relógio do dia só entra no pulso pelo <strong>Pôs no pulso</strong>; sem <strong>tirar sozinho</strong>, só sai pelo ' => 'Sans <strong>mettre tout seul</strong>, la montre du jour ne va au poignet que par <strong>Mise au poignet</strong> ; sans <strong>retirer tout seul</strong>, elle n\'en sort que par ',
        '<strong>Tirou do pulso</strong> (esquecido, continua contando como no pulso). O horário de uso vale sempre para o plano e as previsões. Fora do pulso, o relógio conta como guardado.' => '<strong>Retirée du poignet</strong> (si on l\'oublie, elle continue de compter comme au poignet). Les heures de port valent toujours pour le plan et les prévisions. Hors du poignet, la montre compte comme rangée.',
        'Limites e contas' => 'Limites et calculs',
        'Carregar quando a carga chegar a (%)' => 'Recharger quand la charge atteint (%)',
        'Solar: pôr no sol quando chegar a (%)' => 'Solaire : mettre au soleil quand elle atteint (%)',
        'Gasto da bateria: como calcular' => 'Consommation de la batterie : comment calculer',
        'Conforme o relógio e o grupo (o cadastro)' => 'Selon la montre et le groupe (la fiche)',
        '1. Pelas horas registradas (o motor original)' => '1. Par les heures enregistrées (le moteur d\'origine)',
        '2. Pelas horas registradas, com leituras e cadastro (robusto)' => '2. Par les heures enregistrées, avec relevés et fiche (robuste)',
        '3. Pela marcação: duas taxas separadas' => '3. Par le marquage : deux taux séparés',
        '4. Só o cadastro' => '4. La fiche seulement',
        '5. Pelas fórmulas do cadastro' => '5. Par les formules de la fiche',
        'Gasto medido: contar por' => 'Consommation mesurée : compter par',
        'Dias (os últimos dias)' => 'Jours (les derniers jours)',
        'Leituras (as últimas de cada tipo)' => 'Relevés (les derniers de chaque type)',
        'Gasto medido: média dos últimos (dias)' => 'Consommation mesurée : moyenne des derniers (jours)',
        'Gasto medido: últimas leituras (de cada tipo)' => 'Consommation mesurée : derniers relevés (de chaque type)',
        'Aviso Encostado: dias sem ir ao pulso' => 'Alerte Délaissée : jours sans aller au poignet',
        'Cópia dos documentos no banco' => 'Copie des documents dans la base',
        'Conforme o relógio e o arquivo' => 'Selon la montre et le fichier',
        'Todos os arquivos' => 'Tous les fichiers',
        'Nenhum arquivo' => 'Aucun fichier',
        'O limite de carga de um relógio (no cadastro dele) vale no lugar do geral. O gasto da bateria tem cinco motores (veja a Ajuda); a escolha aqui vale para todos os relógios da coleção, e vazia valem a do relógio e a do grupo (o campo "Como calcular o gasto da bateria" do cadastro). O gasto medido conta as medições dos últimos dias ou as últimas leituras de cada tipo (em uso e em repouso), conforme o "contar por"; as de fora saem da conta. A cópia dos documentos no banco escolhida aqui vale sobre o relógio e o arquivo. ' => 'La limite de charge d\'une montre (dans sa fiche) remplace la limite générale. La consommation de la batterie a cinq moteurs (voir l\'Aide) ; le choix fait ici vaut pour toutes les montres de la collection, et vide, ce sont ceux de la montre et du groupe qui valent (le champ « Comment calculer la consommation de la batterie » de la fiche). La consommation mesurée compte les mesures des derniers jours ou les derniers relevés de chaque type (en usage et au repos), selon « compter par » ; celles d\'en dehors sortent du calcul. La copie des documents dans la base choisie ici prime sur la montre et le fichier. ',
        'O config.php ainda define DOCUMENTOS_COPIA_BANCO, que não vale mais: a cópia dos documentos é escolhida aqui, por coleção. ' => 'Le config.php définit encore DOCUMENTOS_COPIA_BANCO, qui ne vaut plus : la copie des documents se choisit ici, par collection. ',
        'Um relógio da coleção que passa do limite de dias sem ir ao pulso ganha o aviso <strong>Encostado</strong> (desliga na página Avisos).' => 'Une montre de la collection qui dépasse la limite de jours sans aller au poignet reçoit l\'alerte <strong>Délaissée</strong> (à désactiver dans la page Alertes).',
        'Telas' => 'Écrans',
        'Idioma padrão (quem não escolheu outro no menu)' => 'Langue par défaut (pour qui n\'en a pas choisi une autre dans le menu)',
        'Abrir o relógio na página Hoje' => 'Ouvrir la montre sur la page Aujourd\'hui',
        'Ao lado da lista' => 'À côté de la liste',
        'Numa janela flutuante, grande' => 'Dans une grande fenêtre flottante',
        'Destaque no alto da página Hoje' => 'Mise en avant en haut de la page Aujourd\'hui',
        'O relógio do dia' => 'La montre du jour',
        'O relógio no pulso agora' => 'La montre au poignet maintenant',
        'Próximos dias (página Hoje): mostrar até (dias por página)' => 'Prochains jours (page Aujourd\'hui) : afficher jusqu\'à (jours par page)',
        'Plano: mostrar até (dias por página)' => 'Plan : afficher jusqu\'à (jours par page)',
        'Endereço do sistema (a âncora {link})' => 'Adresse du système (le repère {link})',
        '(o do pedido; só o master muda)' => '(celle de la requête ; seul le master la change)',
        '<strong>Ao lado da lista:</strong> o relógio clicado abre num painel à direita, e a lista continua à vista. <strong>Numa janela flutuante:</strong> abre grande, ' => '<strong>À côté de la liste :</strong> la montre cliquée s\'ouvre dans un panneau à droite, et la liste reste visible. <strong>Dans une fenêtre flottante :</strong> elle s\'ouvre en grand, ',
        'no meio da tela, com os quadros lado a lado; fecha no ×, no Esc ou num clique fora. No celular, os dois cobrem a tela inteira.' => 'au milieu de l\'écran, avec les cadres côte à côte ; elle se ferme avec le ×, Échap ou un clic à l\'extérieur. Sur téléphone, les deux couvrent tout l\'écran.',
        '<strong>Destaque:</strong> o quadro grande no alto da página Hoje mostra o relógio do dia (o do plano) ou o que está no pulso agora, ' => '<strong>Mise en avant :</strong> le grand cadre en haut de la page Aujourd\'hui montre la montre du jour (celle du plan) ou celle qui est au poignet maintenant, ',
        'mesmo que seja outro (o do dia aparece embaixo do nome). Sem nenhum relógio no pulso, fica o do dia.' => 'même si c\'est une autre (celle du jour apparaît sous le nom). Sans montre au poignet, c\'est celle du jour.',
        '<strong>Mostrar até:</strong> quantos dias os Próximos dias (página Hoje, padrão 7) e o dia a dia da página Plano (padrão 31) mostram de cada vez. ' => '<strong>Afficher jusqu\'à :</strong> combien de jours les Prochains jours (page Aujourd\'hui, 7 par défaut) et le jour par jour de la page Plan (31 par défaut) affichent à la fois. ',
        'Passando disso, embaixo aparecem as páginas: &lt; (anterior), os números e &gt; (próxima).' => 'Au-delà, les pages apparaissent en bas : &lt; (précédente), les numéros et &gt; (suivante).',
        'Cron' => 'Cron',
        'Sorteios' => 'Tirages',
        'Os números vêm de' => 'Les nombres viennent de',
        '1. RANDOM.ORG (ruído atmosférico) · 2. fora do ar, ANU QRNG (quântico) · 3. sem os dois, o gerador seguro do PHP' => '1. RANDOM.ORG (bruit atmosphérique) · 2. s\'il est indisponible, ANU QRNG (quantique) · 3. sans les deux, le générateur sécurisé de PHP',
        'Último lote' => 'Dernier lot',
        'nenhum ainda' => 'aucun pour l\'instant',
        'Serviços fora' => 'Services indisponibles',
        'os dois sem responder desde {1} {2}; o sistema tenta de novo depois de 10 minutos' => 'les deux sans réponse depuis {1} {2} ; le système réessaie après 10 minutes',
        'Todo sorteio do sistema (o rodízio totalmente aleatório, o sorteio pela nota e o desempate de notas iguais na escala) usa estes números. Eles chegam num lote, e cada sorteio usa só o que precisa, sem viés.' => 'Tout tirage du système (la rotation totalement aléatoire, le tirage par la note et le départage des notes égales dans le planning) utilise ces nombres. Ils arrivent par lot, et chaque tirage n\'utilise que ce dont il a besoin, sans biais.',
        'Avisos, lembretes e mensagens' => 'Alertes, rappels et messages',
        '{1} lembretes · {2} destinos · {3} agendas' => '{1} rappels · {2} destinations · {3} agendas',
        'Os avisos dos relógios, os lembretes (os eventos personalizados) e para onde eles vão ficam juntos na página {1}.' => 'Les alertes des montres, les rappels (les événements personnalisés) et où ils vont sont réunis dans la page {1}.',
        'As mudanças desta página valem depois de salvar.' => 'Les modifications de cette page s\'appliquent après l\'enregistrement.',
        'Salvar configuração' => 'Enregistrer la configuration',
        'Cópia de segurança' => 'Sauvegarde',
        'Uma cópia do banco inteiro por dia, na rodada da noite, guardando as {1} mais novas, {2} o conteúdo dos documentos (os arquivos já ficam na pasta deles). A cópia volta em qualquer um dos três bancos, na mesma versão do sistema. {3}' => 'Une copie de toute la base de données chaque jour, lors du passage du soir, en gardant les {1} plus récentes, {2} le contenu des documents (les fichiers restent déjà dans leur dossier). La copie se restaure dans n\'importe laquelle des trois bases, dans la même version du système. {3}',
        'Última: {1} {2}.' => 'Dernière : {1} {2}.',
        'Nenhuma feita ainda.' => 'Aucune faite pour l\'instant.',
        'A cópia automática está desligada: {1}. Ponha no config.php a BACKUP_PASTA, uma pasta do servidor fora da pasta publicada.' => 'La sauvegarde automatique est désactivée : {1}. Indiquez dans config.php la BACKUP_PASTA, un dossier du serveur en dehors du dossier publié.',
        'Cópia' => 'Copie',
        'Feita em' => 'Faite le',
        'Tamanho' => 'Taille',
        'Baixar' => 'Télécharger',
        'Voltar o banco para a cópia de {1}? Tudo o que foi feito depois some. Antes, o sistema guarda uma cópia do que está agora.' => 'Revenir à la copie du {1} ? Tout ce qui a été fait après disparaît. Avant, le système garde une copie de l\'état actuel.',
        'Restaurar' => 'Restaurer',
        'Fazer uma cópia agora' => 'Faire une copie maintenant',
        'Não consegui ler a configuração: {1}' => 'Impossible de lire la configuration : {1}',
        'Configuração' => 'Configuration',
        'Abrir' => 'Ouvrir',
        'aberta' => 'ouverte',
        'Renomear' => 'Renommer',
        'Nome da coleção' => 'Nom de la collection',
        'Sair' => 'Quitter',
        'sua' => 'à vous',
        'membro' => 'membre',
        'master' => 'master',
        'Coleções' => 'Collections',
        'Você ainda não vê nenhuma coleção: crie uma aqui embaixo, ou peça acesso à de alguém (e espere a aprovação).' => 'Vous ne voyez encore aucune collection : créez-en une ci-dessous, ou demandez l\'accès à celle de quelqu\'un (et attendez l\'approbation).',
        'Dono' => 'Propriétaire',
        'Você é' => 'Vous êtes',
        'Para alguém pedir acesso a uma coleção sua, passe o código dela; para todas as suas, o seu código (em Seus dados). O pedido não mostra a ninguém o seu login nem os nomes das coleções: você aprova ou recusa em Aprovações.' => 'Pour que quelqu\'un demande l\'accès à une de vos collections, donnez-lui son code ; pour toutes, votre code (dans Vos données). La demande ne montre à personne votre identifiant ni les noms des collections : vous approuvez ou refusez dans Approbations.',
        'Nova coleção' => 'Nouvelle collection',
        'Começa' => 'Commence',
        'com o conjunto inicial (grupos, campos, fórmulas, avisos e critérios)' => 'avec l\'ensemble initial (groupes, champs, formules, alertes et critères)',
        'vazia (só a raiz da árvore)' => 'vide (seulement la racine de l\'arbre)',
        'com uma árvore minha que já existe (o cadastro fica em comum)' => 'avec un arbre à moi qui existe déjà (le référentiel est partagé)',
        'Árvore' => 'Arbre',
        'Criar coleção' => 'Créer la collection',
        'Árvores de grupos' => 'Arbres de groupes',
        'A árvore guarda os grupos e o cadastro deles (campos, tipos de lançamento, fórmulas, avisos, categorias e critérios). Uma árvore pode servir a várias coleções suas: o que muda nela vale para todas.' => 'L\'arbre garde les groupes et leur référentiel (champs, types de saisie, formules, alertes, catégories et critères). Un arbre peut servir à plusieurs de vos collections : ce qui change en lui vaut pour toutes.',
        'Grupos' => 'Groupes',
        'Usada por' => 'Utilisé par',
        'nenhuma coleção' => 'aucune collection',
        'Renomear ou copiar' => 'Renommer ou copier',
        'Nome da árvore' => 'Nom de l\'arbre',
        'Cópia de {1}' => 'Copie de {1}',
        'Nome da cópia' => 'Nom de la copie',
        'Copiar' => 'Copier',
        'Pedir acesso' => 'Demander l\'accès',
        'Esperando resposta' => 'En attente de réponse',
        'O quê' => 'Quoi',
        'Pedido em' => 'Demandé le',
        'Há {1} convite(s) para o seu e-mail: aceite pelo link que chegou nele.' => 'Il y a {1} invitation(s) pour votre e-mail : acceptez par le lien qu\'il contient.',
        'O dono (ou o administrador) aprova. Pedidos sem resposta saem sozinhos depois de alguns dias.' => 'Le propriétaire (ou l\'administrateur) approuve. Les demandes sans réponse partent d\'elles-mêmes après quelques jours.',
        'Seus dados' => 'Vos données',
        'Login: {1}' => 'Identifiant : {1}',
        'demonstração' => 'démonstration',
        'desde {1}' => 'depuis le {1}',
        'seu código: {1}' => 'votre code : {1}',
        'Alguém quer ver as suas coleções? Passe o seu código ({1}) para todas elas, também as que você criar depois, ou o código de uma coleção só (na coluna Código da tabela Coleções). A pessoa pede acesso com ele, na Criar conta ou em Minha conta; você recebe um e-mail e aprova ou recusa em Aprovações. Ninguém vê o seu login antes de você aprovar.' => 'Quelqu\'un veut voir vos collections ? Donnez-lui votre code ({1}) pour toutes, aussi celles que vous créerez ensuite, ou le code d\'une seule collection (dans la colonne Code du tableau Collections). La personne demande l\'accès avec lui, dans Créer un compte ou dans Mon compte ; vous recevez un e-mail et approuvez ou refusez dans Approbations. Personne ne voit votre identifiant avant que vous approuviez.',
        'Conta de demonstração: vence em {1} dias ({2}). Depois disso, ela e as suas coleções são apagadas. Para continuar, peça ao administrador para torná-la oficial.' => 'Compte de démonstration : il expire dans {1} jours ({2}). Ensuite, lui et vos collections sont supprimés. Pour continuer, demandez à l\'administrateur de le rendre officiel.',
        'Senha atual (só para trocar a senha)' => 'Mot de passe actuel (seulement pour changer le mot de passe)',
        'O e-mail serve para recuperar a senha, receber os convites e os avisos da conta. Trocou a senha: o navegador pede o login de novo.' => 'L\'e-mail sert à récupérer le mot de passe et à recevoir les invitations et les avis du compte. Mot de passe changé : le navigateur redemande l\'identifiant.',
        'Tokens de API' => 'Jetons d\'API',
        'Para scripts e automações (cabeçalho X-Api-Token): o token vale como o seu login, com as suas coleções. Ele só aparece quando é criado.' => 'Pour les scripts et les automatisations (en-tête X-Api-Token) : le jeton vaut votre identifiant, avec vos collections. Il n\'apparaît qu\'à sa création.',
        'Token {1}:' => 'Jeton {1} :',
        'Criado em' => 'Créé le',
        'Último uso' => 'Dernière utilisation',
        'Revogar' => 'Révoquer',
        'onde vai usar (ex.: atalho do celular)' => 'où il sera utilisé (ex. : raccourci du téléphone)',
        'Nome do token' => 'Nom du jeton',
        'Criar token' => 'Créer un jeton',
        'Este aparelho está lembrado desde {1}: o aplicativo (e este navegador) entra sem pedir a senha.' => 'Cet appareil est mémorisé depuis {1} : l\'application (et ce navigateur) entre sans demander le mot de passe.',
        'Esquecer este aparelho' => 'Oublier cet appareil',
        'O sistema passa a entrar sem pedir a senha neste aparelho (só nele; a chave fica guardada no navegador, e você pode esquecer quando quiser).' => 'Le système entrera sans demander le mot de passe sur cet appareil (sur lui seulement ; la clé reste dans le navigateur, et vous pouvez l\'oublier quand vous voulez).',
        'Lembrar este aparelho' => 'Mémoriser cet appareil',
        'Você já está no aplicativo.' => 'Vous êtes déjà dans l\'application.',
        'Instalar o aplicativo' => 'Installer l\'application',
        'No iPhone e no iPad: abra o sistema no Safari, toque em Compartilhar e em Adicionar à Tela de Início.' => 'Sur l\'iPhone et l\'iPad : ouvrez le système dans Safari, touchez Partager puis Sur l\'écran d\'accueil.',
        'No menu do navegador: Instalar aplicativo (ou Adicionar à tela inicial). Se o botão de instalar aparecer aqui, é só tocar nele.' => 'Dans le menu du navigateur : Installer l\'application (ou Ajouter à l\'écran d\'accueil). Si le bouton d\'installation apparaît ici, il suffit de le toucher.',
        'As notificações (o relógio do dia, a véspera e os avisos) chegam ao aparelho pelo quadro de baixo, {1}; no iPhone, só de dentro do aplicativo instalado. O que chega se escolhe na página Avisos, em Destinos.' => 'Les notifications (la montre du jour, la veille et les alertes) arrivent sur l\'appareil par le cadre ci-dessous, {1} ; sur l\'iPhone, seulement depuis l\'application installée. Ce qui arrive se choisit sur la page Alertes, dans Destinations.',
        'Notificações neste aparelho' => 'Notifications sur cet appareil',
        'Aparelho lembrado' => 'Appareil mémorisé',
        '(sem nome)' => '(sans nom)',
        '(este)' => '(celui-ci)',
        'Esquecer' => 'Oublier',
        'Aplicativo no celular' => 'Application sur le téléphone',
        'O sistema vira um aplicativo no seu celular ou tablet: um ícone na tela inicial, abrindo em tela cheia, entrando sem pedir a senha e recebendo as notificações. Três passos, feitos no aparelho em que você quer o aplicativo:' => 'Le système devient une application sur votre téléphone ou votre tablette : une icône sur l\'écran d\'accueil, ouvrant en plein écran, entrant sans demander le mot de passe et recevant les notifications. Trois étapes, faites sur l\'appareil où vous voulez l\'application :',
        'Lembrar este aparelho.' => 'Mémoriser cet appareil.',
        'Instalar.' => 'Installer.',
        'Ligar as notificações.' => 'Activer les notifications.',
        'Os aparelhos lembrados (trocar a senha esquece todos):' => 'Les appareils mémorisés (changer le mot de passe les oublie tous) :',
        'Aplicativo instalado: abra pelo ícone na tela inicial.' => 'Application installée : ouvrez-la par l\'icône sur l\'écran d\'accueil.',
        'A instalação foi cancelada.' => 'L\'installation a été annulée.',
        'Notificações neste aparelho (Web Push)' => 'Notifications sur cet appareil (Web Push)',
        'O Web Push não está configurado no servidor (VAPID_PUBLICA e VAPID_PRIVADA no config.php).' => 'Le Web Push n\'est pas configuré sur le serveur (VAPID_PUBLICA et VAPID_PRIVADA dans config.php).',
        'Este navegador não recebe notificações (no iPhone, primeiro instale o aplicativo: o quadro Aplicativo no celular, acima).' => 'Ce navigateur ne reçoit pas de notifications (sur l\'iPhone, installez d\'abord l\'application : le cadre Application sur le téléphone, ci-dessus).',
        'Ligue para receber neste aparelho as mensagens dos destinos do tipo Web Push que apontam para você.' => 'Activez-le pour recevoir sur cet appareil les messages des destinations Web Push qui pointent vers vous.',
        'Receber notificações neste aparelho' => 'Recevoir les notifications sur cet appareil',
        'Aparelho' => 'Appareil',
        'Desligar' => 'Désactiver',
        'Mandar uma notificação de teste' => 'Envoyer une notification de test',
        'Chaves do Web Push (master)' => 'Clés du Web Push (master)',
        'Gera um par novo de chaves VAPID para pôr no config.php. Trocar as chaves desliga os aparelhos já inscritos.' => 'Génère une nouvelle paire de clés VAPID à mettre dans config.php. Changer les clés désactive les appareils déjà inscrits.',
        'Gerar chaves' => 'Générer les clés',
        'as notificações foram bloqueadas no navegador' => 'les notifications ont été bloquées dans le navigateur',
        'Não consegui ligar as notificações: {1}' => 'Impossible d\'activer les notifications : {1}',
        'SSL (desde o começo)' => 'SSL (dès le début)',
        'TLS (STARTTLS)' => 'TLS (STARTTLS)',
        'sem criptografia' => 'sans chiffrement',
        'usuário {1}' => 'utilisateur {1}',
        'sem usuário' => 'sans utilisateur',
        'senha definida' => 'mot de passe défini',
        'sem senha' => 'sans mot de passe',
        'Método' => 'Méthode',
        'SMTP (o servidor de e-mail do config.php)' => 'SMTP (le serveur de messagerie du config.php)',
        'mail() do PHP (o sendmail do servidor)' => 'mail() de PHP (le sendmail du serveur)',
        'Remetente' => 'Expéditeur',
        'falta' => 'manquant',
        'SMTP (envio)' => 'SMTP (envoi)',
        'IMAP (cópia em Enviados)' => 'IMAP (copie dans Envoyés)',
        'pasta {1}' => 'dossier {1}',
        'não configurado (opcional)' => 'non configuré (facultatif)',
        'POP (só o teste da conta)' => 'POP (seulement le test du compte)',
        'Servidor de e-mail (master)' => 'Serveur d\'e-mail (master)',
        'O sistema manda e-mail pelo que está no config.php (EMAIL_METODO, EMAIL_REMETENTE, SMTP_*, IMAP_*, POP_*): os convites, o Esqueci a senha, os avisos da conta e os destinos do tipo e-mail. Aqui está o que ele leu de lá, e o teste.' => 'Le système envoie les e-mails avec ce qui est dans le config.php (EMAIL_METODO, EMAIL_REMETENTE, SMTP_*, IMAP_*, POP_*) : les invitations, le Mot de passe oublié, les avis du compte et les destinations de type e-mail. Voici ce qu\'il y a lu, et le test.',
        'Parte' => 'Partie',
        'O que o sistema leu do config.php' => 'Ce que le système a lu du config.php',
        'Para corrigir no config.php:' => 'À corriger dans le config.php :',
        'Testar as conexões (sem mandar nada)' => 'Tester les connexions (sans rien envoyer)',
        'para quem' => 'à qui',
        'Mandar um e-mail de teste' => 'Envoyer un e-mail de test',
        'O teste conecta e entra no SMTP (sem mandar nada), no IMAP (e confere a pasta Enviados) e no POP; o e-mail de teste passa por tudo isso e sai de verdade. A conversa com os servidores aparece embaixo, sem as senhas.' => 'Le test se connecte et s\'authentifie au SMTP (sans rien envoyer), à l\'IMAP (et vérifie le dossier Envoyés) et au POP ; l\'e-mail de test passe par tout cela et part pour de vrai. La conversation avec les serveurs apparaît en dessous, sans les mots de passe.',
        'SMTP' => 'SMTP',
        'IMAP' => 'IMAP',
        'POP' => 'POP',
        'E-mail de teste' => 'E-mail de test',
        'Resultado do teste' => 'Résultat du test',
        'ok' => 'ok',
        'falhou' => 'échec',
        'Nada para testar: o envio está desligado.' => 'Rien à tester : l\'envoi est désactivé.',
        'Conversa com os servidores' => 'Conversation avec les serveurs',
        'Excluir a conta' => 'Supprimer le compte',
        'Sai a conta com tudo o que é dela: as suas coleções (com os relógios, o histórico e os arquivos), as suas árvores, os seus acessos e os seus tokens. Antes de apagar, a API mostra tudo o que sai junto.' => 'Le compte part avec tout ce qui est à lui : vos collections (avec les montres, l\'historique et les fichiers), vos arbres, vos accès et vos jetons. Avant de supprimer, l\'API montre tout ce qui part avec.',
        'Excluir a minha conta' => 'Supprimer mon compte',
        'Minha conta' => 'Mon compte',
        '{1} pedido(s) ou convite(s) esperam a sua resposta em {2}.' => '{1} demande(s) ou invitation(s) attendent votre réponse dans {2}.',
        'Para convidar alguém para as suas coleções, ou ver quem as vê: {1}.' => 'Pour inviter quelqu\'un à vos collections, ou voir qui les voit : {1}.',
        'Não consegui ler a conta: {1}' => 'Impossible de lire le compte : {1}',
        'Inteligente' => 'Intelligent',
        'vai o relógio com a maior nota nos critérios' => 'c\'est la montre avec la meilleure note selon les critères qui sort',
        'Inteligente com sorteio' => 'Intelligent avec tirage',
        'sorteio em que a nota de cada relógio é a chance dele: variedade sem perder o critério' => 'tirage où la note de chaque montre est sa chance : de la variété sans perdre le critère',
        'Totalmente aleatório' => 'Totalement aléatoire',
        'todos com a mesma chance, sem olhar os critérios (os números do RANDOM.ORG; fora do ar, do ANU QRNG; sem os dois, do gerador seguro do PHP)' => 'toutes avec la même chance, sans regarder les critères (les nombres de RANDOM.ORG ; s\'il est indisponible, d\'ANU QRNG ; sans les deux, du générateur sécurisé de PHP)',
        'Fila (FIFO)' => 'File (FIFO)',
        'vai o que está há mais tempo sem uso: todos passam pelo pulso em rodízio' => 'c\'est celle qui n\'a pas servi depuis le plus longtemps qui sort : toutes passent au poignet à tour de rôle',
        'Critérios de escolha do relógio' => 'Critères de choix de la montre',
        'Não foi salvo:' => 'Non enregistré :',
        'Como a nota funciona' => 'Comment fonctionne la note',
        'Cada {1} — todos os relógios, um grupo em qualquer nível da árvore, ou um relógio — pode ter o seu {2}. O relógio usa o conjunto {3}, inteiro: o dele; senão o do grupo dele; senão o do grupo de cima; e assim até o de todos os relógios. Um lugar sem conjunto próprio herda o de cima.' => 'Chaque {1} — toutes les montres, un groupe à n\'importe quel niveau de l\'arbre, ou une montre — peut avoir son propre {2}. La montre utilise l\'ensemble {3}, en entier : le sien ; sinon celui de son groupe ; sinon celui du groupe au-dessus ; et ainsi de suite jusqu\'à celui de toutes les montres. Un endroit sans ensemble propre hérite de celui du dessus.',
        'conjunto de critérios' => 'ensemble de critères',
        'mais perto dele' => 'le plus proche d\'elle',
        'Num conjunto, cada {1} tem um peso, e a soma fecha 100%. Cada parâmetro tem {2}, com peso dentro dele, que também fecha 100%. Cada subparâmetro mede uma coisa do relógio e usa {3} para transformar o valor medido numa nota de 0 a 100. {4} = peso do subparâmetro × peso do parâmetro; {5} = soma de nota × peso efetivo. Subparâmetro sem medida para o relógio (autonomia num relógio que não é smartwatch, por exemplo) sai da conta, e os pesos dos que ficam são reescalados.' => 'Dans un ensemble, chaque {1} a un poids, et la somme fait 100 %. Chaque paramètre a des {2}, pondérés à l\'intérieur, qui font aussi 100 %. Chaque sous-paramètre mesure une chose de la montre et utilise des {3} pour transformer la valeur mesurée en une note de 0 à 100. {4} = poids du sous-paramètre × poids du paramètre ; {5} = somme de note × poids effectif. Un sous-paramètre sans mesure pour la montre (l\'autonomie d\'une montre qui n\'est pas connectée, par exemple) sort du calcul, et les poids de ceux qui restent sont recalculés.',
        'parâmetro' => 'paramètre',
        'subparâmetros' => 'sous-paramètres',
        'Peso efetivo' => 'Poids effectif',
        'nota final' => 'note finale',
        'Como a nota vira escolha' => 'Comment la note devient un choix',
        'Cada modo de rodízio tem a sua forma de escolher o relógio, escolhida no quadro {1}, na página Hoje:' => 'Chaque mode de rotation a sa façon de choisir la montre, choisie dans le cadre {1}, sur la page Aujourd\'hui :',
        'Modo de rodízio' => 'Mode de rotation',
        'Forma de escolha' => 'Méthode de choix',
        '(o modo atual)' => '(le mode actuel)',
        'sempre pela maior nota, com as medidas de cada dia simulado' => 'toujours par la meilleure note, avec les mesures de chaque jour simulé',
        'Garantia de rodízio: {1} (no mesmo quadro). Fora da nota também valem o grupo de cada bloco de dias, os relógios fixos e não repetir o de ontem.' => 'Garantie de rotation : {1} (dans le même cadre). En dehors de la note valent aussi le groupe de chaque bloc de jours, les montres fixes et ne pas répéter celle d\'hier.',
        'nenhum relógio fica mais de {1} dias sem uso' => 'aucune montre ne reste plus de {1} jours sans être portée',
        'Onde há critérios' => 'Où il y a des critères',
        'Lugar' => 'Endroit',
        'Parâmetros' => 'Paramètres',
        'Usado por' => 'Utilisé par',
        'relógio' => 'montre',
        'relógios' => 'montres',
        'Nenhum lugar tem critérios: todos os relógios ficam com nota neutra, 50.' => 'Aucun endroit n\'a de critères : toutes les montres ont une note neutre, 50.',
        'Há relógios sem conjunto nenhum (nota neutra, 50): {1}.' => 'Il y a des montres sans aucun ensemble (note neutre, 50) : {1}.',
        'Editar os critérios de' => 'Modifier les critères de',
        ' — com critérios próprios' => ' — avec ses propres critères',
        '{1} não tem critérios próprios{2}' => '{1} n\'a pas de critères propres{2}',
        ': usa os de {1}.' => ' : utilise ceux de {1}.',
        ', e nenhum lugar acima tem: nota neutra, 50.' => ', et aucun endroit au-dessus n\'en a : note neutre, 50.',
        'Criar critérios próprios, copiando os de {1}' => 'Créer des critères propres, en copiant ceux de {1}',
        'Criar vazio' => 'Créer vide',
        'Critérios de {1}' => 'Critères de {1}',
        'Usado por {1} {2}{3}. Os lugares abaixo deste, sem critérios próprios, também usam estes.' => 'Utilisé par {1} {2}{3}. Les endroits en dessous de celui-ci, sans critères propres, utilisent aussi ceux-ci.',
        'Parâmetro' => 'Paramètre',
        'Peso no conjunto' => 'Poids dans l\'ensemble',
        'Subparâmetros' => 'Sous-paramètres',
        'subparâmetro' => 'sous-paramètre',
        '(fora da conta)' => '(hors du calcul)',
        'Subir' => 'Monter',
        'Descer' => 'Descendre',
        'Soma' => 'Somme',
        'Salvar parâmetros' => 'Enregistrer les paramètres',
        'Excluir o parâmetro {1} ({2}) e os subparâmetros dele?

{3}' => 'Supprimer le paramètre {1} ({2}) et ses sous-paramètres ?

{3}',
        'O peso dele é dividido na proporção dos que ficam:
{1}' => 'Son poids est réparti au prorata de ceux qui restent :
{1}',
        'Era o único: o lugar fica sem critérios próprios e volta a herdar os de cima.' => 'C\'était le seul : l\'endroit n\'a plus de critères propres et hérite de nouveau de ceux du dessus.',
        'Novo parâmetro {1}' => 'Nouveau paramètre {1}',
        'Peso (%) {1}' => 'Poids (%) {1}',
