{2}' => 'Supprimer tous les critères propres de {1} ?

{2}',
        'Passa a usar os de {1}.' => 'Il utilise désormais ceux de {1}.',
        'Os relógios sem conjunto mais perto ficam com nota neutra, 50.' => 'Les montres sans ensemble plus proche ont une note neutre, 50.',
        'Excluir os critérios próprios de {1}{2}' => 'Supprimer les critères propres de {1}{2}',
        ' (volta a usar os de {1})' => ' (revient à ceux de {1})',
        '{1} do conjunto de {2}' => '{1} de l\'ensemble de {2}',
        'Subparâmetro' => 'Sous-paramètre',
        'Mede' => 'Mesure',
        'Peso no parâmetro' => 'Poids dans le paramètre',
        'Peso efetivo no conjunto' => 'Poids effectif dans l\'ensemble',
        'Soma dentro de {1}' => 'Somme dans {1}',
        'Salvar subparâmetros' => 'Enregistrer les sous-paramètres',
        'Excluir o subparâmetro {1} ({2} de {3})?

{4}' => 'Supprimer le sous-paramètre {1} ({2} de {3}) ?

{4}',
        'O parâmetro fica sem subparâmetros e sai da conta até ganhar um.' => 'Le paramètre n\'a plus de sous-paramètres et sort du calcul jusqu\'à en avoir un.',
        'Nota' => 'Note',
        'De' => 'De',
        'Até' => 'À',
        'Faixas de {1} {2}' => 'Tranches de {1} {2}',
        '{1} A linha em branco serve para incluir uma faixa; o "+ faixa" cria mais.' => '{1} La ligne vide sert à ajouter une tranche ; le « + tranche » en crée d\'autres.',
        'Uma nota por categoria; categoria sem faixa: o subparâmetro não se aplica ao relógio daquela categoria.' => 'Une note par catégorie ; catégorie sans tranche : le sous-paramètre ne s\'applique pas aux montres de cette catégorie.',
        'Nota de 0 a 100. "De" entra na faixa, "até" não (a última inclui o seu "até"); "até" vazio = sem limite. A primeira começa em 0; cada uma começa onde a anterior terminou; a última vai até {1}.' => 'Note de 0 à 100. « De » est inclus dans la tranche, « à » non (la dernière inclut son « à ») ; « à » vide = sans limite. La première commence à 0 ; chacune commence là où la précédente s\'est arrêtée ; la dernière va jusqu\'à {1}.',
        '"sem limite" (até vazio)' => '« sans limite » (à vide)',
        '{1} (ou sem limite)' => '{1} (ou sans limite)',
        '+ faixa' => '+ tranche',
        'Salvar faixas' => 'Enregistrer les tranches',
        'Trocar o que {1} mede? As faixas atuais serão apagadas, e ele recomeça com nota 50 em tudo.' => 'Changer ce que mesure {1} ? Les tranches actuelles seront effacées, et il recommence avec une note de 50 partout.',
        'Trocar a medida para {1}' => 'Changer la mesure pour {1}',
        'Mover para o parâmetro {1}' => 'Déplacer vers le paramètre {1}',
        'Mover' => 'Déplacer',
        'Sem subparâmetros: este parâmetro não entra na conta até ganhar um.' => 'Sans sous-paramètres : ce paramètre n\'entre pas dans le calcul tant qu\'il n\'en a pas un.',
        'Novo subparâmetro {1}' => 'Nouveau sous-paramètre {1}',
        'Mede {1}' => 'Mesure {1}',
        'A nota de cada relógio agora' => 'La note de chaque montre maintenant',
        'Relógios disponíveis, da maior nota para a menor, cada um pelo conjunto de critérios que vale para ele. As regras que ficam fora da nota — o grupo de cada bloco de dias, os relógios fixos, não repetir o de ontem e a garantia de rodízio — valem na hora do sorteio.' => 'Montres disponibles, de la meilleure note à la moins bonne, chacune selon l\'ensemble de critères qui vaut pour elle. Les règles hors de la note — le groupe de chaque bloc de jours, les montres fixes, ne pas répéter celle d\'hier et la garantie de rotation — s\'appliquent au moment du tirage.',
        '{1} · critérios de {2}' => '{1} · critères de {2}',
        'Valor medido' => 'Valeur mesurée',
        'Faixa' => 'Tranche',
        'Pontos' => 'Points',
        'Nenhum critério com medida para este relógio: nota neutra, 50.' => 'Aucun critère avec une mesure pour cette montre : note neutre, 50.',
        'Nota final (pesos efetivos somam {1})' => 'Note finale (les poids effectifs font {1})',
        'editar os critérios de {1}' => 'modifier les critères de {1}',
        'critérios só deste relógio' => 'critères de cette montre seulement',
        'Restaurar os critérios iniciais' => 'Restaurer les critères initiaux',
        'Apagar todos os critérios de todos os lugares e voltar aos iniciais?' => 'Supprimer tous les critères de tous les niveaux et revenir aux critères initiaux ?',
        'Apaga os critérios de todos os lugares e volta aos que vieram com o sistema: um conjunto para todos os relógios e um para cada grupo principal. A forma de escolha e a garantia de rodízio não mudam.' => 'Efface les critères de tous les endroits et revient à ceux livrés avec le système : un ensemble pour toutes les montres et un pour chaque groupe principal. La méthode de choix et la garantie de rotation ne changent pas.',
        'fecha 100%' => 'fait 100 %',
        'passa {1}%' => 'dépasse de {1} %',
        'faltam {1}%' => 'il manque {1} %',
        'Não consegui ler os critérios: {1}' => 'Impossible de lire les critères : {1}',
        'Critérios de escolha' => 'Critères de choix',
        'Lista de desejos' => 'Liste d\'envies',
        'Novo desejo' => 'Nouvelle envie',
        'Nenhum relógio na lista de desejos. Em "Novo desejo" (ou no cadastro de qualquer relógio, na "Situação na coleção"), um relógio desejado entra aqui: com a marca, a referência, o preço-alvo, a prioridade e o link. Ele não entra no rodízio nem nos avisos.' => 'Aucune montre dans la liste d\'envies. Dans « Nouvelle envie » (ou dans la fiche de n\'importe quelle montre, dans la « Situation dans la collection »), une montre désirée arrive ici : avec la marque, la référence, le prix cible, la priorité et le lien. Elle n\'entre ni dans la rotation ni dans les alertes.',
        '{1}{2}, a prioridade mais alta primeiro. Somando os preços-alvo: R$ {3}{4}. Comprou? "Comprei" põe o relógio na coleção (disponível para o rodízio) e abre a ficha dele, para preencher a compra.' => '{1}{2}, la priorité la plus haute d\'abord. Total des prix cibles : R$ {3}{4}. Vous l\'avez achetée ? « Achetée » met la montre dans la collection (disponible pour la rotation) et ouvre sa fiche, pour remplir l\'achat.',
        ' relógio desejado' => ' montre désirée',
        ' relógios desejados' => ' montres désirées',
        ' ({1} sem preço-alvo)' => ' ({1} sans prix cible)',
        'Prioridade' => 'Priorité',
        'Preço-alvo' => 'Prix cible',
        'Grupo' => 'Groupe',
        'Link' => 'Lien',
        'R$ ' => 'R$ ',
        'abrir a página' => 'ouvrir la page',
        'Comprei' => 'Achetée',
        'Comprou o {1}? Ele entra na coleção, disponível para o rodízio, e a ficha dele abre para você preencher a compra.' => 'Vous avez acheté la {1} ? Elle entre dans la collection, disponible pour la rotation, et sa fiche s\'ouvre pour que vous remplissiez l\'achat.',
        'Fora da coleção' => 'Hors de la collection',
        'Nenhum relógio emprestado, vendido ou arquivado. No cadastro de um relógio, a "Situação na coleção" muda isso: fora dela, ele sai do rodízio, do plano e dos avisos; a ficha, os documentos e o histórico ficam.' => 'Aucune montre prêtée, vendue ou archivée. Dans la fiche d\'une montre, la « Situation dans la collection » change cela : hors de la collection, elle sort de la rotation, du plan et des alertes ; la fiche, les documents et l\'historique restent.',
        'Emprestados, vendidos e arquivados: fora do rodízio, do plano e dos avisos (o emprestado continua na tabela da página Hoje e no valor da coleção). A ficha, os documentos e o histórico ficam.' => 'Prêtées, vendues et archivées : hors de la rotation, du plan et des alertes (la montre prêtée reste dans le tableau de la page Aujourd\'hui et dans la valeur de la collection). La fiche, les documents et l\'historique restent.',
        'Voltar para a coleção' => 'Retour dans la collection',
        'Voltar o {1} para a coleção? Ele fica disponível para o rodízio de novo.' => 'Remettre la {1} dans la collection ? Elle redevient disponible pour la rotation.',
        'Não consegui ler a lista de desejos: {1}' => 'Impossible de lire la liste d\'envies : {1}',
        'Desejos' => 'Envies',
