        'como JSON' => 'en JSON',
        'Cada valor pode usar {titulo} e {mensagem} (a mensagem já montada pelo modelo).' => 'Chaque valeur peut utiliser {titulo} et {mensagem} (le message déjà monté par le modèle).',
        'Corpo JSON (opcional, só no formato JSON)' => 'Corps JSON (facultatif, seulement au format JSON)',
        'Vazio: os campos acima viram o objeto JSON. Os marcadores {titulo} e {mensagem} vão dentro das aspas.' => 'Vide : les champs ci-dessus deviennent l\'objet JSON. Les marqueurs {titulo} et {mensagem} vont entre les guillemets.',
        'Cabeçalhos' => 'En-têtes',
        'Guardados cifrados (podem ter um token); nunca voltam para a tela.' => 'Enregistrés chiffrés (ils peuvent contenir un jeton) ; ils ne reviennent jamais à l\'écran.',
        'Para (um ou mais, separados por vírgula)' => 'Pour (un ou plusieurs, séparés par des virgules)',
        'O envio de e-mail não está configurado no servidor (EMAIL_METODO no config.php): nada sai por aqui até lá.' => 'L\'envoi d\'e-mail n\'est pas configuré sur le serveur (EMAIL_METODO dans config.php) : rien ne part par ici d\'ici là.',
        'Para os aparelhos de' => 'Vers les appareils de',
        '{1} aparelho(s) inscrito(s). Para inscrever este navegador, entre como esse usuário e ligue as notificações em {2}.' => '{1} appareil(s) inscrit(s). Pour inscrire ce navigateur, connectez-vous en tant que cet utilisateur et activez les notifications dans {2}.',
        'Ligado' => 'Activé',
        'Mensagem padrão' => 'Message par défaut',
        'Inserir âncora na mensagem padrão' => 'Insérer une ancre dans le message par défaut',
        'Cada item vira uma mensagem com este texto (ou com o personalizado dele, abaixo); os do mesmo horário vão juntos, separados por uma linha em branco.' => 'Chaque élément devient un message avec ce texte (ou avec son texte personnalisé, ci-dessous) ; ceux du même horaire partent ensemble, séparés par une ligne vide.',
        'Mandar um teste' => 'Envoyer un test',
        'Mandar a da manhã agora' => 'Envoyer celui du matin maintenant',
        'Mandar a da noite agora' => 'Envoyer celui du soir maintenant',
        'De manhã, hoje' => 'Le matin, aujourd\'hui',
        '(nada a enviar)' => '(rien à envoyer)',
        'À noite, hoje' => 'Le soir, aujourd\'hui',
        'Como sai hoje' => 'Ce qui part aujourd\'hui',
        'As mensagens da manhã (o relógio do dia e os avisos) e da noite (preparar o de amanhã), os avisos na hora e os eventos saem por cada destino ligado, com o que ele recebe. As âncoras entre chaves, como {relogio}, viram os valores na hora de enviar.' => 'Les messages du matin (la montre du jour et les alertes) et du soir (préparer celle de demain), les alertes à l\'heure et les événements partent par chaque destination activée, avec ce qu\'elle reçoit. Les ancres entre accolades, comme {relogio}, deviennent les valeurs à l\'envoi.',
        'Nenhum destino ainda: as mensagens não saem para lugar nenhum.' => 'Aucune destination pour l\'instant : les messages ne partent nulle part.',
