        'Abrir a ficha do relógio' => 'Ouvrir la fiche de la montre',
        'Cópia no banco: a Configuração da coleção (Cópia dos documentos no banco: todos) manda guardar todo arquivo também no banco.' => 'Copie dans la base : la Configuration de la collection (Copie des documents dans la base : tous) impose de garder chaque fichier aussi dans la base.',
        'Cópia no banco: a Configuração da coleção (Cópia dos documentos no banco: nenhum) não deixa; os arquivos ficam só na pasta.' => 'Copie dans la base : la Configuration de la collection (Copie des documents dans la base : aucun) ne le permet pas ; les fichiers restent seulement dans le dossier.',
        'Cópia no banco: todos os arquivos do {1} vão também para o banco. ' => 'Copie dans la base de données : tous les fichiers de la {1} vont aussi dans la base de données. ',
