        'Qualquer arquivo{1}. O título, a data e a descrição valem para todos os escolhidos; depois cada um se edita sozinho.' => 'N\'importe quel fichier{1}. Le titre, la date et la description valent pour tous ceux choisis ; ensuite chacun se modifie séparément.',
