        'Cada relógio' => 'Chaque montre',
        'Do mais usado ao menos usado no período. Dias de uso: os dias em que ele foi ao pulso. A parte: das horas no pulso de todos. Custo por uso: o valor pago dividido por todos os dias de uso (desde sempre). Tendência: as horas da segunda metade do período comparadas com as da primeira.' => 'De la plus portée à la moins portée sur la période. Jours portés : les jours où elle est allée au poignet. La part : des heures au poignet de toutes. Coût par port : le prix payé divisé par tous les jours portés (depuis toujours). Tendance : les heures de la seconde moitié de la période comparées à celles de la première.',
