        'Gerado em {1} {2} pelo Relojoeiro.' => 'Généré le {1} {2} par Relojoeiro.',
        'Não consegui ler a galeria: {1}' => 'Impossible de lire la galerie : {1}',
        '(na raiz)' => '(à la racine)',
        'Grupos de relógios' => 'Groupes de montres',
        'Uma árvore sem limite de níveis. Cada relógio fica num grupo só. Cada grupo pode ter os seus próprios {1}; o relógio usa os do lugar mais perto dele (os dele, os do grupo dele, os do grupo de cima... ou os de todos). O mesmo nome pode se repetir em ramos diferentes. Os campos, os tipos de lançamento, as fórmulas e os avisos de cada grupo ficam em {2}.' => 'Un arbre sans limite de niveaux. Chaque montre est dans un seul groupe. Chaque groupe peut avoir ses propres {1} ; la montre utilise ceux du niveau le plus proche (les siens, ceux de son groupe, ceux du groupe parent... ou ceux de tous). Le même nom peut se répéter dans des branches différentes. Les champs, les types de saisie, les formules et les alertes de chaque groupe sont dans {2}.',
        'critérios' => 'critères',
        'a raiz' => 'la racine',
        'Excluir o grupo {1}?

Vão para {2}: {3} subgrupo(s) e {4} relógio(s), com os campos, os tipos de lançamento e as fórmulas dele.{5}' => 'Supprimer le groupe {1} ?

Vont dans {2} : {3} sous-groupe(s) et {4} montre(s), avec ses champs, types de saisie et formules.{5}',
        '
Os critérios próprios do grupo ({1} parâmetros) serão excluídos; os relógios passam a usar os de cima.' => '
Les critères propres du groupe ({1} paramètres) seront supprimés ; les montres utiliseront ceux du dessus.',
        'Nome do grupo' => 'Nom du groupe',
        'critérios próprios' => 'critères propres',
        'subgrupo e mover' => 'sous-groupe et déplacer',
