        '(indisponível)' => '(indisponible)',
        'Salvar grupos' => 'Enregistrer les groupes',
        'Não consegui ler os grupos: {1}' => 'Impossible de lire les groupes : {1}',
        'Em uso' => 'En usage',
        'Fora do rodízio' => 'Hors rotation',
        'Em repouso' => 'Au repos',
        'Marcações' => 'Marques',
        'Relógio não encontrado.' => 'Montre introuvable.',
        'Histórico · {1} · código {2}' => 'Historique · {1} · code {2}',
        '{1} registros desde {2} {3}' => '{1} enregistrements depuis le {2} {3}',
        'Nada lançado ainda.' => 'Rien de saisi pour l\'instant.',
        'Estado {1}' => 'État {1}',
        '{1} {2} com esses filtros{3}. Os trechos são contínuos: em uso (rodízio), fora do rodízio, em cada tipo de sessão (no winder, no sol...) e em repouso; as marcações (corda, carga, pilha, revisão) não têm fim nem duração.' => '{1} {2} avec ces filtres{3}. Les périodes sont continues : en usage (rotation), hors rotation, dans chaque type de session (sur le remontoir, au soleil...) et au repos ; les marques (remontage, charge, pile, révision) n\'ont ni fin ni durée.',
        'Fim' => 'Fin',
        'Estado' => 'État',
        'em andamento: o fim é o momento desta consulta' => 'en cours : la fin est le moment de cette consultation',
        'Nenhum registro com esses filtros.' => 'Aucun enregistrement avec ces filtres.',
        '« mais recentes' => '« plus récents',
        'mais antigos »' => 'plus anciens »',
        'ver tudo' => 'tout voir',
        'Histórico — {1}' => 'Historique — {1}',
        'Não consegui ler o histórico: {1}' => 'Impossible de lire l\'historique : {1}',
        'Histórico' => 'Historique',
        'Segunda' => 'Lundi',
        'Terça' => 'Mardi',
        'Quarta' => 'Mercredi',
        'Quinta' => 'Jeudi',
        'Sexta' => 'Vendredi',
        'Sábado' => 'Samedi',
        'Domingo' => 'Dimanche',
        'Vai o relógio com a maior nota nos critérios. Previsível: com os mesmos dados, a mesma escolha.' => 'La montre avec la meilleure note selon les critères est choisie. Prévisible : avec les mêmes données, le même choix.',
        'Sorteio em que a nota de cada relógio é a chance dele: quem tem nota maior sai mais vezes, mas todos têm chance. Variedade sem perder o critério.' => 'Tirage où la note de chaque montre est sa chance : les mieux notées sortent plus souvent, mais toutes ont une chance. De la variété sans perdre le critère.',
        'Todos os relógios do tipo têm a mesma chance, sem olhar os critérios. Os números vêm do RANDOM.ORG (ruído atmosférico); fora do ar, do ANU QRNG (quântico); sem os dois, do gerador seguro do PHP.' => 'Toutes les montres du type ont la même chance, sans regarder les critères. Les nombres viennent de RANDOM.ORG (bruit atmosphérique) ; s\'il est indisponible, d\'ANU QRNG (quantique) ; sans les deux, du générateur sécurisé de PHP.',
        'Vai o que está há mais tempo sem uso: todos passam pelo pulso, em fila. Não olha os critérios, e já garante o rodízio por natureza.' => 'Celle qui n\'a pas été portée depuis le plus longtemps est choisie : toutes passent au poignet, à tour de rôle. Ne regarde pas les critères et garantit la rotation par nature.',
        'Dia' => 'Jour',
        'Lembrete' => 'Rappel',
        'Neste modo o sorteio é feito dia a dia.' => 'Dans ce mode, le tirage se fait jour par jour.',
        'Página {1} de {2} · {3} dias no plano, {4} por página (o "Mostrar até" da {5}).' => 'Page {1} sur {2} · {3} jours dans le plan, {4} par page (le « Afficher jusqu\'à » de {5}).',
        'Não consegui ler os próximos dias: {1}' => 'Impossible de lire les prochains jours : {1}',
        'sem modo' => 'sans mode',
        'no pulso agora' => 'au poignet maintenant',
        'Relógio do dia: {1} ({2})' => 'Montre du jour : {1} ({2})',
        'Hoje não tem relógio do dia.' => 'Pas de montre du jour aujourd\'hui.',
        'Por que ele: ' => 'Pourquoi elle : ',
        'Hoje sem relógio? O dia fica livre: o {1} sai do rodízio de hoje (se já está no pulso pelo rodízio, sai agora; o tempo que ficou conta). Os outros dias não mudam.' => 'Pas de montre aujourd\'hui ? La journée reste libre : {1} sort de la rotation d\'aujourd\'hui (si elle est déjà au poignet par la rotation, elle sort maintenant ; le temps porté compte). Les autres jours ne changent pas.',
        'Sem relógio hoje' => 'Jour sans montre',
        'Hoje sem relógio' => 'Aujourd\'hui sans montre',
        'dia livre' => 'jour libre',
        'Nenhum relógio vai ao pulso pelo rodízio hoje. Quer usar um? Escolha abaixo, ou sorteie de novo (inclusive hoje) no quadro do modo de rodízio.' => 'Aucune montre ne va au poignet par la rotation aujourd\'hui. Vous voulez en porter une ? Choisissez ci-dessous, ou refaites le tirage (aujourd\'hui compris) dans le cadre du mode de rotation.',
        'Nenhum relógio para hoje' => 'Aucune montre pour aujourd\'hui',
        'Nenhum relógio disponível no grupo deste dia. Mude o grupo no modo de rodízio ou marque um relógio como disponível.' => 'Aucune montre disponible dans le groupe de ce jour. Changez le groupe dans le mode de rotation ou marquez une montre comme disponible.',
        'Tirou do pulso' => 'Retirée du poignet',
