        'Abrir o {1} no painel' => 'Ouvrir {1} dans le tableau de bord',
        'Hoje é dia de' => 'Aujourd\'hui, c\'est le jour de',
        'O que fazer' => 'Que faire',
        'Por quê' => 'Pourquoi',
        'Próximos dias {1}' => 'Prochains jours {1}',
        'ver o plano inteiro →' => 'voir tout le plan →',
        'Sortear entre' => 'Tirer au sort parmi',
        'Relógio fixo' => 'Montre fixe',
        ' (indisponível: o dia sorteia outro do mesmo grupo)' => ' (indisponible : le jour tire une autre montre du même groupe)',
        'Modo de rodízio {1}' => 'Mode de rotation {1}',
        'Rodízio manual' => 'Rotation manuelle',
        'Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre ({1}).' => 'Vous choisissez la montre de chaque jour d\'une période. Indiquez le début et la fin puis cliquez sur OK : les jours apparaissent 7 par 7, chacun avec la liste des montres, « Décider pour moi » (le système choisit) et « Sans montre (jour libre) ». En dehors de la période, le mode de rotation habituel continue de s\'appliquer ({1}).',
        'nenhum' => 'aucun',
        'Monta o plano do período inteiro de uma vez, simulando a carga de cada relógio dia a dia, com os lembretes de carregar, dar corda e pôr no sol. É refeita toda manhã a partir do estado real.' => 'Construit le plan de toute la période d\'un coup, en simulant la charge de chaque montre jour par jour, avec les rappels pour charger, remonter et mettre au soleil. Il est refait chaque matin à partir de l\'état réel.',
        'Cada bloco de dias sorteia entre os relógios do grupo escolhido, ou usa o relógio fixo; marcando "sortear um por dia", cada dia do bloco tem o seu sorteio. O plano vem montado até domingo; a semana seguinte é sorteada quando começa, ou antes, em Sortear de novo (a próxima semana).' => 'Chaque bloc de jours tire au sort parmi les montres du groupe choisi, ou utilise la montre fixe ; en cochant « tirer une par jour », chaque jour du bloc a son propre tirage. Le plan est construit jusqu\'à dimanche ; la semaine suivante est tirée quand elle commence, ou avant, dans Refaire le tirage (la semaine prochaine).',
        'Período {1}' => 'Période {1}',
        'Uma semana' => 'Une semaine',
        'Um mês' => 'Un mois',
        'Dois meses' => 'Deux mois',
        'Meio ano' => 'Six mois',
        'Um ano' => 'Un an',
        'Dois anos' => 'Deux ans',
        '{1} sortear um por dia' => '{1} tirer une par jour',
        'Como escolher o relógio {1}' => 'Comment choisir la montre {1}',
        'Como escolher o relógio: {1}' => 'Comment choisir la montre : {1}',
        'pela maior nota' => 'par la meilleure note',
        'A escala escolhe sempre pela maior nota nos critérios, com as medidas de cada dia simulado.' => 'Le planning choisit toujours par la meilleure note selon les critères, avec les mesures de chaque jour simulé.',
        'Garantia de rodízio: dias sem uso, no máximo {1}' => 'Garantie de rotation : jours sans usage, au maximum {1}',
        'Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota.' => 'Celle qui dépasse la limite est prioritaire, la plus longtemps inutilisée d\'abord. 0 désactive. La même valeur vaut pour tous les modes qui utilisent la note.',
        'A nota vem dos {1}, que você cadastra.' => 'La note vient des {1}, que vous définissez.',
        'Trocar o modo refaz o plano a partir de amanhã; hoje continua o {1}. Continuar?' => 'Changer de mode refait le plan à partir de demain ; aujourd\'hui reste {1}. Continuer ?',
        'Trocar o modo apaga o plano atual. Continuar?' => 'Changer de mode efface le plan actuel. Continuer ?',
        'Aplicar modo' => 'Appliquer le mode',
        'Trocar o modo apaga o plano atual e gera outro{1}. O histórico de uso, corda, sol e carga continua. Os modos e os blocos de dias se cadastram em {2}.' => 'Changer de mode efface le plan actuel et en génère un autre{1}. L\'historique d\'usage, de remontage, de soleil et de charge est conservé. Les modes et les blocs de jours se définissent dans {2}.',
        ' a partir de amanhã: hoje continua o {1}, que já está no pulso (para trocar hoje, use "Usando hoje")' => ' à partir de demain : aujourd\'hui reste {1}, déjà au poignet (pour changer aujourd\'hui, utilisez « Portée aujourd\'hui »)',
        ' a partir de hoje' => ' à partir d\'aujourd\'hui',
        'Modos de rodízio' => 'Modes de rotation',
        'o fim da escala' => 'la fin du planning',
        'o fim da próxima semana' => 'la fin de la semaine prochaine',
        'domingo' => 'dimanche',
        'a partir de amanhã' => 'à partir de demain',
        'Refaz o plano de amanhã até {1} pelo modo atual; hoje continua o {2}.' => 'Refait le plan de demain jusqu\'au {1} selon le mode actuel ; aujourd\'hui reste {2}.',
        'Sortear de novo a partir de amanhã? Hoje continua o {1}.' => 'Refaire le tirage à partir de demain ? Aujourd\'hui reste {1}.',
        'inclusive hoje' => 'aujourd\'hui compris',
        'Refaz também hoje: se sair outro relógio, ele passa a ser o do pulso a partir de agora, e o {1} sai.' => 'Refait aussi aujourd\'hui : si une autre montre sort, elle devient celle du poignet dès maintenant, et {1} est retirée.',
        'Sortear de novo inclusive hoje? Se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora, e o {1} sai.' => 'Refaire le tirage aujourd\'hui compris ? Si une autre montre sort pour aujourd\'hui, elle devient celle du poignet dès maintenant, et {1} est retirée.',
        'a partir de hoje' => 'à partir d\'aujourd\'hui',
        'Refaz o plano de hoje até {1} pelo modo atual (o dia ainda não começou no pulso).' => 'Refait le plan d\'aujourd\'hui jusqu\'au {1} selon le mode actuel (la journée n\'a pas encore commencé au poignet).',
        'Sortear de novo a partir de hoje?' => 'Refaire le tirage à partir d\'aujourd\'hui ?',
        'a próxima semana ({1} a {2})' => 'la semaine prochaine ({1} au {2})',
        '{1} a semana seguinte inteira, de segunda a domingo, pelo modo atual, com os dias que ainda faltam desta semana já contados como uso. Os dias escolhidos à mão ficam.' => '{1} toute la semaine suivante, du lundi au dimanche, selon le mode actuel, avec les jours qui restent cette semaine déjà comptés comme utilisation. Les jours choisis à la main restent.',
