        'um por bloco (na semana)' => 'une par bloc (dans la semaine)',
        '— sorteia —' => '— tirée au sort —',
        'Cada modo tem blocos de dias da semana. O sorteio segue os critérios, recalculados a cada dia com o uso dos dias anteriores do plano (a carga não é simulada: não se sabe se você vai carregar). Com o ciclo (opcional), um relógio só volta depois que todos os disponíveis do bloco passaram; dentro do ciclo, a forma de escolha decide a ordem. Um bloco sorteia entre os relógios disponíveis de um ponto da árvore — um relógio para o bloco inteiro na semana, ou um por dia — ou usa um relógio fixo. A forma de escolha vale para o modo; a garantia de rodízio ({1} dias), para todos. Na escala inteligente, o modo monta o período inteiro de uma vez (de 7 dias a 2 anos), simulando as fórmulas dia a dia: escolhe sempre pela maior nota no dia simulado, e o relógio escolhido fica os dias da fórmula dias_seguidos (vazio: 1); os blocos dizem de onde escolher em cada dia da semana (ou o relógio fixo), e o "um por" não conta. A escala é refeita toda manhã a partir do estado real.' => 'Chaque mode a des blocs de jours de la semaine. Le tirage suit les critères, recalculés chaque jour avec l\'usage des jours précédents du plan (la charge n\'est pas simulée : on ne sait pas si vous allez recharger). Avec le cycle (facultatif), une montre ne revient qu\'une fois que toutes les disponibles du bloc sont passées ; dans le cycle, la méthode de choix décide de l\'ordre. Un bloc tire au sort parmi les montres disponibles d\'un point de l\'arbre — une montre pour tout le bloc dans la semaine, ou une par jour — ou utilise une montre fixe. La méthode de choix vaut pour le mode ; la garantie de rotation ({1} jours), pour tous. Dans le planning intelligent, le mode construit toute la période d\'un coup (de 7 jours à 2 ans), en simulant les formules jour après jour : il choisit toujours la meilleure note du jour simulé, et la montre choisie reste les jours de la formule dias_seguidos (vide : 1) ; les blocs disent où choisir chaque jour de la semaine (ou la montre fixe), et le « une par » ne compte pas. Le planning est refait chaque matin à partir de l\'état réel.',
