        'Grupo {1} {2}' => 'Groupe {1} {2}',
        'os campos, os lançamentos e os critérios de um grupo valem para tudo abaixo dele (páginas Grupos e Cadastros)' => 'les champs, les saisies et les critères d\'un groupe valent pour tout ce qui est en dessous (pages Groupes et Définitions)',
