        'Excluir este relógio' => 'Supprimer cette montre',
        'O gráfico aparece a partir de duas leituras de carga.' => 'Le graphique apparaît à partir de deux lectures de charge.',
        'Leituras de carga de {1} a {2}' => 'Lectures de charge du {1} au {2}',
        '{1} leitura em uso' => '{1} lecture en usage',
        '{1} leitura em repouso' => '{1} lecture au repos',
        'Período' => 'Période',
        '{1} a {2}' => '{1} au {2}',
        'Escala' => 'Échelle',
        'de 0 a 100%' => 'de 0 à 100 %',
        'A conta' => 'Le calcul',
        'de onde vem cada número: no quadro Previsão' => 'd\'où vient chaque nombre : dans le cadre Prévision',
        'Cada leitura comparada com a anterior. Os dois gastos (em uso e fora do pulso) saem juntos de todas as medições {1}, cada uma dividida pelas marcações de pulso minuto a minuto e pesando as horas que cobre (o motor original). O botão de cada linha tira ou põe a medição na conta.' => 'Chaque relevé comparé au précédent. Les deux consommations (en usage et hors du poignet) sortent ensemble de toutes les mesures {1}, chacune découpée par les marquages de poignet minute par minute et pesant les heures qu\'elle couvre (le moteur d\'origine). Le bouton de chaque ligne retire ou remet la mesure dans le calcul.',
        'Cada leitura comparada com a anterior. Os dois gastos (em uso e fora do pulso) saem juntos das leituras {1}, todas com o mesmo peso e partindo do cadastro; o gasto de cada linha é só o dela. A leitura que não bate bem com as outras pesa menos na conta, e o botão de cada linha tira ou põe a medição na conta.' => 'Chaque relevé comparé au précédent. Les deux consommations (en usage et hors du poignet) sortent ensemble des relevés {1}, tous avec le même poids et en partant de la fiche ; la consommation de chaque ligne n\'est que la sienne. Le relevé qui ne colle pas bien avec les autres pèse moins dans le calcul, et le bouton de chaque ligne retire ou remet la mesure dans le calcul.',
        'Cada leitura comparada com a anterior. Neste relógio vale só o cadastro (o motor escolhido): as medições ficam aqui, no histórico, e não entram em conta nenhuma.' => 'Chaque relevé comparé au précédent. Sur cette montre seule la fiche vaut (le moteur choisi) : les mesures restent ici, dans l\'historique, et n\'entrent dans aucun calcul.',
        'Cada leitura comparada com a anterior. O gasto em uso sai só das medições com as duas leituras marcadas em uso, e o gasto em repouso só das marcadas em repouso, {1} (o "contar por" da Configuração), todas com o mesmo peso e partindo do cadastro; o gasto de cada linha é só o dela. A leitura que não bate bem com as outras pesa menos na conta, e o botão de cada linha tira ou põe a medição na conta.' => 'Chaque relevé comparé au précédent. La consommation en usage ne sort que des mesures dont les deux relevés sont marqués en usage, et la consommation au repos que de celles marquées au repos, {1} (le « compter par » de la Configuration), toutes avec le même poids et en partant de la fiche ; la consommation de chaque ligne n\'est que la sienne. Le relevé qui ne colle pas bien avec les autres pèse moins dans le calcul, et le bouton de chaque ligne retire ou remet la mesure dans le calcul.',
