        'evento "{1}" disparou' => 'l\'événement « {1} » s\'est déclenché',
        ' ({1} ocorrências atrasadas, enviado uma vez)' => ' ({1} occurrences en retard, envoyé une fois)',
        'eventos' => 'événements',
        'Uso: php importar.php <banco antigo> [--substituir]
' => 'Usage : php importar.php <ancienne base> [--substituir]
',
        'Importado de {1}:
' => 'Importé de {1} :
',
        'Erro na instalação: {1}' => 'Erreur d\'installation : {1}',
        '{1}
Pela linha de comando: php criar_usuario.php <login>
' => '{1}
En ligne de commande : php criar_usuario.php <login>
',
        'o config.php não define API_TOKEN' => 'le config.php ne définit pas API_TOKEN',
        'API_TOKEN no config.php tem de ser um texto, entre aspas' => 'API_TOKEN dans le config.php doit être un texte, entre guillemets',
        'semente de teste' => 'graine de test',
        '{1} em {2}' => '{1} le {2}',
        'todos os relógios' => 'toutes les montres',
        'Número inteiro' => 'Nombre entier',
        'Número decimal' => 'Nombre décimal',
        'Sim ou não (nas contas: 1 ou 0)' => 'Oui ou non (dans les calculs : 1 ou 0)',
        'Data (nas contas: por DIAS_DESDE, DIAS_ATE e SOMA_MESES)' => 'Date (dans les calculs : par DIAS_DESDE, DIAS_ATE et SOMA_MESES)',
        'Lista de opções (compara e dá faixa por categoria)' => 'Liste d\'options (compare et donne une plage par catégorie)',
        'Texto (compara e dá faixa por categoria)' => 'Texte (compare et donne une plage par catégorie)',
        'tem de ser um número inteiro' => 'doit être un nombre entier',
        'tem de ser um número' => 'doit être un nombre',
        'tem de ser sim ou não' => 'doit être oui ou non',
        'tem de ser uma data AAAA-MM-DD' => 'doit être une date AAAA-MM-JJ',
        'tem de ser uma das opções: {1}' => 'doit être l\'une des options : {1}',
        'passa de 1000 caracteres' => 'dépasse 1000 caractères',
        'Instantâneo' => 'Instantané',
        'Instantâneo com valor' => 'Instantané avec valeur',
        'Sessão, com início e fim' => 'Session, avec début et fin',
        'lançamentos pela API, com sessões exclusivas (o relógio num lugar só), avisos cadastráveis e a autonomia restante' => 'saisies par l\'API, avec des sessions exclusives (la montre à un seul endroit), des alertes configurables et l\'autonomie restante',
        'modos de rodízio cadastráveis, o plano, os critérios por lugar e o cron' => 'modes de rotation configurables, le plan, les critères par niveau et le cron',
        'a escala inteligente, os eventos personalizados, o Google Agenda, a previsão do smartwatch e a linha do tempo' => 'le planning intelligent, les événements personnalisés, Google Agenda, la prévision de la smartwatch et la chronologie',
        'as telas e as mensagens do sistema antigo: canais com mensagem padrão e personalizada, avisos de carga baixa e de leitura, limite do solar, e o registro completo do cron' => 'les écrans et les messages de l\'ancien système : canaux avec message par défaut et personnalisé, alertes de charge basse et de lecture, limite du solaire, et le journal complet du cron',
        'o gasto medido pelas leituras (a média dos últimos dias) e as autonomias em segundos' => 'la consommation mesurée par les lectures (la moyenne des derniers jours) et les autonomies en secondes',
        'o ciclo no rodízio (opção de cada modo, desligada por padrão): um relógio só volta depois que todos do bloco passaram' => 'le cycle dans la rotation (option de chaque mode, désactivée par défaut) : une montre ne revient qu\'après le passage de toutes celles du bloc',
        'a condição "vale quando" nos tipos de lançamento e nos avisos; o automático sem corda recebe "Pôr no winder" em vez de "Dar corda"' => 'la condition « vaut quand » dans les types de saisie et les alertes ; l\'automatique sans remontage manuel reçoit « Mettre sur le remontoir » au lieu de « Remonter »',
        'o limite de carga, geral e por relógio: carregar, pôr no sol e dar corda só quando a carga chega a ele' => 'la limite de charge, générale et par montre : charger, mettre au soleil et remonter seulement quand la charge l\'atteint',
        'os avisos de carga pelo estado de agora: no winder ou no pulso (o automático carrega no pulso), sem aviso de winder ou de corda; no sol, sem aviso de sol; a data do "Carregar" pelo gasto de agora (no pulso, o de uso; guardado, o de guardado)' => 'les alertes de charge selon l\'état actuel : sur le remontoir ou au poignet (l\'automatique se charge au poignet), sans alerte de remontoir ni de remontage ; au soleil, sans alerte de soleil ; la date du « Charger » selon la consommation actuelle (au poignet, celle d\'usage ; rangée, celle de rangement)',
        'o motivo de cada escolha do plano: por que aquele relógio saiu naquele dia (a garantia de rodízio, a nota, o sorteio, a escolha à mão)' => 'la raison de chaque choix du plan : pourquoi cette montre est sortie ce jour-là (la garantie de rotation, la note, le tirage, le choix à la main)',
        'os dias sem uso de um relógio nunca usado contam desde a compra (antes valiam 9999 para todos: empatavam na garantia de rodízio)' => 'les jours sans usage d\'une montre jamais portée comptent depuis l\'achat (avant, ils valaient 9999 pour toutes : elles étaient à égalité dans la garantie de rotation)',
        'o manual de cada relógio: um arquivo (PDF ou imagem) guardado no banco, que se envia e se abre pela ficha' => 'le manuel de chaque montre : un fichier (PDF ou image) gardé dans la base de données, envoyé et ouvert depuis la fiche',
        'os documentos de cada relógio: qualquer arquivo (manual, nota fiscal em PDF e em XML, fotos, vídeos, diversos), numa categoria, com a página Documentos (galeria, vídeos em sequência, visualizador de PDF, resumo da nota); os manuais da v13 passam para lá' => 'les documents de chaque montre : n\'importe quel fichier (manuel, facture en PDF et en XML, photos, vidéos, divers), dans une catégorie, avec la page Documents (galerie, vidéos en séquence, visionneuse PDF, résumé de la facture) ; les manuels de la v13 y passent',
        'a cópia de segurança de cada documento dentro do banco (em pedaços de 4 MB): o arquivo que sumir da pasta volta sozinho do banco; o cron copia os que já existem e limpa a pasta (relógio excluído, arquivo sem documento)' => 'la sauvegarde de chaque document dans la base de données (en morceaux de 4 Mo) : le fichier qui disparaît du dossier revient tout seul depuis la base ; le cron copie ceux qui existent déjà et nettoie le dossier (montre supprimée, fichier sans document)',
        'o banco no modelo relacional estrito: toda ligação é chave estrangeira, com cascata (ou, se opcional, desfazendo a ligação); as listas guardadas num campo (dias dos blocos e dos eventos, tipos aceitos, opções de um campo) viram tabelas; as mensagens e os canais saem da configuração para a tabela canal_aviso; o modo ativo vira uma marca no modo; a tabela manual sai (os manuais viram documentos)' => 'la base de données dans le modèle relationnel strict : chaque lien est une clé étrangère, en cascade (ou, s\'il est optionnel, en défaisant le lien) ; les listes gardées dans un champ (jours des blocs et des événements, types acceptés, options d\'un champ) deviennent des tables ; les messages et les canaux quittent la configuration pour la table canal_aviso ; le mode actif devient une marque sur le mode ; la table manual disparaît (les manuels deviennent des documents)',
        'o banco valida o que guarda: regras (CHECK) em cada tabela, a origem dos lançamentos e do plano numa lista fechada, no máximo um modo em uso, um arquivo por documento; e a cópia dos documentos no banco em três níveis: o sistema (config.php), o relógio e o próprio arquivo' => 'la base de données valide ce qu\'elle garde : des règles (CHECK) sur chaque table, l\'origine des saisies et du plan dans une liste fermée, au plus un mode en usage, un fichier par document ; et la copie des documents dans la base à trois niveaux : le système (config.php), la montre et le fichier lui-même',
        'o carregador: a sessão "No carregador" onde vale a leitura de carga (o smartwatch), o estado do relógio mostra a sessão aberta (no sol, no winder, no carregador) e, no carregador, o aviso "Carregar" não aparece' => 'le chargeur : la session « Sur le chargeur » où vaut la lecture de charge (la smartwatch), l\'état de la montre montre la session ouverte (au soleil, sur le remontoir, sur le chargeur) et, sur le chargeur, l\'alerte « Charger » n\'apparaît pas',
        'o solar carrega também no pulso: uma parte do que ganharia no sol direto, pelo campo "No pulso: quanto carrega, comparado ao sol direto" (padrão 25%; 0 é o de antes, a carga parada)' => 'le solaire se charge aussi au poignet : une partie de ce qu\'il gagnerait au soleil direct, par le champ « Au poignet : combien il se charge, comparé au soleil direct » (25 % par défaut ; 0 est l\'ancien comportement, la charge arrêtée)',
        'o smartwatch carrega no carregador (o campo "No carregador: horas para encher"), o aviso "Tirar do carregador" que sai na hora pelo Telegram (os avisos "na hora"), as fórmulas "Dias de uso" e "Custo por uso", e no MySQL/MariaDB as tabelas em utf8mb4_unicode_ci' => 'la smartwatch se charge sur le chargeur (le champ « Sur le chargeur : heures pour remplir »), l\'alerte « Retirer du chargeur » envoyée tout de suite par Telegram (les alertes « immédiates »), les formules « Jours d\'usage » et « Coût par usage », et sous MySQL/MariaDB les tables en utf8mb4_unicode_ci',
        'os dias livres do plano: o "Deixar o período livre" da página Plano apaga o que foi gerado e deixa os dias sem relógio, sem sorteio, para você escolher à mão' => 'les jours libres du plan : le « Laisser la période libre » de la page Plan efface ce qui a été généré et laisse les jours sans montre, sans tirage, pour que vous choisissiez à la main',
        'a situação de cada relógio na coleção (na coleção, desejado, emprestado, vendido ou arquivado: fora da coleção, ele sai do rodízio e dos avisos, e a ficha e o histórico ficam) e a lista de desejos; os campos Marca, Referência e Link, e, só nos desejados, Preço-alvo e Prioridade' => 'le statut de chaque montre dans la collection (dans la collection, désirée, prêtée, vendue ou archivée : hors de la collection, elle sort de la rotation et des alertes, et la fiche et l\'historique restent) et la liste d\'envies ; les champs Marque, Référence et Lien, et, seulement pour les désirées, Prix cible et Priorité',
        'o aviso Encostado: um relógio da coleção que passou do limite de dias sem ir ao pulso (a Configuração, "Aviso Encostado: dias sem ir ao pulso", padrão 30)' => 'l\'alerte Délaissée : une montre de la collection qui a dépassé la limite de jours sans aller au poignet (la Configuration, « Alerte Délaissée : jours sans aller au poignet », 30 par défaut)',
        'os acessórios: pulseiras, caixas, estojos, ferramentas, carregadores, peças e o que mais for, de um relógio ou soltos (a página Acessórios e o quadro Acessórios do relógio)' => 'les accessoires : bracelets, boîtes, étuis, outils, chargeurs, pièces et tout le reste, d\'une montre ou libres (la page Accessoires et le cadre Accessoires de la montre)',
        'várias pessoas, cada uma com as suas coleções: usuários (master e comum, conta demo e oficial), coleções com membros, convites e pedidos de acesso, árvores de grupos que servem a várias coleções do mesmo dono, destinos de alerta (webhook, e-mail, Web Push) e agendas (Google, CalDAV, Outlook, link ICS); o banco inteiro em cascata, na 3ª forma normal. O banco antigo é copiado para um arquivo antes, e o usuário mais antigo vira o master e o dono da coleção' => 'plusieurs personnes, chacune avec ses collections : utilisateurs (master et normal, compte démo et officiel), collections avec membres, invitations et demandes d\'accès, arbres de groupes qui servent à plusieurs collections du même propriétaire, destinations d\'alerte (webhook, e-mail, Web Push) et agendas (Google, CalDAV, Outlook, lien ICS) ; toute la base en cascade, en troisième forme normale. L\'ancienne base est d\'abord copiée dans un fichier, et l\'utilisateur le plus ancien devient le master et le propriétaire de la collection',
        'o gasto da bateria em cinco motores, escolhidos na Configuração da coleção, no relógio ou no grupo (o campo "Como calcular o gasto da bateria"): pelas horas registradas (o original), robusto, pela marcação das leituras (em uso e em repouso, gravada em cada leitura), só o cadastro, ou pelas fórmulas do cadastro; e a cópia dos documentos no banco escolhida na Configuração da coleção, no lugar do config.php' => 'la consommation de la batterie en cinq moteurs, choisis dans la Configuration de la collection, dans la montre ou dans le groupe (le champ « Comment calculer la consommation de la batterie ») : par les heures enregistrées (l\'original), robuste, par le marquage des relevés (en usage et au repos, enregistré dans chaque relevé), la fiche seulement, ou par les formules de la fiche ; et la copie des documents dans la base choisie dans la Configuration de la collection, à la place du config.php',
        'o aplicativo no celular (PWA): os aparelhos lembrados de cada usuário (Minha conta: o aplicativo instalado entra sem a senha pela chave gravada no aparelho), o manifesto e o service worker pela API' => 'l\'application sur le téléphone (PWA) : les appareils mémorisés de chaque utilisateur (Mon compte : l\'application installée entre sans le mot de passe par la clé gardée sur l\'appareil), le manifeste et le service worker par l\'API',
        'O banco já tem tabelas ({1}{2}): a instalação é só num banco vazio. Para atualizar um banco que já existe, aplique as migrações (recurso=migracoes, acao=aplicar).' => 'La base de données a déjà des tables ({1}{2}) : l\'installation ne se fait que dans une base vide. Pour mettre à jour une base existante, appliquez les migrations (recurso=migracoes, acao=aplicar).',
        'A instalação terminou, mas faltam as migrações {1}: o schema.sql está incompleto.' => 'L\'installation est terminée, mais il manque les migrations {1} : le schema.sql est incomplet.',
        'Banco instalado ({1}): {2} comandos, {3} tabelas, em {4} s. Agora crie o primeiro usuário (recurso=usuarios, acao=salvar, com o token).' => 'Base de données installée ({1}) : {2} commandes, {3} tables, en {4} s. Créez maintenant le premier utilisateur (recurso=usuarios, acao=salvar, avec le jeton).',
        'Firebird' => 'Firebird',
        'instalar: POST recurso=instalacao, acao=instalar' => 'installer : POST recurso=instalacao, acao=instalar',
        'aplicar as migrações: POST recurso=migracoes, acao=aplicar' => 'appliquer les migrations : POST recurso=migracoes, acao=aplicar',
        'criar o primeiro usuário: POST recurso=usuarios, acao=salvar, login e senha (com o token)' => 'créer le premier utilisateur : POST recurso=usuarios, acao=salvar, login et senha (avec le jeton)',
        'nada: o sistema está pronto' => 'rien : le système est prêt',
        'o menor dos valores (ignora os vazios)' => 'la plus petite des valeurs (ignore les vides)',
        'o maior dos valores (ignora os vazios)' => 'la plus grande des valeurs (ignore les vides)',
        'SE(condição; se verdadeira; se falsa)' => 'SE(condition ; si vraie ; si fausse)',
        '1 se todas as condições são verdadeiras' => '1 si toutes les conditions sont vraies',
        '1 se alguma condição é verdadeira' => '1 si une condition est vraie',
        'inverte a condição' => 'inverse la condition',
        'LIMITA(x; mínimo; máximo)' => 'LIMITA(x ; minimum ; maximum)',
        'o valor sem sinal' => 'la valeur sans signe',
        'PADRAO(x; valor se x estiver vazio)' => 'PADRAO(x ; valeur si x est vide)',
        '1 se o valor está vazio' => '1 si la valeur est vide',
        'o vazio, de propósito (ex.: SE(condição; NADA(); conta))' => 'le vide, exprès (ex. : SE(condition ; NADA() ; calcul))',
        'a data de hoje (em dias)' => 'la date d\'aujourd\'hui (en jours)',
        'o instante de agora (em dias, com a fração do dia)' => 'l\'instant présent (en jours, avec la fraction du jour)',
        'as horas de um dia de uso, pelo horário de uso da Configuração (das 7h às 22h: 15)' => 'les heures d\'un jour d\'usage, selon les heures de port de la Configuration (de 7 h à 22 h : 15)',
        'MEDIDO("uso") ou MEDIDO("repouso"): o gasto medido pelas leituras, em % por dia (de uso ou fora do pulso): os dois saem juntos das medições dos últimos dias da Configuração (cada intervalo entre duas leituras: a queda = dias de uso × gasto em uso + dias fora × gasto fora), na conta feita nas leituras de cada trecho entre recargas, todas com o mesmo peso, a que não bate com as outras pesando menos (regressão robusta) e partindo do gasto do cadastro; sem nenhuma nesses dias, as de antes; sem nenhuma, vazio' => 'MEDIDO("uso") ou MEDIDO("repouso") : la consommation mesurée par les lectures, en % par jour (d\'usage ou hors du poignet) : les deux sortent ensemble des mesures des derniers jours de la Configuration (chaque intervalle entre deux lectures : la baisse = jours d\'usage × consommation en usage + jours hors × consommation hors), dans le calcul fait sur les lectures de chaque tronçon entre recharges, toutes avec le même poids, celle qui ne correspond pas aux autres pesant moins (régression robuste) et en partant de la consommation de la fiche ; sans aucune sur ces jours, celles d\'avant ; sans aucune, vide',
        'CONFIG("chave"): um número da Configuração (ex.: CONFIG("sol_limiar"), o limite do solar); vazio se não for número' => 'CONFIG("clé") : un nombre de la Configuration (ex. : CONFIG("sol_limiar"), la limite du solaire) ; vide si ce n\'est pas un nombre',
        'dias desde uma data' => 'jours depuis une date',
        'dias até uma data (negativo: já passou)' => 'jours jusqu\'à une date (négatif : déjà passée)',
        'SOMA_MESES(data; meses): a data somada de meses, pelo calendário' => 'SOMA_MESES(date ; mois) : la date plus des mois, selon le calendrier',
        'ULTIMO_VALOR("tipo"): o valor do último lançamento daquele tipo' => 'ULTIMO_VALOR("type") : la valeur de la dernière saisie de ce type',
        'ULTIMA_DATA("tipo"): quando foi o último (numa sessão, o fim; aberta: agora)' => 'ULTIMA_DATA("type") : quand a eu lieu la dernière (dans une session, la fin ; ouverte : maintenant)',
        'DIAS_DESDE_ULTIMO("tipo"): dias desde o último (sessão aberta: 0)' => 'DIAS_DESDE_ULTIMO("type") : jours depuis la dernière (session ouverte : 0)',
        'HORAS("sessão"; dias): horas naquela sessão nos últimos N dias' => 'HORAS("session" ; jours) : heures dans cette session au cours des N derniers jours',
        'HORAS_APOS("sessão"; "tipo"): horas naquela sessão desde o último lançamento do outro tipo' => 'HORAS_APOS("session" ; "type") : heures dans cette session depuis la dernière saisie de l\'autre type',
        'CONTAR("tipo"; dias): quantos lançamentos (ou dias com sessão) nos últimos N dias' => 'CONTAR("type" ; jours) : combien de saisies (ou de jours avec session) au cours des N derniers jours',
        'EM_SESSAO("sessão"): 1 se a sessão está aberta agora' => 'EM_SESSAO("session") : 1 si la session est ouverte maintenant',
        'ACUMULA(início; máximo; perda por hora; "tipo"; efeito; ...): um saldo que percorre o histórico: numa sessão da lista, ganha o efeito por hora (negativo: perde); num lançamento instantâneo da lista, passa a valer o efeito; num lançamento com valor (uma leitura), passa a valer a leitura vezes o efeito (1: a própria leitura); no resto, perde a perda por hora; sempre entre 0 e o máximo' => 'ACUMULA(début ; maximum ; perte par heure ; "type" ; effet ; ...) : un solde qui parcourt l\'historique : dans une session de la liste, il gagne l\'effet par heure (négatif : perd) ; sur une saisie instantanée de la liste, il prend la valeur de l\'effet ; sur une saisie avec valeur (une lecture), il prend la lecture fois l\'effet (1 : la lecture elle-même) ; sinon, il perd la perte par heure ; toujours entre 0 et le maximum',
        'MEDIA_COLECAO("variável"): a média daquela variável nos relógios disponíveis' => 'MEDIA_COLECAO("variable") : la moyenne de cette variable sur les montres disponibles',
        'LEITURAS("uso" ou "repouso"; dias): quantas medições com as duas leituras marcadas assim há nos últimos N dias (sem dias, ou 0: a janela da Configuração)' => 'LEITURAS("uso" ou "repouso" ; jours) : combien de mesures dont les deux relevés sont marqués ainsi il y a dans les N derniers jours (sans jours, ou 0 : la fenêtre de la Configuration)',
        'QUEDA("uso" ou "repouso"; dias): a soma das quedas dessas medições, em pontos de carga' => 'QUEDA("uso" ou "repouso" ; jours) : la somme des baisses de ces mesures, en points de charge',
        'DIAS_MEDIDOS("uso" ou "repouso"; dias): a soma do tempo delas, em dias de uso (em repouso: dias guardado)' => 'DIAS_MEDIDOS("uso" ou "repouso" ; jours) : la somme de leur durée, en jours d\'usage (au repos : jours rangé)',
        'MEDIA_TAXA("uso" ou "repouso"; dias): a média simples das taxas de cada uma (% por dia); vazio sem nenhuma' => 'MEDIA_TAXA("uso" ou "repouso" ; jours) : la moyenne simple des taux de chacune (% par jour) ; vide sans aucune',
        'MEDIANA_TAXA("uso" ou "repouso"; dias): a mediana das taxas (resiste a uma medição errada); vazio sem nenhuma' => 'MEDIANA_TAXA("uso" ou "repouso" ; jours) : la médiane des taux (résiste à une mesure fausse) ; vide sans aucune',
        'ULTIMA_TAXA("uso" ou "repouso"): a taxa da medição mais recente assim (% por dia); vazio sem nenhuma' => 'ULTIMA_TAXA("uso" ou "repouso") : le taux de la mesure la plus récente de ce type (% par jour) ; vide sans aucune',
        'texto aberto na posição {1}: falta fechar as aspas' => 'texte ouvert à la position {1} : il manque le guillemet fermant',
        'caractere inesperado "{1}" na posição {2}' => 'caractère inattendu « {1} » à la position {2}',
        'a fórmula está vazia' => 'la formule est vide',
        '"{1}" sobrando na posição {2}' => '« {1} » en trop à la position {2}',
        'na posição {1}' => 'à la position {1}',
        'no fim' => 'à la fin',
        'falta fechar o parêntese {1}' => 'la parenthèse {1} n\'est pas fermée',
        'função desconhecida {1} {2}' => 'fonction inconnue {1} {2}',
        'falta fechar os argumentos de {1} {2} (os argumentos se separam com ponto e vírgula)' => 'les arguments de {1} {2} ne sont pas fermés (les arguments se séparent par des points-virgules)',
        '{1} recebe {2} argumento(s), e recebeu {3} {4}' => '{1} reçoit {2} argument(s), et en a reçu {3} {4}',
        'pelo menos {1}' => 'au moins {1}',
        'de {1} a {2}' => 'de {1} à {2}',
        'a fórmula acabou antes do esperado' => 'la formule s\'est terminée plus tôt que prévu',
        '"{1}" fora do lugar {2}' => '« {1} » hors de sa place {2}',
        'Pelas horas registradas (o motor original)' => 'Par les heures enregistrées (le moteur d\'origine)',
        'Pelas horas registradas, com leituras e cadastro (robusto)' => 'Par les heures enregistrées, avec relevés et fiche (robuste)',
        'Pela marcação: duas taxas separadas' => 'Par le marquage : deux taux séparés',
        'Só o cadastro' => 'La fiche seulement',
        'Pelas fórmulas do cadastro' => 'Par les formules de la fiche',
