        'Sorteio pela nota, {1}: nota {2}, {3}% de chance ({4}).' => 'Tirage selon la note, {1} : note {2}, {3} % de chance ({4}).',
        ' Fica o bloco {1} inteiro.' => ' Elle reste tout le bloc {1}.',
        'Decida por mim: o sistema escolhe pela nota dos critérios (os que você cadastra em Critérios: dias sem uso, equilíbrio, preferência, carga...), recalculada no começo de cada dia, com os dias anteriores do período (os que você escolheu e os que ele decidiu) já contados como uso; a garantia de rodízio vem na frente (quem passou do limite de dias sem uso, o mais tempo parado primeiro); e o relógio de ontem e o de amanhã ficam de fora, se houver outro. Empate: o cadastrado primeiro. A decisão é feita ao gravar e fica gravada no plano, com o motivo; hoje, com "Decida por mim", continua o relógio que já está no plano.' => 'Décider pour moi : le système choisit selon la note des critères (ceux que vous définissez dans Critères : jours sans usage, équilibre, préférence, charge...), recalculée au début de chaque jour, avec les jours précédents de la période (ceux que vous avez choisis et ceux qu\'il a décidés) déjà comptés comme usage ; la garantie de rotation passe en premier (celle qui a dépassé la limite de jours sans usage, la plus longtemps inutilisée d\'abord) ; et la montre d\'hier et celle de demain sont écartées, s\'il y en a une autre. Égalité : celle enregistrée en premier. La décision est prise à l\'enregistrement et reste enregistrée dans le plan, avec la raison ; aujourd\'hui, avec « Décider pour moi », la montre déjà dans le plan reste.',
