        'Não consegui abrir o banco antigo {1} com o usuário {2}: {3}. O usuário precisa poder ler o banco antigo. No mysql, como root: GRANT SELECT ON {4}.* TO \'{5}\'@\'localhost\';{6}' => 'Impossible d\'ouvrir l\'ancienne base {1} avec l\'utilisateur {2} : {3}. L\'utilisateur doit pouvoir lire l\'ancienne base. Dans mysql, en root : GRANT SELECT ON {4}.* TO \'{5}\'@\'localhost\';{6}',
