    'ajuda' => [
        'api.php devolve tudo o que está guardado na coleção do pedido, sem filtro: arvore, campos, lancamento_tipos, formulas, avisos, relogios (com os valores dos campos, o resultado de cada fórmula, os avisos, os lançamentos, a previsão e a linha do tempo inteira com o resumo), modos, plano (inteiro), config (inteira, da coleção), eventos (com os disparos), destinos, agendas, agendas_desejadas, criterios (com a nota de cada relógio), cron (todas as execuções guardadas), usuarios (os logins; o master vê todos), migracoes e motor, e as categorias dos documentos (documento_categorias). A senha dos usuários não existe no sistema: sai o hash dela (veja senhas). Os arquivos dos documentos não vêm (só os dados de cada um, em relogios[].documentos): eles saem pelo recurso=documento. Para pegar só uma parte, ou filtrar, ordenar e paginar: veja filtros.' => 'api.php renvoie tout ce qui est stocké dans la collection de la requête, sans filtre : arvore, campos, lancamento_tipos, formulas, avisos, relogios (avec les valeurs des champs, le résultat de chaque formule, les alertes, les saisies, la prévision et toute la chronologie avec le résumé), modos, plano (entier), config (entière, de la collection), eventos (avec les déclenchements), destinos, agendas, agendas_desejadas, criterios (avec la note de chaque montre), cron (toutes les exécutions enregistrées), usuarios (les identifiants ; le master les voit tous), migracoes et motor, et les catégories de documents (documento_categorias). Le mot de passe des utilisateurs n\'existe pas dans le système : c\'est son hash qui sort (voir senhas). Les fichiers des documents ne viennent pas (seulement les données de chacun, dans relogios[].documentos) : ils sortent par recurso=documento. Pour n\'obtenir qu\'une partie, ou filtrer, trier et paginer : voir filtros.',
        'em todo pedido: o login do site (HTTP Basic: o usuário e a senha de uma conta), um token pessoal (Minha conta, Tokens de API: vale como o login do dono dele, com as coleções dele) ou o token do servidor (o API_TOKEN do config.php, com pelo menos 10 caracteres: vale como o master mais antigo), no cabeçalho X-Api-Token ou no parâmetro token. Sem nada: 401. A conta bloqueada pelo master, ou a de demonstração que venceu, não entra. Ex.: curl -u lucas:senha http://servidor/relojoeiro/api.php?recurso=hoje; curl -H "X-Api-Token: segredo" http://servidor/relojoeiro/api.php?recurso=hoje' => 'dans chaque requête : l\'identifiant du site (HTTP Basic : l\'utilisateur et le mot de passe d\'un compte), un jeton personnel (Mon compte, Jetons d\'API : il vaut comme l\'identifiant de son propriétaire, avec ses collections) ou le jeton du serveur (l\'API_TOKEN du config.php, d\'au moins 10 caractères : il vaut comme le master le plus ancien), dans l\'en-tête X-Api-Token ou le paramètre token. Sans rien : 401. Le compte bloqué par le master, ou le compte de démonstration expiré, n\'entre pas. Ex. : curl -u lucas:senha http://servidor/relojoeiro/api.php?recurso=hoje; curl -H "X-Api-Token: segredo" http://servidor/relojoeiro/api.php?recurso=hoje',
        'cada pedido vale numa coleção: a do parâmetro colecao=<id>, senão a do cookie colecao (o seletor do menu das páginas), senão a primeira que o usuário vê (a dele). Uma coleção que ele não vê: 404, como se não existisse. Tudo o que se lê e se grava (os relógios, o plano, a configuração, os destinos, as agendas...) é dessa coleção; a árvore de grupos e o cadastro dela (campos, tipos, fórmulas, avisos, categorias, critérios dos grupos) são da árvore que a coleção usa, e valem em todas as coleções que usam a mesma árvore. Sem coleção nenhuma (a conta que só pediu acesso), só a conta responde (409 com sem_colecao nos outros recursos). O master vê todas as coleções; com como=<login> (ou o cookie como, da faixa Vendo como das páginas), ele vê e grava como aquele usuário' => 'chaque requête vaut pour une collection : celle du paramètre colecao=<id>, sinon celle du cookie colecao (le sélecteur du menu des pages), sinon la première que l\'utilisateur voit (la sienne). Une collection qu\'il ne voit pas : 404, comme si elle n\'existait pas. Tout ce qui se lit et s\'enregistre (les montres, le plan, la configuration, les destinations, les agendas...) appartient à cette collection ; l\'arbre de groupes et ses définitions (champs, types, formules, alertes, catégories, critères des groupes) appartiennent à l\'arbre que la collection utilise, et valent dans toutes les collections qui utilisent le même arbre. Sans aucune collection (le compte qui a seulement demandé un accès), seul le compte répond (409 avec sem_colecao dans les autres ressources). Le master voit toutes les collections ; avec como=<login> (ou le cookie como, de la bande Vue en tant que des pages), il voit et enregistre comme cet utilisateur',
        'toda exclusão é em dois passos: sem confirmar=1, a API não apaga nada e responde 409 com confirmar: true e impacto (o que sai junto, seguindo o banco em cascata, no banco inteiro: itens, desfeitos, colecoes, relogios, arquivos, bytes e o texto pronto); com confirmar=1, apaga. Os scripts mandam confirmar=1 de uma vez. Os arquivos dos documentos saem do disco na hora (os do relógio, da coleção, da árvore ou da conta que saiu)' => 'toute suppression se fait en deux temps : sans confirmar=1, l\'API n\'efface rien et répond 409 avec confirmar: true et impacto (ce qui part avec, en suivant la cascade de la base, dans toute la base : itens, desfeitos, colecoes, relogios, arquivos, bytes et le texte prêt) ; avec confirmar=1, elle efface. Les scripts envoient confirmar=1 directement. Les fichiers des documents quittent le disque aussitôt (ceux de la montre, de la collection, de l\'arbre ou du compte supprimé)',
        'JSON (padrão) ou XML: formato=xml, ou o cabeçalho Accept com xml. Ex.: http://servidor/relojoeiro/api.php?recurso=plano&formato=xml' => 'JSON (par défaut) ou XML : formato=xml, ou l\'en-tête Accept avec xml. Ex. : http://servidor/relojoeiro/api.php?recurso=plano&formato=xml',
        'tudo o que está guardado, sem filtro (os relógios com os campos, as fórmulas, os avisos, os lançamentos, a previsão e a linha do tempo; modos, plano, configuração, eventos, agenda e o motor)' => 'tout ce qui est enregistré, sans filtre (les montres avec les champs, les formules, les alertes, les saisies, la prévision et la chronologie ; modes, plan, configuration, événements, agenda et le moteur)',
        'nao: sem as fotos em base64 (a resposta fica bem menor)' => 'nao : sans les photos en base64 (la réponse est bien plus petite)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?foto=nao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?foto=nao"',
        'tudo o que a página Hoje mostra: o dia e o relógio dele, os avisos de hoje (com o lançamento que resolve cada um), os próximos 62 dias do plano, os Próximos dias da página (uma página: proximos), os modos com os blocos, os grupos, a tabela dos relógios (os da coleção: na coleção e emprestados), os que estão fora dela (desejados, vendidos, arquivados: fora_da_colecao) e os totais da coleção (quantos, disponíveis, em uso, o valor pago, quantos desejados e quantos fora)' => 'tout ce que montre la page Aujourd\'hui : le jour et sa montre, les alertes d\'aujourd\'hui (avec la saisie qui résout chacune), les 62 prochains jours du plan, les Prochains jours de la page (une page : proximos), les modes avec les blocs, les groupes, le tableau des montres (celles de la collection : dans la collection et prêtées), celles qui en sont hors (désirées, vendues, archivées : fora_da_colecao) et les totaux de la collection (combien, disponibles, en usage, le montant payé, combien de désirées et combien hors collection)',
        'a página dos Próximos dias (padrão 1)' => 'la page des Prochains jours (1 par défaut)',
        'quantos dias por página nos Próximos dias (sem ele: o Mostrar até da Configuração, padrão 7)' => 'combien de jours par page dans les Prochains jours (sans lui : l\'Afficher jusqu\'à de la Configuration, 7 par défaut)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hoje"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hoje"',
        'tudo o que o painel de um relógio mostra: agora, carga e de onde vem, situação, nota, quando entra no rodízio, compra, próximas manutenções, previsão, o gasto da bateria, quantos documentos o relógio tem em cada categoria, os tipos de lançamento dele (com a sessão aberta), as últimas leituras, as marcações dos últimos 14 dias, o resumo do histórico, a situação na coleção (com o desejo, no desejado) e o cadastro; sem relogio, só o cadastro de um relógio novo; relógio que não existe: 404' => 'tout ce que montre le panneau d\'une montre : maintenant, charge et d\'où elle vient, statut, note, quand elle entre dans la rotation, achat, prochains entretiens, prévision, la consommation de la batterie, combien de documents la montre a dans chaque catégorie, ses types de saisie (avec la session ouverte), les dernières lectures, les marques des 14 derniers jours, le résumé de l\'historique, le statut dans la collection (avec l\'envie, parmi les désirées) et la fiche ; sans relogio, seulement la fiche d\'une montre neuve ; montre qui n\'existe pas : 404',
        'o id do relógio (vazio: o cadastro de um relógio novo)' => 'l\'id de la montre (vide : la fiche d\'une montre neuve)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ficha&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ficha&relogio=10"',
        'tudo o que a página Configuração mostra (da coleção do pedido): os valores, o Mostrar até de cada lista (mostrar_ate), de onde vêm os números dos sorteios (aleatorio: RANDOM.ORG, senão ANU QRNG, senão o gerador seguro do PHP; o último lote), o endereço do sistema (sistema: só o master muda), os eventos personalizados, o resumo dos destinos e das agendas (que têm as páginas deles: recurso=destinos e recurso=agendas) e a situação do cron (nunca rodou, parado ou rodando)' => 'tout ce que la page Configuration affiche (de la collection de la requête) : les valeurs, le Afficher jusqu\'à de chaque liste (mostrar_ate), d\'où viennent les nombres des tirages (aleatorio : RANDOM.ORG, sinon ANU QRNG, sinon le générateur sûr de PHP ; le dernier lot), l\'adresse du système (sistema : seul le master la change), les événements personnalisés, le résumé des destinations et des agendas (qui ont leurs pages : recurso=destinos et recurso=agendas) et l\'état du cron (jamais exécuté, arrêté ou en marche)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=config"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=config"',
        'as execuções do cron, com o resumo do período (total, com atividade, com erro, a mais lenta) e páginas; sem atividade elas ficam 7 dias, com atividade ou erro, 1 ano' => 'les exécutions du cron, avec le résumé de la période (total, avec activité, avec erreur, la plus lente) et les pages ; sans activité elles sont conservées 7 jours, avec activité ou erreur, 1 an',
        'data (AAAA-MM-DD) ou data e hora (AAAA-MM-DD HH:MM[:SS], espaço ou T); cron_de e cron_ate também valem' => 'date (AAAA-MM-JJ) ou date et heure (AAAA-MM-JJ HH:MM[:SS], espace ou T) ; cron_de et cron_ate valent aussi',
        'atividade (padrão), erro, nada ou todas; cron_situacao também vale' => 'atividade (par défaut), erro, nada ou todas ; cron_situacao vaut aussi',
        'texto no registro; cron_busca também vale' => 'texte dans l\'enregistrement ; cron_busca vaut aussi',
        'por página (padrão 100, máximo 1000)' => 'par page (100 par défaut, 1000 au maximum)',
        'a página (padrão 1)' => 'la page (1 par défaut)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cron&situacao=erro&de=2026-09-01&busca=agenda"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cron&situacao=erro&de=2026-09-01&busca=agenda"',
        'os grupos em ordem de árvore (com o caminho, os de cima, quantos subgrupos, os relógios direto neles e quantos parâmetros de critérios próprios) e o grupo de cada relógio' => 'les groupes en ordre d\'arbre (avec le chemin, ceux du dessus, combien de sous-groupes, les montres directement dedans et combien de paramètres de critères propres) et le groupe de chaque montre',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=arvore"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=arvore"',
        'tudo o que as páginas Cadastros, Avisos e Modos de rodízio mostram: campos, tipos de lançamento (com quantos lançamentos cada um tem), fórmulas e avisos (todas as versões), modos com os blocos, grupos, relógios e as funções do motor' => 'tout ce que montrent les pages Définitions, Alertes et Modes de rotation : champs, types de saisie (avec combien de saisies chacun a), formules et alertes (toutes les versions), modes avec les blocs, groupes, montres et les fonctions du moteur',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cadastros"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cadastros"',
        'calcula uma fórmula sem gravar, em cada relógio (ou nos pedidos), com as partes da conta (o testar da página Cadastros); fórmula com erro de escrita: 400 com os erros' => 'calcule une formule sans l\'enregistrer, sur chaque montre (ou sur celles demandées), avec les parties du calcul (le tester de la page Définitions) ; formule avec une erreur d\'écriture : 400 avec les erreurs',
        'a fórmula' => 'la formule',
        'um id ou vários separados por vírgula (vazio: todos)' => 'un id ou plusieurs séparés par une virgule (vide : tous)',
        'curl -u lucas:senha -G "http://servidor/relojoeiro/api.php" --data-urlencode recurso=calcular --data-urlencode "expressao=energia * 2" -d relogio=10,12' => 'curl -u lucas:senha -G "http://servidor/relojoeiro/api.php" --data-urlencode recurso=calcular --data-urlencode "expressao=energia * 2" -d relogio=10,12',
        'os avisos de todos os relógios da coleção agora (os desejados, vendidos e arquivados não têm aviso), do mais urgente ao mais distante, com a data prevista, quanto falta, o estado (atrasado, em_breve, ok) e o texto' => 'les alertes de toutes les montres de la collection maintenant (les désirées, vendues et archivées n\'ont pas d\'alerte), de la plus urgente à la plus lointaine, avec la date prévue, combien il reste, l\'état (atrasado, em_breve, ok) et le texte',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=avisos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=avisos"',
        'os conjuntos de critérios por lugar (parâmetros, subparâmetros, faixas), as variáveis que podem medir (com o limite), os lugares (quem tem critérios próprios e de quem herda), os modos e a nota de cada relógio com a conta' => 'les ensembles de critères par niveau (paramètres, sous-paramètres, tranches), les variables que l\'on peut mesurer (avec la limite), les niveaux (qui a ses propres critères et de qui il hérite), les modes et la note de chaque montre avec le calcul',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=criterios"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=criterios"',
        'a linha do tempo: trechos contínuos por estado (rodizio, pulso fora do rodízio, cada tipo de sessão, repouso) e as marcações, com o resumo do tempo em cada estado e os lançamentos crus do período' => 'la chronologie : périodes continues par état (rodizio, poignet hors de la rotation, chaque type de session, repouso) et les marques, avec le résumé du temps dans chaque état et les saisies brutes de la période',
        'um id ou vários (relogio_id também vale; vazio: todos)' => 'un id ou plusieurs (relogio_id vaut aussi ; vide : tous)',
        'data ou data e hora; entra a linha que cruza o período' => 'date ou date et heure ; la ligne qui chevauche la période est incluse',
        'rodizio, pulso, winder, sol, repouso, marca... (um ou vários; linha_estado também vale)' => 'rodizio, pulso, winder, sol, repouso, marca... (un ou plusieurs ; linha_estado vaut aussi)',
        'a página' => 'la page',
        'desc (padrão, mais recente primeiro) ou asc; dois no mesmo instante saem pela ordem em que foram lançados (o id)' => 'desc (par défaut, la plus récente d\'abord) ou asc ; deux au même instant sortent dans l\'ordre où elles ont été saisies (l\'id)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=historico&relogio=3&de=2026-09-01&estado=marca"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=historico&relogio=3&de=2026-09-01&estado=marca"',
        'a previsão da energia dos relógios com leitura (o smartwatch): quanto dura usando, quando chega ao limite parado, com quanto entra no próximo rodízio e quanto precisa, e a confiança da conta' => 'la prévision de l\'énergie des montres avec lecture (la smartwatch) : combien de temps elle dure en usage, quand elle atteint la limite à l\'arrêt, avec combien elle entre dans la prochaine rotation et de combien elle a besoin, et la confiance du calcul',
        'um id ou vários (vazio: todos)' => 'un id ou plusieurs (vide : tous)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=previsao&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=previsao&relogio=10"',
        'o plano gravado (a escala de dois anos sai inteira), o dia a dia da página Plano uma página por vez (dia_a_dia, com os dias livres no meio), com o modo ativo, o fim da escala e o último dia gravado; cada dia com o relógio, o bloco, a origem (sorteio ou manual) e o lembrete; os dias livres do período (sem relógio e sem sorteio, para escolher à mão); e o resumo do período (de hoje em diante), como a página Plano mostra: quantos dias cada relógio tem, a porcentagem, o próximo dia, quantos à mão e os relógios sem nenhum dia' => 'le plan enregistré (le planning de deux ans sort en entier), le jour par jour de la page Plan une page à la fois (dia_a_dia, avec les jours libres au milieu), avec le mode actif, la fin du planning et le dernier jour enregistré ; chaque jour avec la montre, le bloc, l\'origine (tirage ou manual) et le rappel ; les jours libres de la période (sans montre et sans tirage, pour choisir à la main) ; et le résumé de la période (à partir d\'aujourd\'hui), comme le montre la page Plan : combien de jours chaque montre a, le pourcentage, le prochain jour, combien à la main et les montres sans aucun jour',
        'datas AAAA-MM-DD (vazio: o plano inteiro)' => 'dates AAAA-MM-JJ (vide : le plan entier)',
        'a página do dia_a_dia (padrão 1)' => 'la page du dia_a_dia (1 par défaut)',
        'quantos dias por página no dia_a_dia (sem ele: o Mostrar até da Configuração, padrão 31)' => 'combien de jours par page dans le dia_a_dia (sans lui : l\'Afficher jusqu\'à de la Configuration, 31 par défaut)',
        'o id: o dia_a_dia só com os dias desse relógio' => 'l\'id : le dia_a_dia seulement avec les jours de cette montre',
        'N: os próximos N dias, de hoje em diante (no lugar de de e ate); todos: de hoje até o fim do plano' => 'N : les N prochains jours, à partir d\'aujourd\'hui (à la place de de et ate) ; todos : d\'aujourd\'hui jusqu\'à la fin du plan',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=plano&de=2026-10-01&ate=2026-10-31"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=plano&de=2026-10-01&ate=2026-10-31"',
        'a lista de desejos (a página Desejos): os relógios desejados, a prioridade mais alta primeiro, cada um com a marca, a referência, o preço-alvo, a prioridade e o link; a soma dos preços-alvo; e os que estão fora da coleção (emprestados, vendidos, arquivados). Pôr na coleção (o Comprei): recurso=relogio, acao=salvar, posse=colecao' => 'la liste d\'envies (la page Envies) : les montres désirées, la priorité la plus haute d\'abord, chacune avec la marque, la référence, le prix cible, la priorité et le lien ; la somme des prix cibles ; et celles qui sont hors de la collection (prêtées, vendues, archivées). Mettre dans la collection (Achetée) : recurso=relogio, acao=salvar, posse=colecao',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=desejos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=desejos"',
        'o uso da coleção num período (a página Estatísticas): o resumo (dias com relógio, horas no pulso, relógios usados, o mais e o menos usado, o valor da coleção, o custo por uso médio), cada relógio (dias de uso, horas, a parte de cada um, o custo por uso, dias sem uso, a tendência), o uso por dia da semana e por mês, e a distribuição da coleção (por grupo, marca, ano da compra, situação e cada campo de lista); as porcentagens e as alturas das barras (0 a 100, comparadas com a maior) vêm prontas. Contam as sessões no pulso (partidas na meia-noite) e as marcações antigas no pulso (o dia, sem horas)' => 'l\'usage de la collection sur une période (la page Statistiques) : le résumé (jours avec montre, heures au poignet, montres utilisées, la plus et la moins utilisée, le montant de la collection, le coût par port moyen), chaque montre (jours d\'usage, heures, la part de chacune, le coût par port, jours sans usage, la tendance), l\'usage par jour de la semaine et par mois, et la répartition de la collection (par groupe, marque, année d\'achat, statut et chaque champ de liste) ; les pourcentages et les hauteurs des barres (0 à 100, comparées à la plus grande) sont prêts. Comptent les sessions au poignet (coupées à minuit) et les anciennes marques au poignet (le jour, sans les heures)',
        'datas AAAA-MM-DD (padrão: os últimos 90 dias, até hoje; ate depois de hoje vira hoje; até 3661 dias); de=tudo: desde o primeiro uso; inválidas: 400 com erro' => 'dates AAAA-MM-JJ (par défaut : les 90 derniers jours, jusqu\'à aujourd\'hui ; ate après aujourd\'hui devient aujourd\'hui ; jusqu\'à 3661 jours) ; de=tudo : depuis la première utilisation ; invalides : 400 avec erreur',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=estatisticas&de=2026-01-01&ate=2026-06-30"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=estatisticas&de=2026-01-01&ate=2026-06-30"',
        'a hora do servidor para acertar os relógios (a página Hora certa): a local com o fuso, a UTC (Zulu), a letra militar do fuso e o grupo data-hora, o calendário (dia do ano, semana ISO, trimestre, dia juliano) e a fase da lua (pelo ciclo médio, aproximada), e como acertar; agora_ms, em milissegundos, para a tela acertar o relógio dela. Não usa o banco' => 'l\'heure du serveur pour régler les montres (la page Heure exacte) : l\'heure locale avec le fuseau, l\'UTC (Zulu), la lettre militaire du fuseau et le groupe date-heure, le calendrier (jour de l\'année, semaine ISO, trimestre, jour julien) et la phase de la lune (par le cycle moyen, approximative), et comment régler ; agora_ms, en millisecondes, pour que l\'écran règle son horloge. N\'utilise pas la base de données',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hora_certa"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hora_certa"',
        'os acessórios (a página Acessórios): pulseiras, caixas, estojos, ferramentas, carregadores, peças e outros, cada um com o tipo, o relógio de que ele é (ou solto) e a observação, pelo tipo e pelo nome; os tipos, quantos de cada tipo, quantos soltos e os relógios (o menu). Gravar: escrita acessorios' => 'les accessoires (la page Accessoires) : bracelets, boîtes, étuis, outils, chargeurs, pièces et autres, chacun avec le type, la montre à laquelle il appartient (ou libre) et la remarque, par type et par nom ; les types, combien de chaque type, combien de libres et les montres (le menu). Enregistrer : écriture acessorios',
        'o id: só os acessórios desse relógio; 0: só os soltos (sem ele: todos)' => 'l\'id : seulement les accessoires de cette montre ; 0 : seulement les libres (sans lui : tous)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=acessorios&relogio=3"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=acessorios&relogio=3"',
        'o passaporte de um relógio (a página Passaporte, para imprimir ou guardar em PDF), tudo já em texto: quem ele é, o cadastro preenchido (cada valor formatado pelo tipo: data, sim/não, número com a unidade, R$), a compra, o uso (a primeira e a última vez no pulso, as horas no pulso, os dias de uso e o custo por uso), as manutenções (cada tipo de marcação, quantas vezes e a última; as revisões e trocas de pilha), os acessórios, os documentos e os próximos avisos; relógio que não existe: 404' => 'le passeport d\'une montre (la page Passeport, pour imprimer ou garder en PDF), tout déjà en texte : qui elle est, la fiche remplie (chaque valeur formatée selon le type : date, oui/non, nombre avec l\'unité, R$), l\'achat, l\'usage (la première et la dernière fois au poignet, les heures au poignet, les jours d\'usage et le coût par port), les entretiens (chaque type de marque, combien de fois et la dernière ; les révisions et changements de pile), les accessoires, les documents et les prochaines alertes ; montre qui n\'existe pas : 404',
        'o id do relógio (obrigatório)' => 'l\'id de la montre (obligatoire)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=passaporte&relogio=3"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=passaporte&relogio=3"',
        'a coleção em fotos, por grupo (a página Galeria, para ver e imprimir): cada relógio com a foto, a marca, a referência, o ano e o valor da compra e os dias de uso, e os totais' => 'la collection en photos, par groupe (la page Galerie, pour voir et imprimer) : chaque montre avec la photo, la marque, la référence, l\'année et le montant de l\'achat et les jours d\'usage, et les totaux',
        'todos: também os desejados, vendidos e arquivados (sem ele: os da coleção, na coleção e emprestados)' => 'todos : aussi les désirées, vendues et archivées (sans lui : celles de la collection, dans la collection et prêtées)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=galeria&posse=todos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=galeria&posse=todos"',
        'os textos das telas no idioma do pedido (o dicionário da função t() do api.js: o texto em português => a tradução), o idioma, o locale das datas e dos números, o padrão da instalação e os idiomas do sistema. Responde sem login (é só o texto da interface). O idioma de qualquer pedido: lingua=, senão o cookie lingua (o seletor do menu), senão o padrão da instalação (config.idioma), senão o Accept-Language, senão português; toda resposta da API sai nele' => 'les textes des écrans dans la langue de la requête (le dictionnaire de la fonction t() d\'api.js : le texte en portugais => la traduction), la langue, la locale des dates et des nombres, le défaut de l\'installation et les langues du système. Répond sans connexion (ce n\'est que le texte de l\'interface). La langue de toute requête : lingua=, sinon le cookie lingua (le sélecteur du menu), sinon le défaut de l\'installation (config.idioma), sinon l\'Accept-Language, sinon le portugais ; toute réponse de l\'API sort dans cette langue',
        'js: um script (window.TEXTOS_API = {...}), que as páginas carregam antes dos outros' => 'js : un script (window.TEXTOS_API = {...}), que les pages chargent avant les autres',
        'curl "http://servidor/relojoeiro/api.php?recurso=textos&lingua=en"' => 'curl "http://servidor/relojoeiro/api.php?recurso=textos&lingua=en"',
        'os Próximos dias da página Hoje, uma página (de hoje até o fim do plano, com os dias livres no meio): a troca de página da tela lê só eles' => 'les Prochains jours de la page Aujourd\'hui, une page (d\'aujourd\'hui jusqu\'à la fin du plan, avec les jours libres au milieu) : le changement de page de l\'écran ne lit qu\'eux',
        'quantos dias por página (sem ele: o Mostrar até da Configuração, padrão 7)' => 'combien de jours par page (sans lui : l\'Afficher jusqu\'à de la Configuration, 7 par défaut)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=proximos&pagina=2"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=proximos&pagina=2"',
        'o Rodízio manual (o quadro Modo de rodízio da página Hoje): os dias de um período, de 7 em 7, cada um com o que o plano tem agora e a escolha de partida do seletor (o relógio escolhido à mão, livre ou auto: Decida por mim), os relógios disponíveis e o critério do Decida por mim. Gravar: recurso=rodizio, acao=manual' => 'la Rotation manuelle (le cadre Mode de rotation de la page Aujourd\'hui) : les jours d\'une période, par 7, chacun avec ce que le plan a maintenant et le choix de départ du sélecteur (la montre choisie à la main, libre ou auto : Décider pour moi), les montres disponibles et le critère de Décider pour moi. Enregistrer : recurso=rodizio, acao=manual',
        'datas AAAA-MM-DD, de hoje em diante, até 2 anos (obrigatórias; inválidas: 400 com erro)' => 'dates AAAA-MM-JJ, à partir d\'aujourd\'hui, jusqu\'à 2 ans (obligatoires ; invalides : 400 avec erreur)',
        '1, 2...: a página de 7 dias (padrão 1)' => '1, 2... : la page de 7 jours (1 par défaut)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=rodizio_manual&de=2026-12-20&ate=2027-01-05&pagina=2"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=rodizio_manual&de=2026-12-20&ate=2027-01-05&pagina=2"',
        'os eventos personalizados da coleção, com quando disparam, os destinos e as agendas que recebem cada um, as 10 próximas ocorrências e os disparos' => 'les événements personnalisés de la collection, avec quand ils se déclenchent, les destinations et les agendas qui reçoivent chacun, les 10 prochaines occurrences et les déclenchements',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=eventos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=eventos"',
        'os destinos das mensagens da coleção (a página Destinos): cada um (webhook HTTP, e-mail ou Web Push) com o nome, se está ligado, a mensagem padrão, o idioma, o que recebe (cada tipo de aviso e cada evento, com o modelo próprio), o que é do tipo dele (o webhook: método, endereço, formato, campos, corpo JSON e os cabeçalhos, sem o valor; o e-mail: para quem; o Web Push: o usuário e quantos aparelhos dele) e a prévia de hoje (o que sairia de manhã e à noite); os tipos, os avisos, as âncoras, os idiomas, a mensagem padrão do modelo, se o e-mail e o Web Push estão configurados no servidor e quem vê a coleção (para o Web Push)' => 'les destinations des messages de la collection (la page Destinations) : chacune (webhook HTTP, e-mail ou Web Push) avec le nom, si elle est active, le message par défaut, la langue, ce qu\'elle reçoit (chaque type d\'alerte et chaque événement, avec son propre modèle), ce qui est propre à son type (le webhook : méthode, adresse, format, champs, corps JSON et les en-têtes, sans la valeur ; l\'e-mail : à qui ; le Web Push : l\'utilisateur et combien de ses appareils) et l\'aperçu du jour (ce qui sortirait le matin et le soir) ; les types, les alertes, les ancres, les langues, le message par défaut du modèle, si l\'e-mail et le Web Push sont configurés sur le serveur et qui voit la collection (pour le Web Push)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=destinos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=destinos"',
        'as agendas da coleção (a página Agendas): cada uma (Google Agenda, CalDAV, Outlook ou link ICS) com o nome, se está ativa, a janela em dias, o modelo do evento, o idioma, o que recebe, o que é do tipo dela (sem os segredos: só se estão preenchidos; o link ICS sai inteiro), quantos eventos o sistema criou nela e a prévia (os primeiros eventos que têm de estar nela agora); os tipos, os avisos, as âncoras, os idiomas, o padrão do modelo e se o Outlook está configurado no servidor (com o endereço de retorno para registrar o aplicativo na Microsoft)' => 'les agendas de la collection (la page Agendas) : chacune (Google Agenda, CalDAV, Outlook ou lien ICS) avec le nom, si elle est active, la fenêtre en jours, le modèle de l\'événement, la langue, ce qu\'elle reçoit, ce qui est propre à son type (sans les secrets : seulement s\'ils sont remplis ; le lien ICS sort entier), combien d\'événements le système y a créés et l\'aperçu (les premiers événements qui doivent y être maintenant) ; les types, les alertes, les ancres, les langues, le modèle par défaut et si Outlook est configuré sur le serveur (avec l\'adresse de retour pour enregistrer l\'application chez Microsoft)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=agendas"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=agendas"',
        'o calendário de uma agenda do tipo link ICS (text/calendar, não é JSON), para assinar em qualquer app de agenda: responde sem login, pela chave secreta do link (quem tem o link vê os eventos; Gerar outro link, na página Agendas, desliga o antigo); chave desconhecida: 404' => 'le calendrier d\'une agenda de type lien ICS (text/calendar, ce n\'est pas du JSON), à abonner dans n\'importe quelle application d\'agenda : répond sans identifiant, grâce à la clé secrète du lien (qui a le lien voit les événements ; Générer un autre lien, sur la page Agendas, désactive l\'ancien) ; clé inconnue : 404',
        'a chave do link (vem pronta no link da agenda)' => 'la clé du lien (elle vient toute prête dans le lien de l\'agenda)',
        'curl "http://servidor/relojoeiro/api.php?recurso=ics&chave=Xy3..."' => 'curl "http://servidor/relojoeiro/api.php?recurso=ics&chave=Xy3..."',
        'a volta da página da Microsoft depois de Conectar ao Outlook (com code e state): guarda a conexão na agenda e leva para a página Agendas com o recado (302). É o endereço de retorno que se registra no aplicativo da Microsoft (OUTLOOK_CLIENTE_ID); não é para chamar à mão' => 'le retour de la page de Microsoft après Se connecter à Outlook (avec code et state) : enregistre la connexion dans l\'agenda et ramène à la page Agendas avec le message (302). C\'est l\'adresse de retour qu\'on enregistre dans l\'application de Microsoft (OUTLOOK_CLIENTE_ID) ; ce n\'est pas à appeler à la main',
        'o código que a Microsoft manda' => 'le code que Microsoft envoie',
        'a agenda e a assinatura dela' => 'l\'agenda et sa signature',
        '(a Microsoft chama: http://servidor/relojoeiro/api.php?recurso=outlook_retorno&code=...&state=...)' => '(Microsoft appelle : http://servidor/relojoeiro/api.php?recurso=outlook_retorno&code=...&state=...)',
        'a foto de um relógio (a imagem, não é JSON)' => 'la photo d\'une montre (l\'image, ce n\'est pas du JSON)',
        'o id do relógio' => 'l\'id de la montre',
        'curl -u lucas:senha -o foto.jpg "http://servidor/relojoeiro/api.php?recurso=foto&relogio=10"' => 'curl -u lucas:senha -o foto.jpg "http://servidor/relojoeiro/api.php?recurso=foto&relogio=10"',
        'os documentos de um relógio (ou de todos): o manual, a nota fiscal em PDF e em XML (com o resumo da NF-e), fotos, vídeos e o que mais for, com as categorias (e quantos documentos cada uma tem), os relógios (com quantos), se a pasta dos documentos está pronta, se a cópia de segurança no banco está ligada, onde está cada arquivo (na pasta, no banco) e o maior arquivo aceito' => 'les documents d\'une montre (ou de toutes) : le manuel, la facture en PDF et en XML (avec le résumé de la NF-e), photos, vidéos et le reste, avec les catégories (et combien de documents chacune a), les montres (avec combien), si le dossier des documents est prêt, si la sauvegarde dans la base de données est activée, où se trouve chaque fichier (dans le dossier, dans la base) et le plus grand fichier accepté',
        'o id do relógio (sem ele: de todos)' => 'l\'id de la montre (sans lui : de toutes)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=documentos&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=documentos&relogio=10"',
        'o arquivo de um documento (não é JSON): imagens, vídeos, áudios, PDF e texto vêm para mostrar; o resto (inclusive XML, HTML e SVG), para baixar; aceita o pedido de um pedaço (Range), que o vídeo usa para avançar; se o arquivo sumiu da pasta, ele é recriado antes a partir da cópia no banco' => 'le fichier d\'un document (ce n\'est pas du JSON) : images, vidéos, audios, PDF et texte arrivent pour être affichés ; le reste (y compris XML, HTML et SVG), pour être téléchargé ; accepte la demande d\'un fragment (Range), que la vidéo utilise pour avancer ; si le fichier a disparu du dossier, il est recréé au préalable à partir de la copie dans la base de données',
        'o id do documento' => 'l\'id du document',
        '1: sempre para baixar' => '1 : toujours pour télécharger',
        '1: a miniatura da foto (sem ela, a foto)' => '1 : la miniature de la photo (sans elle, la photo)',
        'curl -u lucas:senha -o nota.pdf "http://servidor/relojoeiro/api.php?recurso=documento&id=7"' => 'curl -u lucas:senha -o nota.pdf "http://servidor/relojoeiro/api.php?recurso=documento&id=7"',
        'para o master, o painel das contas: cada usuário com o login, o e-mail, o papel (master ou comum), o idioma, quando foi criado, o último acesso, quando vence (a conta de demonstração) e quantos dias faltam, se está bloqueado, as coleções dele (com quantos relógios), as de que é membro, de quem vê tudo, quantos pedidos e tokens tem e o hash da senha (o algoritmo e o custo, para migrar com a mesma senha: veja senhas); e as coleções todas e os dias da demonstração. Para os outros, só a própria conta (o login, quando foi criada e o hash). A senha não existe no sistema' => 'pour le master, le panneau des comptes : chaque utilisateur avec l\'identifiant, l\'e-mail, le rôle (master ou ordinaire), la langue, la date de création, le dernier accès, quand il expire (le compte de démonstration) et combien de jours restent, s\'il est bloqué, ses collections (avec combien de montres), celles dont il est membre, de qui il voit tout, combien de demandes et de jetons il a et le hash du mot de passe (l\'algorithme et le coût, pour migrer avec le même mot de passe : voir senhas) ; et toutes les collections et les jours de la démonstration. Pour les autres, seulement son propre compte (l\'identifiant, la date de création et le hash). Le mot de passe n\'existe pas dans le système',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=usuarios"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=usuarios"',
        'Minha conta: quem eu sou (o login, o e-mail, o papel, o idioma, se é demonstração e quantos dias faltam), a faixa Vendo como (o master vendo como outro usuário), as coleções que eu vejo (com o dono e o meu papel em cada uma) e a do pedido, as minhas árvores de grupos (com as coleções que usam cada uma), os meus pedidos de acesso esperando, os convites para o meu e-mail, quantas aprovações esperam por mim, os meus tokens de API (sem o token, que só aparece ao criar), os meus aparelhos lembrados (o aplicativo no celular), os meus aparelhos do Web Push e a chave pública dele, se o servidor manda e-mail, os dias da demonstração e os idiomas. Com parte=menu, só o que o menu das páginas usa (o seletor da coleção, o aviso da demonstração, as aprovações e a faixa Vendo como)' => 'Mon compte : qui je suis (le login, l\'e-mail, le rôle, la langue, si c\'est une démonstration et combien de jours restent), le bandeau Voir comme (le master voyant comme un autre utilisateur), les collections que je vois (avec le propriétaire et mon rôle dans chacune) et celle de la requête, mes arbres de groupes (avec les collections qui utilisent chacun), mes demandes d\'accès en attente, les invitations pour mon e-mail, combien d\'approbations m\'attendent, mes jetons d\'API (sans le jeton, qui n\'apparaît qu\'à la création), mes appareils mémorisés (l\'application sur le téléphone), mes appareils du Web Push et sa clé publique, si le serveur envoie des e-mails, les jours de la démonstration et les langues. Avec parte=menu, seulement ce que le menu des pages utilise (le sélecteur de collection, l\'avertissement de démonstration, les approbations et le bandeau Voir comme)',
        'menu: só o pedaço do menu das páginas' => 'menu : seulement la partie du menu des pages',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=conta"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=conta"',
        'as coleções que eu vejo (cada uma com o dono, o meu papel e a raiz da árvore dela), a coleção do pedido e as minhas árvores de grupos (com quantos grupos e as coleções que usam cada uma). Gravar: escrita colecoes' => 'les collections que je vois (chacune avec le propriétaire, mon rôle et la racine de son arbre), la collection de la requête et mes arbres de groupes (avec combien de groupes et les collections qui utilisent chacun). Enregistrer : escrita colecoes',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=colecoes"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=colecoes"',
        'a página Aprovações: os pedidos de acesso que eu aprovo (os das minhas coleções e os de tudo meu; o master, todos), os convites de membros que esperam por mim, os convites que eu fiz, quem vê as minhas coleções (os membros de cada uma e quem tem tudo meu), as minhas coleções, para onde posso convidar, se o servidor manda e-mail e quantos dias um convite vale' => 'la page Approbations : les demandes d\'accès que j\'approuve (celles de mes collections et celles de tout ce qui est à moi ; le master, toutes), les invitations de membres qui m\'attendent, les invitations que j\'ai faites, qui voit mes collections (les membres de chacune et qui a tout ce qui est à moi), mes collections, où je peux inviter, si le serveur envoie des e-mails et combien de jours une invitation est valable',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=aprovacoes"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=aprovacoes"',
        'o cadastro aberto (a página cadastro.php), sem login: se está aberto (CADASTRO_ABERTO), os dias da demonstração, se o servidor manda e-mail, os idiomas e, com ele aberto, as coleções e os donos (para pedir acesso); com convite=<token>, o convite (o e-mail, o que ele dá, até quando e se o e-mail já tem conta; false: o convite não vale mais). Gravar: escrita cadastro' => 'l\'inscription ouverte (la page cadastro.php), sans identifiant : si elle est ouverte (CADASTRO_ABERTO), les jours de la démonstration, si le serveur envoie des e-mails, les langues et, quand elle est ouverte, les collections et les propriétaires (pour demander un accès) ; avec convite=<token>, l\'invitation (l\'e-mail, ce qu\'elle donne, jusqu\'à quand et si l\'e-mail a déjà un compte ; false : l\'invitation n\'est plus valable). Enregistrer : escrita cadastro',
        'o token do link do convite' => 'le jeton du lien de l\'invitation',
        'curl "http://servidor/relojoeiro/api.php?recurso=cadastro"' => 'curl "http://servidor/relojoeiro/api.php?recurso=cadastro"',
        'as migrações que faltam aplicar no banco (lista vazia: está em dia); com o banco desatualizado, só ele (e o manual e o código, que não usam o banco) responde' => 'les migrations qui restent à appliquer sur la base de données (liste vide : elle est à jour) ; avec la base pas à jour, seul celui-ci (et le manuel et le code, qui n\'utilisent pas la base) répond',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=migracoes"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=migracoes"',
        'a situação da instalação: o banco, se está vazio, instalado e em dia, as migrações que faltam, quantos usuários há e o próximo passo (instalar, aplicar as migrações, criar o primeiro usuário ou nada); responde também com o banco vazio, pelo token' => 'l\'état de l\'installation : la base de données, si elle est vide, installée et à jour, les migrations qui manquent, combien d\'utilisateurs il y a et l\'étape suivante (installer, appliquer les migrations, créer le premier utilisateur ou rien) ; répond aussi avec la base vide, par le jeton',
        'curl -H "X-Api-Token: segredo" "http://servidor/relojoeiro/api.php?recurso=instalacao"' => 'curl -H "X-Api-Token: segredo" "http://servidor/relojoeiro/api.php?recurso=instalacao"',
        'o que a importação do sistema anterior usa: o servidor do banco antigo (sem a senha) e de onde ele vem no config.php, se o PHP tem a extensão do MySQL, quantos relógios este banco já tem (com algum, a importação pede substituir=1) e o que ela traz' => 'ce que l\'importation de l\'ancien système utilise : le serveur de l\'ancienne base (sans le mot de passe) et d\'où il vient dans config.php, si PHP a l\'extension MySQL, combien de montres cette base a déjà (s\'il y en a, l\'importation demande substituir=1) et ce qu\'elle apporte',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=importacao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=importacao"',
        'a cópia de segurança do banco (uma por dia, na rodada da noite do cron, na BACKUP_PASTA do config.php): se a pasta serve, quantas cópias ficam, se levam o conteúdo dos documentos, a versão do banco, a última e as cópias da pasta (da mais nova para a mais velha); com arquivo=<nome>, baixa aquela cópia (JSON Lines comprimido, o mesmo nos quatro bancos). Fazer e restaurar: na escrita' => 'la sauvegarde de la base de données (une par jour, lors du passage du soir du cron, dans la BACKUP_PASTA de config.php) : si le dossier convient, combien de copies sont conservées, si elles emportent le contenu des documents, la version de la base, la dernière et les copies du dossier (de la plus récente à la plus ancienne) ; avec arquivo=<nom>, télécharge cette copie (JSON Lines compressé, le même sur les quatre bases). Faire et restaurer : dans l\'écriture',
        'o nome de uma cópia (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): baixa o arquivo' => 'le nom d\'une copie (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz) : télécharge le fichier',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=backup"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=backup"',
        'o manifesto do aplicativo no celular (PWA; application/manifest+json): o nome, o ícone, as cores, o start_url e o scope. Responde sem login (o navegador pede ao instalar); com o cookie do aparelho lembrado (Minha conta, Lembrar este aparelho), o start_url leva a chave dele (index.php?aparelho=...): o aplicativo instalado abre já entrando, também no iPhone, onde o aplicativo não compartilha os cookies do Safari' => 'le manifeste de l\'application sur le téléphone (PWA ; application/manifest+json) : le nom, l\'icône, les couleurs, le start_url et le scope. Répond sans login (le navigateur le demande à l\'installation) ; avec le cookie de l\'appareil mémorisé (Mon compte, Mémoriser cet appareil), le start_url porte sa clé (index.php?aparelho=...) : l\'application installée s\'ouvre déjà connectée, aussi sur l\'iPhone, où l\'application ne partage pas les cookies de Safari',
        'curl "http://servidor/relojoeiro/api.php?recurso=manifest"' => 'curl "http://servidor/relojoeiro/api.php?recurso=manifest"',
        'o service worker do aplicativo (JavaScript, não é JSON): o sw.js com, na frente, a versão (muda quando qualquer arquivo das telas muda) e a lista dos arquivos guardados na instalação (o estilo, os scripts, os ícones e a página sem conexão). Responde sem login. Guarda os arquivos das telas e os textos do idioma; as páginas vêm sempre da rede (sem rede, a página offline.html) e a API nunca fica em cache; recebe o Web Push' => 'le service worker de l\'application (JavaScript, pas du JSON) : le sw.js avec, devant, la version (change dès qu\'un fichier des écrans change) et la liste des fichiers gardés à l\'installation (le style, les scripts, les icônes et la page sans connexion). Répond sans login. Il garde les fichiers des écrans et les textes de la langue ; les pages viennent toujours du réseau (sans réseau, la page offline.html) et l\'API n\'est jamais mise en cache ; il reçoit le Web Push',
        'curl "http://servidor/relojoeiro/api.php?recurso=sw"' => 'curl "http://servidor/relojoeiro/api.php?recurso=sw"',
        'o login das páginas: sem login, 401 (o navegador pede o usuário e a senha); com login, vai para a página de volta (302) ou diz quem entrou (usuario, por, volta). É para onde o api.js manda quem abre uma página sem login' => 'la connexion des pages : sans connexion, 401 (le navigateur demande l\'utilisateur et le mot de passe) ; avec connexion, va vers la page de retour (302) ou dit qui est entré (usuario, por, volta). C\'est là qu\'api.js envoie qui ouvre une page sans connexion',
        'uma página do sistema para onde ir depois de entrar (index.php, plano.php?..., ajuda.php#...); outra coisa não vale' => 'une page du système vers laquelle aller après la connexion (index.php, plano.php?..., ajuda.php#...) ; autre chose ne vaut pas',
        'no navegador: http://servidor/relojoeiro/api.php?recurso=entrar&volta=index.php' => 'dans le navigateur : http://servidor/relojoeiro/api.php?recurso=entrar&volta=index.php',
        'as autonomias de cada relógio, enxuto e rápido, para sistemas de fora, em segundos inteiros: prevista (cheio, pelo cadastro), atual (cheio, pela conta do sistema com o gasto medido), estimada (quanto ainda dura seguindo o plano), restante_em_uso (no pulso sem tirar), restante_guardado (parado) e quando acaba (acaba_em_unixtimestamp, acaba_em_segundos, acaba_em_datacomtz); null com o motivo em motivos' => 'les autonomies de chaque montre, compact et rapide, pour les systèmes externes, en secondes entières : prevista (pleine, selon la fiche), atual (pleine, par le calcul du système avec la consommation mesurée), estimada (combien de temps il reste encore en suivant le plan), restante_em_uso (au poignet sans la retirer), restante_guardado (rangée) et quand elle s\'épuise (acaba_em_unixtimestamp, acaba_em_segundos, acaba_em_datacomtz) ; null avec le motif dans motivos',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=autonomia&f[relogios][acaba_em_segundos][ate]=86400&mostrar[relogios]=nome,acaba_em_datacomtz"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=autonomia&f[relogios][acaba_em_segundos][ate]=86400&mostrar[relogios]=nome,acaba_em_datacomtz"',
        'esta explicação: os recursos, os parâmetros, as ações de escrita com os campos, os exemplos, o dicionário de todos os campos (campos) e as funções do motor; com parte=manual, o manual (veja manual); com parte=reconstrucao, a reconstrução (veja reconstrucao); com parte=codigo, o código (veja codigo)' => 'cette explication : les ressources, les paramètres, les actions d\'écriture avec les champs, les exemples, le dictionnaire de tous les champs (campos) et les fonctions du moteur ; avec parte=manual, le manuel (voir manual) ; avec parte=reconstrucao, la reconstruction (voir reconstrucao) ; avec parte=codigo, le code (voir codigo)',
        'manual: em vez desta explicação, o texto da página Ajuda (o mesmo que recurso=manual); reconstrucao: o roteiro para reescrever a aplicação do zero (o mesmo que recurso=reconstrucao); codigo: o código do sistema (o mesmo que recurso=codigo)' => 'manual : au lieu de cette explication, le texte de la page Aide (le même que recurso=manual) ; reconstrucao : le guide pour réécrire l\'application à partir de zéro (le même que recurso=reconstrucao) ; codigo : le code du système (le même que recurso=codigo)',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ajuda&parte=reconstrucao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ajuda&parte=reconstrucao"',
        'o texto da página Ajuda: os trechos do README para quem usa (a ideia central, como funciona, o cadastro campo por campo, a Configuração, um dia com o sistema, as telas, as perguntas frequentes e como reescrever o sistema do zero), em markdown, inteiro e seção por seção (título, nível, âncora e texto), e já em HTML com o sumário, como a página Ajuda mostra; sem o README.md na pasta: 404; responde mesmo com o banco desatualizado. O mesmo que recurso=ajuda&parte=manual' => 'le texte de la page Aide : les extraits du README pour qui l\'utilise (l\'idée centrale, comment ça fonctionne, la fiche champ par champ, la Configuration, une journée avec le système, les écrans, les questions fréquentes et comment réécrire le système à partir de zéro), en markdown, en entier et section par section (titre, niveau, ancre et texte), et déjà en HTML avec le sommaire, comme le montre la page Aide ; sans le README.md dans le dossier : 404 ; répond même avec la base de données pas à jour. Le même que recurso=ajuda&parte=manual',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=manual&mostrar[secoes]=titulo,ancora"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=manual&mostrar[secoes]=titulo,ancora"',
        'o roteiro para reescrever a aplicação inteira do zero, em qualquer linguagem e banco, chegando ao mesmo sistema: o que ele é, os princípios, a arquitetura, a ordem de construção e as regras de cada parte (árvore e campos, lançamentos, fórmulas, avisos, gasto medido, critérios, rodízio e escala, pulso sozinho, cron, mensagens e agenda, documentos, telas, segurança, testes), a especificação visual de cada tela (telas: o visual com os valores exatos, o menu e cada página com as tabelas, os campos, os botões e as mensagens), a lista do código do sistema (codigo: o mesmo do recurso=codigo, que traz cada arquivo como está agora), o modelo de dados lido do próprio banco (tabelas, colunas, chaves, índices e regras de validação) e as listas do código (funções das fórmulas, tipos de campo, formatos de lançamento, repetições, dias da semana, âncoras, canais, migrações e as constantes do config.php). O mesmo que recurso=ajuda&parte=reconstrucao' => 'le guide pour réécrire l\'application entière à partir de zéro, dans n\'importe quel langage et n\'importe quelle base, pour arriver au même système : ce qu\'il est, les principes, l\'architecture, l\'ordre de construction et les règles de chaque partie (arbre et champs, saisies, formules, alertes, consommation mesurée, critères, rotation et planning, poignet seul, cron, messages et agenda, documents, écrans, sécurité, tests), la spécification visuelle de chaque écran (telas : le visuel avec les valeurs exactes, le menu et chaque page avec les tableaux, les champs, les boutons et les messages), la liste du code du système (codigo : le même que recurso=codigo, qui apporte chaque fichier tel qu\'il est maintenant), le modèle de données lu dans la base elle-même (tables, colonnes, clés, index et règles de validation) et les listes du code (fonctions des formules, types de champ, formats de saisie, répétitions, jours de la semaine, repères, canaux, migrations et les constantes de config.php). Le même que recurso=ajuda&parte=reconstrucao',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reconstrucao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reconstrucao"',
        'o código do sistema como está agora, lido do disco na hora do pedido, para a reescrita ler o original: cada arquivo (as páginas, o estilo, o JavaScript, a API, o núcleo, o banco, as migrações, o servidor, os testes, a documentação e as capturas das telas) com a camada, o que ele é, a linguagem, o tamanho, as linhas, o SHA-256 e a data; nas páginas, os arquivos que ela carrega e o HTML que o navegador recebe; e o que fica de fora de propósito (o config.php, a chave do Google, o banco, os documentos, as senhas), com o que ver no lugar. Só saem os arquivos do sistema (os do repositório); responde mesmo com o banco vazio ou desatualizado. O mesmo que recurso=ajuda&parte=codigo' => 'le code du système tel qu\'il est maintenant, lu sur le disque au moment de la requête, pour que la réécriture lise l\'original : chaque fichier (les pages, le style, le JavaScript, l\'API, le noyau, la base, les migrations, le serveur, les tests, la documentation et les captures des écrans) avec la couche, ce qu\'il est, le langage, la taille, les lignes, le SHA-256 et la date ; dans les pages, les fichiers qu\'elle charge et le HTML que le navigateur reçoit ; et ce qui est laissé de côté exprès (config.php, la clé Google, la base, les documents, les mots de passe), avec quoi voir à la place. Seuls sortent les fichiers du système (ceux du dépôt) ; répond même avec la base vide ou pas à jour. Le même que recurso=ajuda&parte=codigo',
        'um arquivo (o nome como está em arquivos, ex.: estilo.css, docs/telas/hoje.png): vem com o conteúdo como está (conteudo; a imagem em conteudo_base64) e, numa página, com o HTML que o navegador recebe (html)' => 'un fichier (le nom tel qu\'il est dans arquivos, ex. : estilo.css, docs/telas/hoje.png) : vient avec le contenu tel quel (conteudo ; l\'image dans conteudo_base64) et, pour une page, avec le HTML que le navigateur reçoit (html)',
        '1, com arquivo: o arquivo puro, sem JSON (texto como text/plain, para ler no navegador; imagem como imagem)' => '1, avec arquivo : le fichier pur, sans JSON (texte en text/plain, pour le lire dans le navigateur ; image en tant qu\'image)',
        '1, com arquivo de uma página e cru=1: o HTML que o navegador recebe, puro' => '1, avec le fichier d\'une page et cru=1 : le HTML que le navigateur reçoit, pur',
        '1, sem arquivo: a lista com o conteúdo de todos (com f[arquivos][camada]=tela, só o das telas)' => '1, sans arquivo : la liste avec le contenu de tous (avec f[arquivos][camada]=tela, seulement ceux des écrans)',
        'no navegador: http://servidor/relojoeiro/api.php?recurso=codigo&arquivo=estilo.css&cru=1' => 'dans le navigateur : http://servidor/relojoeiro/api.php?recurso=codigo&arquivo=estilo.css&cru=1',
        'POST, com os campos em formulário ou em JSON no corpo (Content-Type: application/json); recurso e acao nos campos ou na URL. Resposta: {ok, mensagem, erros, id}; 400 quando recusado (os erros dizem por quê). Ex. em JSON: curl -u lucas:senha -H "Content-Type: application/json" -d \'{"recurso":"lancamento","acao":"lancar","relogio_id":10,"tipo":"carga","valor":68}\' http://servidor/relojoeiro/api.php' => 'POST, avec les champs en formulaire ou en JSON dans le corps (Content-Type: application/json) ; recurso et acao dans les champs ou dans l\'URL. Réponse : {ok, mensagem, erros, id} ; 400 quand c\'est refusé (les erreurs disent pourquoi). Ex. en JSON : curl -u lucas:senha -H "Content-Type: application/json" -d \'{"recurso":"lancamento","acao":"lancar","relogio_id":10,"tipo":"carga","valor":68}\' http://servidor/relojoeiro/api.php',
        'nome, pai_id (0 = na raiz)' => 'nome, pai_id (0 = à la racine)',
        'curl -u lucas:senha -d recurso=arvore -d acao=novo -d "nome=Cronógrafos" -d pai_id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=novo -d "nome=Cronógrafos" -d pai_id=2 http://servidor/relojoeiro/api.php',
        'id, nome' => 'id, nome',
        'curl -u lucas:senha -d recurso=arvore -d acao=renomear -d id=5 -d "nome=Automáticos" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=renomear -d id=5 -d "nome=Automáticos" http://servidor/relojoeiro/api.php',
        'id, pai_id (0 = na raiz; não pode ir para dentro dele mesmo)' => 'id, pai_id (0 = à la racine ; il ne peut pas aller à l\'intérieur de lui-même)',
        'curl -u lucas:senha -d recurso=arvore -d acao=mover -d id=5 -d pai_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=mover -d id=5 -d pai_id=0 http://servidor/relojoeiro/api.php',
        'id, direcao (sobe ou desce)' => 'id, direcao (sobe ou desce)',
        'curl -u lucas:senha -d recurso=arvore -d acao=ordem -d id=5 -d direcao=sobe http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=ordem -d id=5 -d direcao=sobe http://servidor/relojoeiro/api.php',
        'id; o que é dele (subgrupos, relógios, campos, tipos de lançamento, fórmulas, avisos) sobe para o de cima, menos as versões de fórmulas e avisos que o de cima já tem (essas saem); os blocos dos modos que sorteavam dele passam a sortear do de cima; os critérios próprios saem (os relógios usam os do lugar mais perto, acima)' => 'id ; ce qui lui appartient (sous-groupes, montres, champs, types de saisie, formules, alertes) monte vers celui du dessus, sauf les versions de formules et d\'alertes que celui du dessus a déjà (celles-là sortent) ; les blocs des modes qui tiraient au sort depuis lui tirent désormais depuis celui du dessus ; les critères propres sortent (les montres utilisent ceux du niveau le plus proche, au-dessus)',
        'curl -u lucas:senha -d recurso=arvore -d acao=excluir -d id=5 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=excluir -d id=5 http://servidor/relojoeiro/api.php',
        'grupo[<id do relógio>] = o grupo (0 = na raiz), um ou vários' => 'grupo[<id de la montre>] = le groupe (0 = à la racine), un ou plusieurs',
        'curl -u lucas:senha -d recurso=arvore -d acao=relogios -d "grupo[13]=1" -d "grupo[4]=8" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=relogios -d "grupo[13]=1" -d "grupo[4]=8" http://servidor/relojoeiro/api.php',
        'identificador, nome, tipo (inteiro, decimal, sim_nao, data, lista, texto), unidade, opcoes (lista: uma por linha), padrao, no_id (0 = todos), so_desejado (1: o campo vale só nos relógios desejados, a lista de desejos; padrão 0)' => 'identificador, nome, tipo (inteiro, decimal, sim_nao, data, lista, texto), unidade, opcoes (liste : une par ligne), padrao, no_id (0 = tous), so_desejado (1 : le champ ne vaut que pour les montres désirées, la liste d\'envies ; 0 par défaut)',
        'curl -u lucas:senha -d recurso=campos -d acao=novo -d identificador=resistencia_agua -d "nome=Resistência à água" -d tipo=inteiro -d unidade=m -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=novo -d identificador=resistencia_agua -d "nome=Resistência à água" -d tipo=inteiro -d unidade=m -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos (só o que vier muda)' => 'id et les mêmes champs (seul ce qui arrive change)',
        'curl -u lucas:senha -d recurso=campos -d acao=alterar -d id=21 -d "nome=Resistência (m)" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=alterar -d id=21 -d "nome=Resistência (m)" http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=campos -d acao=ordem -d id=21 -d direcao=sobe http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=ordem -d id=21 -d direcao=sobe http://servidor/relojoeiro/api.php',
        'confirmar=1; id (os valores dele saem junto)' => 'confirmar=1 ; id (ses valeurs partent avec)',
        'curl -u lucas:senha -d recurso=campos -d acao=excluir -d id=21 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=excluir -d id=21 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'identificador, nome, formato (instantaneo, valor, sessao), unidade (com valor), fecha_as (sessão: HH:MM; vazio: não fecha sozinha), exclusiva (1 ou 0, só sessão), mede_gasto (1 ou 0, só com valor: cada leitura mede o gasto, comparando com a anterior), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual), no_id' => 'identificador, nome, formato (instantaneo, valor, sessao), unidade (avec valeur), fecha_as (session : HH:MM ; vide : ne se ferme pas toute seule), exclusiva (1 ou 0, session seulement), mede_gasto (1 ou 0, seulement avec valeur : chaque lecture mesure la consommation, en comparant avec la précédente), condicao (vaut quand : une formule, 1 vaut et 0 non ; vide, vaut toujours ; ex. : corda_manual), no_id',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=novo -d identificador=banho_ultrassom -d "nome=Banho ultrassônico" -d formato=instantaneo -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=novo -d identificador=banho_ultrassom -d "nome=Banho ultrassônico" -d formato=instantaneo -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos' => 'id et les mêmes champs',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=alterar -d id=11 -d fecha_as=18:00 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=alterar -d id=11 -d fecha_as=18:00 http://servidor/relojoeiro/api.php',
        'confirmar=1; id (só sem lançamentos)' => 'confirmar=1 ; id (seulement sans saisies)',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=excluir -d id=11 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=excluir -d id=11 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'identificador, nome, expressao, unidade, no_id: uma fórmula nova, ou mais uma versão de uma que existe, em outro ponto da árvore' => 'identificador, nome, expressao, unidade, no_id : une formule nouvelle, ou une version de plus d\'une qui existe, à un autre point de l\'arbre',
        'curl -u lucas:senha -d recurso=formulas -d acao=nova -d identificador=idade_dias -d "nome=Idade (dias)" --data-urlencode "expressao=AGORA() - data_compra" -d unidade=dias -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=nova -d identificador=idade_dias -d "nome=Idade (dias)" --data-urlencode "expressao=AGORA() - data_compra" -d unidade=dias -d no_id=0 http://servidor/relojoeiro/api.php',
        'id: nome, expressao, unidade, no_id' => 'id : nome, expressao, unidade, no_id',
        'curl -u lucas:senha -d recurso=formulas -d acao=alterar -d id=17 --data-urlencode "expressao=ARREDONDA(AGORA() - data_compra)" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=alterar -d id=17 --data-urlencode "expressao=ARREDONDA(AGORA() - data_compra)" http://servidor/relojoeiro/api.php',
        'confirmar=1; id (a versão)' => 'confirmar=1 ; id (la version)',
        'curl -u lucas:senha -d recurso=formulas -d acao=excluir -d id=17 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=excluir -d id=17 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 ou ausente cria), nome, no_id, disponivel (1 ou 0), copia_banco (1 ou 0: a cópia no banco de todos os documentos dele; o cron copia ou tira aos poucos), posse (a situação na coleção: colecao, o padrão; desejado, a lista de desejos; emprestado; vendido; arquivado. Fora da coleção o relógio fica indisponível (disponivel=1 é ignorado, com uma nota), e, saindo dela, as sessões abertas dele (no pulso, no sol...) fecham agora e os dias dele no plano de amanhã em diante saem e são sorteados de novo (hoje fica, mas ele não vai ao pulso sozinho); voltando para ela sem disponivel, fica disponível), valores[<identificador do campo>]: só muda o que vier; valor vazio apaga (os campos só nos desejados, como o preco_alvo, só gravam no desejado)' => 'id (0 ou absent crée), nome, no_id, disponivel (1 ou 0), copia_banco (1 ou 0 : la copie dans la base de tous ses documents ; le cron copie ou retire petit à petit), posse (le statut dans la collection : colecao, le défaut ; desejado, la liste d\'envies ; emprestado ; vendido ; arquivado. Hors de la collection la montre devient indisponible (disponivel=1 est ignoré, avec une note), et, en la quittant, ses sessions ouvertes (au poignet, au soleil...) se ferment maintenant et ses jours dans le plan à partir de demain sortent et sont tirés au sort à nouveau (aujourd\'hui reste, mais elle ne va pas au poignet toute seule) ; en y revenant sans disponivel, elle devient disponible), valores[<identificador du champ>] : seul ce qui arrive change ; une valeur vide efface (les champs seulement pour les désirées, comme preco_alvo, ne s\'enregistrent que dans la désirée)',
        'curl -u lucas:senha -d recurso=relogio -d acao=salvar -d id=10 -d "valores[preferencia]=80" -d disponivel=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=salvar -d id=10 -d "valores[preferencia]=80" -d disponivel=1 http://servidor/relojoeiro/api.php',
        'id, foto_base64 (JPEG, PNG ou WebP, até 4 MB; data:image/...;base64,... ou só o base64)' => 'id, foto_base64 (JPEG, PNG ou WebP, jusqu\'à 4 Mo ; data:image/...;base64,... ou seulement le base64)',
        'curl -u lucas:senha -d recurso=relogio -d acao=foto -d id=10 --data-urlencode foto_base64@foto.b64 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=foto -d id=10 --data-urlencode foto_base64@foto.b64 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=relogio -d acao=remover_foto -d id=10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=remover_foto -d id=10 http://servidor/relojoeiro/api.php',
        'confirmar=1; id (com todo o histórico, a foto e os documentos, inclusive os arquivos deles; os acessórios dele ficam soltos)' => 'confirmar=1 ; id (avec tout l\'historique, la photo et les documents, y compris leurs fichiers ; ses accessoires restent détachés)',
        'curl -u lucas:senha -d recurso=relogio -d acao=excluir -d id=15 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=excluir -d id=15 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'relogio_id, categoria_id, titulo (vazio: o nome do arquivo), data (AAAA-MM-DD), descricao, copia_banco (1: pede a cópia destes arquivos no banco; o config.php e o relógio, se pedem, valem por cima) e o arquivo: arquivos[] (upload; vários de uma vez) ou arquivo_base64 com arquivo_nome; a miniatura de uma foto, opcional: miniatura (upload, JPEG, PNG ou WebP até 1 MB) ou miniatura_base64. Cada arquivo até o limite (recurso=documentos, limite) e do tipo que a categoria aceita. O arquivo vai para a pasta e, se a cópia é pedida (pelo config.php, pelo relógio ou pelo próprio arquivo), também para o banco, em pedaços de 4 MB (se a cópia falhar, o documento fica e a mensagem avisa; o cron tenta de novo). Responde ids: os documentos guardados' => 'relogio_id, categoria_id, titulo (vide : le nom du fichier), data (AAAA-MM-JJ), descricao, copia_banco (1 : demande la copie de ces fichiers dans la base ; config.php et la montre, s\'ils le demandent, l\'emportent) et le fichier : arquivos[] (envoi ; plusieurs à la fois) ou arquivo_base64 avec arquivo_nome ; la miniature d\'une photo, facultative : miniatura (envoi, JPEG, PNG ou WebP jusqu\'à 1 Mo) ou miniatura_base64. Chaque fichier jusqu\'à la limite (recurso=documentos, limite) et du type que la catégorie accepte. Le fichier va dans le dossier et, si la copie est demandée (par config.php, par la montre ou par le fichier lui-même), aussi dans la base, en morceaux de 4 Mo (si la copie échoue, le document reste et le message le signale ; le cron réessaie). Répond ids : les documents enregistrés',
        'curl -u lucas:senha -F recurso=documentos -F acao=enviar -F relogio_id=10 -F categoria_id=2 -F "arquivos[]=@nota.pdf" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -F recurso=documentos -F acao=enviar -F relogio_id=10 -F categoria_id=2 -F "arquivos[]=@nota.pdf" http://servidor/relojoeiro/api.php',
        'id, categoria_id, titulo, data, descricao, copia_banco (1 ou 0): só muda o que vier; a cópia entra ou sai do banco na hora (só sai se o arquivo da pasta confere com ela)' => 'id, categoria_id, titulo, data, descricao, copia_banco (1 ou 0) : seul ce qui arrive change ; la copie entre dans la base ou en sort tout de suite (elle n\'en sort que si le fichier du dossier correspond à elle)',
        'curl -u lucas:senha -d recurso=documentos -d acao=alterar -d id=7 -d "titulo=No casamento" -d data=2026-09-20 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documentos -d acao=alterar -d id=7 -d "titulo=No casamento" -d data=2026-09-20 http://servidor/relojoeiro/api.php',
        'confirmar=1; id: o documento, o arquivo dele na pasta e a cópia no banco' => 'confirmar=1 ; id : le document, son fichier dans le dossier et la copie dans la base',
        'curl -u lucas:senha -d recurso=documentos -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documentos -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 ou ausente cria), nome (até 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro; padrão pulseira), relogio_id (o relógio de que ele é; 0: solto, serve a vários), observacao (até 1000): só muda o que vier' => 'id (0 ou absent crée), nome (jusqu\'à 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro ; pulseira par défaut), relogio_id (la montre à laquelle il appartient ; 0 : libre, sert à plusieurs), observacao (jusqu\'à 1000) : seul ce qui arrive change',
        'curl -u lucas:senha -d recurso=acessorios -d acao=salvar -d "nome=Pulseira NATO verde" -d tipo=pulseira -d relogio_id=3 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessorios -d acao=salvar -d "nome=Pulseira NATO verde" -d tipo=pulseira -d relogio_id=3 http://servidor/relojoeiro/api.php',
        'confirmar=1; id' => 'confirmar=1 ; id',
        'curl -u lucas:senha -d recurso=acessorios -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessorios -d acao=excluir -d id=4 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'identificador, nome, aceita[] (imagem, video, audio, pdf, xml; nenhum: qualquer arquivo), ordem (vazio: no fim)' => 'identificador, nome, aceita[] (imagem, video, audio, pdf, xml ; aucun : n\'importe quel fichier), ordem (vide : à la fin)',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=nova -d identificador=garantia -d nome=Garantia -d "aceita[]=pdf" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=nova -d identificador=garantia -d nome=Garantia -d "aceita[]=pdf" http://servidor/relojoeiro/api.php',
        'id, nome, aceita[], ordem (o identificador não muda)' => 'id, nome, aceita[], ordem (l\'identificador ne change pas)',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=alterar -d id=7 -d nome=Garantias http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=alterar -d id=7 -d nome=Garantias http://servidor/relojoeiro/api.php',
        'confirmar=1; id (só uma categoria sem documentos)' => 'confirmar=1 ; id (seulement une catégorie sans documents)',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=excluir -d id=7 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (instantâneo ou com valor), valor (com valor), quando (AAAA-MM-DD HH:MM; vazio: agora), medir (1, o padrão, ou 0: num tipo que mede o gasto, com 1 a medição entra na média; com 0 fica só no histórico), estado (uso ou repouso; vazio: não diz): a marcação da leitura, que fica gravada nela e manda (o gasto em uso sai só das leituras marcadas em uso; o em repouso, só das em repouso); se o pulso registrado desde a leitura anterior não bate com ela, a resposta vem com confirmar: true e a pergunta, e o lançamento só grava de novo com confirmar=1 (vale o que a pessoa marcou)' => 'relogio_id, tipo (instantané ou avec valeur), valor (avec valeur), quando (AAAA-MM-JJ HH:MM ; vide : maintenant), medir (1, par défaut, ou 0 : dans un type qui mesure la consommation, avec 1 la mesure entre dans la moyenne ; avec 0 elle reste seulement dans l\'historique), estado (uso ou repouso ; vide : ne dit rien) : le marquage du relevé, enregistré dans celui-ci et qui fait foi (la consommation en usage ne sort que des relevés marqués en usage ; celle au repos, que de ceux au repos) ; si le poignet enregistré depuis le relevé précédent ne correspond pas, la réponse vient avec confirmar: true et la question, et la saisie n\'est enregistrée qu\'en la renvoyant avec confirmar=1 (ce que la personne a marqué fait foi)',
        'curl -u lucas:senha -d recurso=lancamento -d acao=lancar -d relogio_id=10 -d tipo=carga -d valor=68 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=lancar -d relogio_id=10 -d tipo=carga -d valor=68 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (sessão), quando: abre a sessão; uma exclusiva fecha a outra exclusiva aberta' => 'relogio_id, tipo (session), quando : ouvre la session ; une exclusive ferme l\'autre exclusive ouverte',
        'curl -u lucas:senha -d recurso=lancamento -d acao=iniciar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=iniciar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php',
        'relogio_id, tipo, quando: fecha a sessão aberta' => 'relogio_id, tipo, quando : ferme la session ouverte',
        'curl -u lucas:senha -d recurso=lancamento -d acao=encerrar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=encerrar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php',
        'relogio_id, tipo, inicio (quando também vale), fim: uma sessão que já passou (espaço ou T entre data e hora)' => 'relogio_id, tipo, inicio (quando vaut aussi), fim : une session déjà passée (espace ou T entre la date et l\'heure)',
        'curl -u lucas:senha -d recurso=lancamento -d acao=periodo -d relogio_id=3 -d tipo=winder -d "inicio=2026-09-26 20:00" -d "fim=2026-09-27 07:00" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=periodo -d relogio_id=3 -d tipo=winder -d "inicio=2026-09-26 20:00" -d "fim=2026-09-27 07:00" http://servidor/relojoeiro/api.php',
        'id: quando ou inicio e fim, valor, estado (a marcação da leitura: uso, repouso ou vazio; só o que vier)' => 'id : quando ou inicio et fim, valor, estado (le marquage du relevé : uso, repouso ou vide ; seulement ce qui est envoyé)',
        'curl -u lucas:senha -d recurso=lancamento -d acao=alterar -d id=42 -d valor=70 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=alterar -d id=42 -d valor=70 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=lancamento -d acao=excluir -d id=42 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=excluir -d id=42 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (a medição do gasto, de medicoes[] na ficha), usada (1: entra na conta; 0: fica só no histórico): pôr ou tirar uma medição da conta do gasto, sem apagar nada' => 'id (la mesure de la consommation, de medicoes[] dans la fiche), usada (1 : entre dans le calcul ; 0 : reste seulement dans l\'historique) : mettre ou retirer une mesure du calcul de la consommation, sans rien effacer',
        'curl -u lucas:senha -d recurso=lancamento -d acao=medicao -d id=13 -d usada=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=medicao -d id=13 -d usada=0 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (sessão), quando: fecha a sessão se ela está aberta, abre se está fechada (um botão só num atalho de celular). Em todas as ações, relogio_id=hoje é o relógio do dia, pelo plano' => 'relogio_id, tipo (session), quando : ferme la session si elle est ouverte, l\'ouvre si elle est fermée (un seul bouton dans un raccourci de téléphone). Dans toutes les actions, relogio_id=hoje est la montre du jour, selon le plan',
        'curl -H "X-Api-Token: ..." -d recurso=lancamento -d acao=alternar -d relogio_id=hoje -d tipo=pulso http://servidor/relojoeiro/api.php' => 'curl -H "X-Api-Token: ..." -d recurso=lancamento -d acao=alternar -d relogio_id=hoje -d tipo=pulso http://servidor/relojoeiro/api.php',
        'identificador, nome, expressao (a data prevista), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual = 0), antecedencia_dias, texto (o motivo, com {relogio}, {data}, {quando}, {limite}), resolve (o tipo de lançamento), ativo, no_id, escala (nao, uso, sempre), simula_valor, simula_horas, agenda (janela ou sempre), na_hora (1 ou 0: o Telegram recebe o aviso no minuto em que ele vence, uma vez)' => 'identificador, nome, expressao (la date prévue), condicao (vaut quand : une formule, 1 vaut et 0 non ; vide, vaut toujours ; ex. : corda_manual = 0), antecedencia_dias, texto (le motif, avec {relogio}, {data}, {quando}, {limite}), resolve (le type de saisie), ativo, no_id, escala (nao, uso, sempre), simula_valor, simula_horas, agenda (janela ou sempre), na_hora (1 ou 0 : Telegram reçoit l\'alerte à la minute où elle arrive à échéance, une seule fois)',
        'curl -u lucas:senha -d recurso=avisos -d acao=novo -d identificador=pulseira -d "nome=Trocar a pulseira" --data-urlencode "expressao=data_compra + 365" -d antecedencia_dias=15 -d "texto=vence {quando}, {data}" -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=novo -d identificador=pulseira -d "nome=Trocar a pulseira" --data-urlencode "expressao=data_compra + 365" -d antecedencia_dias=15 -d "texto=vence {quando}, {data}" -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos (menos o identificador)' => 'id et les mêmes champs (sauf l\'identificador)',
        'curl -u lucas:senha -d recurso=avisos -d acao=alterar -d id=9 -d antecedencia_dias=30 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=alterar -d id=9 -d antecedencia_dias=30 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=avisos -d acao=excluir -d id=9 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=excluir -d id=9 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'escopo ("" todos, g:<grupo>, r:<relógio>), origem (herdado: copia o que ele usa hoje; vazio)' => 'escopo ("" tous, g:<groupe>, r:<montre>), origem (herdado : copie ce qu\'il utilise aujourd\'hui ; vide)',
        'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_criar -d escopo=r:10 -d origem=herdado http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_criar -d escopo=r:10 -d origem=herdado http://servidor/relojoeiro/api.php',
        'escopo (volta a herdar o de cima)' => 'escopo (revient à hériter de celui du dessus)',
        'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_excluir -d escopo=r:10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_excluir -d escopo=r:10 http://servidor/relojoeiro/api.php',
        'escopo, nome, peso (os outros abrem espaço na proporção)' => 'escopo, nome, peso (les autres font de la place au prorata)',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_novo -d escopo=g:1 -d "nome=Estilo" -d peso=10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_novo -d escopo=g:1 -d "nome=Estilo" -d peso=10 http://servidor/relojoeiro/api.php',
        'escopo, nome[<id>], peso[<id>]: todos os do conjunto, somando 100' => 'escopo, nome[<id>], peso[<id>] : tous ceux de l\'ensemble, en faisant 100',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_pesos -d escopo=g:1 -d "peso[5]=35" -d "peso[6]=10" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_pesos -d escopo=g:1 -d "peso[5]=35" -d "peso[6]=10" http://servidor/relojoeiro/api.php',
        'id (o peso dele vai para os outros na proporção)' => 'id (son poids va aux autres au prorata)',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_excluir -d id=29 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_excluir -d id=29 http://servidor/relojoeiro/api.php',
        'parametro_id, nome, variavel (o identificador de um campo ou fórmula; metrica também vale), peso' => 'parametro_id, nome, variavel (l\'identifiant d\'un champ ou d\'une formule ; metrica vaut aussi), peso',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_novo -d parametro_id=5 -d "nome=Carga" -d variavel=energia -d peso=20 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_novo -d parametro_id=5 -d "nome=Carga" -d variavel=energia -d peso=20 http://servidor/relojoeiro/api.php',
        'parametro_id, nome[<id>], peso[<id>]: somando 100' => 'parametro_id, nome[<id>], peso[<id>] : en faisant 100',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_pesos -d parametro_id=5 -d "peso[6]=60" -d "peso[7]=40" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_pesos -d parametro_id=5 -d "peso[6]=60" -d "peso[7]=40" http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_excluir -d id=7 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_excluir -d id=7 http://servidor/relojoeiro/api.php',
        'id, variavel (metrica também vale; as faixas recomeçam)' => 'id, variavel (metrica vaut aussi ; les tranches recommencent)',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_medida -d id=7 -d variavel=dias_de_carga http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_medida -d id=7 -d variavel=dias_de_carga http://servidor/relojoeiro/api.php',
        'id, parametro_id (o de destino, de qualquer lugar)' => 'id, parametro_id (celui de destination, de n\'importe quel niveau)',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_mover -d id=7 -d parametro_id=8 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_mover -d id=7 -d parametro_id=8 http://servidor/relojoeiro/api.php',
        'tipo (parametro ou sub), id, direcao (sobe ou desce)' => 'tipo (parametro ou sub), id, direcao (sobe ou desce)',
        'curl -u lucas:senha -d recurso=criterios -d acao=ordem -d tipo=parametro -d id=5 -d direcao=desce http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=ordem -d tipo=parametro -d id=5 -d direcao=desce http://servidor/relojoeiro/api.php',
        'sub_id, de[], ate[], categoria[], nota[], apagar[] (todas as faixas do subparâmetro de uma vez; a última vai até o limite da medida ou sem limite)' => 'sub_id, de[], ate[], categoria[], nota[], apagar[] (toutes les tranches du sous-paramètre d\'un coup ; la dernière va jusqu\'à la limite de la mesure ou sans limite)',
        'curl -u lucas:senha -d recurso=criterios -d acao=faixas -d sub_id=6 -d "de[0]=0" -d "ate[0]=50" -d "nota[0]=30" -d "de[1]=50" -d "ate[1]=100" -d "nota[1]=100" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=faixas -d sub_id=6 -d "de[0]=0" -d "ate[0]=50" -d "nota[0]=30" -d "de[1]=50" -d "ate[1]=100" -d "nota[1]=100" http://servidor/relojoeiro/api.php',
        '(nada): volta aos critérios iniciais' => '(rien) : revient aux critères initiaux',
        'curl -u lucas:senha -d recurso=criterios -d acao=restaurar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=restaurar http://servidor/relojoeiro/api.php',
        'modo (o id), bloco_alvo[<bloco>] (0, o grupo, ou r:<id> para um relógio fixo), bloco_cada_dia[<bloco>] (presente: um por dia), selecao, escala_dias, max_sem_uso: grava e ativa o modo' => 'modo (l\'id), bloco_alvo[<bloc>] (0, le groupe, ou r:<id> pour une montre fixe), bloco_cada_dia[<bloc>] (présent : une par jour), selecao, escala_dias, max_sem_uso : enregistre et active le mode',
        'curl -u lucas:senha -d recurso=rodizio -d acao=modo -d modo=2 -d "bloco_alvo[8]=1" -d "bloco_cada_dia[8]=1" -d selecao=ponderado -d max_sem_uso=21 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=modo -d modo=2 -d "bloco_alvo[8]=1" -d "bloco_cada_dia[8]=1" -d selecao=ponderado -d max_sem_uso=21 http://servidor/relojoeiro/api.php',
        '(nada): refaz o plano de amanhã até domingo (até o fim da próxima semana, se ela já foi montada; na escala, até o fim da escala); se o dia ainda não começou no pulso, também hoje' => '(rien) : refait le plan de demain jusqu\'à dimanche (jusqu\'à la fin de la semaine prochaine, si elle a déjà été montée ; dans le planning, jusqu\'à la fin du planning) ; si la journée n\'a pas encore commencé au poignet, aujourd\'hui aussi',
        'curl -u lucas:senha -d recurso=rodizio -d acao=resortear http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=resortear http://servidor/relojoeiro/api.php',
        '(nada): inclusive hoje; se sair outro relógio, ele passa a ser o do pulso a partir de agora' => '(rien) : y compris aujourd\'hui ; si une autre montre sort, elle devient celle du poignet à partir de maintenant',
        'curl -u lucas:senha -d recurso=rodizio -d acao=resortear_hoje http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=resortear_hoje http://servidor/relojoeiro/api.php',
        '(nada): hoje sem relógio: o dia fica livre (sem relógio e sem sorteio) e a sessão do rodízio de hoje termina agora (o tempo que já ficou no pulso conta; a que nem começou sai); nenhum relógio vai ao pulso sozinho hoje; os outros dias não mudam. Desfaz: trocar_dia de hoje (ou usando) com um relógio, ou resortear_hoje' => '(rien) : aujourd\'hui sans montre : le jour reste libre (sans montre et sans tirage) et la session de rotation d\'aujourd\'hui se termine maintenant (le temps déjà passé au poignet compte ; celle qui n\'a même pas commencé sort) ; aucune montre ne va au poignet toute seule aujourd\'hui ; les autres jours ne changent pas. Annuler : trocar_dia d\'aujourd\'hui (ou usando) avec une montre, ou resortear_hoje',
        'curl -u lucas:senha -d recurso=rodizio -d acao=sem_relogio http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=sem_relogio http://servidor/relojoeiro/api.php',
        'relogio_id: o relógio de hoje, a partir de agora (na escala, fica os dias que faltavam do bloco de hoje)' => 'relogio_id : la montre d\'aujourd\'hui, à partir de maintenant (dans le planning, restent les jours qui manquaient du bloc d\'aujourd\'hui)',
        'curl -u lucas:senha -d recurso=rodizio -d acao=usando -d relogio_id=12 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=usando -d relogio_id=12 http://servidor/relojoeiro/api.php',
        'data (AAAA-MM-DD, de hoje em diante), relogio_id: o relógio daquele dia, escolhido à mão (hoje: como o usando; na escala, ela é refeita a partir do dia); relogio_id 0: o dia volta a ser sorteado' => 'data (AAAA-MM-JJ, à partir d\'aujourd\'hui), relogio_id : la montre de ce jour, choisie à la main (aujourd\'hui : comme usando ; dans le planning, il est refait à partir de ce jour) ; relogio_id 0 : le jour redevient tiré au sort',
        'curl -u lucas:senha -d recurso=rodizio -d acao=trocar_dia -d data=2026-10-09 -d relogio_id=12 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=trocar_dia -d data=2026-10-09 -d relogio_id=12 http://servidor/relojoeiro/api.php',
        'de, ate (AAAA-MM-DD, de hoje até 2 anos), relogio_ids[] (um ou vários, na ordem), dias_cada (padrão 1): os dias do período ficam escolhidos à mão, cada relógio dias_cada dias seguidos, e depois do último volta ao primeiro (hoje: o primeiro passa a ser o do pulso a partir de agora; na escala, ela é refeita a partir do começo do período)' => 'de, ate (AAAA-MM-JJ, d\'aujourd\'hui jusqu\'à 2 ans), relogio_ids[] (un ou plusieurs, dans l\'ordre), dias_cada (1 par défaut) : les jours de la période restent choisis à la main, chaque montre dias_cada jours de suite, et après la dernière on revient à la première (aujourd\'hui : la première devient celle du poignet à partir de maintenant ; dans le planning, il est refait à partir du début de la période)',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo -d de=2026-12-20 -d ate=2027-01-05 -d "relogio_ids[]=12" -d "relogio_ids[]=7" -d dias_cada=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo -d de=2026-12-20 -d ate=2027-01-05 -d "relogio_ids[]=12" -d "relogio_ids[]=7" -d dias_cada=2 http://servidor/relojoeiro/api.php',
        'de, ate (um dos dois pode faltar: sem o de, de amanhã; sem o ate, até o último dia do plano): os dias do período, de amanhã em diante (à mão, sorteados ou livres), saem do plano e o modo de rodízio monta esses dias de novo (os dias escolhidos à mão e os livres ficam quando se sorteia de novo ou se monta a próxima semana)' => 'de, ate (l\'un des deux peut manquer : sans de, à partir de demain ; sans ate, jusqu\'au dernier jour du plan) : les jours de la période, à partir de demain (à la main, tirés au sort ou libres), quittent le plan et le mode de rotation refait ces jours (les jours choisis à la main et les libres restent quand on tire au sort de nouveau ou qu\'on monte la semaine suivante)',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_sortear -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_sortear -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php',
        'hoje (1: Excluindo hoje, de hoje em diante; sem ele, de amanhã em diante): toda a programação (os dias escolhidos à mão, os sorteados e os livres) sai e o modo ativo monta o plano de novo; hoje, se mudar, o novo vai para o pulso a partir de agora' => 'hoje (1 : Y compris aujourd\'hui, à partir d\'aujourd\'hui ; sans lui, à partir de demain) : toute la programmation (les jours choisis à la main, les tirés au sort et les libres) sort et le mode actif refait le plan ; aujourd\'hui, s\'il change, la nouvelle va au poignet à partir de maintenant',
        'curl -u lucas:senha -d recurso=rodizio -d acao=apagar_tudo -d hoje=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=apagar_tudo -d hoje=1 http://servidor/relojoeiro/api.php',
        'de, ate; dias[AAAA-MM-DD]: o id do relógio, auto (Decida por mim: o sistema decide ao gravar, pelo critério do recurso=rodizio_manual) ou livre (hoje não). O dia que não vem fica com a escolha de partida (dias[].escolha do recurso=rodizio_manual). Tudo fica gravado à mão, com o motivo; hoje, com outro relógio, ele passa a ser o do pulso a partir de agora; hoje em auto continua o que está. Fora do período, vale o modo ativo' => 'de, ate ; dias[AAAA-MM-JJ] : l\'id de la montre, auto (Décider pour moi : le système décide à l\'enregistrement, selon le critère de recurso=rodizio_manual) ou livre (pas aujourd\'hui). Le jour qui n\'arrive pas garde le choix de départ (dias[].escolha de recurso=rodizio_manual). Tout est enregistré à la main, avec le motif ; aujourd\'hui, avec une autre montre, elle devient celle du poignet à partir de maintenant ; aujourd\'hui en auto continue ce qui est. Hors de la période, le mode actif vaut',
        'curl -u lucas:senha -d recurso=rodizio -d acao=manual -d de=2026-12-20 -d ate=2027-01-05 -d "dias[2026-12-20]=12" -d "dias[2026-12-21]=auto" -d "dias[2026-12-25]=livre" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=manual -d de=2026-12-20 -d ate=2027-01-05 -d "dias[2026-12-20]=12" -d "dias[2026-12-21]=auto" -d "dias[2026-12-25]=livre" http://servidor/relojoeiro/api.php',
        'de, ate (como no periodo_sortear: um dos dois pode faltar): tudo o que o período tem, de amanhã em diante, sai e os dias ficam livres: sem relógio e sem sorteio (nem a escala), para escolher à mão (trocar_dia ou periodo num dia livre o tira de lá)' => 'de, ate (comme dans periodo_sortear : l\'un des deux peut manquer) : tout ce que la période a, à partir de demain, part et les jours deviennent libres : sans montre et sans tirage (ni le planning), à choisir à la main (trocar_dia ou periodo sur un jour libre l\'en sort)',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_livre -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_livre -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php',
        '(nada): em qualquer dia, monta ou refaz a semana seguinte inteira (de segunda a domingo; no domingo, a que começa amanhã), com os dias que ainda faltam desta semana já contados como uso (a simulação no pulso); os dias escolhidos à mão ficam; recusada na escala' => '(rien) : n\'importe quel jour, monte ou refait la semaine suivante entière (du lundi au dimanche ; le dimanche, celle qui commence demain), avec les jours qui restent cette semaine déjà comptés comme utilisation (la simulation au poignet) ; les jours choisis à la main restent ; refusée dans le planning',
        'curl -u lucas:senha -d recurso=rodizio -d acao=proxima_semana http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=proxima_semana http://servidor/relojoeiro/api.php',
        'id (0 cria), nome, selecao (inteligente, ponderado, aleatorio, fifo), escala_dias (vazio: sorteio pelos blocos; 7 a 730: escala), blocos[n][nome], blocos[n][dias][], blocos[n][no_id], blocos[n][um_por] (dia ou bloco), blocos[n][relogio_id] (0: sorteia); substitui os blocos; ciclo (1 ou 0, o padrão: com o ciclo, um relógio só volta depois que todos os disponíveis do bloco passaram na semana; na escala, pelo período dela)' => 'id (0 crée), nome, selecao (inteligente, ponderado, aleatorio, fifo), escala_dias (vide : tirage par blocs ; 7 à 730 : planning), blocos[n][nome], blocos[n][dias][], blocos[n][no_id], blocos[n][um_por] (dia ou bloco), blocos[n][relogio_id] (0 : tire au sort) ; remplace les blocs ; ciclo (1 ou 0, le défaut : avec le cycle, une montre ne revient qu\'une fois que toutes les disponibles du bloc sont passées dans la semaine ; dans le planning, sur sa période)',
        'curl -u lucas:senha -d recurso=modos -d acao=salvar -d id=0 -d "nome=Só smartwatch" -d selecao=inteligente -d "blocos[0][nome]=Todo dia" -d "blocos[0][dias][]=1" -d "blocos[0][dias][]=7" -d "blocos[0][no_id]=1" -d "blocos[0][um_por]=dia" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=salvar -d id=0 -d "nome=Só smartwatch" -d selecao=inteligente -d "blocos[0][nome]=Todo dia" -d "blocos[0][dias][]=1" -d "blocos[0][dias][]=7" -d "blocos[0][no_id]=1" -d "blocos[0][um_por]=dia" http://servidor/relojoeiro/api.php',
        'id (o plano de amanhã em diante é refeito)' => 'id (le plan à partir de demain est refait)',
        'curl -u lucas:senha -d recurso=modos -d acao=ativar -d id=5 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=ativar -d id=5 http://servidor/relojoeiro/api.php',
        'confirmar=1; id (não o ativo)' => 'confirmar=1 ; id (pas l\'actif)',
        'curl -u lucas:senha -d recurso=modos -d acao=excluir -d id=6 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=excluir -d id=6 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'horario_manha, horario_noite, uso_inicio, uso_fim, sol_fim (HH:MM), pulso_auto_inicio e pulso_auto_fim (1 ou 0), carga_limiar (1 a 99), sol_limiar (1 a 99), painel_modo (lado: o relógio abre no painel ao lado da lista; flutuante: numa janela grande por cima da página), destaque_hoje (dia: o destaque no alto da página Hoje é o relógio do dia; pulso: o relógio no pulso agora), idioma (pt-BR, en, zh-CN, hi, es ou fr: o idioma padrão da coleção: o das mensagens e das agendas sem idioma próprio), proximos_por_pagina e plano_por_pagina (1 a 366: o Mostrar até dos Próximos dias da página Hoje e do dia a dia da página Plano; padrão 7 e 31), max_sem_uso, previsao_limite, gasto_motor (vazio, horas, robusto, marcacao, cadastro ou formulas: como calcular o gasto da bateria, para todos os relógios da coleção; vazio: o do relógio e o do grupo), medicao_base (dias ou leituras: o que o gasto medido conta), medicao_janela_dias (1 a 3650: a janela da conta do gasto medido, com contar por dias), medicao_janela_leituras (2 a 1000: as últimas leituras de cada tipo, com contar por leituras), documentos_copia (vazio, todos ou nenhum: a cópia dos documentos no banco, para a coleção inteira), encostado_dias (1 a 3650: o aviso Encostado, dias sem ir ao pulso), url_sistema (o endereço do sistema, para os links das mensagens, do ICS e do Outlook: do sistema inteiro, só o master); só o que vier muda. As mensagens e as agendas têm os recursos delas: destinos e agendas' => 'horario_manha, horario_noite, uso_inicio, uso_fim, sol_fim (HH:MM), pulso_auto_inicio et pulso_auto_fim (1 ou 0), carga_limiar (1 à 99), sol_limiar (1 à 99), painel_modo (lado : la montre s\'ouvre dans le panneau à côté de la liste ; flutuante : dans une grande fenêtre par-dessus la page), destaque_hoje (dia : la mise en avant en haut de la page Aujourd\'hui est la montre du jour ; pulso : la montre au poignet maintenant), idioma (pt-BR, en, zh-CN, hi, es ou fr : la langue par défaut de la collection : celle des messages et des agendas sans langue propre), proximos_por_pagina et plano_por_pagina (1 à 366 : le Afficher jusqu\'à des Prochains jours de la page Aujourd\'hui et du jour par jour de la page Plan ; par défaut 7 et 31), max_sem_uso, previsao_limite, gasto_motor (vide, horas, robusto, marcacao, cadastro ou formulas : comment calculer la consommation de la batterie, pour toutes les montres de la collection ; vide : celui de la montre et du groupe), medicao_base (dias ou leituras : ce que la consommation mesurée compte), medicao_janela_dias (1 à 3650 : la fenêtre du calcul de la consommation mesurée, en comptant par jours), medicao_janela_leituras (2 à 1000 : les derniers relevés de chaque type, en comptant par relevés), documentos_copia (vide, todos ou nenhum : la copie des documents dans la base, pour toute la collection), encostado_dias (1 à 3650 : l\'alerte Délaissée, jours sans aller au poignet), url_sistema (l\'adresse du système, pour les liens des messages, de l\'ICS et d\'Outlook : du système entier, le master seulement) ; seul ce qui est envoyé change. Les messages et les agendas ont leurs ressources : destinos et agendas',
        'curl -u lucas:senha -d recurso=config -d acao=salvar -d horario_manha=06:30 -d carga_limiar=25 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=salvar -d horario_manha=06:30 -d carga_limiar=25 http://servidor/relojoeiro/api.php',
        'evento_id (ou id; 0 cria), nome, ativo, repeticao (uma, diaria, semanal, mensal, intervalo), hora (HH:MM), data_inicio, dias_semana (1 a 7), dia_mes, intervalo_dias, relogio_id; o evento novo já vai para todos os destinos da coleção' => 'evento_id (ou id ; 0 crée), nome, ativo, repeticao (uma, diaria, semanal, mensal, intervalo), hora (HH:MM), data_inicio, dias_semana (1 à 7), dia_mes, intervalo_dias, relogio_id ; le nouvel événement va déjà vers toutes les destinations de la collection',
        'curl -u lucas:senha -d recurso=config -d acao=evento_salvar -d evento_id=0 -d "nome=Limpar as pulseiras" -d repeticao=semanal -d "dias_semana[]=1" -d "dias_semana[]=4" -d hora=20:00 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=evento_salvar -d evento_id=0 -d "nome=Limpar as pulseiras" -d repeticao=semanal -d "dias_semana[]=1" -d "dias_semana[]=4" -d hora=20:00 http://servidor/relojoeiro/api.php',
        'evento_id (ou id), confirmar=1' => 'evento_id (ou id), confirmar=1',
        'curl -u lucas:senha -d recurso=config -d acao=evento_excluir -d evento_id=3 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=evento_excluir -d evento_id=3 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 cria), tipo (webhook, email ou webpush; só ao criar), nome, ativo (1 ou 0), idioma (vazio: o da coleção), modelo (a mensagem padrão, com as âncoras), envia[] (os tipos que ele recebe: dia, vespera, os identificadores dos avisos, ev<id> dos eventos), modelo_<tipo> (o texto próprio de um tipo; vazio: a mensagem padrão); webhook: metodo (GET, POST ou PUT), url, formato (query, form ou json), campo_nome[] e campo_valor[] (cada valor com {titulo} e {mensagem}), corpo_json (opcional), cabecalho_nome[] e cabecalho_valor[] (guardados cifrados; vazio mantém o guardado); email: para (um ou mais, separados por vírgula); webpush: usuario_id (alguém que vê a coleção: vai para os aparelhos dele). Fora das coleções do master, o endereço do webhook tem de ser da internet (nada da rede interna do servidor)' => 'id (0 crée), tipo (webhook, email ou webpush ; seulement à la création), nome, ativo (1 ou 0), idioma (vide : celle de la collection), modelo (le message par défaut, avec les ancres), envia[] (les types qu\'elle reçoit : dia, vespera, les identifiants des alertes, ev<id> des événements), modelo_<tipo> (le texte propre à un type ; vide : le message par défaut) ; webhook : metodo (GET, POST ou PUT), url, formato (query, form ou json), campo_nome[] et campo_valor[] (chaque valeur avec {titulo} et {mensagem}), corpo_json (facultatif), cabecalho_nome[] et cabecalho_valor[] (stockés chiffrés ; vide garde la valeur stockée) ; email : para (un ou plusieurs, séparés par des virgules) ; webpush : usuario_id (quelqu\'un qui voit la collection : va vers ses appareils). Hors des collections du master, l\'adresse du webhook doit être sur internet (rien du réseau interne du serveur)',
        'curl -u lucas:senha -d recurso=destinos -d acao=salvar -d id=0 -d tipo=webhook -d "nome=Telegram" -d metodo=GET --data-urlencode "url=https://api.telegram.org/bot<token>/sendMessage" -d formato=query -d "campo_nome[]=chat_id" -d "campo_valor[]=123" -d "campo_nome[]=text" --data-urlencode "campo_valor[]={mensagem}" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=destinos -d acao=salvar -d id=0 -d tipo=webhook -d "nome=Telegram" -d metodo=GET --data-urlencode "url=https://api.telegram.org/bot<token>/sendMessage" -d formato=query -d "campo_nome[]=chat_id" -d "campo_valor[]=123" -d "campo_nome[]=text" --data-urlencode "campo_valor[]={mensagem}" http://servidor/relojoeiro/api.php',
        'id, qual (texto: uma mensagem de teste; manha ou noite: a mensagem de hoje desse horário, como ela sai por ele)' => 'id, qual (texto : un message de test ; manha ou noite : le message du jour pour cet horaire, tel qu\'il sort par elle)',
        'curl -u lucas:senha -d recurso=destinos -d acao=testar -d id=1 -d qual=manha http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=destinos -d acao=testar -d id=1 -d qual=manha http://servidor/relojoeiro/api.php',
        'id, confirmar=1' => 'id, confirmar=1',
        'curl -u lucas:senha -d recurso=destinos -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=destinos -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'id (0 cria), tipo (google, caldav, outlook ou ics; só ao criar), nome, ativa (1 ou 0), janela_dias (1 a 365: quantos dias à frente ficam na agenda), idioma, modelo (o título na primeira linha, a descrição no resto, com as âncoras), envia[] (os tipos que ela recebe); google: calendario_id, chave_json (o JSON da conta de serviço, guardado cifrado; o caminho de um arquivo no servidor, só o master); caldav: url (o endereço do calendário), usuario, senha (no iCloud, uma senha de app; guardada cifrada; vazio mantém); outlook: calendario_id (vazio: o calendário principal), e depois outlook_conectar; ics: nada (o link sai pronto)' => 'id (0 crée), tipo (google, caldav, outlook ou ics ; seulement à la création), nome, ativa (1 ou 0), janela_dias (1 à 365 : combien de jours à l\'avance restent dans l\'agenda), idioma, modelo (le titre sur la première ligne, la description dans le reste, avec les ancres), envia[] (les types qu\'elle reçoit) ; google : calendario_id, chave_json (le JSON du compte de service, stocké chiffré ; le chemin d\'un fichier sur le serveur, seulement le master) ; caldav : url (l\'adresse du calendrier), usuario, senha (sur iCloud, un mot de passe d\'application ; stocké chiffré ; vide le garde) ; outlook : calendario_id (vide : le calendrier principal), puis outlook_conectar ; ics : rien (le lien sort tout prêt)',
        'curl -u lucas:senha -d recurso=agendas -d acao=salvar -d id=0 -d tipo=caldav -d "nome=iCloud" --data-urlencode "url=https://caldav.icloud.com/123/calendars/relogios/" -d usuario=eu@icloud.com -d senha=abcd-efgh-ijkl-mnop http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=salvar -d id=0 -d tipo=caldav -d "nome=iCloud" --data-urlencode "url=https://caldav.icloud.com/123/calendars/relogios/" -d usuario=eu@icloud.com -d senha=abcd-efgh-ijkl-mnop http://servidor/relojoeiro/api.php',
        'id: deixa a agenda igual ao que tem de estar nela agora (cria, atualiza e apaga os eventos do sistema); o cron faz sozinho de manhã e à noite' => 'id : met l\'agenda dans l\'état où elle doit être maintenant (crée, met à jour et efface les événements du système) ; le cron le fait tout seul le matin et le soir',
        'curl -u lucas:senha -d recurso=agendas -d acao=sincronizar -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=sincronizar -d id=1 http://servidor/relojoeiro/api.php',
        'id: cria um evento de teste daqui a 10 minutos' => 'id : crée un événement de test dans 10 minutes',
        'curl -u lucas:senha -d recurso=agendas -d acao=teste_criar -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=teste_criar -d id=1 http://servidor/relojoeiro/api.php',
        'id: remove o evento de teste' => 'id : retire l\'événement de test',
        'curl -u lucas:senha -d recurso=agendas -d acao=teste_remover -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=teste_remover -d id=1 http://servidor/relojoeiro/api.php',
        'id (uma agenda ICS): gera outro link; o antigo para de funcionar' => 'id (une agenda ICS) : génère un autre lien ; l\'ancien cesse de fonctionner',
        'curl -u lucas:senha -d recurso=agendas -d acao=novo_link -d id=3 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=novo_link -d id=3 http://servidor/relojoeiro/api.php',
        'id (uma agenda do Outlook): devolve url, o endereço da Microsoft para entrar na conta e autorizar; a Microsoft volta para recurso=outlook_retorno' => 'id (une agenda Outlook) : renvoie url, l\'adresse de Microsoft pour se connecter au compte et autoriser ; Microsoft revient vers recurso=outlook_retorno',
        'curl -u lucas:senha -d recurso=agendas -d acao=outlook_conectar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=outlook_conectar -d id=4 http://servidor/relojoeiro/api.php',
        'id, confirmar=1 (os eventos que o sistema criou nela ficam lá)' => 'id, confirmar=1 (les événements que le système y a créés y restent)',
        'curl -u lucas:senha -d recurso=agendas -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=agendas -d acao=excluir -d id=2 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'login, senha (6 caracteres ou mais; login que existe: troca a senha); ou login e senha_hash (o hash de outro sistema, bcrypt ou argon2: o usuário entra com a senha de lá; veja senhas). A conta nova (só o master cria): email, idioma, colecao_nova (modelo: uma coleção com o conjunto inicial, o padrão; vazia: uma coleção sem nada; nenhuma: sem coleção). A conta criada pelo master é oficial (não vence). O primeiro usuário sai pelo token (sem usuários, o login não entra) e é o master. Quem não é o master só troca a própria senha' => 'login, senha (6 caractères ou plus ; identifiant qui existe : change le mot de passe) ; ou login et senha_hash (le hash d\'un autre système, bcrypt ou argon2 : l\'utilisateur entre avec le mot de passe de là-bas ; voir senhas). Le nouveau compte (seul le master le crée) : email, idioma, colecao_nova (modelo : une collection avec l\'ensemble initial, le défaut ; vazia : une collection vide ; nenhuma : sans collection). Le compte créé par le master est officiel (il n\'expire pas). Le premier utilisateur se crée par le jeton (sans utilisateurs, l\'identifiant n\'entre pas) et c\'est le master. Qui n\'est pas le master ne change que son propre mot de passe',
        'curl -u lucas:senha -d recurso=usuarios -d acao=salvar -d login=visitante -d senha=segredo123 -d email=visitante@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=salvar -d login=visitante -d senha=segredo123 -d email=visitante@exemplo.com http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login; novo_login, email, idioma, papel (master ou comum; sobra sempre um master; o master não vence)' => '(seulement le master) usuario_id ou login ; novo_login, email, idioma, papel (master ou comum ; il reste toujours un master ; le master n\'expire pas)',
        'curl -u lucas:senha -d recurso=usuarios -d acao=alterar -d login=visitante -d email=novo@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=alterar -d login=visitante -d email=novo@exemplo.com http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login: a conta de demonstração vira oficial (não vence mais)' => '(seulement le master) usuario_id ou login : le compte de démonstration devient officiel (il n\'expire plus)',
        'curl -u lucas:senha -d recurso=usuarios -d acao=oficializar -d login=visitante http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=oficializar -d login=visitante http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login, dias (1 a 3650): soma os dias ao vencimento (ou a partir de hoje, se já venceu); os avisos de vencimento recomeçam' => '(seulement le master) usuario_id ou login, dias (1 à 3650) : ajoute les jours à l\'expiration (ou à partir d\'aujourd\'hui, s\'il a déjà expiré) ; les avis d\'expiration recommencent',
        'curl -u lucas:senha -d recurso=usuarios -d acao=prorrogar -d login=visitante -d dias=30 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=prorrogar -d login=visitante -d dias=30 http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login, dias (padrão: DEMO_DIAS): a conta oficial volta a ser de demonstração, vencendo daqui a esses dias' => '(seulement le master) usuario_id ou login, dias (défaut : DEMO_DIAS) : le compte officiel redevient de démonstration, expirant dans ce nombre de jours',
        'curl -u lucas:senha -d recurso=usuarios -d acao=voltar_demo -d login=visitante -d dias=15 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=voltar_demo -d login=visitante -d dias=15 http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login, bloqueado (1, o padrão: não entra mais, nem pelo token pessoal; 0: desbloqueia); não o próprio' => '(seulement le master) usuario_id ou login, bloqueado (1, le défaut : il n\'entre plus, pas même par le jeton personnel ; 0 : débloque) ; pas soi-même',
        'curl -u lucas:senha -d recurso=usuarios -d acao=bloquear -d login=visitante -d bloqueado=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=bloquear -d login=visitante -d bloqueado=1 http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login (o dono de agora), colecao_id, para (o login do novo dono): a coleção passa para o outro, com tudo; a árvore vai junto quando só ela a usa; senão, o novo dono ganha uma cópia da árvore, e a coleção passa para a cópia' => '(seulement le master) usuario_id ou login (le propriétaire actuel), colecao_id, para (l\'identifiant du nouveau propriétaire) : la collection passe à l\'autre, avec tout ; l\'arbre part avec elle quand elle seule l\'utilise ; sinon, le nouveau propriétaire reçoit une copie de l\'arbre, et la collection passe à la copie',
        'curl -u lucas:senha -d recurso=usuarios -d acao=transferir -d login=lucas -d colecao_id=3 -d para=maria http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=transferir -d login=lucas -d colecao_id=3 -d para=maria http://servidor/relojoeiro/api.php',
        '(só o master) usuario_id ou login; colecao_id (membro de uma coleção) ou dono_id (ou dono, o login: todas as coleções desse dono, também as que vierem)' => '(seulement le master) usuario_id ou login ; colecao_id (membre d\'une collection) ou dono_id (ou dono, l\'identifiant : toutes les collections de ce propriétaire, aussi celles à venir)',
        'curl -u lucas:senha -d recurso=usuarios -d acao=dar_acesso -d login=maria -d dono=lucas http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=dar_acesso -d login=maria -d dono=lucas http://servidor/relojoeiro/api.php',
        '(só o master) login (ou usuario_id), confirmar=1: o usuário sai com tudo o que é dele (as coleções, as árvores, os relógios, os arquivos, os acessos, os tokens); não o próprio; sobra sempre um master' => '(seulement le master) login (ou usuario_id), confirmar=1 : l\'utilisateur part avec tout ce qui est à lui (les collections, les arbres, les montres, les fichiers, les accès, les jetons) ; pas soi-même ; il reste toujours un master',
        'curl -u lucas:senha -d recurso=usuarios -d acao=excluir -d login=visitante -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=excluir -d login=visitante -d confirmar=1 http://servidor/relojoeiro/api.php',
        'email, idioma (vazio: o da coleção), senha_atual e senha (a nova, 6 caracteres ou mais); só o que vier muda' => 'email, idioma (vide : celle de la collection), senha_atual et senha (le nouveau, 6 caractères ou plus) ; seul ce qui est envoyé change',
        'curl -u lucas:senha -d recurso=conta -d acao=alterar -d email=lucas@exemplo.com -d idioma=pt-BR http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=alterar -d email=lucas@exemplo.com -d idioma=pt-BR http://servidor/relojoeiro/api.php',
        'nome (onde ele vai ser usado): devolve token, que só aparece agora; ele vale como o seu login (cabeçalho X-Api-Token)' => 'nome (où il sera utilisé) : renvoie token, qui n\'apparaît que maintenant ; il vaut comme votre identifiant (en-tête X-Api-Token)',
        'curl -u lucas:senha -d recurso=conta -d acao=token_criar -d "nome=Atalho do celular" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=token_criar -d "nome=Atalho do celular" http://servidor/relojoeiro/api.php',
        'id (um token seu): quem o usava perde o acesso' => 'id (un de vos jetons) : qui l\'utilisait perd l\'accès',
        'curl -u lucas:senha -d recurso=conta -d acao=token_revogar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=token_revogar -d id=2 http://servidor/relojoeiro/api.php',
        'nome (o aparelho; vazio: o navegador que pediu): o aplicativo no celular. Cria a chave deste aparelho, grava o hash dela e devolve a chave num cookie (aparelho: só HTTP, um ano, na pasta do sistema); daí em diante o pedido que chega com o cookie, sem o login do site, entra como você. Devolve id' => 'nome (l\'appareil ; vide : le navigateur qui a demandé) : l\'application sur le téléphone. Crée la clé de cet appareil, enregistre son hash et renvoie la clé dans un cookie (aparelho : HTTP seulement, un an, dans le dossier du système) ; dès lors la requête qui arrive avec le cookie, sans le login du site, entre comme vous. Renvoie id',
        'curl -u lucas:senha -c cookies.txt -d recurso=conta -d acao=aparelho_lembrar -d "nome=Celular" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -c cookies.txt -d recurso=conta -d acao=aparelho_lembrar -d "nome=Celular" http://servidor/relojoeiro/api.php',
        'id (um aparelho seu; vazio: o aparelho deste pedido, pelo cookie): a chave deixa de valer, e o cookie deste navegador é apagado se era ele. Trocar a senha esquece todos' => 'id (un de vos appareils ; vide : l\'appareil de cette requête, par le cookie) : la clé cesse de valoir, et le cookie de ce navigateur est effacé si c\'était lui. Changer le mot de passe les oublie tous',
        'curl -u lucas:senha -d recurso=conta -d acao=aparelho_esquecer -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=aparelho_esquecer -d id=1 http://servidor/relojoeiro/api.php',
        'endpoint (https), p256dh e auth (a inscrição do navegador, como o PushManager entrega), aparelho (um nome): o aparelho passa a receber as notificações dos destinos Web Push que apontam para você' => 'endpoint (https), p256dh et auth (l\'inscription du navigateur, telle que le PushManager la livre), aparelho (un nom) : l\'appareil se met à recevoir les notifications des destinations Web Push qui pointent vers vous',
        'curl -u lucas:senha -d recurso=conta -d acao=push_inscrever --data-urlencode endpoint=https://fcm.googleapis.com/fcm/send/... -d p256dh=BN... -d auth=k3... http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=push_inscrever --data-urlencode endpoint=https://fcm.googleapis.com/fcm/send/... -d p256dh=BN... -d auth=k3... http://servidor/relojoeiro/api.php',
        'id (ou endpoint): o aparelho deixa de receber' => 'id (ou endpoint) : l\'appareil cesse de recevoir',
        'curl -u lucas:senha -d recurso=conta -d acao=push_cancelar -d id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=push_cancelar -d id=1 http://servidor/relojoeiro/api.php',
        '(nada): manda uma notificação de teste para os seus aparelhos' => '(rien) : envoie une notification de test à vos appareils',
        'curl -u lucas:senha -d recurso=conta -d acao=push_testar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=push_testar http://servidor/relojoeiro/api.php',
        '(só o master) para (vazio: só as conexões, sem mandar nada): conecta e entra no SMTP, no IMAP (e confere a pasta Enviados) e no POP, os que estiverem configurados, e manda um e-mail de teste para o endereço. A resposta traz teste: metodo, remetente, smtp, imap, pop e envio (cada um null, se não houve, ou {ok, erro}), registro (a conversa com os servidores, linha a linha, sem a senha nem o usuário em base64) e config (o mesmo que o email do recurso=conta). Sem o envio configurado, a resposta é um erro, com teste.config dizendo o que falta' => '(seulement le master) para (vide : seulement les connexions, sans rien envoyer) : se connecte et s\'authentifie au SMTP, à l\'IMAP (et vérifie le dossier Envoyés) et au POP, ceux qui sont configurés, et envoie un e-mail de test à l\'adresse. La réponse apporte teste : metodo, remetente, smtp, imap, pop et envio (chacun null, s\'il n\'a pas eu lieu, ou {ok, erro}), registro (la conversation avec les serveurs, ligne par ligne, sans le mot de passe ni l\'utilisateur en base64) et config (la même chose que l\'email du recurso=conta). Sans envoi configuré, la réponse est une erreur, avec teste.config qui dit ce qui manque',
        'curl -u lucas:senha -d recurso=conta -d acao=email_testar -d para=lucas@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=email_testar -d para=lucas@exemplo.com http://servidor/relojoeiro/api.php',
        '(só o master; nada): gera um par de chaves do Web Push; a resposta traz config (as duas linhas para o config.php) e chaves' => '(seulement le master ; rien) : génère une paire de clés du Web Push ; la réponse apporte config (les deux lignes pour le config.php) et chaves',
        'curl -u lucas:senha -d recurso=conta -d acao=vapid_gerar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=vapid_gerar http://servidor/relojoeiro/api.php',
        'confirmar=1: a sua conta sai com tudo o que é dela (as coleções, as árvores, os relógios, os arquivos, os acessos, os tokens); sobra sempre um master' => 'confirmar=1 : votre compte part avec tout ce qui est à lui (les collections, les arbres, les montres, les fichiers, les accès, les jetons) ; il reste toujours un master',
        'curl -u lucas:senha -d recurso=conta -d acao=excluir -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=conta -d acao=excluir -d confirmar=1 http://servidor/relojoeiro/api.php',
        'nome, opcao (modelo: com o conjunto inicial, numa árvore nova, o padrão; vazia: numa árvore nova só com a raiz; arvore: numa árvore sua que já existe, com arvore_id: o cadastro fica em comum com as outras coleções dela); o master cria para outro com dono_id. A resposta traz id e arvore_id' => 'nome, opcao (modelo : avec l\'ensemble initial, dans un nouvel arbre, le défaut ; vazia : dans un nouvel arbre avec seulement la racine ; arvore : dans un de vos arbres qui existe déjà, avec arvore_id : les définitions sont partagées avec ses autres collections) ; le master crée pour un autre avec dono_id. La réponse apporte id et arvore_id',
        'curl -u lucas:senha -d recurso=colecoes -d acao=criar -d "nome=Relógios do meu pai" -d opcao=modelo http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=criar -d "nome=Relógios do meu pai" -d opcao=modelo http://servidor/relojoeiro/api.php',
        'id, nome (não repete entre as coleções do dono)' => 'id, nome (ne se répète pas entre les collections du propriétaire)',
        'curl -u lucas:senha -d recurso=colecoes -d acao=renomear -d id=3 -d "nome=Herança" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=renomear -d id=3 -d "nome=Herança" http://servidor/relojoeiro/api.php',
        'id, confirmar=1: a coleção sai com tudo o que é dela (os relógios, o histórico, o plano, os destinos, as agendas, os arquivos); a árvore fica' => 'id, confirmar=1 : la collection part avec tout ce qui est à elle (les montres, l\'historique, le plan, les destinations, les agendas, les fichiers) ; l\'arbre reste',
        'curl -u lucas:senha -d recurso=colecoes -d acao=excluir -d id=3 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=excluir -d id=3 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'arvore_id, nome: uma cópia da árvore inteira (os grupos e o cadastro deles), sem coleção; a resposta traz arvore_id' => 'arvore_id, nome : une copie de l\'arbre entier (les groupes et leurs définitions), sans collection ; la réponse apporte arvore_id',
        'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_copiar -d arvore_id=1 -d "nome=Grupos para testes" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_copiar -d arvore_id=1 -d "nome=Grupos para testes" http://servidor/relojoeiro/api.php',
        'arvore_id, nome' => 'arvore_id, nome',
        'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_renomear -d arvore_id=1 -d "nome=Meus grupos" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_renomear -d arvore_id=1 -d "nome=Meus grupos" http://servidor/relojoeiro/api.php',
        'arvore_id, confirmar=1: a árvore sai com o cadastro dela e com as coleções que a usam (e tudo delas)' => 'arvore_id, confirmar=1 : l\'arbre part avec ses définitions et avec les collections qui l\'utilisent (et tout ce qui est à elles)',
        'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_excluir -d arvore_id=9 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=colecoes -d acao=arvore_excluir -d arvore_id=9 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'usuario_id; colecao_id (membro de uma coleção sua) ou dono_id (ou dono, o login: o acesso a tudo seu), confirmar=1: a pessoa deixa de ver; nada mais é apagado. Só o dono (ou o master)' => 'usuario_id ; colecao_id (membre d\'une de vos collections) ou dono_id (ou dono, l\'identifiant : l\'accès à tout ce qui est à vous), confirmar=1 : la personne cesse de voir ; rien d\'autre n\'est effacé. Seulement le propriétaire (ou le master)',
        'curl -u lucas:senha -d recurso=acessos -d acao=remover -d usuario_id=5 -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessos -d acao=remover -d usuario_id=5 -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'colecao_id ou dono_id (ou dono), confirmar=1: você deixa de ver (o dono não sai da própria coleção: ele a exclui ou o master a transfere)' => 'colecao_id ou dono_id (ou dono), confirmar=1 : vous cessez de voir (le propriétaire ne quitte pas sa propre collection : il la supprime ou le master la transfère)',
        'curl -u maria:senha -d recurso=acessos -d acao=sair -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=acessos -d acao=sair -d colecao_id=1 -d confirmar=1 http://servidor/relojoeiro/api.php',
        'email; colecao_id (uma coleção que você vê) ou dono_id (ou dono: tudo de um dono; só o próprio dono ou o master): o convite do dono (ou do master) sai na hora, por e-mail, com o link (vale CONVITE_DIAS dias; sem e-mail no servidor, a resposta traz link, para você mandar); o de um membro espera o dono aprovar' => 'email ; colecao_id (une collection que vous voyez) ou dono_id (ou dono : tout ce qui est à un propriétaire ; seulement le propriétaire lui-même ou le master) : l\'invitation du propriétaire (ou du master) part aussitôt, par e-mail, avec le lien (valable CONVITE_DIAS jours ; sans e-mail sur le serveur, la réponse apporte link, pour que vous l\'envoyiez) ; celle d\'un membre attend l\'approbation du propriétaire',
        'curl -u lucas:senha -d recurso=convites -d acao=convidar -d email=amigo@exemplo.com -d colecao_id=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=convidar -d email=amigo@exemplo.com -d colecao_id=1 http://servidor/relojoeiro/api.php',
        'id (um convite de membro, para uma coleção sua): aprova e manda o link' => 'id (une invitation de membre, pour une de vos collections) : approuve et envoie le lien',
        'curl -u lucas:senha -d recurso=convites -d acao=aprovar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=aprovar -d id=4 http://servidor/relojoeiro/api.php',
        'id: o convite sai' => 'id : l\'invitation part',
        'curl -u lucas:senha -d recurso=convites -d acao=recusar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=recusar -d id=4 http://servidor/relojoeiro/api.php',
        'id (um convite já aprovado): manda de novo, com um link novo (o anterior para de valer)' => 'id (une invitation déjà approuvée) : l\'envoie de nouveau, avec un nouveau lien (le précédent cesse d\'être valable)',
        'curl -u lucas:senha -d recurso=convites -d acao=reenviar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=reenviar -d id=4 http://servidor/relojoeiro/api.php',
        'id (quem convidou, ou o dono): o convite sai' => 'id (qui a invité, ou le propriétaire) : l\'invitation part',
        'curl -u lucas:senha -d recurso=convites -d acao=cancelar -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=convites -d acao=cancelar -d id=4 http://servidor/relojoeiro/api.php',
        'token (o do link): quem já tem conta aceita o convite e passa a ver o que ele dá (quem não tem cria a conta pelo link: recurso=cadastro)' => 'token (celui du lien) : qui a déjà un compte accepte l\'invitation et se met à voir ce qu\'elle donne (qui n\'en a pas crée le compte par le lien : recurso=cadastro)',
        'curl -u maria:senha -d recurso=convites -d acao=aceitar -d token=Xy3... http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=convites -d acao=aceitar -d token=Xy3... http://servidor/relojoeiro/api.php',
        'colecao_id (o código de uma coleção) ou dono_id (o código de um dono: tudo dele, também o que vier), o código que o dono passou (nunca o login: nada no pedido diz quem tem conta; um código que não serve dá sempre o mesmo erro), mensagem (um recado para o dono): o dono recebe um e-mail; o pedido espera CONVITE_DIAS dias; a resposta e a lista dos seus pedidos mostram só o código até a aprovação' => 'colecao_id (le code d\'une collection) ou dono_id (le code d\'un propriétaire : tout ce qui est à lui, aussi ce qui viendra), le code donné par le propriétaire (jamais l\'identifiant : rien dans la demande ne dit qui a un compte ; un code qui ne sert pas donne toujours la même erreur), mensagem (un mot pour le propriétaire) : le propriétaire reçoit un e-mail ; la demande attend CONVITE_DIAS jours ; la réponse et la liste de vos demandes ne montrent que le code jusqu\'à l\'approbation',
        'curl -u maria:senha -d recurso=pedidos -d acao=pedir -d dono_id=1 -d "mensagem=Oi, é a Maria" http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=pedidos -d acao=pedir -d dono_id=1 -d "mensagem=Oi, é a Maria" http://servidor/relojoeiro/api.php',
        'id (o dono do alvo, ou o master): a pessoa passa a ver, e recebe um e-mail' => 'id (le propriétaire de la cible, ou le master) : la personne se met à voir, et reçoit un e-mail',
        'curl -u lucas:senha -d recurso=pedidos -d acao=aprovar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=pedidos -d acao=aprovar -d id=2 http://servidor/relojoeiro/api.php',
        'id: o pedido sai, e a pessoa recebe um e-mail' => 'id : la demande part, et la personne reçoit un e-mail',
        'curl -u lucas:senha -d recurso=pedidos -d acao=recusar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=pedidos -d acao=recusar -d id=2 http://servidor/relojoeiro/api.php',
        'id (um pedido seu)' => 'id (une de vos demandes)',
        'curl -u maria:senha -d recurso=pedidos -d acao=cancelar -d id=2 http://servidor/relojoeiro/api.php' => 'curl -u maria:senha -d recurso=pedidos -d acao=cancelar -d id=2 http://servidor/relojoeiro/api.php',
        '(sem login) login (até 60 caracteres, sem dois-pontos), senha (6 ou mais), email, idioma, opcao (modelo: uma coleção com o conjunto inicial; vazia: uma coleção sem nada; pedir: pedir acesso, com colecao_id ou dono_id, o código que o dono passou, e mensagem), convite (o token do link: a conta já vê o que o convite dá; opcao modelo ou nenhuma). Com o cadastro fechado (CADASTRO_ABERTO = false), só com convite. A conta é de demonstração por DEMO_DIAS dias (0: oficial), com aviso por e-mail 7 dias e 1 dia antes; vencida, o cron a apaga com tudo' => '(sans identifiant) login (jusqu\'à 60 caractères, sans deux-points), senha (6 ou plus), email, idioma, opcao (modelo : une collection avec l\'ensemble initial ; vazia : une collection vide ; pedir : demander un accès, avec colecao_id ou dono_id, le code donné par le propriétaire, et mensagem), convite (le jeton du lien : le compte voit déjà ce que l\'invitation donne ; opcao modelo ou nenhuma). Avec l\'inscription fermée (CADASTRO_ABERTO = false), seulement avec invitation. Le compte est de démonstration pendant DEMO_DIAS jours (0 : officiel), avec un avis par e-mail 7 jours et 1 jour avant ; expiré, le cron l\'efface avec tout',
        'curl -d recurso=cadastro -d acao=criar_conta -d login=maria -d senha=segredo123 -d email=maria@exemplo.com -d opcao=modelo http://servidor/relojoeiro/api.php' => 'curl -d recurso=cadastro -d acao=criar_conta -d login=maria -d senha=segredo123 -d email=maria@exemplo.com -d opcao=modelo http://servidor/relojoeiro/api.php',
        '(sem login) email (ou o login): manda o link para escolher uma senha nova (vale 2 horas); a resposta é a mesma exista a conta ou não' => '(sans identifiant) email (ou le login) : envoie le lien pour choisir un nouveau mot de passe (valable 2 heures) ; la réponse est la même que le compte existe ou non',
        'curl -d recurso=cadastro -d acao=esqueci_senha -d email=maria@exemplo.com http://servidor/relojoeiro/api.php' => 'curl -d recurso=cadastro -d acao=esqueci_senha -d email=maria@exemplo.com http://servidor/relojoeiro/api.php',
        '(sem login) token (o do link), senha (a nova)' => '(sans identifiant) token (celui du lien), senha (le nouveau)',
        'curl -d recurso=cadastro -d acao=nova_senha -d token=Ab9... -d senha=outra12345 http://servidor/relojoeiro/api.php' => 'curl -d recurso=cadastro -d acao=nova_senha -d token=Ab9... -d senha=outra12345 http://servidor/relojoeiro/api.php',
        '(nada): aplica as migrações pendentes, na ordem: o SQL de cada uma e, se ela tiver, o passo em PHP' => '(rien) : applique les migrations en attente, dans l\'ordre : le SQL de chacune et, si elle en a un, le pas en PHP',
        'curl -u lucas:senha -d recurso=migracoes -d acao=aplicar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=migracoes -d acao=aplicar http://servidor/relojoeiro/api.php',
        '(nada; lingua= escolhe o idioma, como em qualquer pedido: fora do português, o cadastro inicial sai nele e ele vira o idioma padrão, config.idioma): instala o banco do config.php, só num banco vazio (o schema.sql traduzido para o banco, com os passos em PHP das migrações), pelo token (antes da instalação não há usuários); a resposta traz comandos, tabelas e segundos. Depois: o primeiro usuário, em recurso=usuarios, acao=salvar' => '(rien ; lingua= choisit la langue, comme dans toute requête : hors du portugais, les définitions initiales sortent dans cette langue et elle devient la langue par défaut, config.idioma) : installe la base de config.php, seulement sur une base vide (le schema.sql traduit pour la base, avec les pas en PHP des migrations), par le jeton (avant l\'installation il n\'y a pas d\'utilisateurs) ; la réponse apporte comandos, tabelas et segundos. Ensuite : le premier utilisateur, dans recurso=usuarios, acao=salvar',
        'curl -H "X-Api-Token: segredo" -d recurso=instalacao -d acao=instalar http://servidor/relojoeiro/api.php' => 'curl -H "X-Api-Token: segredo" -d recurso=instalacao -d acao=instalar http://servidor/relojoeiro/api.php',
        'banco (o nome do banco antigo, MySQL/MariaDB), substituir (1: apaga antes os relógios e o histórico deste banco; obrigatório quando ele já tem relógios): traz a árvore, os relógios, as fotos, os usuários, os valores dos campos e o histórico, tudo numa transação (parou no meio: nada fica gravado); a resposta traz contagem (quantos de cada)' => 'banco (le nom de l\'ancienne base, MySQL/MariaDB), substituir (1 : efface avant les montres et l\'historique de cette base ; obligatoire quand elle a déjà des montres) : apporte l\'arbre, les montres, les photos, les utilisateurs, les valeurs des champs et l\'historique, le tout dans une transaction (arrêtée au milieu : rien n\'est enregistré) ; la réponse apporte contagem (combien de chaque)',
        'curl -u lucas:senha -d recurso=importacao -d acao=importar -d banco=relogios -d substituir=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=importacao -d acao=importar -d banco=relogios -d substituir=1 http://servidor/relojoeiro/api.php',
        '(nada): faz uma cópia agora na BACKUP_PASTA (as mais velhas que passam do BACKUP_MANTER saem); a resposta traz arquivo' => '(rien) : fait une copie maintenant dans BACKUP_PASTA (les plus anciennes qui dépassent BACKUP_MANTER sortent) ; la réponse apporte arquivo',
        'curl -u lucas:senha -d recurso=backup -d acao=fazer http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=backup -d acao=fazer http://servidor/relojoeiro/api.php',
        'arquivo (o nome de uma cópia da pasta): antes, guarda uma cópia do que está agora; depois, num passo só, troca todos os registros pelos da cópia (se algo falha, nada muda); só uma cópia da mesma versão do banco; sem o conteúdo dos documentos, eles voltam sem a cópia no banco e o cron refaz a pedida' => 'arquivo (le nom d\'une copie du dossier) : avant, garde une copie de l\'état actuel ; ensuite, en une seule étape, remplace tous les enregistrements par ceux de la copie (si quelque chose échoue, rien ne change) ; seulement une copie de la même version de la base ; sans le contenu des documents, ils reviennent sans la copie dans la base et le cron refait celle qui est demandée',
        'curl -u lucas:senha -d recurso=backup -d acao=restaurar -d arquivo=relojoeiro-2026-10-12-200000.jsonl.gz http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=backup -d acao=restaurar -d arquivo=relojoeiro-2026-10-12-200000.jsonl.gz http://servidor/relojoeiro/api.php',
        'a senha não fica guardada em lugar nenhum: fica só o hash dela, feito pelo password_hash do PHP com PASSWORD_DEFAULT (bcrypt). O hash tem 60 caracteres: $2y$, o custo com dois dígitos e $ (12 é 2^12 rodadas), o sal (22 caracteres, sorteado a cada senha) e o resultado (31). O sal e o custo vão dentro do próprio hash' => 'le mot de passe n\'est conservé nulle part : il ne reste que son hash, fait par password_hash de PHP avec PASSWORD_DEFAULT (bcrypt). Le hash a 60 caractères : $2y$, le coût sur deux chiffres et $ (12, c\'est 2^12 tours), le sel (22 caractères, tiré au sort à chaque mot de passe) et le résultat (31). Le sel et le coût vont à l\'intérieur du hash lui-même',
        'o hash não se desfaz em senha (é de mão única). Para conferir, calcula-se o bcrypt da senha digitada com o sal e o custo que estão no hash e compara-se com o resultado: é o que o password_verify do PHP faz no login. A mesma senha dá hashes diferentes a cada cálculo (o sal muda), e todos conferem' => 'le hash ne se défait pas en mot de passe (il est à sens unique). Pour vérifier, on calcule le bcrypt du mot de passe saisi avec le sel et le coût qui sont dans le hash et on compare avec le résultat : c\'est ce que fait password_verify de PHP à la connexion. Le même mot de passe donne des hash différents à chaque calcul (le sel change), et tous correspondent',
        'leve o login e o senha_hash de cada um (recurso=usuarios, ou a resposta sem recurso) e, no outro sistema, confira a senha digitada contra o hash com o bcrypt dele: cada um entra lá com a mesma senha de sempre. $2y$ (PHP) e $2b$ (Python, Node, Java, C#...) são o mesmo cálculo; se a biblioteca recusar o $2y$, troque o começo por $2b$' => 'emportez le login et le senha_hash de chacun (recurso=usuarios, ou la réponse sans ressource) et, dans l\'autre système, vérifiez le mot de passe saisi contre le hash avec son bcrypt : chacun y entre avec le même mot de passe que toujours. $2y$ (PHP) et $2b$ (Python, Node, Java, C#...) sont le même calcul ; si la bibliothèque refuse le $2y$, remplacez le début par $2b$',
        'POST recurso=usuarios, acao=salvar, login e senha_hash (um bcrypt $2y$, $2b$ ou $2a$, ou um argon2): o usuário entra aqui com a senha que tinha lá, sem ninguém saber qual é (o $2b$ é guardado como $2y$, o mesmo cálculo)' => 'POST recurso=usuarios, acao=salvar, login et senha_hash (un bcrypt $2y$, $2b$ ou $2a$, ou un argon2) : l\'utilisateur entre ici avec le mot de passe qu\'il avait là-bas, sans que personne sache lequel (le $2b$ est gardé comme $2y$, le même calcul)',
        'conferir: password_verify($senha, $hash); fazer: password_hash($senha, PASSWORD_DEFAULT)' => 'vérifier : password_verify($senha, $hash) ; faire : password_hash($senha, PASSWORD_DEFAULT)',
        'pip install bcrypt; conferir: bcrypt.checkpw(senha.encode(), hash.encode()); fazer: bcrypt.hashpw(senha.encode(), bcrypt.gensalt()).decode()' => 'pip install bcrypt ; vérifier : bcrypt.checkpw(senha.encode(), hash.encode()) ; faire : bcrypt.hashpw(senha.encode(), bcrypt.gensalt()).decode()',
        'npm install bcryptjs; conferir: require("bcryptjs").compareSync(senha, hash); fazer: require("bcryptjs").hashSync(senha, 12)' => 'npm install bcryptjs ; vérifier : require("bcryptjs").compareSync(senha, hash) ; faire : require("bcryptjs").hashSync(senha, 12)',
        'Spring Security: new BCryptPasswordEncoder().matches(senha, hash) (com jBCrypt, BCrypt.checkpw(senha, hash) trocando $2y$ por $2a$)' => 'Spring Security : new BCryptPasswordEncoder().matches(senha, hash) (avec jBCrypt, BCrypt.checkpw(senha, hash) en remplaçant $2y$ par $2a$)',
        'BCrypt.Net-Next: BCrypt.Net.BCrypt.Verify(senha, hash)' => 'BCrypt.Net-Next : BCrypt.Net.BCrypt.Verify(senha, hash)',
        'em qualquer consulta: a resposta sem parâmetros e todos os recursos' => 'dans toute consultation : la réponse sans paramètres et toutes les ressources',
        'incluir=relogios,plano: só essas partes da resposta' => 'incluir=relogios,plano : seulement ces parties de la réponse',
        'excluir=motor,criterios: a resposta sem essas partes' => 'excluir=motor,criterios : la réponse sans ces parties',
        'as regras valem para uma lista da resposta, pelo caminho dela entre os colchetes: relogios, plano, avisos, eventos, usuarios, cron.execucoes, criterios.notas, criterios.conjuntos, agendas_desejadas, relogios.lancamentos, relogios.avisos, relogios.linha_do_tempo, relogio.leituras (na ficha)...; lista dentro de lista vale em cada item' => 'les règles valent pour une liste de la réponse, par son chemin entre les crochets : relogios, plano, avisos, eventos, usuarios, cron.execucoes, criterios.notas, criterios.conjuntos, agendas_desejadas, relogios.lancamentos, relogios.avisos, relogios.linha_do_tempo, relogio.leituras (dans la fiche)... ; une liste dans une liste vaut pour chaque élément',
        'qualquer campo do item; com ponto entra num objeto (compra.valor) ou, numa lista de itens com identificador, no item daquele identificador (formulas.energia.valor, campos.loja.valor)' => 'n\'importe quel champ de l\'élément ; avec un point on entre dans un objet (compra.valor) ou, dans une liste d\'éléments avec identifiant, dans l\'élément de cet identifiant (formulas.energia.valor, campos.loja.valor)',
        'igual a v (vários separados por vírgula: igual a um deles; numa lista de valores, se algum for)' => 'égal à v (plusieurs séparés par une virgule : égal à l\'un d\'eux ; dans une liste de valeurs, si l\'un l\'est)',
        'a partir de v (números como números; datas e textos como texto)' => 'à partir de v (les nombres comme nombres ; les dates et les textes comme texte)',
        'até v (uma data sem hora vai até o fim daquele dia)' => 'jusqu\'à v (une date sans heure va jusqu\'à la fin de ce jour)',
        'o texto contém t' => 'le texte contient t',
        'diferente de v (vários separados por vírgula: de todos)' => 'différent de v (plusieurs séparés par une virgule : de tous)',
        'vazio (1) ou preenchido (0)' => 'vide (1) ou rempli (0)',
        'o texto t em qualquer campo do item' => 'le texte t dans n\'importe quel champ de l\'élément',
        'ordena pelo campo; -campo: do maior para o menor; vários separados por vírgula' => 'trie par le champ ; -campo : du plus grand au plus petit ; plusieurs séparés par une virgule',
        'N itens por página, a página P' => 'N éléments par page, la page P',
        'só esses campos de cada item (com ponto também)' => 'seulement ces champs de chaque élément (avec un point aussi)',
        'textos sem diferença de maiúsculas e acentos; verdadeiro e falso valem 1 e 0; filtros juntos: o item tem de passar em todos' => 'textes sans différence de majuscules ni d\'accents ; vrai et faux valent 1 et 0 ; filtres ensemble : l\'élément doit passer dans tous',
        'ganha _filtros: {listas: {caminho: {antes, passaram, devolvidos, pagina, limite}}, ignorados: [o caminho sem lista, a parte que não existe]}; com filtros, objetos vazios saem como listas vazias' => 'gagne _filtros : {listas: {caminho: {antes, passaram, devolvidos, pagina, limite}}, ignorados: [le chemin sans liste, la partie qui n\'existe pas]} ; avec des filtres, les objets vides sortent comme des listes vides',
        'limite, pagina, ordem e busca sem colchetes continuam sendo os do recurso (historico, cron)' => 'limite, pagina, ordem et busca sans crochets restent ceux de la ressource (historico, cron)',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][disponivel]=1&mostrar[relogios]=id,nome&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][disponivel]=1&mostrar[relogios]=id,nome&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][formulas.energia.valor][ate]=20&ordem[relogios]=formulas.energia.valor&mostrar[relogios]=nome,formulas.energia.valor&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][formulas.energia.valor][ate]=20&ordem[relogios]=formulas.energia.valor&mostrar[relogios]=nome,formulas.energia.valor&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][id]=10,12&f[relogios.lancamentos][tipo]=carga&f[relogios.lancamentos][inicio][de]=2026-09-01&mostrar[relogios]=nome,lancamentos&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][id]=10,12&f[relogios.lancamentos][tipo]=carga&f[relogios.lancamentos][inicio][de]=2026-09-01&mostrar[relogios]=nome,lancamentos&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][campos.loja.valor][contem]=aliexpress&mostrar[relogios]=nome,campos.valor_compra.valor&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][campos.loja.valor][contem]=aliexpress&mostrar[relogios]=nome,campos.valor_compra.valor&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=plano&f[plano][data][de]=2026-10-01&f[plano][data][ate]=2026-10-31&f[plano][relogio][contem]=xiaomi"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=plano&f[plano][data][de]=2026-10-01&f[plano][data][ate]=2026-10-31&f[plano][relogio][contem]=xiaomi"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=cron&f[cron.execucoes][teve_erro]=1&limite[cron.execucoes]=20&pagina[cron.execucoes]=2"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=cron&f[cron.execucoes][teve_erro]=1&limite[cron.execucoes]=20&pagina[cron.execucoes]=2"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=criterios&f[criterios.notas][nota][de]=50&ordem[criterios.notas]=-nota&mostrar[criterios.notas]=relogio,nota"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=criterios&f[criterios.notas][nota][de]=50&ordem[criterios.notas]=-nota&mostrar[criterios.notas]=relogio,nota"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=hoje&f[relogios][com_aviso]=1&mostrar[relogios]=nome,manutencao.nome"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=hoje&f[relogios][com_aviso]=1&mostrar[relogios]=nome,manutencao.nome"',
        '[] no caminho: uma lista (o campo é de cada item); <...>: uma chave que varia (o identificador de um campo, um estado, uma função...). Datas e horas no fuso do sistema (o FUSO do config.php; sem ele, o do PHP, date.timezone); null: sem valor. Números de tempo em segundos são inteiros.' => '[] dans le chemin : une liste (le champ est celui de chaque élément) ; <...> : une clé qui varie (l\'identifiant d\'un champ, un état, une fonction...). Dates et heures dans le fuseau du système (le FUSO de config.php ; sans lui, celui de PHP, date.timezone) ; null : sans valeur. Les nombres de temps en secondes sont entiers.',
        'os grupos, em ordem de árvore' => 'les groupes, en ordre d\'arbre',
        'o caminho por extenso ("Tradicional › Quartzo › Solar")' => 'le chemin en toutes lettres (« Traditionnel › Quartz › Solaire »)',
        'o número do grupo' => 'le numéro du groupe',
        'o nome do grupo' => 'le nom du groupe',
        'a posição entre os irmãos' => 'la position parmi les frères',
        'o grupo de cima; null: na raiz' => 'le groupe du dessus ; null : à la racine',
        'o nível na árvore (0: na raiz)' => 'le niveau dans l\'arbre (0 : à la racine)',
        'os avisos cadastrados (cada identificador pode ter uma versão por grupo)' => 'les alertes enregistrées (chaque identifiant peut avoir une version par groupe)',
        'a data na agenda: janela (só dentro da antecedência da agenda) ou sempre' => 'la date dans l\'agenda : janela (seulement dans l\'anticipation de l\'agenda) ou sempre',
        '1: o aviso vai pelo Telegram no minuto em que vence (uma vez, até ser resolvido); 0: só no alerta da manhã' => '1 : l\'alerte part par Telegram à la minute où elle arrive à échéance (une fois, jusqu\'à être résolue) ; 0 : seulement dans l\'alerte du matin',
        'com quantos dias antes ele entra "em breve" (número)' => 'combien de jours avant elle passe à « bientôt » (nombre)',
        'o aviso vale' => 'l\'alerte s\'applique',
        'vale quando: uma fórmula que diz para quais relógios do grupo o aviso vale (1 vale, 0 não; ex.: corda_manual = 0, só o automático sem corda); null: vale para todos' => 'vaut quand : une formule qui dit pour quelles montres du groupe l\'alerte vaut (1 vaut, 0 non ; ex. : corda_manual = 0, seulement l\'automatique sans remontage) ; null : vaut pour toutes',
        'na escala inteligente: nao, uso ou sempre' => 'dans le planning intelligent : nao, uso ou sempre',
        'a fórmula da data prevista' => 'la formule de la date prévue',
        'o número da versão' => 'le numéro de la version',
