        'como calcular o gasto da bateria, para todos os relógios da coleção: horas (pelas horas registradas, o motor original), robusto (pelas horas registradas, com leituras e cadastro), marcacao (pela marcação das leituras: duas taxas separadas), cadastro (só o cadastro) ou formulas (pelas fórmulas taxa_uso e taxa_repouso); vazio: vale o do relógio (o campo gasto_motor do cadastro), senão o padrão desse campo (o grupo), senão horas' => 'comment calculer la consommation de la batterie, pour toutes les montres de la collection : horas (par les heures enregistrées, le moteur d\'origine), robusto (par les heures enregistrées, avec relevés et fiche), marcacao (par le marquage des relevés : deux taux séparés), cadastro (la fiche seulement) ou formulas (par les formules taxa_uso et taxa_repouso) ; vide : celui de la montre vaut (le champ gasto_motor de la fiche), sinon la valeur par défaut de ce champ (le groupe), sinon horas',
        'a cópia dos documentos no banco, para a coleção inteira: todos (todo arquivo vai também para o banco), nenhum (nenhum vai, nem o que o relógio ou o arquivo pedem) ou vazio (cada relógio e cada arquivo decidem)' => 'la copie des documents dans la base, pour toute la collection : todos (chaque fichier va aussi dans la base), nenhum (aucun n\'y va, même pas ce que la montre ou le fichier demandent) ou vide (chaque montre et chaque fichier décident)',
