        'o destaque no alto da página Hoje: dia (o relógio do dia, o do plano) ou pulso (o relógio no pulso agora; sem nenhum no pulso, o do dia); vazio: dia' => 'la mise en avant en haut de la page Aujourd\'hui : dia (la montre du jour, celle du plan) ou pulso (la montre au poignet maintenant ; sans aucune au poignet, celle du jour) ; vide : dia',
