        '(verdadeiro ou falso) o modo usa o ciclo: um relógio só volta depois que todos os disponíveis do bloco passaram na semana (na escala, pelo período dela); dentro do ciclo, a forma de escolha decide a ordem' => '(vrai ou faux) le mode utilise le cycle : une montre ne revient qu\'une fois que toutes les disponibles du bloc sont passées dans la semaine (dans le planning, sur sa période) ; dans le cycle, la méthode de choix décide l\'ordre',
