        'o dia (texto AAAA-MM-DD)' => 'le jour (texte AAAA-MM-JJ)',
        'por que este relógio saiu neste dia, numa frase (a garantia de rodízio, a nota, o sorteio, a escolha à mão); null: o dia foi gravado antes de o sistema guardar o motivo' => 'pourquoi cette montre est sortie ce jour-là, en une phrase (la garantie de rotation, la note, le tirage, le choix à la main) ; null : le jour a été enregistré avant que le système garde le motif',
