        'os acessórios (como em recurso=acessorios): id, nome, tipo, tipo_texto, relogio_id (null: solto), relogio, observacao, criado' => 'les accessoires (comme dans recurso=acessorios) : id, nome, tipo, tipo_texto, relogio_id (null : libre), relogio, observacao, criado',
        'o número do acessório' => 'le numéro de l\'accessoire',
