        'quando foi cadastrado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'quand il a été enregistré (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'os relógios, com tudo o que se sabe de cada um' => 'les montres, avec tout ce que l\'on sait de chacune',
        'quando acaba, em ISO 8601 com o fuso (texto, ex.: 2026-10-02T18:40:00-03:00); null com o motivo' => 'quand elle s\'épuise, en ISO 8601 avec le fuseau (texte, ex. : 2026-10-02T18:40:00-03:00) ; null avec le motif',
        'quantos segundos faltam para acabar, a partir de calculado_em_unixtimestamp (número inteiro, em segundos; igual a autonomia_estimada); null com o motivo' => 'combien de secondes restent avant l\'épuisement, à partir de calculado_em_unixtimestamp (nombre entier, en secondes ; égal à autonomia_estimada) ; null avec le motif',
        'quando a energia chega a zero seguindo o plano (número inteiro: instante Unix (segundos desde 01/01/1970 UTC)); null com o motivo' => 'quand l\'énergie arrive à zéro en suivant le plan (nombre entier : instant Unix (secondes depuis le 01/01/1970 UTC)) ; null avec le motif',
        'quanto o relógio dura com a carga cheia, pela conta do sistema (número inteiro, em segundos): no smartwatch, pelo gasto em uso medido pelas leituras (a média da janela da Configuração), senão pelo informado; nos outros, igual à prevista; a diferença para a prevista mostra a bateria envelhecendo; a fórmula autonomia_atual' => 'combien de temps la montre dure avec la charge pleine, par le calcul du système (nombre entier, en secondes) : sur la smartwatch, par la consommation en usage mesurée par les lectures (la moyenne de la fenêtre de la Configuration), sinon par celle indiquée ; sur les autres, égale à la prévue ; la différence avec la prévue montre la batterie qui vieillit ; la formule autonomia_atual',
        'quanto ainda dura a partir de agora, seguindo o plano (número inteiro, em segundos): usado nos dias em que está no rodízio, guardado nos outros; o mesmo número de acaba_em_segundos; null com o motivo em motivos' => 'combien de temps il reste encore à partir de maintenant, en suivant le plan (nombre entier, en secondes) : en usage les jours où elle est dans la rotation, rangée les autres ; le même nombre que acaba_em_segundos ; null avec le motif dans motivos',
        'quanto o relógio dura com a carga cheia, pelo cadastro (número inteiro, em segundos): a autonomia do smartwatch, a reserva de marcha do mecânico, a reserva do solar ou a vida da pilha; a fórmula autonomia_prevista; null se falta o dado no cadastro' => 'combien de temps la montre dure avec la charge pleine, selon la fiche (nombre entier, en secondes) : l\'autonomie de la smartwatch, la réserve de marche de la mécanique, la réserve de la solaire ou la vie de la pile ; la formule autonomia_prevista ; null si la donnée manque dans la fiche',
        'os avisos do relógio agora (os que valem para ele e têm data prevista), do mais urgente ao mais distante' => 'les alertes de la montre maintenant (celles qui valent pour elle et ont une date prévue), de la plus urgente à la plus lointaine',
        'a data na agenda: janela (só dentro da antecedência da agenda) ou sempre (qualquer data); se vai pela agenda é a Configuração' => 'la date dans l\'agenda : janela (seulement dans l\'anticipation de l\'agenda) ou sempre (n\'importe quelle date) ; si elle part par l\'agenda, c\'est la Configuration',
        'verdadeiro: o aviso vai pelo Telegram no minuto em que vence (uma vez), além do alerta da manhã' => 'vrai : l\'alerte part par Telegram à la minute où elle arrive à échéance (une fois), en plus de l\'alerte du matin',
        'a data prevista, pela fórmula do aviso (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'la date prévue, par la formule de l\'alerte (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'na escala inteligente: nao, uso (conferido no relógio do dia) ou sempre (também nos guardados)' => 'dans le planning intelligent : nao, uso (vérifiée sur la montre du jour) ou sempre (aussi sur les rangées)',
        'atrasado (a data passou), em_breve (dentro da antecedência) ou ok' => 'atrasado (la date est passée), em_breve (dans l\'anticipation) ou ok',
