        'o aviso (corda, carregar, sol, pilha, revisao, garantia, carga_baixa, leitura, ou um que você cadastrou)' => 'l\'alerte (corda, carregar, sol, pilha, revisao, garantia, carga_baixa, leitura, ou une que vous avez enregistrée)',
        'o texto do cadastro, sem trocar as âncoras (só o {limite})' => 'le texte de la fiche, sans remplacer les repères (seulement le {limite})',
        'o nome do aviso ("Dar corda") — a âncora {acao}' => 'le nom de l\'alerte (« Remonter ») — le repère {acao}',
        'o tipo de lançamento que resolve o aviso (o botão na tela Hoje); null: nenhum' => 'le type de saisie qui résout l\'alerte (le bouton sur l\'écran Aujourd\'hui) ; null : aucun',
        'as horas da sessão que a escala simula para resolver o aviso (número; null: nenhuma)' => 'les heures de la session que le planning simule pour résoudre l\'alerte (nombre ; null : aucune)',
        'o valor do lançamento que a escala simula para resolver o aviso (leitura) (número; null: nenhum)' => 'la valeur de la saisie que le planning simule pour résoudre l\'alerte (lecture) (nombre ; null : aucune)',
        'o motivo por extenso, com {relogio}, {data}, {quando} e {limite} trocados — a âncora {motivo}' => 'le motif en toutes lettres, avec {relogio}, {data}, {quando} et {limite} remplacés — le repère {motivo}',
        'o lugar da árvore da versão do aviso usada (texto)' => 'le niveau de l\'arbre de la version de l\'alerte utilisée (texte)',
        'o instante em que as autonomias foram calculadas (número inteiro: instante Unix (segundos desde 01/01/1970 UTC)); segundos que faltam agora = acaba_em_unixtimestamp − hora atual' => 'l\'instant où les autonomies ont été calculées (nombre entier : instant Unix (secondes depuis le 01/01/1970 UTC)) ; secondes qui restent maintenant = acaba_em_unixtimestamp − heure actuelle',
