        'verdadeiro: o relógio pede a cópia no banco de todos os documentos dele (o segundo dos três níveis da cópia; a Configuração da coleção, documentos_copia, se escolhe, vale por cima)' => 'vrai : la montre demande la copie dans la base de tous ses documents (le deuxième des trois niveaux de la copie ; la Configuration de la collection, documentos_copia, si elle choisit, prime)',
        'a situação na coleção: colecao (na coleção), desejado (a lista de desejos), emprestado, vendido ou arquivado; fora da coleção, disponivel é sempre falso' => 'le statut dans la collection : colecao (dans la collection), desejado (la liste d\'envies), emprestado, vendido ou arquivado ; hors de la collection, disponivel est toujours faux',
        'verdadeiro ou falso: o relógio está com uma sessão no pulso aberta agora' => 'vrai ou faux : la montre a une session au poignet ouverte maintenant',
        'a energia agora, em % inteiro (a fórmula energia: bateria, reserva, luz ou pilha); null sem dados para calcular' => 'l\'énergie maintenant, en % entier (la formule energia : batterie, réserve, lumière ou pile) ; null sans données pour calculer',
