        'os identificadores dos tipos de lançamento que valem para ele (texto)' => 'les identifiants des types de saisie qui valent pour elle (texte)',
        'todos os lançamentos do relógio, do mais antigo para o mais recente' => 'toutes les saisies de la montre, de la plus ancienne à la plus récente',
        'quando foi gravado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'quand il a été enregistré (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'o fim da sessão (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema); null: marcação, leitura, ou sessão aberta' => 'la fin de la session (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système) ; null : marque, lecture, ou session ouverte',
        'o número do lançamento' => 'le numéro de la saisie',
        'quando (a marcação ou a leitura), ou o começo da sessão (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'quand (la marque ou la lecture), ou le début de la session (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'manual (lançado por alguém), rodizio (a sessão do dia, pelo cron) ou importado' => 'manual (saisie par quelqu\'un), rodizio (la session du jour, par le cron) ou importado',
        'o identificador do tipo' => 'l\'identifiant du type',
        'o valor da leitura (número); null nos outros' => 'la valeur de la lecture (nombre) ; null pour les autres',
        'os trechos da linha do tempo do relógio, do mais recente para o mais antigo: cada trecho é um período contínuo num estado, ou uma marcação (um lançamento instantâneo)' => 'les périodes de la chronologie de la montre, de la plus récente à la plus ancienne : chaque période est un intervalle continu dans un état, ou une marque (une saisie instantanée)',
        'a mesma duração por extenso ("2d 3h", "40min"); null numa marcação' => 'la même durée en toutes lettres (« 2d 3h », « 40min ») ; null pour une marque',
        'quanto o trecho durou, número inteiro, em segundos; null numa marcação' => 'combien de temps la période a duré, nombre entier, en secondes ; null pour une marque',
        'verdadeiro ou falso: o trecho ainda não terminou (o fim é o momento da consulta)' => 'vrai ou faux : la période n\'est pas encore terminée (la fin est le moment de la consultation)',
        'o estado do trecho: rodizio (no pulso pelo rodízio), pulso (no pulso fora do rodízio), o identificador de um tipo de sessão (winder, sol...), repouso (parado) ou marca (uma marcação)' => 'l\'état de la période : rodizio (au poignet par la rotation), pulso (au poignet hors de la rotation), l\'identifiant d\'un type de session (winder, sol...), repouso (à l\'arrêt) ou marca (une marque)',
        'quando o trecho terminou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema); null numa marcação' => 'quand la période s\'est terminée (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système) ; null pour une marque',
        'quando o trecho começou (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'quand la période a commencé (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'o trecho por extenso, como a tela mostra ("em uso", "no sol", "Leitura de carga 80%")' => 'la période en toutes lettres, comme l\'écran la montre (« en usage », « au soleil », « Lecture de charge 80 % »)',
        'o identificador do tipo de lançamento que originou o trecho (pulso, sol, corda, carga...); null no repouso' => 'l\'identifiant du type de saisie qui a produit la période (pulso, sol, corda, carga...) ; null au repos',
        'o grupo por extenso' => 'le groupe en toutes lettres',
        'as medições do gasto pelas leituras (cada leitura de um tipo que mede o gasto, comparada com a anterior), da mais recente para a mais antiga' => 'les mesures de consommation par les lectures (chaque lecture d\'un type qui mesure la consommation, comparée à la précédente), de la plus récente à la plus ancienne',
        'a leitura que fechou a medição (número)' => 'la lecture qui a clos la mesure (nombre)',
        'quando a medição foi gravada (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'quand la mesure a été enregistrée (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'a leitura de antes (número, na unidade da leitura)' => 'la lecture d\'avant (nombre, dans l\'unité de la lecture)',
        'quando foi a leitura que fechou a medição (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'quand a eu lieu la lecture qui a clos la mesure (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'as horas guardado entre as duas leituras (número)' => 'les heures rangée entre les deux lectures (nombre)',
        'as horas no pulso entre as duas leituras (número)' => 'les heures au poignet entre les deux lectures (nombre)',
        'o número da medição' => 'le numéro de la mesure',
        'quando foi a leitura de antes (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'quand a eu lieu la lecture d\'avant (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'o lançamento (a leitura) que fechou a medição' => 'la saisie (la lecture) qui a clos la mesure',
        'o gasto do intervalo sozinho, no histórico: uso (o gasto por dia de uso, quando o intervalo teve meio dia de uso ou mais, ou mais dias de uso que fora) ou repouso (o gasto por dia fora do pulso); o gasto que vale sai de todas as medições juntas' => 'la consommation de l\'intervalle seul, dans l\'historique : uso (la consommation par jour d\'usage, quand l\'intervalle a eu une demi-journée d\'usage ou plus, ou plus de jours d\'usage que hors poignet) ou repouso (la consommation par jour hors du poignet) ; la consommation qui vaut sort de toutes les mesures ensemble',
        'o quanto a conta de agora erra a leitura desta medição que menos bate com as outras (a do começo ou a do fim), em pontos de carga (número; null fora da janela ou só no histórico)' => 'de combien le calcul actuel se trompe sur la lecture de cette mesure qui correspond le moins aux autres (celle du début ou celle de la fin), en points de charge (nombre ; null hors de la fenêtre ou historique seulement)',
        'o valor da leitura desta medição que menos bate com as outras (a do começo ou a do fim) (número; null fora da conta)' => 'la valeur de la lecture de cette mesure qui correspond le moins aux autres (celle du début ou celle de la fin) (nombre ; null hors du calcul)',
        'verdadeiro ou falso: uma leitura desta medição não bate com as outras e pesa menos da metade na conta (regressão robusta)' => 'vrai ou faux : une lecture de cette mesure ne correspond pas aux autres et pèse moins de la moitié dans le calcul (régression robuste)',
        'a marcação da leitura do começo da medição: uso ou repouso (null fora da conta)' => 'le marquage du relevé du début de la mesure : uso ou repouso (null hors du calcul)',
        'a marcação da leitura do fim da medição: uso ou repouso (null fora da conta)' => 'le marquage du relevé de la fin de la mesure : uso ou repouso (null hors du calcul)',
        'verdadeiro ou falso, no motor pela marcação (e no das fórmulas): as duas leituras têm a mesma marcação, e a medição entra na conta daquele gasto; com marcações diferentes, não entra em nenhum dos dois. null nos outros motores (eles não escolhem pela marcação)' => 'vrai ou faux, dans le moteur par le marquage (et dans celui des formules) : les deux relevés ont le même marquage, et la mesure entre dans le calcul de cette consommation ; avec des marquages différents, elle n\'entre dans aucun des deux. null dans les autres moteurs (ils ne choisissent pas par le marquage)',
        'verdadeiro ou falso: entra na conta agora (usada e dentro da janela da Configuração, medicao_janela_dias)' => 'vrai ou faux : entre dans le calcul maintenant (utilisée et dans la fenêtre de la Configuration, medicao_janela_dias)',
        'o peso, de 0 a 1, que a leitura desta medição que menos bate com as outras tem na conta (1: bate; menos: a regressão robusta a pesa menos) (número; null fora da conta)' => 'le poids, de 0 à 1, qu\'a dans le calcul la lecture de cette mesure qui correspond le moins aux autres (1 : elle correspond ; moins : la régression robuste la pèse moins) (nombre ; null hors du calcul)',
        'as horas que a medição cobriu, no pulso (uso) ou guardado (repouso) (número; a conta não pesa mais por horas: todas as medições pesam igual)' => 'les heures couvertes par la mesure, au poignet (uso) ou rangée (repouso) (nombre ; le calcul ne pondère plus par les heures : toutes les mesures pèsent pareil)',
        'o gasto medido, em % por dia de uso (uso) ou por dia guardado (repouso) (número)' => 'la consommation mesurée, en % par jour d\'usage (usage) ou par jour rangée (repos) (nombre)',
        'verdadeiro ou falso: a caixa "Atualizar o gasto com esta medição" estava marcada (entra na média); falso: só histórico' => 'vrai ou faux : la case « Mettre à jour la consommation avec cette mesure » était cochée (entre dans la moyenne) ; faux : historique seulement',
        'por que cada campo acima ficou null (objeto; vazio quando todos foram calculados)' => 'pourquoi chaque champ ci-dessus est resté null (objet ; vide quand tous ont été calculés)',
        'o motivo de o campo <campo> estar null (texto), ex.: sem dados para calcular a energia; não chega a zero em até 10 anos' => 'le motif pour lequel le champ <champ> est null (texte), ex. : pas de données pour calculer l\'énergie ; n\'arrive pas à zéro avant 10 ans',
        'o grupo do relógio; null: na raiz' => 'le groupe de la montre ; null : à la racine',
        'a previsão da energia (só nos relógios com leitura, como o smartwatch): as frases da tela e os mesmos números' => 'la prévision de l\'énergie (seulement sur les montres avec lecture, comme la smartwatch) : les phrases de l\'écran et les mêmes nombres',
        'verdadeiro ou falso: o relógio tem leitura com valor (senão os outros campos ficam vazios)' => 'vrai ou faux : la montre a une lecture avec valeur (sinon les autres champs restent vides)',
        'com quanto ele entra nesse dia, em % (número)' => 'avec combien elle entre ce jour-là, en % (nombre)',
        'verdadeiro ou falso: a carga na entrada não basta (é preciso carregar antes)' => 'vrai ou faux : la charge à l\'entrée ne suffit pas (il faut recharger avant)',
        'quando, parado, a carga chega ao limite (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema); null se passa de um ano' => 'quand, à l\'arrêt, la charge atteint la limite (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système) ; null si cela dépasse un an',
        'a confiança da conta: alta (leitura de até 2 dias e nenhum dado vazio, ou gasto em uso medido), media ou baixa (leitura com mais de 7 dias)' => 'la confiance du calcul : alta (lecture d\'au plus 2 jours et aucune donnée vide, ou consommation en usage mesurée), media ou baixa (lecture de plus de 7 jours)',
        'de onde vem cada número da conta: os campos do cadastro usados e o gasto medido pelas leituras' => 'd\'où vient chaque nombre du calcul : les champs de la fiche utilisés et la consommation mesurée par les lectures',
        'o identificador do campo, ou MEDIDO("uso") / MEDIDO("repouso") para o gasto medido' => 'l\'identifiant du champ, ou MEDIDO("uso") / MEDIDO("repouso") pour la consommation mesurée',
        'no gasto medido, como ele foi medido ("conta dos dois gastos juntos, com 3 medições dos últimos 90 dias"); null nos campos' => 'pour la consommation mesurée, comment elle a été mesurée (« calcul des deux consommations ensemble, avec 3 mesures des 90 derniers jours ») ; null pour les champs',
        'o nome do campo, ou do gasto medido (Gasto em uso medido, Gasto fora do pulso medido)' => 'le nom du champ, ou de la consommation mesurée (Consommation en usage mesurée, Consommation hors du poignet mesurée)',
        'de onde veio: informado (no cadastro do relógio), padrão (o do campo), vazio (sem valor) ou medido (pelas leituras)' => 'd\'où c\'est venu : informado (dans la fiche de la montre), padrão (celui du champ), vazio (sans valeur) ou medido (par les lectures)',
        'o valor usado na conta (número; null se vazio)' => 'la valeur utilisée dans le calcul (nombre ; null si vide)',
        'até que dia a carga aguenta se usar a partir de hoje (texto AAAA-MM-DD)' => 'jusqu\'à quel jour la charge tient si on l\'utilise à partir d\'aujourd\'hui (texte AAAA-MM-JJ)',
        'quantos dias de uso a carga de agora aguenta (número, dias; a fórmula dias_de_carga)' => 'combien de jours d\'usage la charge actuelle tient (nombre, jours ; la formule dias_de_carga)',
        'a energia agora, em % (número; null sem leitura)' => 'l\'énergie maintenant, en % (nombre ; null sans lecture)',
        'os dois gastos da bateria lado a lado (as fórmulas taxa_uso e taxa_repouso; null se o relógio não as tem)' => 'les deux consommations de la batterie côte à côte (les formules taxa_uso et taxa_repouso ; null si la montre ne les a pas)',
        'true: os dois gastos saem juntos da conta das medições; false: a média das medições de cada um' => 'true : les deux consommations sortent ensemble du calcul des mesures ; false : la moyenne des mesures de chacune',
        'o motor que calculou o gasto: horas, robusto, marcacao, cadastro ou formulas (veja config.gasto_motor)' => 'le moteur qui a calculé la consommation : horas, robusto, marcacao, cadastro ou formulas (voir config.gasto_motor)',
        'o nome do motor por extenso ("Pela marcação: duas taxas separadas")' => 'le nom du moteur en toutes lettres (« Par le marquage : deux taux séparés »)',
        'de onde veio a escolha: colecao (a Configuração), relogio (o campo gasto_motor do relógio), grupo (o padrão do campo) ou padrao (nada escolhido: horas)' => 'd\'où vient le choix : colecao (la Configuration), relogio (le champ gasto_motor de la montre), grupo (la valeur par défaut du champ) ou padrao (rien de choisi : horas)',
        'o que a conta do gasto medido conta (o "contar por" da Configuração): dias ou leituras' => 'ce que le calcul de la consommation mesurée compte (le « compter par » de la Configuration) : dias ou leituras',
        'as últimas tantas medições de cada tipo que entram, com base leituras (número)' => 'les tant derniers mesures de chaque type qui entrent, avec base leituras (nombre)',
