        'a janela do gasto medido (medicao_janela_dias da Configuração), em dias (número)' => 'la fenêtre de la consommation mesurée (medicao_janela_dias de la Configuration), en jours (nombre)',
        'quantas medições da janela têm uma leitura que não bate com as outras e pesa menos da metade na conta (número)' => 'combien de mesures de la fenêtre ont une lecture qui ne correspond pas aux autres et pèse moins de la moitié dans le calcul (nombre)',
        'quantas medições da janela entram na conta (número)' => 'combien de mesures de la fenêtre entrent dans le calcul (nombre)',
