        'o gasto em uso, em % por dia de uso, medido na janela anterior (número; null sem medição)' => 'la consommation en usage, en % par jour d\'usage, mesurée dans la fenêtre précédente (nombre ; null sans mesure)',
        'o gasto em uso, em % por dia de uso, pelo cadastro, sem as medições (número)' => 'la consommation en usage, en % par jour d\'usage, selon la fiche, sans les mesures (nombre)',
        'a incerteza do gasto em uso medido: um desvio padrão, na mesma unidade (número; null sem medição)' => 'l\'incertitude de la consommation en usage mesurée : un écart type, dans la même unité (nombre ; null sans mesure)',
        'o gasto em uso, em % por dia de uso, medido pelas leituras, como o MEDIDO (número; null sem medição)' => 'la consommation en usage, en % par jour d\'usage, mesurée par les lectures, comme MEDIDO (nombre ; null sans mesure)',
        'o gasto em uso, em % por dia de uso que vale na conta: o medido, senão o cadastro (número)' => 'la consommation en usage, en % par jour d\'usage, qui vaut dans le calcul : la mesurée, sinon la fiche (nombre)',
