        'o gasto fora do pulso, em % por dia, medido na janela anterior (número; null sem medição)' => 'la consommation hors du poignet, en % par jour, mesurée dans la fenêtre précédente (nombre ; null sans mesure)',
        'o gasto fora do pulso, em % por dia, pelo cadastro, sem as medições (número)' => 'la consommation hors du poignet, en % par jour, selon la fiche, sans les mesures (nombre)',
