        'o gasto fora do pulso, em % por dia, medido pelas leituras, como o MEDIDO (número; null sem medição)' => 'la consommation hors du poignet, en % par jour, mesurée par les lectures, comme MEDIDO (nombre ; null sans mesure)',
        'o gasto fora do pulso, em % por dia que vale na conta: o medido, senão o cadastro (número)' => 'la consommation hors du poignet, en % par jour, qui vaut dans le calcul : la mesurée, sinon la fiche (nombre)',
        'os campos do cadastro de onde sai o gasto fora do pulso do cadastro (o decaimento, a autonomia...): o painel mostra o medido ao lado deles' => 'les champs de la fiche d\'où vient la consommation hors du poignet de la fiche (la décroissance, l\'autonomie...) : le panneau montre la mesure à côté d\'eux',
