        'quanto ainda dura a partir de agora se ficar no pulso sem tirar, o dia todo (número inteiro, em segundos); null com o motivo (ex.: o automático no pulso se recarrega e não acaba)' => 'combien de temps il reste encore à partir de maintenant si elle reste au poignet sans être retirée, toute la journée (nombre entier, en secondes) ; null avec le motif (ex. : l\'automatique au poignet se recharge et ne s\'épuise pas)',
        'quanto ainda dura a partir de agora se ficar parado depois do que já está lançado (número inteiro, em segundos); null com o motivo' => 'combien de temps il reste encore à partir de maintenant si elle reste à l\'arrêt après ce qui est déjà saisi (nombre entier, en secondes) ; null avec le motif',
