        'o cálculo do hash: bcrypt (o padrão do password_hash do PHP), ou argon2i/argon2id' => 'le calcul du hash : bcrypt (le défaut de password_hash de PHP), ou argon2i/argon2id',
        'o custo do bcrypt (quantas rodadas: 2 elevado a ele), que também está escrito no próprio hash ($2y$12$...: 12); null no argon2' => 'le coût du bcrypt (combien de tours : 2 élevé à cette puissance), qui est aussi écrit dans le hash lui-même ($2y$12$... : 12) ; null pour argon2',
        'o hash da senha (a senha não existe no sistema): $2y$<custo>$ seguido do sal (22 caracteres) e do resultado (31). Não se desfaz em senha: confere-se a senha digitada contra ele (veja senhas na ajuda). Levado para outro sistema que confira por bcrypt, o usuário entra lá com a mesma senha; e volta para cá por usuarios/salvar com senha_hash' => 'le hash du mot de passe (le mot de passe n\'existe pas dans le système) : $2y$<coût>$ suivi du sel (22 caractères) et du résultat (31). Il ne se défait pas en mot de passe : on vérifie le mot de passe saisi contre lui (voir senhas dans l\'aide). Emporté vers un autre système qui vérifie par bcrypt, l\'utilisateur y entre avec le même mot de passe ; et il revient ici par usuarios/salvar avec senha_hash',
