        'verdadeiro: a cópia de segurança do arquivo está completa no banco (se ele sumir da pasta, volta dali)' => 'vrai : la sauvegarde du fichier est complète dans la base (s\'il disparaît du dossier, il en revient)',
        'verdadeiro: o próprio arquivo pede a cópia no banco (o terceiro nível; o relógio e a Configuração da coleção, se pedem, valem por cima)' => 'vrai : le fichier lui-même demande la copie dans la base (le troisième niveau ; la montre et la Configuration de la collection, si elles le demandent, priment)',
