        'o relógio do destaque; null: nenhum (sem relógio do dia e ninguém no pulso). No pulso: o que está no pulso agora (havendo mais de um, o que foi ao pulso por último); ninguém no pulso, o relógio do dia' => 'la montre de la mise en avant ; null : aucune (sans montre du jour et personne au poignet). Au poignet : celle qui est au poignet maintenant (s\'il y en a plus d\'une, la dernière mise au poignet) ; personne au poignet, la montre du jour',
        'numa frase, por que é ele: O relógio do dia. / O relógio do dia, no pulso agora. / No pulso agora; o relógio do dia é outro. / No pulso agora; hoje não tem relógio do dia. / Nenhum relógio no pulso agora: aqui, o relógio do dia. / Nenhum relógio para hoje e nenhum no pulso.' => 'en une phrase, pourquoi c\'est elle : La montre du jour. / La montre du jour, au poignet maintenant. / Au poignet maintenant ; la montre du jour est une autre. / Au poignet maintenant ; aujourd\'hui n\'a pas de montre du jour. / Aucune montre au poignet maintenant : ici, la montre du jour. / Aucune montre pour aujourd\'hui et aucune au poignet.',
