        'o estado na tabela: uso (no pulso), sessao (numa sessão que não é o pulso: no sol, no winder, no carregador...), repouso ou indisponivel (o indisponível parado; no pulso ou numa sessão, vale o que ele está fazendo)' => 'l\'état dans le tableau : uso (au poignet), sessao (dans une session qui n\'est pas le poignet : au soleil, sur le remontoir, sur le chargeur...), repouso ou indisponivel (l\'indisponible à l\'arrêt ; au poignet ou dans une session, vaut ce qu\'elle est en train de faire)',
        'o estado como a tabela mostra: "Em uso", o nome da sessão aberta ("No sol", "No carregador"; duas juntas: "No sol · No winder"), "Em repouso", "Indisponível" ou "Emprestado" (o emprestado parado)' => 'l\'état comme le tableau le montre : « En usage », le nom de la session ouverte (« Au soleil », « Sur le chargeur » ; deux ensemble : « Au soleil · Sur le remontoir »), « Au repos », « Indisponible » ou « Prêtée » (la prêtée à l\'arrêt)',
