        'as situações na coleção, na ordem (o menu "Situação na coleção" do cadastro)' => 'les statuts dans la collection, dans l\'ordre (le menu « Statut dans la collection » de la fiche)',
        'o nome ("Na coleção", "Desejado", "Emprestado", "Vendido", "Arquivado")' => 'le nom (« Dans la collection », « Désirée », « Prêtée », « Vendue », « Archivée »)',
        'o valor que vai na gravação (posse): colecao, desejado, emprestado, vendido ou arquivado' => 'la valeur qui part à l\'enregistrement (posse) : colecao, desejado, emprestado, vendido ou arquivado',
        'os ids do grupo e dos de cima' => 'les ids du groupe et de ceux du dessus',
        'a cópia no banco pela Configuração da coleção (documentos_copia), que vale sobre o relógio e o arquivo: verdadeiro (todos), todo arquivo vai; falso (nenhum), nenhum vai; null (vazio), cada relógio decide (a caixa do cadastro só aparece então)' => 'la copie dans la base par la Configuration de la collection (documentos_copia), qui prime sur la montre et le fichier : vrai (todos), chaque fichier y va ; faux (nenhum), aucun n\'y va ; null (vide), chaque montre décide (la case de la fiche n\'apparaît qu\'alors)',
        'como o relógio abre na página Hoje (a Configuração): lado (no painel à direita da lista, o padrão) ou flutuante (numa janela grande por cima da página); no celular, os dois cobrem a tela' => 'comment la montre s\'ouvre sur la page Aujourd\'hui (la Configuration) : lado (dans le panneau à droite de la liste, le défaut) ou flutuante (dans une grande fenêtre par-dessus la page) ; sur le téléphone, les deux couvrent l\'écran',
        'o relógio; null: o cadastro de um relógio novo' => 'la montre ; null : la fiche d\'une montre neuve',
        'as autonomias do relógio (as mesmas do recurso autonomia)' => 'les autonomies de la montre (les mêmes que recurso=autonomia)',
