        'onde comprou' => 'où elle a été achetée',
        'o valor pago' => 'le montant payé',
        'há quantos dias foi a compra (número inteiro); null: sem a data' => 'il y a combien de jours a eu lieu l\'achat (nombre entier) ; null : sans la date',
        'em quantos dias ele foi ao pulso (a fórmula dias_de_uso); null: sem a fórmula' => 'en combien de jours elle est allée au poignet (la formule dias_de_uso) ; null : sans la formule',
        'o valor pago dividido pelos dias de uso, em R$ (a fórmula custo_por_uso); null: sem o valor pago ou sem nenhum dia de uso' => 'le montant payé divisé par les jours d\'usage, en R$ (la formule custo_por_uso) ; null : sans le montant payé ou sans aucun jour d\'usage',
        'os campos do cadastro que valem para o relógio (os do grupo dele e dos de cima), com o valor que as contas usam' => 'les champs de la fiche qui valent pour la montre (ceux de son groupe et de ceux du dessus), avec la valeur que les calculs utilisent',
        'de onde vem o valor usado: informado, padrão (o do campo) ou vazio' => 'd\'où vient la valeur utilisée : informado, padrão (celui du champ) ou vazio',
        'a unidade (texto)' => 'l\'unité (texte)',
        'o valor informado no relógio (texto; null: não preenchido)' => 'la valeur indiquée sur la montre (texte ; null : non remplie)',
        'o valor que as contas usam: o informado, senão o padrão do campo (null: nenhum)' => 'la valeur que les calculs utilisent : l\'indiquée, sinon le défaut du champ (null : aucune)',
        'desde quando (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'depuis quand (texte AAAA-MM-JJ HH:MM:SS, dans le fuseau du système)',
        'a situação na coleção: colecao, desejado, emprestado, vendido ou arquivado (fora da coleção, disponivel é sempre falso)' => 'le statut dans la collection : colecao, desejado, emprestado, vendido ou arquivado (hors de la collection, disponivel est toujours faux)',
        'a mesma por extenso ("Na coleção", "Desejado"...)' => 'le même en toutes lettres (« Dans la collection », « Désirée »...)',
        'verdadeiro: é da coleção agora (na coleção ou emprestado); falso: desejado, vendido ou arquivado' => 'vrai : elle est de la collection maintenant (dans la collection ou prêtée) ; faux : désirée, vendue ou archivée',
        'os acessórios dele (o quadro Acessórios), pelo tipo e pelo nome' => 'ses accessoires (le cadre Accessoires), par type et par nom',
        'este relógio' => 'cette montre',
        'o que a lista de desejos mostra (o quadro Desejo do painel): só no desejado; null nos outros' => 'ce que montre la liste d\'envies (le cadre Envie du panneau) : seulement pour la désirée ; null pour les autres',
        'o link da página do relógio (o campo link; null)' => 'le lien de la page de la montre (le champ link ; null)',
