        'o estado agora: uso (no pulso), sessao (numa sessão que não é o pulso: no sol, no winder, no carregador...) ou repouso' => 'l\'état maintenant : uso (au poignet), sessao (dans une session qui n\'est pas le poignet : au soleil, sur le remontoir, sur le chargeur...) ou repouso',
        'o estado como a tela mostra: "Em uso", o nome da sessão aberta ("No sol", "No carregador"; duas juntas: "No sol · No winder") ou "Em repouso"' => 'l\'état comme l\'écran le montre : « En usage », le nom de la session ouverte (« Au soleil », « Sur le chargeur » ; deux ensemble : « Au soleil · Sur le remontoir ») ou « Au repos »',
        'até que dia vai a escala (null fora da escala)' => 'jusqu\'à quel jour va le planning (null hors du planning)',
        'a dica da foto no painel (aparece com o mouse parado em cima dela), em linhas: o nome, o grupo e o código; o estado e a carga; a nota e o próximo dia no rodízio (ou indisponível); a compra (data e valor); e a frase: Duplo clique (ou "Abrir foto", embaixo): a foto em tamanho grande.' => 'l\'info-bulle de la photo dans le panneau (apparaît avec la souris arrêtée dessus), en lignes : le nom, le groupe et le code ; l\'état et la charge ; la note et le prochain jour dans la rotation (ou indisponible) ; l\'achat (date et montant) ; et la phrase : Double clic (ou « Ouvrir la photo », en dessous) : la photo en grand.',
        'as 40 últimas leituras com valor (o gráfico)' => 'les 40 dernières lectures avec valeur (le graphique)',
        'verdadeiro ou falso: a leitura é de uso (a marcação dela, ou, sem marcação, o pulso registrado naquele instante)' => 'vrai ou faux : le relevé est en usage (son marquage, ou, sans marquage, le poignet enregistré à cet instant)',
        'a marcação da leitura: uso ou repouso (a gravada, ou, sem marcação, a do pulso registrado naquele instante)' => 'le marquage du relevé : uso ou repouso (celui enregistré, ou, sans marquage, celui du poignet enregistré à cet instant)',
        'verdadeiro ou falso: a marcação foi gravada na leitura (falso: veio do pulso registrado)' => 'vrai ou faux : le marquage a été enregistré dans le relevé (faux : il vient du poignet enregistré)',
        'os lançamentos dos últimos 14 dias e a sessão ainda aberta, do mais recente ao mais antigo (até 40): o que o quadro "Corrigir marcações" do painel mostra' => 'les saisies des 14 derniers jours et la session encore ouverte, de la plus récente à la plus ancienne (jusqu\'à 40) : ce que montre le cadre « Corriger les marques » du panneau',
        'quando a sessão terminou (texto AAAA-MM-DD HH:MM:SS); null: ainda aberta, ou um lançamento instantâneo' => 'quand la session s\'est terminée (texte AAAA-MM-JJ HH:MM:SS) ; null : encore ouverte, ou une saisie instantanée',
        'instantaneo, valor ou sessao' => 'instantaneo, valor ou sessao',
        'o número do lançamento (para recurso=lancamento, acao=alterar ou excluir)' => 'le numéro de la saisie (pour recurso=lancamento, acao=alterar ou excluir)',
