        'os trechos da linha do tempo do relógio, os 5 mais recentes: cada trecho é um período contínuo num estado, ou uma marcação (um lançamento instantâneo)' => 'les périodes de la chronologie de la montre, les 5 plus récentes : chaque période est un intervalle continu dans un état, ou une marque (une saisie instantanée)',
        'o aviso Encostado deste relógio (o quadro Agora; não entra nas próximas manutenções); null: sem data' => 'l\'alerte Délaissée de cette montre (le cadre Maintenant ; n\'entre pas dans les prochains entretiens) ; null : sans date',
