        'a janela da conta do gasto medido por extenso (o "contar por" da Configuração: dias ou leituras)' => 'la fenêtre du calcul de la consommation mesurée en toutes lettres (le « compter par » de la Configuration : jours ou relevés)',
        'a janela da média do gasto medido, em dias (a da Configuração)' => 'la fenêtre de la moyenne de la consommation mesurée, en jours (celle de la Configuration)',
