        'o nome da categoria' => 'le nom de la catégorie',
        'verdadeiro: a pasta dos documentos (DOCUMENTOS_PASTA do config.php) está pronta para receber arquivos' => 'vrai : le dossier des documents (DOCUMENTOS_PASTA de config.php) est prêt à recevoir des fichiers',
        'a cópia no banco pela Configuração da coleção (documentos_copia), que vale sobre o relógio e o arquivo: verdadeiro (todos), todo arquivo vai; falso (nenhum), nenhum vai; null (vazio), cada relógio e cada arquivo decidem' => 'la copie dans la base par la Configuration de la collection (documentos_copia), qui prime sur la montre et le fichier : vrai (todos), chaque fichier y va ; faux (nenhum), aucun n\'y va ; null (vide), chaque montre et chaque fichier décident',
        'quantos documentos ele tem' => 'combien de documents elle a',
        'quantos dias as listas mostram por página (o "Mostrar até" da Configuração, já com o padrão)' => 'combien de jours les listes montrent par page (l\'« Afficher jusqu\'à » de la Configuration, déjà avec le défaut)',
        'os Próximos dias da página Hoje (proximos_por_pagina; padrão 7)' => 'les Prochains jours de la page Aujourd\'hui (proximos_por_pagina ; 7 par défaut)',
