        'de onde vêm os números dos sorteios: RANDOM.ORG (ruído atmosférico); fora do ar, ANU QRNG (quântico); sem os dois, o gerador seguro do PHP (random_int)' => 'd\'où viennent les nombres des tirages : RANDOM.ORG (bruit atmosphérique) ; s\'il est hors service, ANU QRNG (quantique) ; sans les deux, le générateur sécurisé de PHP (random_int)',
        'as fontes, na ordem em que o sistema tenta: RANDOM.ORG, ANU QRNG, gerador seguro do PHP (random_int)' => 'les sources, dans l\'ordre où le système les essaie : RANDOM.ORG, ANU QRNG, générateur sécurisé de PHP (random_int)',
        'a fonte do último lote de números e quando ("RANDOM.ORG em AAAA-MM-DD HH:MM:SS"); null: nenhum ainda' => 'la source du dernier lot de nombres et quand (« RANDOM.ORG le AAAA-MM-JJ HH:MM:SS ») ; null : aucun encore',
        'desde quando os dois serviços estão sem responder (AAAA-MM-DD HH:MM:SS): por 10 minutos o sistema nem tenta e usa o gerador do PHP; null: no ar (ou não se sabe)' => 'depuis quand les deux services ne répondent plus (AAAA-MM-JJ HH:MM:SS) : pendant 10 minutes le système n\'essaie même pas et utilise le générateur de PHP ; null : en ligne (ou on ne sait pas)',
        'a situação do cron, como a Configuração mostra (o cron roda a cada minuto)' => 'l\'état du cron, comme la Configuration le montre (le cron tourne chaque minute)',
        'a linha do crontab que roda o sistema (com a pasta dele)' => 'la ligne du crontab qui fait tourner le système (avec son dossier)',
        'o erro guardado da última execução com erro (null: sem erro; some na primeira execução sem erro)' => 'l\'erreur conservée de la dernière exécution en erreur (null : sans erreur ; disparaît à la première exécution sans erreur)',
        'há quantos minutos ele rodou pela última vez (null: nunca rodou)' => 'il y a combien de minutes il a tourné pour la dernière fois (null : n\'a jamais tourné)',
        'nunca (ainda não rodou), parado (mais de 10 minutos sem rodar) ou rodando' => 'nunca (n\'a pas encore tourné), parado (plus de 10 minutes sans tourner) ou rodando',
        'a frase da Configuração ("Cron rodando: última execução às 10:41."; parado e nunca trazem a linha do crontab)' => 'la phrase de la Configuration (« Cron actif : dernière exécution à 10:41. » ; arrêté et jamais apportent la ligne du crontab)',
        'quando rodou pela última vez (AAAA-MM-DD HH:MM:SS, no fuso do sistema; null: nunca rodou)' => 'quand il a tourné pour la dernière fois (AAAA-MM-JJ HH:MM:SS, dans le fuseau du système ; null : n\'a jamais tourné)',
        'o idioma padrão da instalação (pt-BR, en, zh-CN, hi, es, fr): o de quem não escolheu outro no menu, o das mensagens do cron e o da API sem lingua= (vazio: o do navegador, senão português)' => 'la langue par défaut de l\'installation (pt-BR, en, zh-CN, hi, es, fr) : celle de qui n\'en a pas choisi une autre dans le menu, celle des messages du cron et celle de l\'API sans lingua= (vide : celle du navigateur, sinon le portugais)',
        'os idiomas do sistema, na ordem (o menu Idioma padrão)' => 'les langues du système, dans l\'ordre (le menu Langue par défaut)',
