        'o que é do sistema inteiro (não da coleção)' => 'ce qui est propre à tout le système (pas à la collection)',
        'o endereço do sistema, para os links das mensagens ({link}), do ICS e do Outlook (vazio: o do pedido)' => 'l\'adresse du système, pour les liens des messages ({link}), de l\'ICS et d\'Outlook (vide : celle de la requête)',
        'verdadeiro ou falso: quem pede pode mudar (só o master)' => 'vrai ou faux : qui demande peut la changer (seulement le master)',
        'o resumo dos destinos da coleção (a página Destinos tem o resto)' => 'le résumé des destinations de la collection (la page Destinations a le reste)',
