        'o registro da última rodada com atividade (o master vê o do sistema inteiro; os outros, o da coleção); null: nenhum' => 'l\'enregistrement de la dernière exécution avec activité (le master voit celui de tout le système ; les autres, celui de la collection) ; null : aucun',
