        'o nome da regra (ck_<tabela>_<o quê>; null: a de uma lista fechada, sem nome)' => 'le nom de la règle (ck_<tabela>_<o quê> ; null : celle d\'une liste fermée, sans nom)',
        'a condição que toda linha tem de cumprir, como o banco escreve' => 'la condition que chaque ligne doit remplir, comme la base l\'écrit',
        'as listas do código que a reescrita precisa ter iguais' => 'les listes du code que la réécriture doit avoir identiques',
        'as funções do motor das fórmulas' => 'les fonctions du moteur des formules',
        'o nome da função' => 'le nom de la fonction',
        'quantos argumentos ela aceita ("2", "1 a 2", "3 ou mais")' => 'combien d\'arguments elle accepte (« 2 », « 1 à 2 », « 3 ou plus »)',
        'o que ela devolve' => 'ce qu\'elle renvoie',
        'verdadeiro: lê os lançamentos do relógio (o primeiro argumento é um tipo de lançamento, entre aspas)' => 'vrai : lit les saisies de la montre (le premier argument est un type de saisie, entre guillemets)',
        'os tipos de campo do cadastro' => 'les types de champ de la fiche',
        'o tipo (inteiro, decimal, sim_nao, data, lista, texto)' => 'le type (inteiro, decimal, sim_nao, data, lista, texto)',
        'o que ele é, e como entra nas contas' => 'ce qu\'il est, et comment il entre dans les calculs',
        'os formatos dos tipos de lançamento' => 'les formats des types de saisie',
        'o que ele é' => 'ce qu\'il est',
        'as repetições dos eventos personalizados' => 'les répétitions des événements personnalisés',
        'a repetição (uma, diaria, semanal, mensal, intervalo)' => 'la répétition (uma, diaria, semanal, mensal, intervalo)',
        'como ela aparece na tela' => 'comment elle apparaît à l\'écran',
        'os dias da semana como o sistema numera' => 'les jours de la semaine comme le système les numérote',
        'o número (1 segunda a 7 domingo)' => 'le numéro (1 lundi à 7 dimanche)',
        'as âncoras das mensagens (entre chaves no texto)' => 'les repères des messages (entre accolades dans le texte)',
        'a âncora, sem as chaves' => 'le repère, sans les accolades',
        'o que ela vira' => 'ce qu\'il devient',
        'as migrações, na ordem' => 'les migrations, dans l\'ordre',
        'o arquivo do SQL dela' => 'le fichier SQL de celle-ci',
        'o que ela traz' => 'ce qu\'elle apporte',
        'verdadeiro: ela tem também um passo em programa, depois do SQL' => 'vrai : elle a aussi un pas en programme, après le SQL',
        'as constantes do config.php' => 'les constantes de config.php',
        'o nome (ou os nomes) da constante' => 'le nom (ou les noms) de la constante',
        'para que ela serve' => 'à quoi elle sert',
        'os tipos de destino das mensagens' => 'les types de destination des messages',
        'o código (webhook, email, webpush)' => 'le code (webhook, email, webpush)',
        'os tipos de agenda' => 'les types d\'agenda',
        'o código (google, caldav, outlook, ics)' => 'le code (google, caldav, outlook, ics)',
        'falso: a cópia de segurança está desligada no config.php (BACKUP_ATIVO = false): o cron não faz cópia, a escrita fazer é recusada e a Configuração não mostra o quadro Cópia de segurança' => 'faux : la sauvegarde est désactivée dans le config.php (BACKUP_ATIVO = false) : le cron ne fait pas de copie, l\'écriture fazer est refusée et la Configuration n\'affiche pas le cadre Sauvegarde',
        'verdadeiro: a pasta das cópias (BACKUP_PASTA do config.php) existe, aceita gravar e fica fora da pasta publicada' => 'vrai : le dossier des copies (BACKUP_PASTA de config.php) existe, accepte l\'écriture et se trouve hors du dossier publié',
        'por que a pasta não serve (sem BACKUP_PASTA, não existe, sem permissão de escrita, ou dentro da pasta publicada); null: serve' => 'pourquoi le dossier ne convient pas (sans BACKUP_PASTA, n\'existe pas, sans droit d\'écriture, ou dans le dossier publié) ; null : il convient',
        'quantas cópias ficam na pasta (BACKUP_MANTER; padrão 7): a cada cópia nova, as mais velhas que passam disso saem' => 'combien de copies restent dans le dossier (BACKUP_MANTER ; 7 par défaut) : à chaque nouvelle copie, les plus anciennes qui dépassent cela sortent',
        'verdadeiro: as cópias levam o conteúdo dos documentos guardado no banco (BACKUP_DOCUMENTOS); falso: não levam (os arquivos já estão na pasta dos documentos)' => 'vrai : les copies emportent le contenu des documents gardé dans la base (BACKUP_DOCUMENTOS) ; faux : elles ne l\'emportent pas (les fichiers sont déjà dans le dossier des documents)',
        'a versão do banco agora (a última migração): só uma cópia da mesma versão volta' => 'la version de la base maintenant (la dernière migration) : seule une copie de la même version revient',
        'quando foi feita a última cópia (texto AAAA-MM-DD HH:MM:SS); null: nenhuma' => 'quand la dernière copie a été faite (texte AAAA-MM-JJ HH:MM:SS) ; null : aucune',
        'as cópias que estão na pasta, da mais nova para a mais velha' => 'les copies qui sont dans le dossier, de la plus récente à la plus ancienne',
        'o nome do arquivo (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): é o que se passa em arquivo= para baixar ou restaurar' => 'le nom du fichier (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz) : c\'est ce qu\'on passe dans arquivo= pour télécharger ou restaurer',
        'o tamanho por extenso ("7 KB", "1,2 MB")' => 'la taille en toutes lettres (« 7 Ko », « 1,2 Mo »)',
        'quando a cópia foi feita (texto AAAA-MM-DD HH:MM:SS)' => 'quand la copie a été faite (texte AAAA-MM-JJ HH:MM:SS)',
        'verdadeiro: a cópia leva o conteúdo dos documentos' => 'vrai : la copie emporte le contenu des documents',
        'a versão do banco da cópia (a última migração dele)' => 'la version de la base de la copie (sa dernière migration)',
        'as camadas do sistema, na ordem' => 'les couches du système, dans l\'ordre',
        'cada arquivo do sistema (os do repositório), pela camada' => 'chaque fichier du système (ceux du dépôt), par la couche',
        'o conteúdo do arquivo, como está (texto); só com arquivo= ou conteudo=1' => 'le contenu du fichier, tel quel (texte) ; seulement avec arquivo= ou conteudo=1',
        'o conteúdo da imagem, em base64; só com arquivo= ou conteudo=1' => 'le contenu de l\'image, en base64 ; seulement avec arquivo= ou conteudo=1',
        'só nas páginas, com arquivo= ou conteudo=1: o HTML que o navegador recebe, já montado (o topo com o menu, o esqueleto da página e os scripts)' => 'seulement pour les pages, avec arquivo= ou conteudo=1 : le HTML que le navigateur reçoit, déjà monté (le haut avec le menu, le squelette de la page et les scripts)',
        'o que fica de fora de propósito, e o que ver no lugar' => 'ce qui est laissé de côté exprès, et quoi voir à la place',
        'o que é (o config.php, a chave do Google, o banco, a pasta dos documentos, as senhas)' => 'ce que c\'est (config.php, la clé Google, la base, le dossier des documents, les mots de passe)',
        'com arquivo=: o nome do arquivo, com a pasta (estilo.css, testes/cenario.php, docs/telas/hoje.png): é o que se passa em arquivo=' => 'avec arquivo= : le nom du fichier, avec le dossier (estilo.css, testes/cenario.php, docs/telas/hoje.png) : c\'est ce qu\'on passe dans arquivo=',
        'com arquivo=: a camada (tela, api, linha_de_comando, banco, servidor, testes, documentacao, repositorio, imagem; veja camadas)' => 'avec arquivo= : la couche (tela, api, linha_de_comando, banco, servidor, testes, documentacao, repositorio, imagem ; voir camadas)',
        'com arquivo=: o que o arquivo é e o que ele faz' => 'avec arquivo= : ce que le fichier est et ce qu\'il fait',
        'com arquivo=: php, javascript, css, sql, markdown, apache, nginx, texto ou png' => 'avec arquivo= : php, javascript, css, sql, markdown, apache, nginx, texte ou png',
        'com arquivo=: o tamanho, em bytes' => 'avec arquivo= : la taille, en octets',
        'com arquivo=: quantas linhas (null na imagem)' => 'avec arquivo= : combien de lignes (null pour l\'image)',
        'com arquivo=: o SHA-256 do arquivo: para conferir a cópia, ou saber se mudou desde a última leitura' => 'avec arquivo= : le SHA-256 du fichier : pour vérifier la copie, ou savoir s\'il a changé depuis la dernière lecture',
        'com arquivo=: a data da última alteração do arquivo no servidor (AAAA-MM-DD HH:MM:SS)' => 'avec arquivo= : la date de la dernière modification du fichier sur le serveur (AAAA-MM-JJ HH:MM:SS)',
        'com arquivo=: o endereço deste arquivo na API, com o conteúdo, em JSON' => 'avec arquivo= : l\'adresse de ce fichier dans l\'API, avec le contenu, en JSON',
        'com arquivo=: o endereço do arquivo puro, sem JSON (texto como text/plain; imagem como imagem)' => 'avec arquivo= : l\'adresse du fichier pur, sans JSON (texte en text/plain ; image en tant qu\'image)',
        'com arquivo=: só nas páginas: os arquivos que ela usa, na ordem (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega)' => 'avec arquivo= : seulement pour les pages : les fichiers qu\'elle utilise, dans l\'ordre (pagina.php, estilo.css, la page elle-même et les scripts qu\'elle charge)',
        'com arquivo=: só nas páginas: o endereço do HTML que o navegador recebe, puro' => 'avec arquivo= : seulement pour les pages : l\'adresse du HTML que le navigateur reçoit, pur',
        'com arquivo=: o conteúdo do arquivo, como está (texto); só com arquivo= ou conteudo=1' => 'avec arquivo= : le contenu du fichier, tel quel (texte) ; seulement avec arquivo= ou conteudo=1',
        'com arquivo=: o conteúdo da imagem, em base64; só com arquivo= ou conteudo=1' => 'avec arquivo= : le contenu de l\'image, en base64 ; seulement avec arquivo= ou conteudo=1',
        'com arquivo=: só nas páginas, com arquivo= ou conteudo=1: o HTML que o navegador recebe, já montado (o topo com o menu, o esqueleto da página e os scripts)' => 'avec arquivo= : seulement pour les pages, avec arquivo= ou conteudo=1 : le HTML que le navigateur reçoit, déjà monté (le haut avec le menu, le squelette de la page et les scripts)',
        'aparece quando a consulta usa filtros (incluir, excluir, f, busca, ordem, limite, pagina, mostrar)' => 'apparaît quand la consultation utilise des filtres (incluir, excluir, f, busca, ordem, limite, pagina, mostrar)',
        'o que foi pedido e não existe (caminho sem lista, parte que não existe)' => 'ce qui a été demandé et n\'existe pas (chemin sans liste, partie qui n\'existe pas)',
        'quantos itens a lista tinha' => 'combien d\'éléments la liste avait',
        'quantos vieram (a página)' => 'combien sont venus (la page)',
        'o limite por página; null: sem' => 'la limite par page ; null : sans',
        'quantos passaram nos filtros' => 'combien ont passé les filtres',
        'o recurso (vazio: tudo)' => 'la ressource (vide : tout)',
        'a ação (escrita)' => 'l\'action (écriture)',
        'json (padrão) ou xml' => 'json (par défaut) ou xml',
        'o token da API (o pessoal, de Minha conta, ou o do servidor); também no cabeçalho X-Api-Token, ou o login do site (HTTP Basic) no lugar dele' => 'le jeton de l\'API (le personnel, de Mon compte, ou celui du serveur) ; aussi dans l\'en-tête X-Api-Token, ou l\'identifiant du site (HTTP Basic) à sa place',
        'o id da coleção do pedido (sem ele: o cookie colecao, senão a primeira que você vê); uma que você não vê: 404' => 'l\'id de la collection de la requête (sans lui : le cookie colecao, sinon la première que vous voyez) ; une que vous ne voyez pas : 404',
        '1: confirma uma exclusão (sem ele, a API só diz o que sai junto: 409)' => '1 : confirme une suppression (sans lui, l\'API dit seulement ce qui part avec : 409)',
        '(só o master) o login de outro usuário: o pedido vale como se fosse dele (a faixa Vendo como das páginas)' => '(seulement le master) l\'identifiant d\'un autre utilisateur : la requête vaut comme si elle était de lui (la bande Vue en tant que des pages)',
        'o idioma da resposta: pt-BR, en, zh-CN, hi, es ou fr' => 'la langue de la réponse : pt-BR, en, zh-CN, hi, es ou fr',
        'pedido recusado: uma escrita que não passou nas validações ({ok: false, mensagem, erros: [...]}, um erro por motivo) ou uma fórmula mal escrita no recurso=calcular ({erro, erros})' => 'requête refusée : une écriture qui n\'a pas passé les validations ({ok: false, mensagem, erros: [...]}, une erreur par motif) ou une formule mal écrite dans recurso=calcular ({erro, erros})',
        'recurso=entrar com o login certo e volta=<página>: vai para a página' => 'recurso=entrar avec la bonne connexion et volta=<page> : va vers la page',
        'sem o token nem o login do site, ou com eles errados; sem nenhum usuário (ou com o banco vazio), também sem_usuarios: true e como (o que fazer: instalar, criar o primeiro usuário pelo token)' => 'sans le jeton ni la connexion du site, ou avec eux incorrects ; sans aucun utilisateur (ou avec la base vide), aussi sem_usuarios: true et como (que faire : installer, créer le premier utilisateur par le jeton)',
        'a cópia de segurança e as migrações: só o master' => 'la copie de sécurité et les migrations : seulement le master',
        'recurso desconhecido (com recursos, a lista deles), ou a coleção que você não vê (colecao=), o relógio, a foto, o documento (ou o arquivo dele), o link ICS ou o README.md (recurso=manual) que não existe, ou um arquivo que não sai pelo recurso=codigo ({erro, e o_que_ver no que fica de fora de propósito, como o config.php, ou arquivos, os que saem)' => 'ressource inconnue (avec recursos, leur liste), ou la collection que vous ne voyez pas (colecao=), la montre, la photo, le document (ou son fichier), le lien ICS ou le README.md (recurso=manual) qui n\'existe pas, ou un fichier qui ne sort pas par recurso=codigo ({erro, et o_que_ver pour ce qui reste exclu exprès, comme le config.php, ou arquivos, ceux qui sortent)',
        'uma exclusão sem confirmar=1 ({ok: false, confirmar: true, impacto: o que sai junto}: nada foi apagado); a conta sem coleção nenhuma (sem_colecao: true; só a conta responde); ou o banco recusou a gravação (um registro que outro ainda usa, um valor repetido, ou um valor fora das regras de validação do banco: o nome da regra, ck_<tabela>_<o quê>, vem no detalhe)' => 'une suppression sans confirmar=1 ({ok: false, confirmar: true, impacto : ce qui part avec} : rien n\'a été effacé) ; le compte sans aucune collection (sem_colecao: true ; seul le compte répond) ; ou la base a refusé l\'enregistrement (un enregistrement qu\'un autre utilise encore, une valeur répétée, ou une valeur hors des règles de validation de la base : le nom de la règle, ck_<tabela>_<o quê>, vient dans le détail)',
        'o envio passou do limite do PHP do servidor (post_max_size): um arquivo grande demais' => 'l\'envoi a dépassé la limite PHP du serveur (post_max_size) : un fichier trop gros',
        'sistema parado (token ou fuso inválido no config.php) ou erro interno' => 'système arrêté (jeton ou fuseau invalide dans config.php) ou erreur interne',
        'banco desatualizado (só recurso=migracoes responde, e o recurso=manual e o recurso=codigo, que não usam o banco), banco vazio (antes da instalação só recurso=instalacao responde, e o manual e o código) ou banco fora do ar' => 'base pas à jour (seul recurso=migracoes répond, ainsi que recurso=manual et recurso=codigo, qui n\'utilisent pas la base), base vide (avant l\'installation seul recurso=instalacao répond, ainsi que le manuel et le code) ou base hors service',
        'números com vírgula ou ponto; textos entre aspas; argumentos separados por ponto e vírgula; operações + - * / ^; comparações = <> < <= > >= (dão 1 ou 0); variáveis: os identificadores dos campos e das fórmulas; vazio se propaga; divisão por zero: vazio' => 'nombres avec virgule ou point ; textes entre guillemets ; arguments séparés par un point-virgule ; opérations + - * / ^ ; comparaisons = <> < <= > >= (donnent 1 ou 0) ; variables : les identifiants des champs et des formules ; le vide se propage ; division par zéro : vide',
    ],
    'reconstrucao' => [
        'quem vê todas as coleções de um dono, também as que ele criar depois, e desde quando' => 'qui voit toutes les collections d\'un propriétaire, aussi celles qu\'il créera plus tard, et depuis quand',
        'os acessórios de uma coleção: o nome, o tipo e a observação' => 'les accessoires d\'une collection : le nom, le type et la remarque',
        'o relógio de que um acessório é (sem linha: solto)' => 'la montre à laquelle appartient un accessoire (sans ligne : détaché)',
        'as agendas de uma coleção: o tipo (google, caldav, outlook, ics), o nome, se está ativa, a janela em dias, o modelo do evento, o idioma e o evento de teste' => 'les agendas d\'une collection : le type (google, caldav, outlook, ics), le nom, si elle est active, la fenêtre en jours, le modèle de l\'événement, la langue et l\'événement de test',
        'o que uma agenda recebe: cada tipo de aviso, se envia' => 'ce qu\'une agenda reçoit : chaque type d\'alerte, si elle envoie',
        'o CalDAV de uma agenda: o endereço do calendário, o usuário e a senha (cifrada)' => 'le CalDAV d\'une agenda : l\'adresse du calendrier, l\'utilisateur et le mot de passe (chiffré)',
        'os eventos personalizados que uma agenda recebe' => 'les événements personnalisés qu\'une agenda reçoit',
        'o Google Agenda de uma agenda: o id da agenda e a chave da conta de serviço (cifrada)' => 'le Google Agenda d\'une agenda : l\'id de l\'agenda et la clé du compte de service (chiffrée)',
        'o link ICS de uma agenda: o token secreto do link' => 'le lien ICS d\'une agenda : le jeton secret du lien',
        'o Outlook de uma agenda: a conta, o calendário e o token de renovação (cifrado)' => 'l\'Outlook d\'une agenda : le compte, le calendrier et le jeton de renouvellement (chiffré)',
        'os eventos que o sistema criou em cada agenda: a chave (o que o evento é: o tipo, o relógio e o dia), o id no serviço, a data, o título e a assinatura (o resumo do conteúdo, para saber se mudou)' => 'les événements que le système a créés dans chaque agenda : la clé (ce qu\'est l\'événement : le type, la montre et le jour), l\'id dans le service, la date, le titre et la signature (le résumé du contenu, pour savoir s\'il a changé)',
        'os tokens de API de cada conta: o nome e o hash (o token só aparece ao criar), quando foi criado e o último uso' => 'les jetons d\'API de chaque compte : le nom et le hash (le jeton n\'apparaît qu\'à la création), quand il a été créé et la dernière utilisation',
        'os avisos do cadastro: o identificador, o nome, a fórmula da data prevista (expressao), a condição (vale quando), a antecedência em dias, o texto, se está ativo, o grupo da versão, a escala, a simulação, se vai para a agenda, o tipo de lançamento que o resolve e se avisa na hora' => 'les alertes des définitions : l\'identifiant, le nom, la formule de la date prévue (expressao), la condition (vaut quand), l\'anticipation en jours, le texte, si elle est active, le groupe de la version, le planning, la simulation, si elle va à l\'agenda, le type de saisie qui la résout et si elle alerte à l\'heure',
        'os campos do cadastro dos relógios, por árvore: o identificador (o nome nas fórmulas), o nome, o tipo, a unidade, o valor padrão, o grupo em que vale (a raiz: todos), a ordem e se vale só nos desejados' => 'les champs des définitions des montres, par arbre : l\'identifiant (le nom dans les formules), le nom, le type, l\'unité, la valeur par défaut, le groupe où il vaut (la racine : tous), l\'ordre et s\'il ne vaut que pour les envies',
        'as opções de um campo do tipo lista, em ordem (sem repetir, sem diferenciar maiúsculas e acentos)' => 'les options d\'un champ de type liste, dans l\'ordre (sans répétition, sans distinguer majuscules et accents)',
        'o valor de cada campo em cada relógio (texto normalizado pelo tipo do campo: número com ponto, data AAAA-MM-DD, sim/não 1 ou 0)' => 'la valeur de chaque champ pour chaque montre (texte normalisé selon le type du champ : nombre avec point, date AAAA-MM-JJ, oui/non 1 ou 0)',
        'as coleções: o dono, a raiz da árvore que ela usa (uma árvore do mesmo dono), o nome (sem repetir entre as do dono) e quando foi criada' => 'les collections : le propriétaire, la racine de l\'arbre qu\'elle utilise (un arbre du même propriétaire), le nom (sans répétition entre celles du propriétaire) et quand elle a été créée',
        'os membros de uma coleção (o dono não entra aqui) e desde quando' => 'les membres d\'une collection (le propriétaire n\'y figure pas) et depuis quand',
        'os valores soltos da Configuração de cada coleção (horários, limites, o idioma), chave e valor' => 'les valeurs isolées de la Configuration de chaque collection (horaires, limites, la langue), clé et valeur',
        'os convites para uma coleção ou para tudo de um dono (um ou outro): o e-mail, quem convidou, o estado (pendente: espera o dono; aprovado: enviado), o hash do token do link e até quando vale' => 'les invitations à une collection ou à tout ce qui est à un propriétaire (l\'un ou l\'autre) : l\'e-mail, qui a invité, l\'état (pendente : attend le propriétaire ; aprovado : envoyée), le hash du jeton du lien et jusqu\'à quand elle est valable',
        'as faixas de um subparâmetro: de um número até outro (ou sem limite) ou uma categoria, e a nota (0 a 100) que o valor ganha nela' => 'les tranches d\'un sous-paramètre : d\'un nombre jusqu\'à un autre (ou sans limite) ou une catégorie, et la note (0 à 100) que la valeur y gagne',
        'os parâmetros de um conjunto de critérios: o lugar (um grupo da árvore, a raiz para todos, ou um relógio: um ou outro), o nome, o peso (%) e a ordem' => 'les paramètres d\'un ensemble de critères : le lieu (un groupe de l\'arbre, la racine pour tous, ou une montre : l\'un ou l\'autre), le nom, le poids (%) et l\'ordre',
        'os subparâmetros de um parâmetro: o nome, a variável que mede (um campo ou uma fórmula), o peso dentro do parâmetro (%) e a ordem' => 'les sous-paramètres d\'un paramètre : le nom, la variable qu\'il mesure (un champ ou une formule), le poids dans le paramètre (%) et l\'ordre',
        'cada execução do cron que registrou algo: início, fim, duração, o registro do sistema em texto, se teve erro e se teve atividade' => 'chaque exécution du cron qui a enregistré quelque chose : début, fin, durée, le journal du système en texte, s\'il y a eu une erreur et s\'il y a eu de l\'activité',
        'o registro de cada coleção numa execução do cron, se teve erro e se teve atividade' => 'le journal de chaque collection dans une exécution du cron, s\'il y a eu une erreur et s\'il y a eu de l\'activité',
        'os destinos das mensagens de uma coleção: o tipo (webhook, email, webpush), o nome, se está ligado, a mensagem padrão e o idioma' => 'les destinations des messages d\'une collection : le type (webhook, email, webpush), le nom, si elle est active, le message par défaut et la langue',
        'o que um destino recebe: cada tipo de aviso (dia, vespera, o identificador de um aviso), se envia e o texto próprio' => 'ce qu\'une destination reçoit : chaque type d\'alerte (dia, vespera, l\'identifiant d\'une alerte), si elle envoie et le texte propre',
        'para quem vai o e-mail de um destino' => 'à qui va l\'e-mail d\'une destination',
        'os eventos personalizados que um destino recebe, com o texto próprio' => 'les événements personnalisés qu\'une destination reçoit, avec le texte propre',
        'o webhook de um destino: o método, o endereço, o formato (query, form, json) e o corpo JSON opcional' => 'le webhook d\'une destination : la méthode, l\'adresse, le format (query, form, json) et le corps JSON facultatif',
        'os cabeçalhos do pedido de um webhook (o valor cifrado: pode ter um token)' => 'les en-têtes de la requête d\'un webhook (la valeur chiffrée : elle peut contenir un jeton)',
        'os campos do pedido de um webhook, em ordem, com {titulo} e {mensagem} no valor' => 'les champs de la requête d\'un webhook, dans l\'ordre, avec {titulo} et {mensagem} dans la valeur',
        'o usuário cujos aparelhos recebem o Web Push de um destino' => 'l\'utilisateur dont les appareils reçoivent le Web Push d\'une destination',
        'os documentos de cada relógio: a categoria, o título, a data, a descrição, o nome e o tipo do arquivo, o tamanho, o caminho na pasta (arquivo e miniatura), se a cópia no banco está completa e se o arquivo pede a cópia' => 'les documents de chaque montre : la catégorie, le titre, la date, la description, le nom et le type du fichier, la taille, le chemin dans le dossier (fichier et miniature), si la copie dans la base est complète et si le fichier demande la copie',
        'as categorias dos documentos (Manual, Nota fiscal, Fotos...), por árvore: identificador, nome e ordem' => 'les catégories des documents (Manuel, Facture, Photos...), par arbre : identifiant, nom et ordre',
        'as famílias de arquivo que uma categoria aceita (imagem, video, audio, pdf, xml); nenhuma: qualquer arquivo' => 'les familles de fichiers qu\'une catégorie accepte (imagem, video, audio, pdf, xml) ; aucune : n\'importe quel fichier',
        'a cópia de um documento dentro do banco, em pedaços de 4 MB (parte 0, 1, 2...; a parte -1 é a miniatura)' => 'la copie d\'un document dans la base, en morceaux de 4 Mo (partie 0, 1, 2… ; la partie -1 est la miniature)',
        'os dias da semana de um evento personalizado semanal (1 segunda a 7 domingo)' => 'les jours de la semaine d\'un événement personnalisé hebdomadaire (1 lundi à 7 dimanche)',
        'cada ocorrência de um evento personalizado que já disparou (para não disparar duas vezes)' => 'chaque occurrence d\'un événement personnalisé déjà déclenché (pour ne pas le déclencher deux fois)',
        'os lembretes de uma coleção: nome, se está ativo, a repetição (uma vez, todo dia, em dias da semana, todo mês, a cada N dias), a data de início, a hora, o dia do mês e o intervalo' => 'les rappels d\'une collection : nom, s\'il est actif, la répétition (une fois, tous les jours, certains jours de la semaine, tous les mois, tous les N jours), la date de début, l\'heure, le jour du mois et l\'intervalle',
        'o relógio de um evento personalizado (sem linha: um evento geral)' => 'la montre d\'un événement personnalisé (sans ligne : un événement général)',
        'as fórmulas do cadastro: o identificador (o nome nas outras fórmulas, nos avisos e nos critérios), o nome, a expressão, a unidade e o grupo da versão (a raiz: todos). A mesma fórmula pode ter uma versão por grupo; vale a do grupo mais perto do relógio' => 'les formules des définitions : l\'identifiant (le nom dans les autres formules, dans les alertes et dans les critères), le nom, l\'expression, l\'unité et le groupe de la version (la racine : tous). La même formule peut avoir une version par groupe ; c\'est celle du groupe le plus proche de la montre qui vaut',
        'a foto de cada relógio (a imagem inteira, o tipo e quando foi trocada)' => 'la photo de chaque montre (l\'image entière, le type et quand elle a été changée)',
        'o histórico de cada relógio: o tipo, o início (o instante, num instantâneo), o fim (numa sessão; vazio: aberta), o valor (numa leitura), a marcação da leitura de carga (uso ou repouso; vazio: vale o pulso registrado naquele instante) e a origem (manual, rodizio, importado)' => 'l\'historique de chaque montre : le type, le début (l\'instant, dans un instantané), la fin (dans une session ; vide : ouverte), la valeur (dans un relevé), le marquage du relevé de charge (uso ou repouso ; vide : le poignet enregistré à cet instant fait foi) et l\'origine (manual, rodizio, importado)',
        'os tipos de lançamento: identificador, nome, formato (instantâneo, com valor ou sessão), unidade, a hora em que a sessão esquecida fecha sozinha (fecha_as), o grupo, a ordem, se a sessão é exclusiva, se a leitura mede o gasto e a condição (vale quando)' => 'les types de saisie : identifiant, nom, format (instantané, avec valeur ou session), unité, l\'heure à laquelle la session oubliée se ferme toute seule (fecha_as), le groupe, l\'ordre, si la session est exclusive, si la lecture mesure la dépense et la condition (vaut quand)',
        'cada medição do gasto: o lançamento (a leitura) que a fechou, se mede o uso ou o repouso, o gasto achado (% por dia), as duas leituras, o intervalo, as horas no pulso e fora, o peso (horas) e se entra na média' => 'chaque mesure de la consommation : la saisie (la lecture) qui l\'a close, si elle mesure l\'usage ou le repos, la consommation trouvée (% par jour), les deux lectures, l\'intervalle, les heures au poignet et hors du poignet, le poids (heures) et si elle entre dans la moyenne',
        'os modos de rodízio de uma coleção: nome, a forma de escolha, a ordem, o horizonte da escala inteligente (escala_dias; vazio: o modo sorteia pelos blocos), o ciclo e a marca do modo em uso (1 no ativo, vazio nos outros)' => 'les modes de rotation d\'une collection : nom, la manière de choisir, l\'ordre, l\'horizon du planning intelligent (escala_dias ; vide : le mode tire au sort par les blocs), le cycle et la marque du mode en usage (1 sur l\'actif, vide sur les autres)',
        'os blocos de um modo: nome, de onde sortear (um grupo; a raiz: todos), um relógio por dia ou um para o bloco inteiro e a ordem' => 'les blocs d\'un mode : nom, d\'où tirer au sort (un groupe ; la racine : tous), une montre par jour ou une pour tout le bloc et l\'ordre',
        'os dias da semana de um bloco (1 segunda a 7 domingo; um dia em um bloco só)' => 'les jours de la semaine d\'un bloc (1 lundi à 7 dimanche ; un jour dans un seul bloc)',
        'o relógio fixo de um bloco (sem linha: sorteia)' => 'la montre fixe d\'un bloc (sans ligne : tire au sort)',
        'a árvore dos grupos: a raiz (sem pai) é a árvore inteira e guarda o dono; cada grupo aponta para o de cima; o nome e a ordem entre irmãos. Uma árvore serve a várias coleções do mesmo dono' => 'l\'arbre des groupes : la racine (sans parent) est l\'arbre entier et garde le propriétaire ; chaque groupe pointe vers celui du dessus ; le nom et l\'ordre entre frères. Un arbre sert à plusieurs collections du même propriétaire',
        'os pedidos de acesso de uma conta a uma coleção ou a tudo de um dono (um ou outro), com o recado e até quando espera' => 'les demandes d\'accès d\'un compte à une collection ou à tout ce qui est à un propriétaire (l\'un ou l\'autre), avec le mot et jusqu\'à quand elle attend',
        'o relógio de cada dia de uma coleção: o relógio, a origem (sorteio ou manual), a ação do dia (o que fazer antes de usar), o motivo da escolha e quando foi gravado' => 'la montre de chaque jour d\'une collection : la montre, l\'origine (tirage ou manuelle), l\'action du jour (quoi faire avant de la porter), le motif du choix et quand il a été enregistré',
        'o bloco do modo que escolheu o relógio do dia (sem linha: escolhido à mão)' => 'le bloc du mode qui a choisi la montre du jour (sans ligne : choisie à la main)',
        'os dias livres do plano de uma coleção: sem relógio e sem sorteio (nem a escala), para escolher à mão' => 'les jours libres du plan d\'une collection : sans montre et sans tirage (ni le planning), à choisir à la main',
        'os aparelhos (navegadores) de cada conta inscritos no Web Push: o endereço, as chaves do navegador (p256dh, auth) e o nome do aparelho' => 'les appareils (navigateurs) de chaque compte inscrits au Web Push : l\'adresse, les clés du navigateur (p256dh, auth) et le nom de l\'appareil',
        'os relógios de uma coleção: nome, apelido (para distinguir dois iguais), grupo, se está disponível para o rodízio, a situação na coleção (posse), se pede a cópia no banco de todos os documentos e quando foi cadastrado' => 'les montres d\'une collection : nom, surnom (pour distinguer deux identiques), groupe, si elle est disponible pour la rotation, la situation dans la collection (possession), si elle demande la copie dans la base de tous les documents et quand elle a été enregistrée',
        'os valores do sistema inteiro: as marcas do cron, da cópia de segurança, do aleatório, das migrações, o endereço do sistema, o idioma da instalação e os avisos de vencimento já mandados' => 'les valeurs de tout le système : les marques du cron, de la sauvegarde, de l\'aléatoire, des migrations, l\'adresse du système, la langue de l\'installation et les avis d\'expiration déjà envoyés',
        'as contas: o login, o e-mail (para recuperar a senha, os convites e os avisos da conta), o hash da senha (password_hash), o papel (master: cuida do sistema inteiro; comum), o idioma, quando vence (a conta de demonstração; vazio: oficial), se está bloqueada, quando foi criada e o último acesso' => 'les comptes : l\'identifiant, l\'e-mail (pour récupérer le mot de passe, les invitations et les avis du compte), le hash du mot de passe (password_hash), le rôle (master : s\'occupe de tout le système ; comum), la langue, quand il expire (le compte de démonstration ; vide : officiel), s\'il est bloqué, quand il a été créé et le dernier accès',
        'os links de Esqueci a senha: o hash do token e até quando vale (2 horas)' => 'les liens de Mot de passe oublié : le hash du jeton et jusqu\'à quand il est valable (2 heures)',
        'mysql (MySQL ou MariaDB, o padrão), pgsql (PostgreSQL), sqlite ou firebird (Firebird 3+)' => 'mysql (MySQL ou MariaDB, le défaut), pgsql (PostgreSQL), sqlite ou firebird (Firebird 3+)',
        'o servidor do banco (MySQL, PostgreSQL e Firebird; no Firebird, DB_NOME é o caminho do arquivo .fdb no servidor ou um apelido, e DB_HOST vazio abre o arquivo direto)' => 'le serveur de la base (MySQL, PostgreSQL et Firebird ; sous Firebird, DB_NOME est le chemin du fichier .fdb sur le serveur ou un alias, et DB_HOST vide ouvre le fichier directement)',
        'o arquivo do banco (SQLite), fora da pasta publicada' => 'le fichier de la base (SQLite), hors du dossier publié',
        'obrigatório, com pelo menos 10 caracteres: o token do servidor (vale como o master mais antigo); sem ele o sistema inteiro para (as páginas, a API e o cron dizem o motivo)' => 'obligatoire, d\'au moins 10 caractères : le jeton du serveur (il vaut comme le master le plus ancien) ; sans lui tout le système s\'arrête (les pages, l\'API et le cron disent pourquoi)',
        'opcional: a chave que cifra os segredos guardados no banco (as senhas do CalDAV, as chaves do Google, os tokens do Outlook, os cabeçalhos dos webhooks); sem ela, o API_TOKEN (trocar a chave perde os segredos guardados)' => 'facultatif : la clé qui chiffre les secrets stockés dans la base (les mots de passe CalDAV, les clés Google, les jetons Outlook, les en-têtes des webhooks) ; sans elle, l\'API_TOKEN (changer la clé fait perdre les secrets stockés)',
        'o fuso horário do sistema e das datas gravadas (vazio: o do PHP)' => 'le fuseau horaire du système et des dates enregistrées (vide : celui de PHP)',
        'opcional: false fecha o cadastro aberto (cadastro.php): só entra quem o master cria ou quem tem um convite; sem a linha, aberto' => 'facultatif : false ferme l\'inscription ouverte (cadastro.php) : n\'entre que qui le master crée ou qui a une invitation ; sans la ligne, ouverte',
        'opcional: os dias da conta de demonstração, a criada pelo cadastro aberto (padrão 30; 0: a conta já nasce oficial). Vencida, o cron a apaga com tudo' => 'facultatif : les jours du compte de démonstration, celui créé par l\'inscription ouverte (30 par défaut ; 0 : le compte naît déjà officiel). Expiré, le cron l\'efface avec tout',
        'opcional: quantos dias um convite ou um pedido de acesso espera (padrão 7); depois, o cron apaga' => 'facultatif : combien de jours une invitation ou une demande d\'accès attend (7 par défaut) ; ensuite, le cron l\'efface',
        'o envio de e-mail (os destinos de e-mail, o Esqueci a senha, os convites, os avisos da conta): smtp ou mail (o mail() do PHP); o remetente (sem ele, o SMTP_USUARIO). Sem EMAIL_METODO e com SMTP_HOST, vale smtp' => 'l\'envoi d\'e-mails (les destinations e-mail, Mot de passe oublié, les invitations, les avis du compte) : smtp ou mail (le mail() de PHP) ; l\'expéditeur (sans lui, le SMTP_USUARIO). Sans EMAIL_METODO et avec SMTP_HOST, smtp s\'applique',
        'o servidor SMTP: o endereço, a porta (padrão 587, ou 465 com ssl), a segurança (tls: STARTTLS, o padrão; ssl: TLS desde o começo; nenhuma) e o login' => 'le serveur SMTP : l\'adresse, le port (587 par défaut, ou 465 avec ssl), la sécurité (tls : STARTTLS, le défaut ; ssl : TLS dès le début ; nenhuma) et l\'identifiant',
        'opcional: guarda uma cópia de cada e-mail enviado na pasta Enviados (padrão Sent) da conta, por IMAP' => 'facultatif : garde une copie de chaque e-mail envoyé dans le dossier Envoyés (Sent par défaut) du compte, par IMAP',
        'opcional: só para o teste do e-mail conferir a caixa por POP3 (alguns provedores pedem o POP antes do SMTP)' => 'facultatif : seulement pour que le test de l\'e-mail vérifie la boîte par POP3 (certains fournisseurs exigent le POP avant le SMTP)',
        'o Web Push: o par de chaves VAPID em base64url (o master gera em Minha conta) e o assunto (mailto: ou o endereço do sistema)' => 'le Web Push : la paire de clés VAPID en base64url (le master la génère dans Mon compte) et le sujet (mailto: ou l\'adresse du système)',
        'o aplicativo registrado na Microsoft (Entra ID) para as agendas do Outlook; o endereço de retorno é api.php?recurso=outlook_retorno. Sem eles, o Outlook fica de fora (use o link ICS)' => 'l\'application enregistrée chez Microsoft (Entra ID) pour les agendas Outlook ; l\'adresse de retour est api.php?recurso=outlook_retorno. Sans elles, Outlook reste à l\'écart (utilisez le lien ICS)',
        'só para a migração v25: a API de mensagem antiga (Telegram) vira o primeiro destino webhook da coleção; MSG_TITULO continua sendo o título das mensagens' => 'seulement pour la migration v25 : l\'ancienne API de messages (Telegram) devient la première destination webhook de la collection ; MSG_TITULO reste le titre des messages',
        'a pasta dos arquivos dos documentos, fora da pasta publicada, com escrita para o PHP' => 'le dossier des fichiers des documents, hors du dossier publié, accessible en écriture pour PHP',
        'a constante antiga da cópia dos documentos no banco para o servidor inteiro: não vale mais (a escolha é a chave documentos_copia da Configuração de cada coleção); o código só a lê para a Configuração avisar que ela ainda está no config.php' => 'l\'ancienne constante de la copie des documents dans la base pour tout le serveur : elle ne vaut plus (le choix est la clé documentos_copia de la Configuration de chaque collection) ; le code ne la lit que pour que la Configuration avertisse qu\'elle est encore dans le config.php',
        'o maior documento aceito, em bytes (sem ele: 100 MB; 0 ou -1: sem limite do sistema)' => 'le plus grand document accepté, en octets (sans lui : 100 Mo ; 0 ou -1 : pas de limite du système)',
        'opcional, para quem traduz: true faz a tradução que falta parar com erro (na API e no cron; nas telas, o texto aparece entre ⟦ ⟧ e o erro vai para o console)' => 'facultatif, pour qui traduit : true fait qu\'une traduction manquante s\'arrête sur une erreur (dans l\'API et le cron ; sur les écrans, le texte apparaît entre ⟦ ⟧ et l\'erreur va dans la console)',
        'opcional: false desliga a cópia de segurança (sem cópia automática, sem a escrita fazer e sem o quadro da Configuração); sem a linha, ligada' => 'facultatif : false désactive la sauvegarde (pas de copie automatique, pas d\'écriture fazer et pas de cadre dans la Configuration) ; sans la ligne, activée',
        'a cópia de segurança do banco: a pasta (fora da publicada; sem ela, não há cópia automática), quantas ficam (padrão 7) e se leva o conteúdo dos documentos guardado no banco' => 'la sauvegarde de la base : le dossier (hors du dossier publié ; sans lui, pas de sauvegarde automatique), combien sont gardées (7 par défaut) et si elle emporte le contenu des documents stocké dans la base',
        'só para importar o sistema anterior (importar.php)' => 'seulement pour importer le système précédent (importar.php)',
        'só para testes: as fontes dos números aleatórios (RANDOM.ORG e ANU QRNG); trocadas, os sorteios pedem os números a um servidor de teste' => 'seulement pour les tests : les sources des nombres aléatoires (RANDOM.ORG et ANU QRNG) ; une fois remplacées, les tirages demandent les nombres à un serveur de test',
        'só para testes: os endereços do Google e da Microsoft que as agendas usam; trocados, a sincronização conversa com um servidor de teste' => 'seulement pour les tests : les adresses de Google et de Microsoft que les agendas utilisent ; changées, la synchronisation parle à un serveur de test',
        'A interface que a reescrita tem de reproduzir, tela por tela: o visual (cores, letras, controles e componentes, com os valores exatos), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem, com cada tabela (as colunas), cada formulário (os campos com o rótulo, o tipo, o padrão e os limites), cada botão (o texto e o que ele manda para a API) e cada mensagem. Os textos entre aspas são os da tela, palavra por palavra. As capturas em docs/telas/ mostram o resultado; o estilo.css é a referência de cada medida. O código de cada página, como está agora, sai pelo recurso=codigo (os arquivos dela em codigo; o HTML que ela entrega ao navegador em recurso=codigo&arquivo=<página>&html=1&cru=1).' => 'L\'interface que la réécriture doit reproduire, écran par écran : le visuel (couleurs, caractères, contrôles et composants, avec les valeurs exactes), le menu, et chaque page avec l\'adresse, ce qu\'elle lit et enregistre dans l\'API, et les parties dans l\'ordre, avec chaque tableau (les colonnes), chaque formulaire (les champs avec le libellé, le type, la valeur par défaut et les limites), chaque bouton (le texte et ce qu\'il envoie à l\'API) et chaque message. Les textes entre guillemets sont ceux de l\'écran, mot pour mot. Les captures dans docs/telas/ montrent le résultat ; le estilo.css est la référence de chaque mesure. Le code de chaque page, tel qu\'il est maintenant, sort par recurso=codigo (ses fichiers dans codigo ; le HTML qu\'elle livre au navigateur dans recurso=codigo&arquivo=<página>&html=1&cru=1).',
        'Fundo da página: aço #e4e8ec. Bordas: aço escuro #c3cad2. Texto: tinta #1c2530 (também o fundo da barra do menu). Rótulos e notas: cinza #6b7684. Botões, links, aba ativa, barras de carga: safira #1f4f8f. O que fazer, recados e carga baixa: âmbar #a8661a. Fundo de cartões, quadros e tabelas: papel #fbfcfd.' => 'Fond de la page : acier #e4e8ec. Bordures : acier foncé #c3cad2. Texte : encre #1c2530 (aussi le fond de la barre du menu). Libellés et notes : gris #6b7684. Boutons, liens, onglet actif, barres de charge : saphir #1f4f8f. Que faire, messages et charge basse : ambre #a8661a. Fond des cartes, cadres et tableaux : papier #fbfcfd.',
        'Etiquetas de estado (pílulas): em uso: fundo #e3f3e6, texto #1e6b2e, borda #a9d8b3. Em repouso e erro: fundo #fbe8e6, texto #9b2c22, borda #efb5ae. Indisponível e sem atividade: fundo #eef1f4, texto cinza, borda aço escuro. Atividade, "você" e "relógio de hoje": fundo #e6eef8, texto #1f4f8f, borda #b8cbe6. Numa sessão que não é o pulso (no sol, no winder, no carregador), outras sessões e carga: fundo #fff4e0, texto #8a5a00, borda #efd29a.' => 'Étiquettes d\'état (pilules) : en usage : fond #e3f3e6, texte #1e6b2e, bordure #a9d8b3. Au repos et erreur : fond #fbe8e6, texte #9b2c22, bordure #efb5ae. Indisponible et sans activité : fond #eef1f4, texte gris, bordure acier foncé. Activité, « vous » et « montre du jour » : fond #e6eef8, texte #1f4f8f, bordure #b8cbe6. Dans une session qui n\'est pas le poignet (au soleil, sur le remontoir, sur le chargeur), les autres sessions et la charge : fond #fff4e0, texte #8a5a00, bordure #efd29a.',
        'Origem de um valor do cadastro: "informado" em azul (#e6eef8 / #1f4f8f / #b8cbe6), "padrão" em bege (#fbf1e3 / #8a5a00 / #ecd2a8), "vazio" sem etiqueta e com a linha em cinza.' => 'Origine d\'une valeur de la fiche : « informado » en bleu (#e6eef8 / #1f4f8f / #b8cbe6), « par défaut » en beige (#fbf1e3 / #8a5a00 / #ecd2a8), « vazio » sans étiquette et avec la ligne en gris.',
        'Atrasado (um prazo vencido, "faltam" e "passa" das somas): texto #9b2c22 em negrito. Caixa de erros de gravação: fundo #fdf0ee, borda #e3b4ae, texto #7a2419, cantos 10px. Linha de execução com erro: fundo #fdf2f1.' => 'En retard (une échéance dépassée, « il manque » et « dépasse » des sommes) : texte #9b2c22 en gras. Boîte d\'erreurs d\'enregistrement : fond #fdf0ee, bordure #e3b4ae, texte #7a2419, coins 10px. Ligne d\'exécution avec erreur : fond #fdf2f1.',
        'Letras e números' => 'Caractères et nombres',
        'Fonte: "Segoe UI", "Helvetica Neue", Arial, sans-serif, 16px, entrelinha 1,5.' => 'Police : "Segoe UI", "Helvetica Neue", Arial, sans-serif, 16px, interligne 1,5.',
        'Título da página (h1): grande, de 2rem a 3,4rem conforme a largura (clamp(2rem, 6vw, 3.4rem)), negrito 700, espaçamento -0,02em, entrelinha 1,05. Título de seção (h2): 1,1rem. Notas e explicações: 0,92rem, cinza. Título dos quadros do painel do relógio: 0,78rem, maiúsculas, negrito, espaçado 0,06em, cinza, com uma linha embaixo. Números em tabelas e valores com algarismos de largura igual (tabular).' => 'Titre de la page (h1) : grand, de 2rem à 3,4rem selon la largeur (clamp(2rem, 6vw, 3.4rem)), gras 700, espacement -0,02em, interligne 1,05. Titre de section (h2) : 1,1rem. Notes et explications : 0,92rem, gris. Titre des cadres du panneau de la montre : 0,78rem, majuscules, gras, espacé 0,06em, gris, avec un trait en dessous. Nombres dans les tableaux et valeurs avec des chiffres de largeur égale (tabular).',
        'Formatos: data DD/MM/AAAA (curta: DD/MM); hora HH:MM; números com vírgula e sem zeros sobrando (1 casa por padrão); dinheiro "R$ 1.234,56"; porcentagem "12,5%"; duração pelas duas maiores partes: "1a 5m", "5d 3h", "12h 22min", "40min", "menos de 1min"; dia da semana curto: seg, ter, qua, qui, sex, sáb, dom.' => 'Formats : date JJ/MM/AAAA (courte : JJ/MM) ; heure HH:MM ; nombres avec virgule et sans zéros en trop (1 décimale par défaut) ; argent « R$ 1.234,56 » ; pourcentage « 12,5 % » ; durée par les deux plus grandes parties : « 1a 5m », « 5j 3h », « 12h 22min », « 40min », « moins de 1min » ; jour de la semaine court : lun, mar, mer, jeu, ven, sam, dim.',
        'Campos, listas e botões' => 'Champs, listes et boutons',
        'Uma altura só para campo, lista e botão: 2,4rem, para ficarem alinhados lado a lado. Cantos 8px; campo e lista com borda 1px aço escuro e fundo branco; textarea com a mesma borda. Foco visível: contorno 2px safira afastado 2px. Campo numérico curto: 5,5rem. Números digitados aceitam vírgula ou ponto (teclado decimal no celular). No celular, os campos têm letra de 16px (o iPhone não aproxima a tela).' => 'Une seule hauteur pour le champ, la liste et le bouton : 2,4rem, pour qu\'ils s\'alignent côte à côte. Coins 8px ; champ et liste avec une bordure 1px acier foncé et un fond blanc ; textarea avec la même bordure. Focus visible : contour 2px saphir écarté de 2px. Champ numérique court : 5,5rem. Les nombres saisis acceptent la virgule ou le point (clavier décimal sur le téléphone). Sur le téléphone, les champs ont une lettre de 16px (l\'iPhone ne zoome pas l\'écran).',
        'Botão principal: fundo safira, texto branco, borda safira, preenchimento 0,3rem 1rem. Botão "leve": fundo transparente, texto e borda safira (as ações secundárias). Botão "discreto": sem borda, 0,85rem, preenchimento lateral 0,45rem (↑, ↓ e Excluir das linhas). O Excluir das ações de linha é vermelho: texto #9b2c22, borda #efb5ae, fundo #fbe8e6 ao passar o mouse.' => 'Bouton principal : fond saphir, texte blanc, bordure saphir, remplissage 0,3rem 1rem. Bouton « léger » : fond transparent, texte et bordure saphir (les actions secondaires). Bouton « discret » : sans bordure, 0,85rem, remplissage latéral 0,45rem (↑, ↓ et Supprimer des lignes). Le Supprimer des actions de ligne est rouge : texte #9b2c22, bordure #efb5ae, fond #fbe8e6 au survol.',
        'Caixa de marcar (checkbox) sempre à esquerda do texto, na mesma linha. Rótulo de campo: acima do campo nas grades de formulário; à esquerda na Configuração (veja os componentes). Botões desativados durante o envio de um formulário.' => 'Case à cocher (checkbox) toujours à gauche du texte, sur la même ligne. Libellé de champ : au-dessus du champ dans les grilles de formulaire ; à gauche dans la Configuration (voir les composants). Boutons désactivés pendant l\'envoi d\'un formulaire.',
        'Barra do menu: fundo tinta, links #b9c3ce sem sublinhado; o da página atual em branco com uma linha branca de 2px embaixo.' => 'Barre du menu : fond encre, liens #b9c3ce sans soulignement ; celui de la page actuelle en blanc avec un trait blanc de 2px en dessous.',
        'Cartão (as seções das páginas de cadastro): fundo papel, borda 1px aço escuro, cantos 12px, preenchimento 1rem, título h2 em cima.' => 'Carte (les sections des pages de définitions) : fond papier, bordure 1px acier foncé, coins 12px, remplissage 1rem, titre h2 en haut.',
        'Quadro (o painel do relógio): igual ao cartão (cantos 12px, preenchimento 0,85rem 1rem), com o título em maiúsculas pequenas, o corpo, e um rodapé opcional (linha em cima, botões à direita, alinhados no pé: os quadros da mesma linha da grade têm a mesma altura). Quadro "largo" ocupa a linha inteira da grade.' => 'Cadre (le panneau de la montre) : identique à la carte (coins 12px, remplissage 0,85rem 1rem), avec le titre en petites majuscules, le corps, et un pied facultatif (trait au-dessus, boutons à droite, alignés en bas : les cadres de la même ligne de la grille ont la même hauteur). Cadre « large » occupe toute la ligne de la grille.',
        'Pares (rótulo e valor): duas colunas, o rótulo em cinza 0,85rem à esquerda (até 55% da largura), o valor à direita; uma linha fina aço entre os pares (a última sem); um texto menor (0,78rem, cinza) embaixo do valor é a explicação dele; rótulo vazio continua a linha de cima.' => 'Paires (libellé et valeur) : deux colonnes, le libellé en gris 0,85rem à gauche (jusqu\'à 55 % de la largeur), la valeur à droite ; un trait fin acier entre les paires (la dernière sans) ; un texte plus petit (0,78rem, gris) sous la valeur est son explication ; un libellé vide continue la ligne du dessus.',
        'Tabela: fundo papel, cantos 10px, cabeçalho em cinza 0,9rem negrito, células com preenchimento 0,55rem 0,75rem e uma linha aço embaixo. Linha clicável: o fundo muda para #f1f4f8 ao passar e fica #e3eaf5 quando selecionada; fim de semana em #f4f6f8; o relógio de hoje com uma faixa safira de 3px na borda esquerda, e um com aviso pendente com a faixa âmbar. Tabela compacta (dos cadastros): 0,88rem, sem fundo próprio.' => 'Tableau : fond papier, coins 10px, en-tête en gris 0,9rem gras, cellules avec remplissage 0,55rem 0,75rem et un trait acier en dessous. Ligne cliquable : le fond passe à #f1f4f8 au survol et reste #e3eaf5 quand elle est sélectionnée ; week-end en #f4f6f8 ; la montre du jour avec une bande saphir de 3px sur le bord gauche, et une avec une alerte en attente avec la bande ambre. Tableau compact (des définitions) : 0,88rem, sans fond propre.',
        'Etiqueta de estado: pílula com cantos arredondados por inteiro, 0,8rem negrito, preenchimento 0,12rem 0,55rem, cores em "cores". Numa linha só; nos pares rótulo/valor (o quadro Agora do painel estreito) e nas marcas da cabeça, a comprida ("Em repouso desde 25/09 20:40") quebra a linha nos espaços (nunca no meio da palavra), com cantos de 0,8rem, e fica dentro do quadro.' => 'Étiquette d\'état : pilule aux coins entièrement arrondis, 0,8rem gras, remplissage 0,12rem 0,55rem, couleurs dans « cores ». Sur une seule ligne ; dans les paires libellé/valeur (le cadre Maintenant du panneau étroit) et dans les marques de l\'en-tête, la longue (« Au repos depuis 25/09 20:40 ») passe à la ligne sur les espaces (jamais au milieu du mot), avec des coins de 0,8rem, et reste dans le cadre.',
        'Barra de carga: trilho aço com 7px de altura (44px na tabela, 56 a 70px nos quadros), preenchido em safira até a porcentagem (âmbar com carga até 20%), seguido do número em negrito ("68%"; estimado: "~68%") e, menor, de onde a carga vem.' => 'Barre de charge : rail acier de 7px de haut (44px dans le tableau, 56 à 70px dans les cadres), rempli en saphir jusqu\'au pourcentage (ambre avec une charge jusqu\'à 20 %), suivi du nombre en gras (« 68 % » ; estimé : « ~68 % ») et, plus petit, d\'où vient la charge.',
        'Janela de data (o "só hoje" / "até sexta, 02/10" do relógio do dia): caixa branca, borda 2px tinta, cantos 3px, negrito, sombra interna fina, como a janela de data de um mostrador.' => 'Fenêtre de date (le « seulement aujourd\'hui » / « jusqu\'à vendredi, 02/10 » de la montre du jour) : boîte blanche, bordure 2px encre, coins 3px, gras, ombre interne fine, comme la fenêtre de date d\'un cadran.',
        'Recado (o resultado de uma gravação): um parágrafo âmbar em negrito no topo da área (ou do painel do relógio). Erros de gravação: a caixa vermelha clara com "Não foi salvo:" e um parágrafo por erro, no topo da página.' => 'Message (le résultat d\'un enregistrement) : un paragraphe ambre en gras en haut de la zone (ou du panneau de la montre). Erreurs d\'enregistrement : la boîte rouge clair avec « Non enregistré : » et un paragraphe par erreur, en haut de la page.',
        'Abas (Cadastros e Documentos): links lado a lado com borda aço e cantos 0,4rem, preenchimento 0,35rem 0,8rem, texto safira; a ativa com fundo safira e texto branco.' => 'Onglets (Définitions et Documents) : liens côte à côte avec bordure acier et coins 0,4rem, remplissage 0,35rem 0,8rem, texte saphir ; l\'actif avec fond saphir et texte blanc.',
        'Grade de formulário (form-grade): colunas de no mínimo 14rem lado a lado, o rótulo acima de cada campo; textareas, grupos de caixas e botões na linha inteira. Linha de inclusão: campos com o rótulo em cima, lado a lado, separados do resto por uma linha tracejada acima.' => 'Grille de formulaire (form-grade) : colonnes d\'au moins 14rem côte à côte, le libellé au-dessus de chaque champ ; textareas, groupes de cases et boutons sur toute la ligne. Ligne d\'ajout : champs avec le libellé au-dessus, côte à côte, séparés du reste par un trait en pointillés au-dessus.',
        'Barra de salvar (Configuração): presa no pé da tela enquanto a página rola (sticky), fundo papel quase opaco, borda, cantos 12px, sombra para cima; à esquerda "As mudanças desta página valem depois de salvar.", à direita o botão.' => 'Barre d\'enregistrement (Configuration) : collée au pied de l\'écran pendant le défilement de la page (sticky), fond papier presque opaque, bordure, coins 12px, ombre vers le haut ; à gauche « Les modifications de cette page s\'appliquent après l\'enregistrement. », à droite le bouton.',
        'Sem foto: quadrado tracejado (2px aço escuro, cantos 14px) com "Sem foto" em cinza no meio. Foto: quadrada (recortada), cantos 14px, borda aço escuro. Miniatura na tabela: 28px (36px no celular), cantos 5px.' => 'Pas de photo : carré en pointillés (2px acier foncé, coins 14px) avec « Pas de photo » en gris au milieu. Photo : carrée (recadrée), coins 14px, bordure acier foncé. Miniature dans le tableau : 28px (36px sur le téléphone), coins 5px.',
        'Ações de uma linha (Editar, ↑, ↓, Excluir): numa linha só, à direita da linha da tabela.' => 'Actions d\'une ligne (Modifier, ↑, ↓, Supprimer) : sur une seule ligne, à droite de la ligne du tableau.',
        'Resumo em números (Execuções e Histórico): uma grade de caixinhas (4 colunas; 2 no celular), cada uma com o número grande (1,4rem) e o que ele é embaixo em cinza; a de erros com fundo vermelho claro.' => 'Résumé en nombres (Exécutions et Historique) : une grille de petites cases (4 colonnes ; 2 sur le téléphone), chacune avec le nombre en grand (1,4rem) et ce qu\'il est en dessous en gris ; celle des erreurs avec un fond rouge clair.',
        'Larguras e tamanhos de tela' => 'Largeurs et tailles d\'écran',
        'Conteúdo centrado com margens de 1,25rem: largura máxima 56rem nas páginas comuns (Plano, Usuários), 72rem na Ficha, 76rem na Configuração, Cadastros, Critérios, Grupos, Execuções e Histórico, 60rem na Ajuda. A página Hoje usa a largura toda.' => 'Contenu centré avec des marges de 1,25rem : largeur maximale 56rem sur les pages courantes (Plan, Utilisateurs), 72rem sur la Fiche, 76rem sur la Configuration, Définitions, Critères, Groupes, Exécutions et Historique, 60rem sur l\'Aide. La page Aujourd\'hui utilise toute la largeur.',
        'Página Hoje: duas colunas, o meio e o painel do relógio com 22rem à direita, preso ao rolar (sticky) e com rolagem própria; sem relógio aberto, o meio ocupa tudo. Com a Configuração "Numa janela flutuante, grande": o relógio abre no meio da tela, até 78rem ou 94% da largura, de 3% do alto a 3% de baixo, cantos 16px, sombra forte, com o fundo escurecido (rgba(16, 22, 29, .55)) e os quadros lado a lado; fecha no ×, no Esc ou num clique no fundo.' => 'Page Aujourd\'hui : deux colonnes, le milieu et le panneau de la montre de 22rem à droite, collé au défilement (sticky) et avec son propre défilement ; sans montre ouverte, le milieu occupe tout. Avec la Configuration « Dans une grande fenêtre flottante » : la montre s\'ouvre au milieu de l\'écran, jusqu\'à 78rem ou 94 % de la largeur, de 3 % du haut à 3 % du bas, coins 16px, ombre forte, avec le fond assombri (rgba(16, 22, 29, .55)) et les cadres côte à côte ; se ferme sur le ×, sur Échap ou sur un clic dans le fond.',
        'Até 900px (celular e tablet de pé): o menu recolhido; as tabelas viram fichas (cada célula com o título da coluna ao lado) ou cartões; o painel do relógio cobre a tela inteira, com o botão "× Fechar" preso no alto, e o voltar do aparelho fecha o painel; as grades viram uma coluna. De 901 a 1199px (tablet deitado): o painel "ao lado" desliza por cima, pela direita, com até 30rem, cantos 16px à esquerda e o fundo escurecido. De 1200px em diante: o painel ao lado.' => 'Jusqu\'à 900px (téléphone et tablette à la verticale) : le menu replié ; les tableaux deviennent des fiches (chaque cellule avec le titre de la colonne à côté) ou des cartes ; le panneau de la montre couvre tout l\'écran, avec le bouton « × Fermer » collé en haut, et le retour de l\'appareil ferme le panneau ; les grilles deviennent une colonne. De 901 à 1199px (tablette à l\'horizontale) : le panneau « à côté » glisse par-dessus, par la droite, jusqu\'à 30rem, coins 16px à gauche et le fond assombri. À partir de 1200px : le panneau à côté.',
        'Nenhuma página rola de lado, em nenhum tamanho. A mesma informação em todos os tamanhos: nada é escondido por falta de espaço (a tabela dos relógios vira cartões com todos os campos quando as 12 colunas não cabem).' => 'Aucune page ne défile de côté, à aucune taille. La même information à toutes les tailles : rien n\'est caché par manque de place (le tableau des montres devient des cartes avec tous les champs quand les 12 colonnes ne tiennent pas).',
        'As tabelas de um quadro se arrumam pela largura do quadro (container queries), não pela da tela: o mesmo quadro é estreito no painel ao lado e largo na ficha. Até 40rem, as Medições do gasto viram cartões; até 26rem, as tabelas dos Dados do relógio ficam mais justas e o valor quebra a linha.' => 'Les tableaux d\'un cadre s\'arrangent selon la largeur du cadre (container queries), pas celle de l\'écran : le même cadre est étroit dans le panneau à côté et large dans la fiche. Jusqu\'à 40rem, les Mesures de consommation deviennent des cartes ; jusqu\'à 26rem, les tableaux des Données de la montre se resserrent et la valeur passe à la ligne.',
        'Nada sai da caixa em que está, de 320px (celular pequeno) a 1920px: as grades de colunas automáticas encolhem a coluna mínima até a largura da tela; um grupo de campos (fieldset) e os menus dentro dele encolhem com a tela (um menu de nome comprido não vaza); o menu de escolher o relógio da Ficha fica na largura da tela; o código comprido da Ajuda (uma URL de exemplo) quebra a linha. Os botões nunca partem o texto em duas linhas: os da foto (Abrir, Trocar, Remover foto) ficam numa linha, na largura da foto (6,5rem no painel ao lado e no celular); o botão de marcar do quadro Marcar fica numa linha própria, embaixo dos campos. Até 420px, as tabelas do painel e o resumo do Plano ficam mais justas (0,82rem, 0,3rem entre as colunas) e quebram dentro da célula. No Histórico do celular, as colunas são 25%, 25%, 18% e 32% (o Estado, a mais larga).' => 'Rien ne sort de la boîte où il est, de 320px (petit téléphone) à 1920px : les grilles de colonnes automatiques réduisent la colonne minimale jusqu\'à la largeur de l\'écran ; un groupe de champs (fieldset) et les menus à l\'intérieur se réduisent avec l\'écran (un menu au nom long ne déborde pas) ; le menu de choix de la montre de la Fiche tient dans la largeur de l\'écran ; le code long de l\'Aide (une URL d\'exemple) passe à la ligne. Les boutons ne coupent jamais le texte en deux lignes : ceux de la photo (Ouvrir, Changer, Retirer la photo) restent sur une ligne, dans la largeur de la photo (6,5rem dans le panneau à côté et sur le téléphone) ; le bouton de marquage du cadre Marquer reste sur sa propre ligne, sous les champs. Jusqu\'à 420px, les tableaux du panneau et le résumé du Plan se resserrent (0,82rem, 0,3rem entre les colonnes) et passent à la ligne dans la cellule. Dans l\'Historique sur le téléphone, les colonnes font 25 %, 25 %, 18 % et 32 % (l\'État, la plus large).',
        'Comportamento comum' => 'Comportement commun',
        'Cada página entrega só o esqueleto; o JavaScript dela lê a API e monta a tela. Gravar é um formulário que manda um POST para a API (recurso e acao nos campos); depois a página se remonta com os dados novos, sem recarregar, e mostra a mensagem da API no topo (ou no painel do relógio, se a gravação era dele).' => 'Chaque page ne livre que le squelette ; son JavaScript lit l\'API et monte l\'écran. Enregistrer est un formulaire qui envoie un POST à l\'API (recurso et acao dans les champs) ; ensuite la page se reconstruit avec les données nouvelles, sans rechargement, et montre le message de l\'API en haut (ou dans le panneau de la montre, si l\'enregistrement était le sien).',
        'Antes de toda exclusão e de toda ação que refaz o plano, uma confirmação do navegador com o texto do que vai acontecer (os textos estão em cada página). Durante o envio os botões do formulário ficam desativados; se a conexão falhar: "Não consegui gravar: <motivo>. Confira a conexão e tente de novo."' => 'Avant toute suppression et toute action qui refait le plan, une confirmation du navigateur avec le texte de ce qui va se passer (les textes sont sur chaque page). Pendant l\'envoi les boutons du formulaire restent désactivés ; si la connexion échoue : « Impossible d\'enregistrer : <motif>. Vérifiez la connexion et réessayez. »',
        'Sem login, nada da página sai: o topo() confere o usuário e a senha no servidor (pagina_login(), no lib.php) antes da primeira linha e responde 401 com o pedido de senha do navegador (realm "Relogios", o mesmo da API); cancelado, só a página mínima "Entrar" com "Tentar de novo" e "Criar conta". Passam sem login só a Criar conta e, sem nenhum usuário (ou com o banco vazio ou fora do ar), as páginas, que não têm dado nenhum. Se o login cair com a página aberta, a API responde 401 e a página manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e volta. Banco desatualizado (503 com pendentes): a página vai para a Configuração, que mostra só o aviso e o "Aplicar agora". Erro ao ler: "Não consegui ler <o quê>: <motivo>" em âmbar, no lugar da página.' => 'Sans identifiant, rien de la page ne sort : topo() vérifie l\'utilisateur et le mot de passe sur le serveur (pagina_login(), dans lib.php) avant la première ligne et répond 401 avec la demande de mot de passe du navigateur (realm « Relogios », le même que l\'API) ; si on annule, seulement la page minimale « Se connecter » avec « Réessayer » et « Créer un compte ». Passent sans identifiant seulement Créer un compte et, sans aucun utilisateur (ou avec la base vide ou hors service), les pages, qui n\'ont aucune donnée. Si la connexion tombe avec la page ouverte, l\'API répond 401 et la page envoie vers api.php?recurso=entrar&volta=<la page>, le navigateur demande l\'utilisateur et le mot de passe et revient. Base pas à jour (503 avec pendentes) : la page va à la Configuration, qui ne montre que l\'avis et le « Appliquer maintenant ». Erreur de lecture : « Impossible de lire <quoi> : <motif> » en ambre, à la place de la page.',
        'Fotos reduzidas no navegador antes de enviar: no máximo 1200px no lado maior, JPEG 85%, com a prévia na tela; imagem que não abre: alerta "Não consegui abrir essa imagem. Use JPEG ou PNG.".' => 'Photos réduites dans le navigateur avant l\'envoi : au plus 1200px sur le plus grand côté, JPEG 85 %, avec l\'aperçu à l\'écran ; image qui ne s\'ouvre pas : alerte « Impossible d\'ouvrir cette image. Utilisez JPEG ou PNG. ».',
        'A foto do relógio ampliada, só no detalhe do relógio (o painel, ou a ficha): duplo clique na foto (o cursor é a lupa de ampliar) ou o botão "Abrir foto" embaixo dela abre por cima de tudo uma janela flutuante (nas outras fotos, como a do "Hoje é dia de" e as miniaturas da lista, o clique abre o relógio e o duplo clique não faz nada a mais): fundo rgba(10,14,20,.82) na tela inteira, a foto no meio, no tamanho dela (os pixels da imagem em px da página), cantos 6px, fundo branco e sombra; maior que a área que se vê, em escala, sem deformar: a escala é o menor entre 1, (largura − 32px) ÷ a largura da foto e (altura − 72px) ÷ a altura da foto, com a largura e a altura sendo o menor entre o monitor (screen.availWidth/availHeight) e a janela do navegador; refeita quando a janela muda de tamanho ou de monitor. Embaixo, em branco, "<nome> · <largura> × <altura> px" e, em escala, "(mostrada a N%)". Um botão redondo "×" (branco, 2,4rem) no canto de cima, à direita. Fecha com o ×, com um clique fora da foto ou com Esc (o Esc fecha só a foto: o painel por baixo continua aberto); enquanto aberta, a página não rola.' => 'La photo de la montre agrandie, seulement dans le détail de la montre (le panneau, ou la fiche) : un double clic sur la photo (le curseur est la loupe d\'agrandissement) ou le bouton « Ouvrir la photo » en dessous l\'ouvre par-dessus tout dans une fenêtre flottante (sur les autres photos, comme celle du « Aujourd\'hui, c\'est le jour de » et les miniatures de la liste, le clic ouvre la montre et le double clic ne fait rien de plus) : fond rgba(10,14,20,.82) sur tout l\'écran, la photo au milieu, à sa taille (les pixels de l\'image en px de la page), coins 6px, fond blanc et ombre ; plus grande que la zone visible, à l\'échelle, sans déformation : l\'échelle est le plus petit entre 1, (largeur − 32px) ÷ la largeur de la photo et (hauteur − 72px) ÷ la hauteur de la photo, la largeur et la hauteur étant le plus petit entre l\'écran (screen.availWidth/availHeight) et la fenêtre du navigateur ; refaite quand la fenêtre change de taille ou d\'écran. En dessous, en blanc, « <nom> · <largeur> × <hauteur> px » et, à l\'échelle, « (affichée à N %) ». Un bouton rond « × » (blanc, 2,4rem) dans le coin du haut, à droite. Se ferme avec le ×, avec un clic hors de la photo ou avec Échap (Échap ne ferme que la photo : le panneau en dessous reste ouvert) ; tant qu\'elle est ouverte, la page ne défile pas.',
        'O título da aba do navegador é o título da página ("Relógio de hoje", "Plano", "Configuração", "Critérios de escolha", "Grupos de relógios", "Execuções do cron", "Usuários", "Cadastros", "Ajuda", "Ficha do relógio", "Documentos", "Desejos", "Estatísticas", "Hora certa", "Acessórios", "Galeria", "Passaporte do relógio" ("Passaporte — <relógio>" depois de ler); no histórico, "Histórico — <relógio>").' => 'Le titre de l\'onglet du navigateur est le titre de la page (« Montre du jour », « Plan », « Configuration », « Critères de choix », « Groupes de montres », « Exécutions du cron », « Utilisateurs », « Définitions », « Aide », « Fiche de la montre », « Documents », « Envies », « Statistiques », « Heure exacte », « Accessoires », « Galerie », « Passeport de la montre » (« Passeport — <montre> » après la lecture) ; dans l\'historique, « Historique — <montre> »).',
        'O navegador de páginas (Próximos dias, Dia a dia do Plano, Rodízio manual): botões leves pequenos (padding .3rem .65rem, letra .9rem) numa linha que quebra: "<" (dica "Anterior"; desativado na primeira), os números (a 1, a última e até 2 de cada lado da atual, com "…" sem borda nos saltos; dica "Página N"; a atual em safira com letra branca, sem ser botão) e ">" (dica "Próximo"; desativado na última). Uma página só: sem navegador. Cada botão relê a API com a página.' => 'Le navigateur de pages (Prochains jours, Jour par jour du Plan, Rotation manuelle) : petits boutons légers (padding .3rem .65rem, lettre .9rem) sur une ligne qui passe à la ligne : « < » (indication « Précédent » ; désactivé sur la première), les numéros (la 1, la dernière et jusqu\'à 2 de chaque côté de l\'actuelle, avec « … » sans bordure sur les sauts ; indication « Page N » ; l\'actuelle en saphir avec une lettre blanche, sans être un bouton) et « > » (indication « Suivant » ; désactivé sur la dernière). Une seule page : pas de navigateur. Chaque bouton relit l\'API avec la page.',
        'Na barra escura do topo, em todas as páginas, nessa ordem: Hoje, Avisos e Hora certa soltos; os grupos Rodízio, Coleção, Sistema e Conta; e a Ajuda. No computador, cada grupo é um botão com "▾" que abre embaixo dele uma caixa escura com as páginas do grupo, uma por linha (abre uma de cada vez; fecha num clique fora ou no Esc); o grupo da página atual e a página atual em branco e sublinhados. A Ficha, o Histórico, os Documentos, os Destinos e as Agendas não estão no menu: os três primeiros abrem do painel do relógio (o histórico e os documentos numa aba nova), os Destinos e as Agendas da página Avisos. No celular (até 900px): a barra, presa no alto ao rolar, mostra o nome da página atual à esquerda e o botão "☰ Menu" à direita; aberto, ele vira "✕ Menu" e os itens aparecem em duas colunas, cada um num botão escuro (#27323f), o atual em safira; os grupos ficam abertos, com o nome do grupo em letras pequenas maiúsculas em cima das páginas dele, e os itens soltos depois de um grupo ocupam a linha inteira. Depois do último item, o seletor do idioma: uma caixa pequena com o código curto de cada idioma (PT, EN, 中文, हिं, ES, FR; o nome inteiro na dica); escolher grava o cookie lingua (um ano, o caminho todo) e abre a página de novo nele. Os rótulos abaixo são os do português: em outro idioma, as traduções do dicionário das telas. À direita, antes do idioma, o que é de quem entrou (recurso=conta, parte=menu): com mais de uma coleção, o seletor da coleção (grava o cookie colecao e abre a página de novo; o nome, e "· <dono>" nas dos outros); "Aprovações (N)" em âmbar quando há pedidos ou convites esperando; "Demo: N dias" em âmbar na conta de demonstração. O Usuários só aparece para o master. O master vendo como outro usuário: uma faixa âmbar acima de tudo, "Vendo como <login>: o que aparece e o que se grava é da conta dele." e o botão "Voltar a ser <master>". A conta sem coleção nenhuma (409 sem_colecao) vai para Minha conta. A página pública (cadastro.php) não tem menu, só o idioma.' => 'Dans la barre sombre du haut, sur toutes les pages, dans cet ordre : Aujourd\'hui, Alertes et Heure exacte seuls ; les groupes Rotation, Collection, Système et Compte ; et l\'Aide. Sur l\'ordinateur, chaque groupe est un bouton avec « ▾ » qui ouvre en dessous une boîte sombre avec les pages du groupe, une par ligne (un seul ouvert à la fois ; il se ferme sur un clic à l\'extérieur ou sur Échap) ; le groupe de la page actuelle et la page actuelle en blanc et soulignés. La Fiche, l\'Historique, les Documents, les Destinations et les Agendas ne sont pas dans le menu : les trois premiers s\'ouvrent depuis le panneau de la montre (l\'historique et les documents dans un nouvel onglet), les Destinations et les Agendas depuis la page Alertes. Sur le téléphone (jusqu\'à 900px) : la barre, fixée en haut au défilement, montre le nom de la page actuelle à gauche et le bouton « ☰ Menu » à droite ; ouvert, il devient « ✕ Menu » et les éléments apparaissent sur deux colonnes, chacun dans un bouton sombre (#27323f), l\'actuel en saphir ; les groupes restent ouverts, avec le nom du groupe en petites majuscules au-dessus de ses pages, et les éléments seuls après un groupe prennent toute la ligne. Après le dernier élément, le sélecteur de langue : une petite boîte avec le code court de chaque langue (PT, EN, 中文, हिं, ES, FR ; le nom complet dans l\'infobulle) ; choisir enregistre le cookie lingua (un an, tout le chemin) et rouvre la page dans cette langue. Les libellés ci-dessous sont ceux du portugais : dans une autre langue, les traductions du dictionnaire des écrans. À droite, avant la langue, ce qui est à la personne connectée (recurso=conta, parte=menu) : avec plus d\'une collection, le sélecteur de collection (enregistre le cookie colecao et rouvre la page ; le nom, et « · <dono> » sur celles des autres) ; « Approbations (N) » en ambre quand des demandes ou des invitations attendent ; « Démo : N jours » en ambre sur le compte de démonstration. Utilisateurs n\'apparaît que pour le master. Le master voyant comme un autre utilisateur : une bande ambre au-dessus de tout, « Vue en tant que <login> : ce qui s\'affiche et ce qui s\'enregistre est de son compte. » et le bouton « Redevenir <master> ». Le compte sans aucune collection (409 sem_colecao) va à Mon compte. La page publique (cadastro.php) n\'a pas de menu, seulement la langue.',
        'Avisos' => 'Alertes',
        'Hora certa' => 'Heure exacte',
        'Rodízio' => 'Rotation',
        'Modos de rodízio' => 'Modes de rotation',
        'Critérios de escolha' => 'Critères de choix',
        'Coleção' => 'Collection',
        'Acessórios' => 'Accessoires',
        'Estatísticas' => 'Statistiques',
        'Configuração' => 'Configuration',
        'Sistema' => 'Système',
        'Execuções do cron' => 'Exécutions du cron',
        'Usuários' => 'Utilisateurs',
        'Minha conta' => 'Mon compte',
        'Conta' => 'Compte',
        'Aprovações' => 'Approbations',
        'Relógio de hoje' => 'Montre du jour',
        'index.php; index.php?r=<id> abre o relógio no painel; index.php?novo=1 abre o cadastro de um novo; index.php#manual abre o quadro Modo de rodízio no Rodízio manual' => 'index.php ; index.php?r=<id> ouvre la montre dans le panneau ; index.php?novo=1 ouvre la fiche d\'une nouvelle ; index.php#manual ouvre le cadre Mode de rotation sur la Rotation manuelle',
        'recurso=hoje (com proximos_pagina)' => 'recurso=hoje (avec proximos_pagina)',
        'recurso=proximos (a troca de página dos Próximos dias)' => 'recurso=proximos (le changement de page des Prochains jours)',
        'recurso=ficha (o painel)' => 'recurso=ficha (le panneau)',
        'recurso=rodizio_manual (o Rodízio manual, de 7 em 7 dias)' => 'recurso=rodizio_manual (la Rotation manuelle, de 7 en 7 jours)',
        'lancamento: iniciar, encerrar, lancar, periodo, alterar, excluir' => 'lancamento : iniciar, encerrar, lancar, periodo, alterar, excluir',
        'rodizio: trocar_dia, modo, resortear, resortear_hoje, proxima_semana, usando, sem_relogio, manual, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio : trocar_dia, modo, resortear, resortear_hoje, proxima_semana, usando, sem_relogio, manual, periodo_sortear, periodo_livre, apagar_tudo',
        'relogio: salvar, foto, remover_foto, excluir' => 'relogio : salvar, foto, remover_foto, excluir',
        'O relógio do dia (um cartão grande, no alto do meio)' => 'La montre du jour (une grande carte, en haut du milieu)',
        'O relógio do cartão é o de destaque.relogio_id da API (o que tem relogios[].destaque): o relógio do dia, ou, com a Configuração "Destaque no alto da página Hoje" em "O relógio no pulso agora" (destaque_hoje = pulso), o que está no pulso agora. Quando ele não é o do dia (destaque.e = pulso): o nome dele em h1 (link que abre o painel), a janela de data com "no pulso agora" e o tipo dele, e em âmbar "Relógio do dia: <nome, link que abre o painel> (<até>)" (ou "Hoje não tem relógio do dia."), sem o motivo. Com o destaque no pulso e ninguém no pulso, o cartão do dia como sempre e, embaixo do motivo, o destaque.texto em cinza ("Nenhum relógio no pulso agora: aqui, o relógio do dia."). Os pares, o botão Pôs/Tirou do pulso e a foto são do relógio do cartão.' => 'La montre de la carte est celle de destaque.relogio_id de l\'API (celle qui a relogios[].destaque) : la montre du jour, ou, avec la Configuration « Mise en avant en haut de la page Aujourd\'hui » sur « La montre au poignet maintenant » (destaque_hoje = pulso), celle qui est au poignet maintenant. Quand ce n\'est pas celle du jour (destaque.e = pulso) : son nom en h1 (lien qui ouvre le panneau), la fenêtre de date avec « au poignet maintenant » et son type, et en ambre « Montre du jour : <nom, lien qui ouvre le panneau> (<jusqu\'à>) » (ou « Pas de montre du jour aujourd\'hui. »), sans le motif. Avec la mise en avant sur le poignet et personne au poignet, la carte du jour comme toujours et, sous le motif, le destaque.texto en gris (« Aucune montre au poignet maintenant : ici, la montre du jour. »). Les paires, le bouton Mise/Retirée du poignet et la photo sont ceux de la montre de la carte.',
        'À esquerda: "<Dia da semana>, DD/MM/AAAA · <nome do modo>" em cinza; o nome do relógio do dia em h1 (link que abre o painel); a janela de data com o "até" ("só hoje", "até sexta, 02/10") e o tipo dele; o lembrete do dia em âmbar ("Pôr no winder: <relógio> (8 h)"); "Por que ele: <motivo>" (o motivo em cinza); embaixo, o botão leve discreto "Sem relógio hoje" (rodizio sem_relogio; confirma "Hoje sem relógio? O dia fica livre: ...").' => 'À gauche : « <Jour de la semaine>, JJ/MM/AAAA · <nom du mode> » en gris ; le nom de la montre du jour en h1 (lien qui ouvre le panneau) ; la fenêtre de date avec le « jusqu\'à » (« seulement aujourd\'hui », « jusqu\'à vendredi, 02/10 ») et son type ; le rappel du jour en ambre (« Mettre sur le remontoir : <montre> (8 h) ») ; « Pourquoi elle : <motif> » (le motif en gris) ; en dessous, le bouton léger discret « Jour sans montre » (rodizio sem_relogio ; confirme « Pas de montre aujourd\'hui ? La journée reste libre : ... »).',
        'No meio, em pares: Agora (a etiqueta "Em uso desde 07:00", "No sol desde 09:12" ou "Em repouso desde ...", na cor do estado, e o botão leve "Pôs no pulso" / "Tirou do pulso", que manda lancamento iniciar/encerrar do tipo pulso); Carga (a barra, o % e de onde vem, ou só o texto); Última leitura ("89% em 06/10 21:30", se houver); Situação (as linhas da API); Próxima manutenção ("<nome> · <data ou hoje> (<falta>)", a falta em vermelho se atrasada, ou "nenhuma prevista"; o aviso mais perto, sem o Encostado); Encostado (só quando o aviso já venceu: a falta em vermelho); Compra ("R$ valor · loja · data"); Garantia ("até DD/MM/AAAA", "(vencida)" se passou); Código.' => 'Au milieu, en paires : Maintenant (l\'étiquette « En usage depuis 07:00 », « Au soleil depuis 09:12 » ou « Au repos depuis ... », dans la couleur de l\'état, et le bouton léger « Mise au poignet » / « Retirée du poignet », qui envoie lancamento iniciar/encerrar du type pulso) ; Charge (la barre, le % et d\'où elle vient, ou seulement le texte) ; Dernière lecture (« 89 % le 06/10 21:30 », s\'il y en a) ; Statut (les lignes de l\'API) ; Prochain entretien (« <nom> · <date ou aujourd\'hui> (<reste>) », le reste en rouge s\'il est en retard, ou « aucun prévu » ; l\'alerte la plus proche, sans la Délaissée) ; Délaissée (seulement quand l\'alerte est déjà échue : le reste en rouge) ; Achat (« R$ valeur · boutique · date ») ; Garantie (« jusqu\'au JJ/MM/AAAA », « (expirée) » si elle est passée) ; Code.',
        'À direita: a foto do relógio (ou o quadrado "Sem foto"), que abre o painel.' => 'À droite : la photo de la montre (ou le carré « Pas de photo »), qui ouvre le panneau.',
        'Hoje livre (hoje_livre da API: o Sem relógio hoje, ou um período livre): h1 "Hoje sem relógio", a janela "dia livre", "Nenhum relógio vai ao pulso pelo rodízio hoje. Quer usar um? ..." e o "escolher…" dos dias livres (trocar_dia de hoje: o escolhido vai para o pulso a partir de agora); sem os pares nem a foto (a não ser com o destaque no pulso).' => 'Aujourd\'hui libre (hoje_livre de l\'API : le Jour sans montre, ou une période libre) : h1 « Aujourd\'hui sans montre », la fenêtre « jour libre », « Aucune montre ne va au poignet par la rotation aujourd\'hui. Vous voulez en porter une ? ... » et le « choisir… » des jours libres (trocar_dia d\'aujourd\'hui : la choisie va au poignet à partir de maintenant) ; sans les paires ni la photo (sauf avec la mise en avant sur le poignet).',
        'Sem relógio para hoje: h1 "Nenhum relógio para hoje" e "Nenhum relógio disponível no grupo deste dia. Mude o grupo no modo de rodízio ou marque um relógio como disponível."' => 'Pas de montre pour aujourd\'hui : h1 « Aucune montre pour aujourd\'hui » et « Aucune montre disponible dans le groupe de ce jour. Changez le groupe dans le mode de rotation ou marquez une montre comme disponible. »',
        'Hoje é dia de (só quando há aviso)' => 'Aujourd\'hui, c\'est le jour de (seulement quand il y a une alerte)',
        'Tabela com as colunas "O que fazer" (o nome do aviso; atrasado em vermelho), "Relógio" (link que abre o painel), "Por quê" (o texto do aviso) e, à direita, o botão do lançamento que resolve, com o texto e a ação que a API dá (resolve.botao e resolve.acao): sessão fechada: "Pôs <nome em minúsculas>" (lancamento iniciar); sessão aberta: "Tirou do carregador" (lancamento encerrar); com valor: um campo curto com a unidade de dica ("%") e "Informar <nome>" (lancamento lancar com valor), ou, com resolve.estados (a leitura que mede o gasto num relógio que vai ao pulso), os dois botões leves "Em uso" e "Em repouso" no lugar dele (o lancar com estado=uso ou estado=repouso); instantâneo: o nome do tipo (lancamento lancar).' => 'Tableau avec les colonnes « Que faire » (le nom de l\'alerte ; en retard en rouge), « Montre » (lien qui ouvre le panneau), « Pourquoi » (le texte de l\'alerte) et, à droite, le bouton de la saisie qui résout, avec le texte et l\'action que l\'API donne (resolve.botao et resolve.acao) : session fermée : « Mise <nom en minuscules> » (lancamento iniciar) ; session ouverte : « Retirée du chargeur » (lancamento encerrar) ; avec valeur : un champ court avec l\'unité en indication (« % ») et « Indiquer <nom> » (lancamento lancar avec valor) ; instantané : le nom du type (lancamento lancar). Avec resolve.estados (la lecture qui mesure la consommation sur une montre qui va au poignet), les deux boutons légers « En usage » et « Au repos » à la place de « Indiquer <nom> » (le lancar avec estado=uso ou estado=repouso).',
        'Próximos dias' => 'Prochains jours',
        'Título "Próximos dias" com o link "ver o plano inteiro →" (plano.php). Tabela: Dia ("DD/MM" e o dia da semana curto, menor), Relógio (o nome; "à mão" pequeno quando escolhido à mão; o motivo embaixo, menor), Lembrete, e o "trocar por…". Fim de semana com fundo #f4f6f8. Sem plano: "Neste modo o sorteio é feito dia a dia." Os dias livres entram no meio, como na página Plano ("livre: escolha à mão", "escolher…"). Os dias vêm da API (hoje.proximos), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 7); passando disso, embaixo o navegador de páginas (recurso=proximos com pagina; só a lista se remonta) e "Página N de M · <total> dias no plano, <n> por página (o "Mostrar até" da Configuração)." (link para configuracao.php). A página à mostra fica a mesma quando a página Hoje se remonta depois de uma gravação.' => 'Titre « Prochains jours » avec le lien « voir tout le plan → » (plano.php). Tableau : Jour (« JJ/MM » et le jour de la semaine court, plus petit), Montre (le nom ; « à la main » en petit quand elle est choisie à la main ; le motif en dessous, plus petit), Rappel, et le « remplacer par… ». Week-end avec le fond #f4f6f8. Sans plan : « Dans ce mode, le tirage se fait jour par jour. » Les jours libres s\'intercalent, comme sur la page Plan (« libre : choisissez à la main », « choisir… »). Les jours viennent de l\'API (hoje.proximos), de « Afficher jusqu\'à » en « Afficher jusqu\'à » (la Configuration, 7 par défaut) ; au-delà, en dessous le navigateur de pages (recurso=proximos avec pagina ; seule la liste se reconstruit) et « Page N sur M · <total> jours dans le plan, <n> par page (le « Afficher jusqu\'à » de la Configuration). » (lien vers configuracao.php). La page affichée reste la même quand la page Aujourd\'hui se reconstruit après un enregistrement.',
        '"trocar por…": uma lista com os relógios disponíveis (menos o do dia) e, num dia de amanhã em diante escolhido à mão, "↺ voltar a sortear" (valor 0); escolhido um, aparece o botão leve "Trocar" (rodizio trocar_dia com data e relogio_id).' => '« remplacer par… » : une liste avec les montres disponibles (moins celle du jour) et, sur un jour à partir de demain choisi à la main, « ↺ retirer au sort » (valeur 0) ; une fois choisi, le bouton léger « Changer » apparaît (rodizio trocar_dia avec data et relogio_id).',
        'Modo de rodízio (um quadro que abre e fecha)' => 'Mode de rotation (un cadre qui s\'ouvre et se ferme)',
        'Fechado: "Modo de rodízio" (cinza) e o nome do modo em negrito, "· <forma de escolha>" (na escala: "pela maior nota") e, à direita, o link "editar".' => 'Fermé : « Mode de rotation » (gris) et le nom du mode en gras, « · <façon de choisir> » (dans le planning : « par la meilleure note ») et, à droite, le lien « modifier ».',
        'Aberto, em duas colunas: à esquerda a lista "Modo de rodízio" (os modos), a explicação do modo escolhido (escala: "Monta o plano do período inteiro de uma vez..."; sorteio: "Cada bloco de dias sorteia entre os relógios do grupo escolhido...") e os campos do modo escolhido: na escala, "Período" (Uma semana, Um mês, Dois meses, Meio ano, Um ano, Dois anos = 7, 30, 60, 180, 365, 730); para cada bloco, uma lista com o nome do bloco (grupos "Sortear entre": Todos e cada grupo com recuo pela profundidade; "Relógio fixo": cada relógio disponível) e, fora da escala, a caixa "sortear um por dia".' => 'Ouvert, en deux colonnes : à gauche la liste « Mode de rotation » (les modes), l\'explication du mode choisi (planning : « Construit le plan de toute la période d\'un coup... » ; tirage : « Chaque bloc de jours tire au sort parmi les montres du groupe choisi... ») et les champs du mode choisi : dans le planning, « Période » (Une semaine, Un mois, Deux mois, Six mois, Un an, Deux ans = 7, 30, 60, 180, 365, 730) ; pour chaque bloc, une liste avec le nom du bloc (groupes « Tirer au sort parmi » : Tous et chaque groupe avec un retrait selon la profondeur ; « Montre fixe » : chaque montre disponible) et, hors du planning, la case « tirer une par jour ».',
        'À direita: "Como escolher o relógio" (Inteligente; Inteligente com sorteio; Totalmente aleatório; Fila (FIFO)) com a explicação de cada uma (na escala, "Como escolher o relógio: pela maior nota"); "Garantia de rodízio: dias sem uso, no máximo" (número de 0 a 365; só nas formas inteligente, com sorteio e na escala) com "Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota." e "A nota vem dos critérios, que você cadastra."' => 'À droite : « Comment choisir la montre » (Intelligent ; Intelligent avec tirage ; Totalement aléatoire ; File (FIFO)) avec l\'explication de chacune (dans le planning, « Comment choisir la montre : par la meilleure note ») ; « Garantie de rotation : jours sans usage, au maximum » (nombre de 0 à 365 ; seulement dans les formes intelligent, avec tirage et dans le planning) avec « Celle qui dépasse la limite est prioritaire, la plus longtemps inutilisée d\'abord. 0 désactive. La même valeur vaut pour tous les modes qui utilisent la note. » et « La note vient des critères, que vous définissez. »',
        'Botão "Aplicar modo" (rodizio modo), com a confirmação "Trocar o modo apaga o plano atual. Continuar?" (com o dia já começado: "Trocar o modo refaz o plano a partir de amanhã; hoje continua o <relógio>. Continuar?") e a nota sobre o histórico que continua e o link para Cadastros (os modos).' => 'Bouton « Appliquer le mode » (rodizio modo), avec la confirmation « Changer de mode efface le plan actuel. Continuer ? » (avec la journée déjà commencée : « Changer de mode refait le plan à partir de demain ; aujourd\'hui reste <montre>. Continuer ? ») et la note sur l\'historique qui continue et le lien vers Définitions (les modes).',
        '"Sortear de novo": uma lista com as ações possíveis agora e o botão leve "Sortear": "a partir de amanhã" (resortear) e "inclusive hoje" (resortear_hoje) com o dia já começado no pulso, ou "a partir de hoje" (resortear); fora da escala, "a próxima semana (DD/MM a DD/MM)" (proxima_semana; em qualquer dia: a semana seguinte, de segunda a domingo, sorteada com os dias que faltam desta já contados como uso; o "Sortear de novo" de depois refaz até o fim dela). Embaixo, a explicação da opção escolhida; cada uma tem a sua confirmação.' => '« Refaire le tirage » : une liste avec les actions possibles maintenant et le bouton léger « Tirer au sort » : « à partir de demain » (resortear) et « aujourd\'hui compris » (resortear_hoje) avec la journée déjà commencée au poignet, ou « à partir d\'aujourd\'hui » (resortear) ; hors du planning, « la semaine prochaine (JJ/MM au JJ/MM) » (proxima_semana ; n\'importe quel jour : la semaine suivante, du lundi au dimanche, tirée avec les jours qui restent de celle-ci déjà comptés comme utilisation ; un « Refaire le tirage » ultérieur refait jusqu\'à sa fin). En dessous, l\'explication de l\'option choisie ; chacune a sa confirmation.',
        'Rodízio manual: a última opção da lista "Modo de rodízio" (não é um modo: o modo de sempre continua valendo fora do período). Escolhida, a explicação diz "Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre (<modo>)."; somem a coluna da direita, o "Aplicar modo" com a nota e o "Sortear de novo"; aparece, abaixo de uma linha, o formulário do período: "De" (data, de hoje em diante, já com hoje), "Até" (data) e o botão "OK". O endereço index.php#manual abre o quadro já no Rodízio manual (o link da página Plano).' => 'Rotation manuelle : la dernière option de la liste « Mode de rotation » (ce n\'est pas un mode : le mode habituel continue de valoir hors de la période). Une fois choisie, l\'explication dit « Vous choisissez la montre de chaque jour d\'une période. Indiquez le début et la fin puis cliquez sur OK : les jours apparaissent 7 par 7, chacun avec la liste des montres, « Décider pour moi » (le système choisit) et « Sans montre (jour libre) ». En dehors de la période, le mode de rotation habituel continue de s\'appliquer (<mode>). » ; disparaissent la colonne de droite, le « Appliquer le mode » avec la note et le « Refaire le tirage » ; apparaît, sous un trait, le formulaire de la période : « De » (date, à partir d\'aujourd\'hui, déjà avec aujourd\'hui), « À » (date) et le bouton « OK ». L\'adresse index.php#manual ouvre le cadre déjà sur la Rotation manuelle (le lien de la page Plan).',
        'OK lê recurso=rodizio_manual (de, ate, pagina) e mostra a tabela compacta (até 46rem): Dia ("DD/MM" e o dia da semana por extenso, menor, com " · hoje"; o número em safira no fim de semana), No plano agora (o relógio com "à mão" ou "sorteado" pequeno em âmbar, "dia livre" ou "—" em cinza) e Relógio do dia (uma lista: "Decida por mim", o grupo "Relógios" com os disponíveis por nome e, menos hoje, "Sem relógio (dia livre)"; de partida, a escolha que a API manda). Mais de 7 dias: embaixo, os botões leves "‹ Anterior", os números das páginas (a 1, a última e até 2 de cada lado da atual, com "…" nos saltos; a atual em safira) e "Próxima ›"; cada um relê a API. O que se escolhe fica guardado na tela ao trocar de página. Embaixo, "Página N de M · <n> dias, de DD/MM/AAAA a DD/MM/AAAA. O que você escolhe fica guardado enquanto você anda pelas páginas; nada muda antes de gravar.", os botões "Gravar o rodízio manual" (rodizio manual com de, ate e dias[data] dos que você mudou; confirma "Gravar o rodízio manual de DD/MM/AAAA a DD/MM/AAAA? Os dias ficam com os relógios escolhidos; os de "Decida por mim" são decididos agora pelo sistema."); e as notas com o critério do Decida por mim (o texto da API) e "Para apagar o que um período tem (e sortear de novo, ou deixar os dias livres): "Apagar um período", embaixo deste quadro, ou na página Plano." (link). Recusado: o motivo em âmbar acima da tabela, e as escolhas ficam; gravado: o recado no alto da página e a página remontada.' => 'OK lit recurso=rodizio_manual (de, ate, pagina) et montre le tableau compact (jusqu\'à 46rem) : Jour (« JJ/MM » et le jour de la semaine en toutes lettres, plus petit, avec « · aujourd\'hui » ; le numéro en saphir le week-end), Dans le plan maintenant (la montre avec « à la main » ou « tiré » en petit en ambre, « jour libre » ou « — » en gris) et Montre du jour (une liste : « Décider pour moi », le groupe « Montres » avec les disponibles par nom et, sauf aujourd\'hui, « Sans montre (jour libre) » ; au départ, le choix que l\'API envoie). Plus de 7 jours : en dessous, les boutons légers « ‹ Précédent », les numéros des pages (la 1, la dernière et jusqu\'à 2 de chaque côté de l\'actuelle, avec « … » sur les sauts ; l\'actuelle en saphir) et « Suivant › » ; chacun relit l\'API. Ce que l\'on choisit reste conservé à l\'écran en changeant de page. En dessous, « Page N sur M · <n> jours, du JJ/MM/AAAA au JJ/MM/AAAA. Vos choix sont conservés pendant que vous changez de page ; rien ne change avant l\'enregistrement. », les boutons « Enregistrer la rotation manuelle » (rodizio manual avec de, ate et dias[date] de ceux que vous avez changés ; confirme « Enregistrer la rotation manuelle du JJ/MM/AAAA au JJ/MM/AAAA ? Les jours reçoivent les montres choisies ; ceux en « Décider pour moi » sont décidés maintenant par le système. ») ; et les notes avec le critère de Décider pour moi (le texte de l\'API) et « Pour effacer ce qu\'une période contient (et refaire le tirage, ou laisser les jours libres) : « Effacer une période », sous ce cadre, ou sur la page Plan. » (lien). Refusé : le motif en ambre au-dessus du tableau, et les choix restent ; enregistré : le message en haut de la page et la page reconstruite.',
        'Abaixo do Sortear de novo, cada um abaixo de uma linha, os mesmos dois formulários da página Plano: "Apagar um período" e "Apagar tudo" (veja a página Plano).' => 'Sous Refaire le tirage, chacun sous un trait, les deux mêmes formulaires de la page Plan : « Effacer une période » et « Tout effacer » (voir la page Plan).',
        'Relógios (a tabela da coleção)' => 'Montres (le tableau de la collection)',
        'Título "Relógios" com "<mostrados> de <total> relógios · <n> em uso" em cinza e, à direita, os botões "Limpar filtros" (leve) e "Novo relógio" (abre o cadastro no painel).' => 'Titre « Montres » avec « <affichées> sur <total> montres · <n> en usage » en gris et, à droite, les boutons « Effacer les filtres » (léger) et « Nouvelle montre » (ouvre la fiche dans le panneau).',
        '12 colunas, todas ordenáveis clicando no título (▲ ou ▼ ao lado; clicar de novo inverte; vazios sempre por último): Código, Relógio (miniatura e nome em negrito), Tipo, Estado (o estado_texto da API em etiqueta, na cor do estado: Em uso verde, a sessão aberta (No sol, No winder, No carregador) laranja, Em repouso vermelho, Indisponível cinza), Carga (barra e %, ou o texto de por que não tem), Última vez usado, Próxima manutenção (data ou "hoje"), Em (quanto falta; atrasado em vermelho negrito; atualizado a cada minuto), O que fazer (em âmbar negrito; o aviso de manutenção mais perto, sem o Encostado), Encostado (quanto falta para o limite de dias sem ir ao pulso, ou "atrasado …" em vermelho negrito quando já passou; "—" sem data; atualizado a cada minuto), Comprado em, Valor (à direita, "R$ 1.234,56").' => '12 colonnes, toutes triables en cliquant sur le titre (▲ ou ▼ à côté ; cliquer de nouveau inverse ; les vides toujours en dernier) : Code, Montre (miniature et nom en gras), Type, État (le estado_texto de l\'API en étiquette, dans la couleur de l\'état : En usage vert, la session ouverte (Au soleil, Sur le remontoir, Sur le chargeur) orange, Au repos rouge, Indisponible gris), Charge (barre et %, ou le texte de pourquoi il n\'y en a pas), Dernière fois portée, Prochain entretien (date ou « aujourd\'hui »), Dans (combien il reste ; en retard en rouge gras ; mis à jour chaque minute), Que faire (en ambre gras ; l\'alerte d\'entretien la plus proche, sans la Délaissée), Délaissée (combien il reste avant la limite de jours sans aller au poignet, ou « en retard de … » en rouge gras quand c\'est déjà passé ; « — » sans date ; mis à jour chaque minute), Achetée le, Montant (à droite, « R$ 1.234,56 »).',
        'Uma linha de filtros embaixo dos títulos: Código ("nº"), Relógio ("buscar" no nome), Tipo (os tipos que existem), Estado (Todos e os estados da API, na ordem: Em uso, cada sessão, Em repouso, Indisponível), Carga (Todas, ≤ 20%, ≤ 50%), Última vez usado (Todos, 7 dias, +7 dias, nunca), Próxima manutenção (Todas, até hoje, 7 dias, 30 dias), O que fazer (os avisos de manutenção, sem o Encostado), Encostado (Todos, Encostados, Dentro do prazo, sem data), Comprado em (Todas, 30 dias, 90 dias, este ano, sem data), Valor (Todos, ≤ 500, 500–1.500, > 1.500, sem valor). A ordem e os filtros ficam guardados na sessão do navegador.' => 'Une ligne de filtres sous les titres : Code (« n° »), Montre (« rechercher » dans le nom), Type (les types qui existent), État (Tous et les états de l\'API, dans l\'ordre : En usage, chaque session, Au repos, Indisponible), Charge (Toutes, ≤ 20 %, ≤ 50 %), Dernière fois portée (Tous, 7 jours, +7 jours, jamais), Prochain entretien (Toutes, jusqu\'à aujourd\'hui, 7 jours, 30 jours), Que faire (les alertes d\'entretien, sans la Délaissée), Délaissée (Tous, Délaissées, Dans le délai, sans date), Achetée le (Toutes, 30 jours, 90 jours, cette année, sans date), Montant (Tous, ≤ 500, 500–1 500, > 1 500, sans valeur). L\'ordre et les filtres restent conservés dans la session du navigateur.',
        'Ordem inicial: os disponíveis primeiro (o de hoje, depois os com aviso), os indisponíveis no fim e em cinza. A linha do relógio de hoje tem a faixa safira à esquerda; a de um com aviso, a âmbar. Clicar numa linha (ou Enter nela) abre o relógio no painel. Rodapé: "Total dos relógios mostrados" e a soma dos valores, à direita. Sem relógios: "Nenhum relógio cadastrado. Use o botão Novo relógio."; com filtros que não deixam nenhum: "Nenhum relógio com esses filtros."' => 'Ordre initial : les disponibles d\'abord (celle d\'aujourd\'hui, puis celles avec une alerte), les indisponibles à la fin et en gris. La ligne de la montre du jour a la bande saphir à gauche ; celle d\'une avec alerte, l\'ambre. Cliquer sur une ligne (ou Entrée dessus) ouvre la montre dans le panneau. Pied : « Total des montres affichées » et la somme des montants, à droite. Sans montres : « Aucune montre enregistrée. Utilisez le bouton Nouvelle montre. » ; avec des filtres qui n\'en laissent aucune : « Aucune montre avec ces filtres. »',
        'Quando as 12 colunas não cabem na largura que a tabela tem: cada relógio vira um cartão, com a foto e o nome na linha de cima e embaixo os mesmos campos com o nome da coluna em cima, em colunas iguais (5; 2 no celular); os títulos viram botões "Ordenar por" e os filtros ficam todos, com o nome em cima.' => 'Quand les 12 colonnes ne tiennent pas dans la largeur qu\'a le tableau : chaque montre devient une carte, avec la photo et le nom sur la ligne du haut et en dessous les mêmes champs avec le nom de la colonne au-dessus, en colonnes égales (5 ; 2 sur le téléphone) ; les titres deviennent des boutons « Trier par » et les filtres restent tous, avec le nom au-dessus.',
        'O painel do relógio (à direita, flutuante ou em tela cheia)' => 'Le panneau de la montre (à droite, flottant ou en plein écran)',
        'Um botão redondo "×" no canto (no celular "× Fechar") fecha o painel; Esc também. O endereço vira index.php?r=<id>.' => 'Un bouton rond « × » dans le coin (sur le téléphone « × Fermer ») ferme le panneau ; Échap aussi. L\'adresse devient index.php?r=<id>.',
        'Cabeça: a foto (ou "Sem foto"; com o mouse parado em cima, a dica relogio.dica_foto da API, em linhas: o nome, o grupo e o código; o estado e a carga; a nota e o próximo dia no rodízio; a compra; e "Duplo clique (ou "Abrir foto", embaixo): a foto em tamanho grande.") com os botões leves "Abrir foto" (só com foto: abre a foto ampliada), "Escolher foto" / "Trocar foto" (abre o seletor de arquivo; escolhida, aparece a prévia e o botão "Salvar foto": relogio foto) e, com foto, "Remover foto" (discreto; confirma "Remover a foto?"); ao lado "<tipo> · <caminho no grupo>" em cinza, o nome em h1, a observação, e as etiquetas: em uso/em repouso, "indisponível", "relógio de hoje" e, fora da coleção, a situação (etiqueta lilás: "desejado", "emprestado", "vendido", "arquivado"; no desejado, sem a etiqueta do estado). Embaixo das etiquetas, o atalho do pulso (não no desejado; só havendo a sessão "pulso"): "Pulso" em letras pequenas maiúsculas cinza e um botão só, "Pôr" (cheio, lancamento iniciar tipo=pulso, agora) quando ele não está no pulso, ou "Tirar" (leve, lancamento encerrar tipo=pulso, agora) com "desde HH:MM (N h M min)" em cinza ao lado quando está; a dica do botão é o "Pôr no pulso" / "Tirar do pulso" inteiro. A hora certa, e o resto, ficam no quadro Marcar.' => 'Tête : la photo (ou « Pas de photo » ; avec la souris arrêtée dessus, l\'indication relogio.dica_foto de l\'API, en lignes : le nom, le groupe et le code ; l\'état et la charge ; la note et le prochain jour dans la rotation ; l\'achat ; et « Double clic (ou « Ouvrir la photo », en dessous) : la photo en grand. ») avec les boutons légers « Ouvrir la photo » (seulement avec photo : ouvre la photo agrandie), « Choisir photo » / « Changer la photo » (ouvre le sélecteur de fichier ; une fois choisie, l\'aperçu et le bouton « Enregistrer la photo » apparaissent : relogio foto) et, avec photo, « Retirer » (discret ; confirme « Supprimer la photo ? ») ; à côté « <type> · <chemin dans le groupe> » en gris, le nom en h1, l\'observation, et les étiquettes : en usage/au repos, « indisponible », « montre du jour » et, hors de la collection, le statut (étiquette lilas : « désirée », « prêtée », « vendue », « archivée » ; pour la désirée, sans l\'étiquette de l\'état). Sous les étiquettes, le raccourci du poignet (pas pour la désirée ; seulement s\'il existe la session « pulso ») : « Poignet » en petites majuscules grises et un seul bouton, « Mettre » (plein, lancamento iniciar tipo=pulso, maintenant) quand elle n\'est pas au poignet, ou « Retirer » (léger, lancamento encerrar tipo=pulso, maintenant) avec « depuis HH:MM (N h M min) » en gris à côté quand elle y est ; l\'infobulle du bouton est le « Mettre au poignet » / « Retirer du poignet » complet. L\'heure exacte, et le reste, restent dans le cadre Marquer.',
        'Num relógio desejado, no lugar dos quadros abaixo (Agora, Previsão, Gasto, Autonomia, Rodízio, Compra, Manutenções, Marcar), só o quadro Desejo (pares: Marca, Referência, Preço-alvo "R$ ...", Prioridade, Link "abrir a página" numa aba nova; vazio: "—"; no rodapé "Comprou? Em "Editar cadastro", mude a situação para "Na coleção" e preencha a compra.") e o de Documentos; os quadros largos (Dados, Histórico) e o Editar cadastro continuam.' => 'Sur une montre désirée, à la place des cadres ci-dessous (Maintenant, Prévision, Consommation, Autonomie, Rotation, Achat, Entretiens, Marquer), seulement le cadre Envie (paires : Marque, Référence, Prix cible « R$ ... », Priorité, Lien « ouvrir la page » dans un nouvel onglet ; vide : « — » ; au pied « Achetée ? Dans « Modifier la fiche », passez le statut à « Dans la collection » et complétez l\'achat. ») et celui des Documents ; les cadres larges (Données, Historique) et Modifier la fiche continuent.',
        'Os quadros, numa grade (lado a lado onde cabem): Agora (pares: Estado ("No carregador desde 06:30", na cor do estado); Carga com a barra e "~68%" e de onde vem; Encostado (a falta, em vermelho negrito se já passou do limite de dias sem ir ao pulso; só quando há data); Situação, uma linha por item; Última leitura); Previsão (só nos que têm leitura: as frases da API, ou "Informe a carga atual para o sistema começar a prever."; embaixo, "De onde vem a conta" (título pequeno em maiúsculas cinza) e a tabela da previsao.conta, uma linha por número: o nome (e, menor, embaixo, o detalhe de como o gasto foi medido), o valor (com a unidade menor embaixo; "—" se vazio, a linha em cinza) e a origem em etiqueta: informado azul, padrão âmbar, medido verde, vazio cinza); Gasto da bateria (No pulso, Fora do pulso: o que vale "% por dia" e embaixo se é medido ou do cadastro e, menor, "no cadastro: <campo>: <valor> <unidade> (<origem>)" com os campos de onde sai o gasto do cadastro (previsao.gasto.<medida>.campos), separados por " · "; Janela anterior; Medições; no rodapé "Medições mais velhas que a janela saem da conta..."); Autonomia (Cheio, pelo cadastro; Cheio, pela conta; Acaba, seguindo o plano (data e hora, e "em <duração>"); No pulso sem tirar; Guardado; sem dado, o motivo em cinza); Rodízio (Nota com o link "ver a conta" (Critérios, numa aba nova); Critérios de; Próxima vez; no rodapé o botão leve "Usando hoje" (rodizio usando, com confirmação), se ele está disponível e não é o de hoje); Compra (Valor pago, Loja, Comprado em com "há N dias", Garantia "até" ou "vencida em"; sem nada: "Sem dados da compra. Preencha em "Editar cadastro"."); Compra também com "Custo por uso" ("R$ 100,00" em negrito e "3 dias de uso" embaixo; sem: "sem o valor pago" ou "ainda não foi ao pulso" em cinza) e o "há N dias" da compra vindo da API (compra.ha_dias). Documentos (cada categoria com "N arquivos", link para a página Documentos numa aba nova; o botão "Enviar documentos" ou "Abrir os documentos"); Próximas manutenções (data em negrito e o nome; ou "Nada previsto."). Depois de Documentos, Acessórios (pares: o tipo e o nome, com a observação menor embaixo; sem nenhum, "Nenhum: a pulseira extra, a caixa, o estojo, a ferramenta..."; o botão leve "Cadastrar acessórios" ou "Ver os acessórios", que abre acessorios.php?relogio=<id> numa aba nova). No rodapé de Documentos, ao lado do botão dele, o botão leve "Passaporte" (passaporte.php?id=<id> numa aba nova).' => 'Les cadres, dans une grille (côte à côte là où ils tiennent) : Maintenant (paires : État (« Sur le chargeur depuis 06:30 », dans la couleur de l\'état) ; Charge avec la barre et « ~68 % » et d\'où elle vient ; Délaissée (le reste, en rouge gras si la limite de jours sans aller au poignet est déjà dépassée ; seulement quand il y a une date) ; Statut, une ligne par élément ; Dernière lecture) ; Prévision (seulement pour celles qui ont une lecture : les phrases de l\'API, ou « Indiquez la charge actuelle pour que le système commence à prévoir. » ; en dessous, « D\'où vient le calcul » (petit titre en majuscules grises) et le tableau de previsao.conta, une ligne par nombre : le nom (et, plus petit, en dessous, le détail de comment la consommation a été mesurée), la valeur (avec l\'unité plus petite en dessous ; « — » si vide, la ligne en gris) et l\'origine en étiquette : informado bleu, par défaut ambre, medido vert, vazio gris) ; Consommation de la batterie (Au poignet, Hors du poignet : ce qui vaut « % par jour » et en dessous si c\'est mesuré ou de la fiche ; Fenêtre précédente ; Mesures ; au pied « Les mesures plus anciennes que la fenêtre sortent du calcul... ») ; Autonomie (Pleine, selon la fiche ; Pleine, selon le calcul ; S\'épuise, en suivant le plan (date et heure, et « dans <durée> ») ; Au poignet sans la retirer ; Rangée ; sans donnée, le motif en gris) ; Rotation (Note avec le lien « voir le calcul » (Critères, dans un nouvel onglet) ; Critères de ; Prochaine fois ; au pied le bouton léger « Portée aujourd\'hui » (rodizio usando, avec confirmation), si elle est disponible et n\'est pas celle d\'aujourd\'hui) ; Achat (Prix payé, Boutique, Achetée le avec « il y a N jours », Garantie « jusqu\'au » ou « expirée le » ; sans rien : « Pas de données d\'achat. Complétez dans « Modifier la fiche ». ») ; Achat aussi avec « Coût par port » (« R$ 100,00 » en gras et « 3 jours d\'usage » en dessous ; sans : « sans le prix payé » ou « pas encore portée » en gris) et le « il y a N jours » de l\'achat venant de l\'API (compra.ha_dias). Documents (chaque catégorie avec « N fichiers », lien vers la page Documents dans un nouvel onglet ; le bouton « Envoyer des documents » ou « Ouvrir les documents ») ; Prochains entretiens (date en gras et le nom ; ou « Rien de prévu. »). Après Documents, Accessoires (paires : le type et le nom, avec l\'observation plus petite en dessous ; sans aucun, « Aucun : le bracelet supplémentaire, la boîte, l\'étui, l\'outil... » ; le bouton léger « Enregistrer des accessoires » ou « Voir les accessoires », qui ouvre acessorios.php?relogio=<id> dans un nouvel onglet). Au pied de Documents, à côté de son bouton, le bouton léger « Passeport » (passaporte.php?id=<id> dans un nouvel onglet). Dans Consommation de la batterie, sous chaque ligne, plus petit : « dans la fiche : <champ> : <valeur> <unité> (<origine>) », les champs d\'où vient la consommation de la fiche (previsao.gasto.<medida>.campos), séparés par « · ».',
        'Marcar (um quadro na largura toda): "O que você quer marcar?" com uma lista em grupos: "Agora, ou numa hora que você disser" (cada sessão como verbo: "Pôr no sol" / "Tirar do sol" conforme está aberta; cada tipo com valor pelo nome; cada instantâneo pelo nome), "Algo que já passou" ("Um período que já passou (<sessões>)") e "Corrigir" ("Corrigir ou excluir uma marcação (últimos 14 dias)"). Escolhido um, aparecem só os campos dele: sessão: o estado aberto e "Pôs às" / "Tirou às" (data e hora, "Anda com o relógio até você mudar (vazio: agora).") e o botão com o verbo; com valor: "Agora em uso/em repouso" e a estimativa, "Leitura" (com a unidade), "Lida às", a caixa "Atualizar o gasto com esta medição" (marcada; só nos tipos que medem o gasto) e "Informar <nome>"; o tipo que mede o gasto, num relógio que vai ao pulso, entra na lista duas vezes, "Informar <nome> em uso" e "Informar <nome> em repouso" (o lancar com estado=uso ou repouso; o botão, mais curto, "Informar em uso" / "Informar em repouso"), e quando o escolhido não bate com o estado de agora aparecem, em âmbar, "O sistema tem ele no pulso agora (<desde ...>). Lendo em repouso, a medição deste intervalo fica só no histórico (ele estava registrado errado)." (ou "O sistema tem ele fora do pulso agora. Lendo em uso, ...") e a caixa marcada "Tirar do pulso na hora da leitura" / "Pôr no pulso na hora da leitura" (ajustar=1; desmarcada, 0); instantâneo: "Quando" e "Marcar <nome>"; período: "Onde" (se houver mais de uma sessão), "De" (uma hora atrás) e "Até" (agora) e "Registrar o período"; corrigir: "Qual marcação" ("DD/MM HH:MM · nome até HH:MM", "(aberta)", ": 68 %", "(rodízio)") e os campos dela com "Salvar" e "Excluir" (confirma). Nada pode ser no futuro. Os campos de data e hora andam com o relógio do navegador: "Pôs às", "Tirou às", "Lida às", "Quando" e o "Até" do período vêm com a hora de agora e acompanham o relógio (a cada 15 s e ao clicar no campo) até a pessoa mexer, e daí ficam no que ela pôs; sem mexer, "Pôs às", "Tirou às", "Lida às" e "Quando" vão vazios (a API usa o agora dela, com os segundos) e o "Até" vai com o minuto de agora; o máximo de todos (nada no futuro) também anda.' => 'Marquer (un cadre sur toute la largeur) : « Que voulez-vous marquer ? » avec une liste en groupes : « Maintenant, ou à l\'heure que vous indiquez » (chaque session comme verbe : « Mettre au soleil » / « Terminer : Au soleil » selon qu\'elle est ouverte ; chaque type avec valeur par le nom ; chaque instantané par le nom), « Quelque chose de passé » (« Une période passée (<sessions>) ») et « Corriger » (« Corriger ou supprimer une marque (14 derniers jours) »). Une fois choisi, seuls ses champs apparaissent : session : l\'état ouvert et « Mise à » / « Retirée à » (date et heure, « Avance avec l\'horloge jusqu\'à ce que vous changiez (vide : maintenant). ») et le bouton avec le verbe ; avec valeur : « Maintenant en usage/au repos » et l\'estimation, « Lecture » (avec l\'unité), « Lue à », la case « Mettre à jour la consommation avec cette mesure » (cochée ; seulement pour les types qui mesurent la consommation) et « Indiquer <nom> » ; instantané : « Quand » et « Marquer <nom> » ; période : « Où » (s\'il y a plus d\'une session), « De » (une heure avant) et « À » (maintenant) et « Enregistrer la période » ; corriger : « Quelle marque » (« JJ/MM HH:MM · nom jusqu\'à HH:MM », « (ouverte) », « : 68 % », « (rotation) ») et ses champs avec « Enregistrer » et « Supprimer » (confirme). Rien ne peut être dans le futur. Les champs de date et d\'heure avancent avec l\'horloge du navigateur : « Mise à », « Retirée à », « Lue à », « Quand » et le « À » de la période arrivent avec l\'heure de maintenant et suivent l\'horloge (toutes les 15 s et au clic dans le champ) jusqu\'à ce que la personne y touche, et dès lors restent sur ce qu\'elle a mis ; sans y toucher, « Mise à », « Retirée à », « Lue à » et « Quand » partent vides (l\'API utilise son maintenant, avec les secondes) et le « À » part avec la minute de maintenant ; le maximum de tous (rien dans le futur) avance aussi. Le type qui mesure la consommation, sur une montre qui va au poignet, entre deux fois dans la liste, « Indiquer <nom> en usage » et « Indiquer <nom> au repos » (le lancar avec estado=uso ou repouso ; le bouton, plus court, « Indiquer en usage » / « Indiquer au repos »), et quand le choix ne correspond pas à l\'état actuel apparaissent, en ambre, « Le système l\'a au poignet maintenant (<depuis ...>). En lisant au repos, la mesure de cet intervalle reste seulement dans l\'historique (il était mal enregistré). » (ou « Le système l\'a hors du poignet maintenant. En lisant en usage, ... ») et la case cochée « Retirer du poignet à l\'heure de la lecture » / « Mettre au poignet à l\'heure de la lecture » (ajustar=1 ; décochée, 0).',
        'Editar cadastro (um quadro que abre e fecha; no relógio novo, já aberto com o título "Novo relógio"): Nome (obrigatório); Grupo ("(na raiz)" e cada grupo pelo caminho, com a nota "os campos, os lançamentos e os critérios de um grupo valem para tudo abaixo dele"); depois os campos do cadastro, só os que valem para o grupo escolhido (mudar o grupo mostra e esconde na hora): sim/não como caixa; lista como menu (com "—"); data como campo de data; texto como campo; número como campo decimal, com o padrão de dica ("vazio: 5"); a Compra num grupo com título (Data da compra, Valor pago, Onde comprou, Garantia até); a Observação; no novo, a Foto; "Situação na coleção" (menu: Na coleção, Desejado, Emprestado, Vendido, Arquivado; no novo, a do endereço, index.php?novo=1&posse=desejado, senão Na coleção; os campos só nos desejados, como o Preço-alvo e a Prioridade, aparecem só com Desejado, e a caixa do disponível só com Na coleção, na hora); "Disponível para o rodízio" (marcada no novo); "Guardar no banco a cópia de todos os documentos dele" (só quando o config.php não decide); botão "Cadastrar relógio" ou "Salvar alterações" (relogio salvar). Embaixo, "Excluir este relógio" (discreto; confirma "Excluir <nome> com todo o histórico e a foto?").' => 'Modifier la fiche (un cadre qui s\'ouvre et se ferme ; sur la montre nouvelle, déjà ouvert avec le titre « Nouvelle montre ») : Nom (obligatoire) ; Groupe (« (à la racine) » et chaque groupe par le chemin, avec la note « les champs, les saisies et les critères d\'un groupe valent pour tout ce qui est en dessous ») ; ensuite les champs de la fiche, seulement ceux qui valent pour le groupe choisi (changer de groupe montre et cache sur-le-champ) : oui/non comme case ; liste comme menu (avec « — ») ; date comme champ de date ; texte comme champ ; nombre comme champ décimal, avec la valeur par défaut en indication (« vide : 5 ») ; l\'Achat dans un groupe avec titre (Date d\'achat, Prix payé, Lieu d\'achat, Garantie jusqu\'au) ; l\'Observation ; sur la nouvelle, la Photo ; « Statut dans la collection » (menu : Dans la collection, Désirée, Prêtée, Vendue, Archivée ; sur la nouvelle, celui de l\'adresse, index.php?novo=1&posse=desejado, sinon Dans la collection ; les champs seulement pour les envies, comme le Prix cible et la Priorité, n\'apparaissent qu\'avec Désirée, et la case du disponible seulement avec Dans la collection, sur-le-champ) ; « Disponible pour la rotation » (cochée sur la nouvelle) ; « Garder dans la base de données une copie de tous ses documents » (seulement quand config.php ne décide pas) ; bouton « Enregistrer la montre » ou « Enregistrer les modifications » (relogio salvar). En dessous, « Supprimer cette montre » (discret ; confirme « Supprimer <nom> avec tout l\'historique et la photo ? »).',
        'Carga ao longo do tempo (largo; nos que têm leitura): um gráfico de linha das leituras (eixo de 0 a 100%, guias em 0, 50 e 100%, pontos verdes em uso e vermelhos em repouso, a linha em safira), com a legenda em pares rótulo/valor, menores (Pontos: as bolinhas "leitura em uso" e "leitura em repouso"; Período: "DD/MM a DD/MM"; Escala: "de 0 a 100%"; A conta: "de onde vem cada número: no quadro Previsão"); com menos de duas leituras, "O gráfico aparece a partir de duas leituras de carga." Embaixo, "Medições do gasto" (no quadro estreito, até 40rem, como no painel ao lado: cada medição vira um cartão, a data em negrito e embaixo cada valor com o nome da coluna em maiúsculas cinza na frente): tabela Quando, Leituras ("89 → 75", e embaixo, menor, a marcação das duas leituras: "em uso → em repouso"), Horas ("14 h no pulso, 2 h fora"), Gasto medido ("% por dia de uso" ou "fora do pulso"), Na conta (sim; "em parte: pesa N%" quando uma leitura dela pesa menos, em vermelho negrito abaixo de 50%, e embaixo, menor, "a leitura de 100% não bate bem com as outras (a conta erra 4,5 pontos nela)"; não (fora da janela); não (só histórico); não (as duas leituras marcadas de jeitos diferentes, no motor pela marcação); não (o motor só o cadastro)), e um botão leve por linha, "Tirar da conta" (na usada) ou "Pôr na conta" (lancamento medicao com usada 0 ou 1), as 10 mais recentes. A nota em cima, conforme o motor: "... das leituras dos últimos N dias (ou das últimas N leituras de cada tipo), todas com o mesmo peso, partindo do cadastro ..." (robusto), a conta por marcação (duas taxas separadas), o original (pelas horas), só o cadastro (as medições ficam no histórico) ou as fórmulas; A leitura que não bate bem com as outras pesa menos na conta, e o botão de cada linha tira ou põe a medição na conta." No quadro Gasto da bateria, a primeira linha é "Calculado por": o nome do motor (gasto.motor_nome) e, menor, de onde veio a escolha ("a escolha da coleção, na Configuração", "a escolha deste relógio, no cadastro", "a escolha do grupo, no cadastro" ou "o padrão: nada escolhido"); o gasto medido ganha "± <incerteza>" em cinza depois do valor, e a linha Medições ganha, em vermelho, "N com uma leitura que não bate com as outras e pesa pouco na conta (veja Medições do gasto)".' => 'Charge au fil du temps (large ; dans celles qui ont des relevés) : un graphique en ligne des relevés (axe de 0 à 100 %, repères à 0, 50 et 100 %, points verts en usage et rouges au repos, la ligne en saphir), avec la légende en paires libellé/valeur, plus petites (Points : les pastilles « relevé en usage » et « relevé au repos » ; Période : « JJ/MM à JJ/MM » ; Échelle : « de 0 à 100 % » ; Le calcul : « d\'où vient chaque nombre : dans le cadre Prévision ») ; avec moins de deux relevés, « Le graphique apparaît à partir de deux relevés de charge. » En dessous, « Mesures de la consommation » (dans le cadre étroit, jusqu\'à 40rem, comme dans le panneau latéral : chaque mesure devient une carte, la date en gras et dessous chaque valeur avec le nom de la colonne en majuscules grises devant) : tableau Quand, Relevés (« 89 → 75 », et dessous, plus petit, le marquage des deux relevés : « en usage → au repos »), Heures (« 14 h au poignet, 2 h hors »), Consommation mesurée (« % par jour d\'usage » ou « hors du poignet »), Dans le calcul (oui ; « en partie : pèse N % » quand un de ses relevés pèse moins, en rouge gras sous 50 %, et dessous, plus petit, « le relevé de 100 % ne colle pas bien avec les autres (le calcul se trompe de 4,5 points sur lui) » ; non (hors de la fenêtre) ; non (historique seulement) ; non (les deux relevés marqués différemment, dans le moteur par le marquage) ; non (le moteur fiche seulement)), et un bouton léger par ligne, « Retirer du calcul » (sur celle utilisée) ou « Remettre dans le calcul » (lancamento medicao avec usada 0 ou 1), les 10 plus récentes. La note au-dessus, selon le moteur : « ... des relevés des N derniers jours (ou des N derniers relevés de chaque type), tous avec le même poids, en partant de la fiche ... » (robuste), le calcul par marquage (deux taux séparés), l\'original (par les heures), la fiche seulement (les mesures restent dans l\'historique) ou les formules ; Le relevé qui ne colle pas bien avec les autres pèse moins dans le calcul, et le bouton de chaque ligne retire ou remet la mesure dans le calcul. » Dans le cadre Consommation de la batterie, la première ligne est « Calculé par » : le nom du moteur (gasto.motor_nome) et, plus petit, d\'où vient le choix (« le choix de la collection, dans la Configuration », « le choix de cette montre, dans sa fiche », « le choix du groupe, dans la fiche » ou « la valeur par défaut : rien de choisi ») ; la consommation mesurée gagne « ± <incertitude> » en gris après la valeur, et la ligne Mesures gagne, en rouge, « N avec un relevé qui ne colle pas avec les autres et pèse peu dans le calcul (voir Mesures de la consommation) ».',
        'Dados do relógio (largo): duas tabelas lado a lado (o valor numérico, a data e o sim/não numa linha só; o valor de texto, como a observação ou uma fórmula que dá texto, quebra a linha dentro da coluna, sem invadir a tabela do lado): Cadastro (Campo, Valor, Origem com a etiqueta informado/padrão/vazio) e Calculado agora (Fórmula com o identificador em código, Valor com a unidade (segundos por extenso), Versão). O calculado junto do informado, numa linha cinza menor embaixo do valor: no campo de onde sai um gasto (previsao.gasto.<medida>.campos: o decaimento, a autonomia), "calculado pelas leituras: 5,57% por dia de uso" (ou "calculado pelas leituras: ainda sem medição (em uso)") e " · na conta: <o que vale>"; na fórmula do gasto (previsao.gasto.<medida>.formula), "medido: <medido ou sem medição> · do cadastro: <o do cadastro>".' => 'Données de la montre (large) : deux tableaux côte à côte (la valeur numérique, la date et le oui/non sur une seule ligne ; la valeur de texte, comme l\'observation ou une formule qui donne du texte, passe à la ligne dans la colonne, sans envahir le tableau d\'à côté) : Fiche (Champ, Valeur, Origine avec l\'étiquette informado/par défaut/vazio) et Calculé maintenant (Formule avec l\'identifiant en code, Valeur avec l\'unité (secondes en toutes lettres), Version). Le calculé à côté de l\'indiqué, sur une ligne grise plus petite sous la valeur : sur le champ d\'où vient une consommation (previsao.gasto.<medida>.campos : la décroissance, l\'autonomie), « calculé par les lectures : 5,57% par jour d\'usage » (ou « calculé par les lectures : pas encore de mesure (en usage) ») et « · dans le calcul : <ce qui vaut> » ; sur la formule de la consommation (previsao.gasto.<medida>.formula), « mesuré : <mesuré ou sans mesure> · de la fiche : <celle de la fiche> ».',
        'Histórico (largo): "<n> registros desde DD/MM/AAAA HH:MM. Agora <estado> há <duração>." e a tabela das 5 linhas mais recentes (Quando com "até ..." embaixo, Duração, Estado em etiqueta ou o texto da marcação) e o botão leve "Abrir o histórico completo" (historico.php numa aba nova).' => 'Historique (large) : « <n> enregistrements depuis le JJ/MM/AAAA HH:MM. Maintenant <état> depuis <durée>. » et le tableau des 5 lignes les plus récentes (Quand avec « jusqu\'à ... » en dessous, Durée, État en étiquette ou le texte de la marque) et le bouton léger « Ouvrir l\'historique complet » (historico.php dans un nouvel onglet).',
        'Depois de gravar no painel, o recado aparece no topo do painel e a página e o painel se remontam sem perder os quadros abertos nem a rolagem; excluir o relógio recarrega a página.' => 'Après un enregistrement dans le panneau, le message apparaît en haut du panneau et la page et le panneau se reconstruisent sans perdre les cadres ouverts ni le défilement ; supprimer la montre recharge la page.',
        'Ficha do relógio' => 'Fiche de la montre',
        'ficha.php?id=<id> (sem id: o primeiro)' => 'ficha.php?id=<id> (sans id : la première)',
        'recurso=hoje (a lista)' => 'recurso=hoje (la liste)',
        'as mesmas do painel do relógio' => 'les mêmes que le panneau de la montre',
        'Escolha e painel' => 'Choix et panneau',
        'No alto, "Relógio" e uma lista com todos (os disponíveis primeiro, o estado entre parênteses nos outros: "(indisponível)", "(emprestado)"); havendo relógios fora da coleção, a lista vem em dois grupos, "Na coleção" e "Fora da coleção" (cada um com a situação: "(desejado)", "(vendido)", "(arquivado)"); trocar abre o escolhido. Embaixo, o mesmo painel do relógio da página Hoje, numa página própria de até 72rem, com os quadros lado a lado e sem o ×. Sem relógios: "Nenhum relógio cadastrado. Cadastre o primeiro." (link para index.php?novo=1).' => 'En haut, « Montre » et une liste avec toutes (les disponibles d\'abord, l\'état entre parenthèses pour les autres : « (indisponible) », « (prêtée) ») ; s\'il y a des montres hors de la collection, la liste vient en deux groupes, « Dans la collection » et « Hors de la collection » (chacun avec le statut : « (désirée) », « (vendue) », « (archivée) ») ; changer ouvre la choisie. En dessous, le même panneau de la montre de la page Aujourd\'hui, sur une page propre jusqu\'à 72rem, avec les cadres côte à côte et sans le ×. Sans montres : « Aucune montre enregistrée. Enregistrez la première. » (lien vers index.php?novo=1).',
        'relogio: salvar (id e posse=colecao: o Comprei e o Voltar para a coleção)' => 'relogio : salvar (id et posse=colecao : le Achetée et le Retour dans la collection)',
        'Lista de desejos' => 'Liste d\'envies',
        'h1 "Lista de desejos" com o botão "Novo desejo" à direita (index.php?novo=1&posse=desejado: o cadastro de um relógio novo já como Desejado). A nota: sem desejados, como um relógio entra na lista ("Novo desejo" ou a "Situação na coleção" do cadastro) e que ele não entra no rodízio nem nos avisos; com desejados, "<n> relógios desejados, a prioridade mais alta primeiro. Somando os preços-alvo: R$ <total> (<n> sem preço-alvo). Comprou? ...".' => 'h1 « Liste d\'envies » avec le bouton « Nouvelle envie » à droite (index.php?novo=1&posse=desejado : la fiche d\'une montre nouvelle déjà comme Désirée). La note : sans envies, comment une montre entre dans la liste (« Nouvelle envie » ou le « Statut dans la collection » de la fiche) et qu\'elle n\'entre ni dans la rotation ni dans les alertes ; avec des envies, « <n> montres désirées, la priorité la plus haute d\'abord. Total des prix cibles : R$ <total> (<n> sans prix cible). Vous l\'avez achetée ? ... ».',
        'Tabela (vira fichas até 900px) Relógio (a miniatura, o nome com o link da ficha e, embaixo, menor, "marca · referência"), Prioridade, Preço-alvo ("R$ 1.234,56" ou —), Grupo (o caminho; — na raiz), Link ("abrir a página" numa aba nova, só para http:// e https://; outro texto, como está; —) e o botão leve "Comprei" (confirma "Comprou o <nome>? Ele entra na coleção, disponível para o rodízio, e a ficha dele abre para você preencher a compra."; gravado, abre ficha.php?id=<id>).' => 'Tableau (devient des fiches jusqu\'à 900px) Montre (la miniature, le nom avec le lien de la fiche et, en dessous, plus petit, « marque · référence »), Priorité, Prix cible (« R$ 1.234,56 » ou —), Groupe (le chemin ; — à la racine), Lien (« ouvrir la page » dans un nouvel onglet, seulement pour http:// et https:// ; un autre texte, tel quel ; —) et le bouton léger « Achetée » (confirme « Vous avez acheté la <nom> ? Elle entre dans la collection, disponible pour la rotation, et sa fiche s\'ouvre pour que vous remplissiez l\'achat. » ; enregistré, ouvre ficha.php?id=<id>).',
        'Fora da coleção' => 'Hors de la collection',
        'h2 "Fora da coleção", a nota (fora do rodízio, do plano e dos avisos; o emprestado continua na tabela da página Hoje e no valor da coleção; a ficha, os documentos e o histórico ficam) e a tabela Relógio (miniatura e nome), Situação (etiqueta lilás: emprestado, vendido, arquivado), Grupo e o botão leve "Voltar para a coleção" (confirma; gravado, abre a ficha).' => 'h2 « Hors de la collection », la note (hors de la rotation, du plan et des alertes ; la prêtée reste dans le tableau de la page Aujourd\'hui et dans la valeur de la collection ; la fiche, les documents et l\'historique restent) et le tableau Montre (miniature et nom), Statut (étiquette lilas : prêtée, vendue, archivée), Groupe et le bouton léger « Retour dans la collection » (confirme ; enregistré, ouvre la fiche).',
        'Na página Hoje, ao lado do "Novo relógio", o botão leve "Desejos (<n>) · Fora da coleção (<n>)" (só as partes que têm algum; sem nenhum, o botão some) leva a esta página.' => 'Sur la page Aujourd\'hui, à côté de « Nouvelle montre », le bouton léger « Envies (<n>) · Hors collection (<n>) » (seulement les parties qui en ont ; sans aucune, le bouton disparaît) mène à cette page.',
        'estatisticas.php?de=AAAA-MM-DD&ate=AAAA-MM-DD (de=tudo: desde o primeiro uso; sem nada: os últimos 90 dias)' => 'estatisticas.php?de=AAAA-MM-JJ&ate=AAAA-MM-JJ (de=tudo : depuis la première utilisation ; sans rien : les 90 derniers jours)',
        'Período e resumo' => 'Période et résumé',
        'h1 "Estatísticas" com "de DD/MM/AAAA a DD/MM/AAAA · N dias" em cinza à direita. Filtro num cartão: De, Até (máximo hoje), "Ver" e os atalhos 30 dias, 90 dias, 1 ano, desde o começo.' => 'h1 « Statistiques » avec « du JJ/MM/AAAA au JJ/MM/AAAA · N jours » en gris à droite. Filtre dans une carte : De, À (maximum aujourd\'hui), « Voir » et les raccourcis 30 jours, 90 jours, 1 an, depuis le début.',
        'Quatro caixas (duas por linha até 900px): "<n>" dias com relógio no pulso (de <dias>); "<h> h" no pulso · <h> h por dia com relógio; "<usados> de <coleção>" relógios usados · <n> sem uso; "R$ <custo médio>" custo por uso, em média · coleção: R$ <valor>. Embaixo, "Mais usado: <link> (<h> h, <n> dias). Menos usado (dos que foram ao pulso): <link> (<h> h)."' => 'Quatre cases (deux par ligne jusqu\'à 900px) : « <n> » jours avec une montre au poignet (sur <jours>) ; « <h> h » au poignet · <h> h par jour avec montre ; « <portées> sur <collection> » montres portées · <n> non portées ; « R$ <coût moyen> » coût par port, en moyenne · collection : R$ <montant>. En dessous, « La plus portée : <lien> (<h> h, <n> jours). La moins portée (parmi celles allées au poignet) : <lien> (<h> h). »',
        'Cada relógio' => 'Chaque montre',
        'Cartão com a nota do que cada coluna é e a tabela (fichas até 900px) Relógio (o link da ficha e, embaixo, menor, o grupo e a situação fora da coleção), Dias de uso, Horas ("12,5 h"), A parte (a barra horizontal safira com a largura relogios[].barra e "56,8%"), Custo por uso ("R$ 83,30" ou —), Sem uso há ("3 dias", "usado hoje", "nunca usado"), Tendência ("↑ usando mais" em verde, "↓ usando menos" em vermelho, "→ estável", "· poucos dados" em cinza; a dica com as horas de cada metade).' => 'Carte avec la note de ce qu\'est chaque colonne et le tableau (fiches jusqu\'à 900px) Montre (le lien de la fiche et, en dessous, plus petit, le groupe et le statut hors de la collection), Jours portés, Heures (« 12,5 h »), La part (la barre horizontale saphir avec la largeur relogios[].barra et « 56,8 % »), Coût par port (« R$ 83,30 » ou —), Non portée depuis (« 3 jours », « portée aujourd\'hui », « jamais portée »), Tendance (« ↑ portée plus » en vert, « ↓ portée moins » en rouge, « → stable », « · peu de données » en gris ; l\'indication avec les heures de chaque moitié).',
        'Gráficos' => 'Graphiques',
        'Dois cartões lado a lado (um embaixo do outro até 900px): Por dia da semana e Por mês, cada um um gráfico de barras verticais em SVG (largura 100%, as barras safira com a altura da barra da API, o valor "14 h" em cima de cada uma quando são até 8, os rótulos embaixo: seg...dom, set/26..., no máximo uns 7 rótulos) e a nota com os números (a média por dia de cada dia da semana; as horas e quantos relógios em cada mês).' => 'Deux cartes côte à côte (l\'une sous l\'autre jusqu\'à 900px) : Par jour de la semaine et Par mois, chacune un graphique de barres verticales en SVG (largeur 100 %, les barres saphir avec la hauteur de la barre de l\'API, la valeur « 14 h » au-dessus de chacune quand elles sont au plus 8, les libellés en dessous : lun...dim, sep/26..., au plus une petite dizaine de libellés) et la note avec les nombres (la moyenne par jour de chaque jour de la semaine ; les heures et combien de montres chaque mois).',
        'A coleção' => 'La collection',
        'Cartão com a nota e as divisões em grade (lado a lado onde cabem, cada uma com pelo menos 22rem): h3 com o título e a tabela nome, "<n> relógios", a barra com a porcentagem e as horas; numa divisão estreita (até 26rem), cada linha em duas: o nome em negrito em cima e os números embaixo.' => 'Carte avec la note et les divisions en grille (côte à côte là où elles tiennent, chacune d\'au moins 22rem) : h3 avec le titre et le tableau nom, « <n> montres », la barre avec le pourcentage et les heures ; dans une division étroite (jusqu\'à 26rem), chaque ligne en deux : le nom en gras au-dessus et les nombres en dessous.',
        'recurso=hora_certa (ao abrir e a cada minuto)' => 'recurso=hora_certa (à l\'ouverture et chaque minute)',
        'O relógio' => 'L\'horloge',
        'h1 "Hora certa" com "<fuso> · UTC<deslocamento>" em cinza. Um cartão com o mostrador em SVG (até 15rem: caixa branca de borda escura, 60 marcas, as das horas grossas; ponteiros das horas e dos minutos escuros e arredondados, o dos segundos vermelho fino, o eixo vermelho) e ao lado (embaixo, no celular) a hora digital grande (HH:MM:SS, números de largura fixa), a data por extenso, a hora UTC em cinza e a nota "O relógio deste aparelho está certo (menos de meio segundo de diferença)." ou "... está <n> s adiantado/atrasado." e de onde vem a hora.' => 'h1 « Heure exacte » avec « <fuseau> · UTC<décalage> » en gris. Une carte avec le cadran en SVG (jusqu\'à 15rem : boîte blanche à bordure sombre, 60 repères, ceux des heures épais ; aiguilles des heures et des minutes sombres et arrondies, celle des secondes rouge fine, l\'axe rouge) et à côté (en dessous, sur le téléphone) l\'heure numérique grande (HH:MM:SS, nombres de largeur fixe), la date en toutes lettres, l\'heure UTC en gris et la note « L\'horloge de cet appareil est à l\'heure (moins d\'une demi-seconde d\'écart). » ou « ... avance/retarde de <n> s. » et d\'où vient l\'heure.',
        'O relógio da página: a diferença é agora_ms menos o meio do pedido (antes e depois); a cada virada de segundo do relógio acertado, os ponteiros e a hora digital andam (no fuso.segundos da API); a cada minuto, lê a API de novo.' => 'L\'horloge de la page : la différence est agora_ms moins le milieu de la requête (avant et après) ; à chaque passage de seconde de l\'horloge réglée, les aiguilles et l\'heure numérique avancent (dans fuso.segundos de l\'API) ; chaque minute, elle relit l\'API.',
        'Os quadros' => 'Les cadres',
        'Três cartões lado a lado (um embaixo do outro até 900px), com pares rótulo/valor: Fuso e UTC (Fuso com a abreviação, Deslocamento, UTC (Zulu), Letra militar "P (Papa)", Grupo data-hora local e Zulu em código, ISO 8601), Calendário (Hoje, Dia do ano "286 de 365 · faltam 79", Semana (ISO), Trimestre, Dia juliano, Unix) e Lua (Fase com o símbolo, Idade, Iluminada, Próxima cheia, Próxima nova e a nota do ciclo médio). Embaixo, o cartão Como acertar com o texto da API.' => 'Trois cartes côte à côte (l\'une sous l\'autre jusqu\'à 900px), avec des paires libellé/valeur : Fuseau et UTC (Fuseau avec l\'abréviation, Décalage, UTC (Zulu), Lettre militaire « P (Papa) », Groupe date-heure local et Zulu en code, ISO 8601), Calendrier (Aujourd\'hui, Jour de l\'année « 286 sur 365 · il reste 79 », Semaine (ISO), Trimestre, Jour julien, Unix) et Lune (Phase avec le symbole, Âge, Éclairée, Prochaine pleine lune, Prochaine nouvelle lune et la note du cycle moyen). En dessous, la carte Comment régler avec le texte de l\'API.',
        'acessorios.php?relogio=<id> (0: os soltos; sem ele: todos)&editar=<id do acessório>' => 'acessorios.php?relogio=<id> (0 : les libres ; sans lui : tous)&editar=<id de l\'accessoire>',
        'recurso=acessorios (com relogio)' => 'recurso=acessorios (avec relogio)',
        'acessorios: salvar, excluir' => 'acessorios : salvar, excluir',
        'Lista e cadastro' => 'Liste et fiche',
        'h1 "Acessórios" com "<n> acessórios [do <relógio> | soltos] · 1 pulseira, 2 caixas..." em cinza. Um cartão com o filtro Relógio (Todos, Soltos (de nenhum relógio) e cada relógio; trocar abre o filtrado).' => 'h1 « Accessoires » avec « <n> accessoires [de la <montre> | libres] · 1 bracelet, 2 boîtes... » en gris. Une carte avec le filtre Montre (Tous, Libres (d\'aucune montre) et chaque montre ; changer ouvre le filtré).',
        'Tabela (fichas até 900px) Acessório, Tipo, Relógio (o link da ficha, ou "solto" em cinza), Observação (cinza; —) e as ações Editar (link: editar=<id>#form) e Excluir (botão leve discreto; confirma "Excluir o acessório <nome>?"). Vazia: "Nenhum acessório. Cadastre abaixo."' => 'Tableau (fiches jusqu\'à 900px) Accessoire, Type, Montre (le lien de la fiche, ou « libre » en gris), Observation (gris ; —) et les actions Modifier (lien : editar=<id>#form) et Supprimer (bouton léger discret ; confirme « Supprimer l\'accessoire <nom> ? »). Vide : « Aucun accessoire. Ajoutez-en un ci-dessous. »',
        'Cartão Novo acessório (ou "Alterar <nome>", que a página rola até ele), em grade: Nome (obrigatório, até 120, a dica "Pulseira de couro marrom"), Tipo (Pulseira, Caixa, Estojo, Ferramenta, Carregador, Peça, Outro), Relógio ("— solto (serve a vários) —" e cada relógio; no novo, o do filtro), Observação (texto, até 1000) e "Cadastrar" ou "Salvar" e "cancelar". Gravou: volta à lista, com o mesmo filtro; recusou: o alerta com os erros.' => 'Carte Nouvel accessoire (ou « Modifier <nom> », jusqu\'à laquelle la page défile), en grille : Nom (obligatoire, jusqu\'à 120, l\'indication « Bracelet en cuir marron »), Type (Bracelet, Boîte, Étui, Outil, Chargeur, Pièce, Autre), Montre (« — libre (sert à plusieurs) — » et chaque montre ; sur le nouveau, celui du filtre), Observation (texte, jusqu\'à 1000) et « Ajouter » ou « Enregistrer » et « annuler ». Enregistré : retour à la liste, avec le même filtre ; refusé : l\'alerte avec les erreurs.',
        'galeria.php (posse=todos: também os de fora da coleção)' => 'galeria.php (posse=todos : aussi celles hors de la collection)',
        'Fotos por grupo' => 'Photos par groupe',
        'Uma barra com o botão "Imprimir" (window.print) e o leve "Também os de fora da coleção" / "Só a coleção". h1 "Galeria" com "<n> relógios · R$ <valor> · <n> com foto" em cinza. Um cartão por grupo (h2 com o caminho) com a grade das fotos (colunas de pelo menos 9rem: duas no celular): a foto quadrada (ou o quadrado "Sem foto"), com o link da ficha, e embaixo o nome em negrito, "marca · referência" e, menor, "ano · R$ valor · <n> dias de uso" em cinza, e a etiqueta lilás da situação fora da coleção. No pé, "Gerado em ... pelo Relojoeiro." No papel (@media print): sem o menu e sem a barra, fundo branco, quatro fotos por linha, nenhuma partida entre páginas.' => 'Une barre avec le bouton « Imprimer » (window.print) et le léger « Aussi celles hors de la collection » / « La collection seulement ». h1 « Galerie » avec « <n> montres · R$ <montant> · <n> avec photo » en gris. Une carte par groupe (h2 avec le chemin) avec la grille des photos (colonnes d\'au moins 9rem : deux sur le téléphone) : la photo carrée (ou le carré « Pas de photo »), avec le lien de la fiche, et en dessous le nom en gras, « marque · référence » et, plus petit, « année · R$ montant · <n> jours d\'usage » en gris, et l\'étiquette lilas du statut hors de la collection. Au pied, « Généré le ... par Relojoeiro. » Sur le papier (@media print) : sans le menu et sans la barre, fond blanc, quatre photos par ligne, aucune coupée entre les pages.',
        'Passaporte do relógio' => 'Passeport de la montre',
        'A ficha para imprimir' => 'La fiche à imprimer',
        'Uma barra com "Imprimir", o leve "Voltar para a ficha" e a nota de que no papel saem só os dados. A cabeça: a foto (9rem), "Passaporte do relógio · código N", o nome em h1, "marca · referência · caminho", a situação ("Na coleção · no rodízio · no sistema desde DD/MM/AAAA") e a observação.' => 'Une barre avec « Imprimer », le léger « Retour à la fiche » et la note que sur le papier ne sortent que les données. La tête : la photo (9rem), « Passeport de la montre · code N », le nom en h1, « marque · référence · chemin », le statut (« Dans la collection · dans la rotation · dans le système depuis le JJ/MM/AAAA ») et l\'observation.',
        'Cartões (largura até 60rem; os pares lado a lado onde cabem, um embaixo do outro até 700px): Compra e Uso; Cadastro (os valores já em texto); Manutenções (cada tipo: "<n> vezes · a última em DD/MM/AAAA", e a lista das revisões e trocas de pilha); Acessórios e Documentos; Próximos avisos. Vazios: "Sem dados da compra.", "Ainda não foi ao pulso.", "Nada preenchido.", "Nenhuma marcação.", "Nenhum." No pé, "Gerado em ...". No papel: só os cartões, nenhum partido entre páginas.' => 'Cartes (largeur jusqu\'à 60rem ; les paires côte à côte là où elles tiennent, l\'une sous l\'autre jusqu\'à 700px) : Achat et Usage ; Fiche (les valeurs déjà en texte) ; Entretiens (chaque type : « <n> fois · la dernière le JJ/MM/AAAA », et la liste des révisions et changements de pile) ; Accessoires et Documents ; Prochaines alertes. Vides : « Pas de données d\'achat. », « Pas encore portée. », « Rien de rempli. », « Aucune marque. », « Aucun. » Au pied, « Généré le ... ». Sur le papier : seulement les cartes, aucune coupée entre les pages.',
        'recurso=plano (com dias=30, 90, 365, 730 ou todos; pagina e relogio)' => 'recurso=plano (avec dias=30, 90, 365, 730 ou todos ; pagina et relogio)',
        'rodizio: trocar_dia, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio : trocar_dia, periodo_sortear, periodo_livre, apagar_tudo',
        'Cabeça e filtros' => 'Tête et filtres',
        'h1 "Plano" e a nota "Modo: <modo> · a escala vai até DD/MM/AAAA · o plano gravado vai até DD/MM/AAAA. Troque o relógio de qualquer dia em "trocar por…": o dia fica escolhido à mão (e a escala é refeita a partir dele)." Filtros lado a lado: Período (Próximos 30 dias, Próximos 90 dias (o padrão), Próximo ano, Próximos 2 anos, Tudo; trocar relê a API) e Relógio (Todos e cada um; filtra o dia a dia na tela).' => 'h1 « Plan » et la note « Mode : <mode> · le planning va jusqu\'au JJ/MM/AAAA · le plan enregistré va jusqu\'au JJ/MM/AAAA. Changez la montre de n\'importe quel jour dans « remplacer par… » : le jour devient choisi à la main (et le planning est refait à partir de lui). » Filtres côte à côte : Période (30 prochains jours, 90 prochains jours (le défaut), Année prochaine, 2 prochaines années, Tout ; changer relit l\'API) et Montre (Tous et chacune ; filtre le jour par jour à l\'écran).',
        'O período à mão' => 'La période à la main',
        'Uma nota: "Para escolher os relógios de um período, dia a dia: na página Hoje, no quadro Modo de rodízio, escolha "Rodízio manual". Para apagar a programação, veja o fim desta página." (o link Hoje vai para index.php#manual).' => 'Une note : « Pour choisir les montres d\'une période, jour par jour : sur la page Aujourd\'hui, dans le cadre Mode de rotation, choisissez « Rotation manuelle ». Pour effacer la programmation, voyez la fin de cette page. » (le lien Aujourd\'hui va vers index.php#manual).',
        'Resumo do período (<n> dias)' => 'Résumé de la période (<n> jours)',
        'Tabela Relógio, Dias, %, Próximo dia ("DD/MM/AAAA seg"), À mão; do que tem mais dias ao que tem menos. Embaixo, "Sem nenhum dia no período: <relógios>." Sem dias: "Nenhum dia no plano neste período."' => 'Tableau Montre, Jours, %, Prochain (« JJ/MM/AAAA lun ») , À la main ; de celle qui a le plus de jours à celle qui en a le moins. En dessous, « Aucun jour dans la période : <montres>. » Sans jours : « Aucun jour dans le plan sur cette période. »',
        'Dia a dia' => 'Jour par jour',
        'Os dias livres (livres, da API) entram entre os do plano, na ordem das datas: no lugar do relógio, "livre: escolha à mão" em cinza com a marca "livre", e a lista do dia começa em "escolher…" (com "↺ voltar a sortear"). Um título por mês ("Outubro de 2026") e uma tabela de dias: o dia ("DD/MM" e o dia da semana, "hoje" no de hoje, com a faixa safira), o relógio (com "à mão" e o motivo embaixo), o lembrete e o "trocar por…" (como na página Hoje). Fim de semana com fundo cinza claro. Sem dias: "Neste modo o sorteio é feito semana a semana: o plano tem só a semana atual." ou "Nenhum dia." Os dias vêm da API (plano.dia_a_dia, com pagina e relogio: o filtro de relógio relê a API), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 31); passando disso, o navegador de páginas embaixo (cada página relê a API e rola até o dia a dia) e "Página N de M · <total> dias, <n> por página (o "Mostrar até" da Configuração)."' => 'Les jours libres (livres, de l\'API) s\'intercalent entre ceux du plan, dans l\'ordre des dates : à la place de la montre, « libre : choisissez à la main » en gris avec la marque « libre », et la liste du jour commence par « choisir… » (avec « ↺ retirer au sort »). Un titre par mois (« Octobre sur 2026 ») et un tableau de jours : le jour (« JJ/MM » et le jour de la semaine, « aujourd\'hui » sur celui d\'aujourd\'hui, avec la bande saphir), la montre (avec « à la main » et le motif en dessous), le rappel et le « remplacer par… » (comme sur la page Aujourd\'hui). Week-end avec un fond gris clair. Sans jours : « Dans ce mode, le tirage se fait semaine par semaine : le plan n\'a que la semaine en cours. » ou « Aucun jour. » Les jours viennent de l\'API (plano.dia_a_dia, avec pagina et relogio : le filtre de montre relit l\'API), de « Afficher jusqu\'à » en « Afficher jusqu\'à » (la Configuration, 31 par défaut) ; au-delà, le navigateur de pages en dessous (chaque page relit l\'API et défile jusqu\'au jour par jour) et « Page N sur M · <total> jours, <n> par page (le « Afficher jusqu\'à » de la Configuration). »',
        'Rodapé: Apagar a programação (um cartão no fim da página, depois do dia a dia, separado por uma margem grande e uma borda de 3px aço escuro em cima)' => 'Pied : Effacer la programmation (une carte à la fin de la page, après le jour par jour, séparée par une grande marge et une bordure de 3px acier foncé en haut)',
        'Título h2 "Apagar a programação". "Apagar um período" (o rótulo em cinza): numa linha que quebra, "De" e "Até" (datas, de hoje em diante; um dos dois pode ficar vazio) e o botão leve "Apagar" (rodizio periodo_sortear). Embaixo, a nota "Os dias do período saem do plano, de amanhã em diante (os escolhidos à mão, os sorteados e os livres), e o modo de rodízio monta esses dias de novo. Pode deixar um lado vazio: só o começo apaga dele até o fim do plano; só o fim apaga de amanhã até ele." Confirma "Apagar os dias deste período do plano (escolhidos à mão, sorteados e livres)? O modo de rodízio monta esses dias de novo." Sem nenhuma das datas, a API recusa ("Dê o começo, o fim ou os dois ...").' => 'Titre h2 « Effacer la programmation ». « Effacer une période » (le libellé en gris) : sur une ligne qui se replie, « Du » et « Au » (dates, à partir d\'aujourd\'hui ; l\'une des deux peut rester vide) et le bouton léger « Effacer » (rodizio periodo_sortear). En dessous, la note « Les jours de la période quittent le plan, à partir de demain (ceux choisis à la main, ceux tirés au sort et les libres), et le mode de rotation refait ces jours. Vous pouvez laisser un côté vide : seulement le début supprime de lui jusqu\'à la fin du plan ; seulement la fin supprime de demain jusqu\'à elle. » Il confirme « Supprimer du plan les jours de cette période (choisis à la main, tirés au sort et libres) ? Le mode de rotation refait ces jours. » Sans aucune des dates, l\'API refuse (« Indiquez le début, la fin ou les deux ... »).',
        'Abaixo de uma linha, "Apagar tudo": a caixa "Excluindo hoje (apaga também o dia de hoje)" e o botão leve "Apagar tudo" (rodizio apagar_tudo, com hoje=1 marcada), e a nota "Limpa toda a programação, de amanhã em diante: os dias escolhidos à mão, os sorteados e os livres. Marcando "Excluindo hoje", apaga de hoje em diante (se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora). Depois, o modo de rodízio monta o plano de novo, do zero." Confirma (com hoje: "Apagar toda a programação, de hoje em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo, e hoje pode sair outro relógio, que passa a ser o do pulso a partir de agora."; sem: "... de amanhã em diante ...; hoje continua como está.").' => 'Sous un trait, « Tout effacer » : la case « Y compris aujourd\'hui (efface aussi la journée d\'aujourd\'hui) » et le bouton léger « Tout effacer » (rodizio apagar_tudo, avec hoje=1 cochée), et la note « Efface toute la programmation, à partir de demain : les jours choisis à la main, les tirés au sort et les libres. En cochant « Y compris aujourd\'hui », efface à partir d\'aujourd\'hui (si une autre montre sort pour aujourd\'hui, elle devient celle du poignet dès maintenant). Ensuite, le mode de rotation refait le plan, depuis zéro. » Confirme (avec aujourd\'hui : « Effacer toute la programmation, à partir d\'aujourd\'hui (choisis à la main, tirés au sort et jours libres) ? Le mode de rotation refait le plan, et aujourd\'hui une autre montre peut sortir ; elle devient celle du poignet dès maintenant. » ; sans : « ... à partir de demain ... ; aujourd\'hui reste tel quel. »).',
        'avisos.php; ?editar=<id>#form abre um aviso para alterar; ?evento=<id>#lembretes, um lembrete; #avisos-relogios, #lembretes e #para-onde vão direto a cada parte' => 'avisos.php ; ?editar=<id>#form ouvre une alerte à modifier ; ?evento=<id>#lembretes, un rappel ; #avisos-relogios, #lembretes et #para-onde vont directement à chaque partie',
        'recurso=cadastros (os avisos, os grupos e os tipos de lançamento)' => 'recurso=cadastros (les alertes, les groupes et les types de saisie)',
        'recurso=config (os lembretes, os relógios, as repetições, os destinos e as agendas)' => 'recurso=config (les rappels, les montres, les répétitions, les destinations et les agendas)',
        'avisos: novo, alterar, excluir' => 'avisos: novo, alterar, excluir',
        'config: evento_salvar, evento_excluir' => 'config: evento_salvar, evento_excluir',
        'No alto' => 'En haut',
        'h1 "Avisos", as abas-âncora Avisos dos relógios, Lembretes e Para onde vão (levam a cada parte da mesma página) e a nota "Tudo o que o sistema lembra: os avisos dos relógios, que ele calcula sozinho... os lembretes, que você marca com hora e repetição; e para onde vão os dois...". Depois de gravar, o recado e a página volta na parte gravada; recusado, os erros em cima, e o que foi digitado fica.' => 'h1 « Alertes », les onglets-ancres Alertes des montres, Rappels et Où elles vont (ils mènent à chaque partie de la même page) et la note « Tout ce que le système rappelle : les alertes des montres, qu\'il calcule tout seul... les rappels, que vous fixez avec une heure et une répétition ; et où vont les deux... ». Après l\'enregistrement, le message, et la page revient sur la partie enregistrée ; refusé, les erreurs en haut, et ce qui a été tapé reste.',
        'Avisos dos relógios' => 'Alertes des montres',
        'Tabela Aviso, Versão para, Data prevista, Vale quando, Antecedência ("N d"), Resolve, Na escala (com o valor ou as horas simuladas), Na agenda, Na hora (sim/não), Ativo, ações. Formulário: Identificador (na novo), Nome, Antecedência (dias), Resolve (os tipos), Versão para, ativo, "na hora (Telegram no minuto em que vence)" (caixa), Na escala inteligente (não; no relógio do dia; sempre), Escala: valor do lançamento simulado, Escala: horas da sessão simulada, Data na agenda (só dentro da antecedência; qualquer data), Data prevista (fórmula), Vale quando (fórmula), Texto (até 300).' => 'Tableau Alerte, Version pour, Date prévue, Vaut quand, Anticipation (« N j »), Résout, Dans le planning (avec la valeur ou les heures simulées), Dans l\'agenda, Immédiate (oui/non), Active, actions. Formulaire : Identifiant (sur le nouveau), Nom, Anticipation (jours), Résout (les types), Version pour, actif, « immédiate (Telegram à la minute de l\'échéance) » (case), Dans le planning intelligent (non ; sur la montre du jour ; toujours), Planning : valeur de la saisie simulée, Planning : heures de la session simulée, Date dans l\'agenda (seulement dans l\'anticipation ; n\'importe quelle date), Date prévue (formule), Vaut quand (formule), Texte (jusqu\'à 300).',
        'Lembretes (eventos personalizados)' => 'Rappels (événements personnalisés)',
        'A tabela dos eventos: Evento (o nome), Quando (a repetição por extenso), Relógio, Vai para (os destinos e as agendas que recebem) e as ações Editar e Excluir (Excluir mostra o que sai junto e pede a confirmação). Embaixo, o quadro que abre e fecha ("Novo evento" ou "Editar o evento <nome>"): Nome (obrigatório), Relógio (opcional), Quando dispara (uma vez, todo dia, toda semana, todo mês, a cada N dias), e só os campos da repetição escolhida. O evento novo já vai para todos os destinos.' => 'Le tableau des événements : Événement (le nom), Quand (la répétition en toutes lettres), Montre, Va vers (les destinations et les agendas qui le reçoivent) et les actions Modifier et Supprimer (Supprimer montre ce qui part avec et demande la confirmation). En dessous, le cadre qui s\'ouvre et se ferme (« Nouvel événement » ou « Modifier l\'événement <nome> ») : Nom (obligatoire), Montre (facultative), Quand il se déclenche (une fois, tous les jours, toutes les semaines, tous les mois, tous les N jours), et seulement les champs de la répétition choisie. Le nouvel événement va déjà vers toutes les destinations.',
        'Para onde vão: destinos e agendas' => 'Où elles vont : destinations et agendas',
        'Um quadro com dois lados: "Destinos das mensagens" (cada destino com o nome, o tipo e "(desligado)" quando está; o link para a página Destinos; vazio: "Nenhum ainda: as mensagens da manhã, da noite e os avisos não saem para lugar nenhum.") e "Agendas" (cada agenda; o link para a página Agendas; vazio: "Nenhuma ainda."), e a explicação "Um destino é um webhook (Telegram, n8n...), um e-mail ou o Web Push do navegador; uma agenda é o Google, um CalDAV (Nextcloud, iCloud, Fastmail), o Outlook ou um link ICS...".' => 'Un cadre à deux côtés : « Destinations des messages » (chaque destination avec le nom, le type et « (désactivé) » quand elle l\'est ; le lien vers la page Destinations ; vide : « Aucune pour l\'instant : les messages du matin, du soir et les alertes ne partent nulle part. ») et « Agendas » (chaque agenda ; le lien vers la page Agendas ; vide : « Aucun pour l\'instant. »), et l\'explication « Une destination est un webhook (Telegram, n8n...), un e-mail ou le Web Push du navigateur ; une agenda est Google, un CalDAV (Nextcloud, iCloud, Fastmail), Outlook ou un lien ICS... ».',
        'configuracao.php (o ?evento=<id> e o #personalizados antigos levam para a página Avisos)' => 'configuracao.php (les anciens ?evento=<id> et #personalizados mènent à la page Alertes)',
        'recurso=migracoes (antes de tudo)' => 'recurso=migracoes (avant tout)',
        'config: salvar' => 'config: salvar',
        'migracoes: aplicar (só o master)' => 'migracoes: aplicar (seulement le master)',
        'backup: fazer, restaurar (só o master)' => 'backup: fazer, restaurar (seulement le master)',
        'Banco desatualizado (só quando há migração pendente)' => 'Base de données pas à jour (seulement quand il y a une migration en attente)',
        'Um cartão só: "O banco está desatualizado", a explicação ("Esta versão do sistema precisa de migrações que ainda não foram aplicadas... as páginas, a API e o cron ficam parados..."), a tabela das pendentes (versão em negrito, o que traz, o arquivo em código) e o botão "Aplicar as migrações" (só o master aplica; a v25 guarda antes uma cópia do banco antigo em relojoeiro-antes-da-v25.jsonl.gz).' => 'Une seule carte : « La base de données n\'est pas à jour », l\'explication (« Cette version du système a besoin de migrations qui n\'ont pas encore été appliquées... les pages, l\'API et le cron restent arrêtés... »), le tableau des migrations en attente (version en gras, ce qu\'elle apporte, le fichier en code) et le bouton « Appliquer les migrations » (seul le master applique ; la v25 garde d\'abord une copie de l\'ancienne base dans relojoeiro-antes-da-v25.jsonl.gz).',
        'Os quadros do alto (uma grade de 3 colunas; um formulário só, salvo pela barra do pé)' => 'Les cadres du haut (une grille de 3 colonnes ; un seul formulaire, enregistré par la barre du pied)',
        'Cada opção numa linha: o rótulo à esquerda e o campo à direita, alinhados na mesma coluna em todos os quadros; caixas de marcar no lugar do campo; textos longos com o rótulo em cima e o campo na largura toda. Cada quadro com a explicação embaixo.' => 'Chaque option sur une ligne : le libellé à gauche et le champ à droite, alignés dans la même colonne dans tous les cadres ; cases à cocher à la place du champ ; textes longs avec le libellé au-dessus et le champ sur toute la largeur. Chaque cadre avec l\'explication en dessous.',
        'Rotina do dia: Manhã: relógio do dia e avisos (hora); Noite: preparar o de amanhã (hora); No pulso a partir de (hora); Pôr no pulso sozinho (caixa); No pulso até (hora); Tirar do pulso sozinho (caixa); Sessão no sol esquecida fecha às (hora).' => 'Routine du jour : Matin : montre du jour et alertes (heure) ; Soir : préparer celle de demain (heure) ; Au poignet à partir de (heure) ; Mettre au poignet tout seul (case) ; Au poignet jusqu\'à (heure) ; Retirer du poignet tout seul (case) ; Une session au soleil oubliée se ferme à (heure).',
        'Limites e contas: Carregar quando a carga chegar a (%); Solar: pôr no sol quando chegar a (%); Gasto da bateria: como calcular (uma lista: "Conforme o relógio e o grupo (o cadastro)" e os cinco motores numerados, "1. Pelas horas registradas (o motor original)" a "5. Pelas fórmulas do cadastro"); Gasto medido: contar por (Dias (os últimos dias) ou Leituras (as últimas de cada tipo)); Gasto medido: média dos últimos (dias); Gasto medido: últimas leituras (de cada tipo); Aviso Encostado: dias sem ir ao pulso; Máximo de dias sem uso; Previsão: limite (%); Cópia dos documentos no banco (Conforme o relógio e o arquivo, Todos os arquivos, Nenhum arquivo). Embaixo, a nota explicando o limite por relógio, os cinco motores e a cópia (e, em vermelho, o aviso de que o config.php ainda define DOCUMENTOS_COPIA_BANCO, que não vale mais, quando é o caso).' => 'Limites et calculs : Charger quand la charge atteint (%) ; Solaire : mettre au soleil quand elle atteint (%) ; Consommation de la batterie : comment calculer (une liste : « Selon la montre et le groupe (la fiche) » et les cinq moteurs numérotés, « 1. Par les heures enregistrées (le moteur d\'origine) » à « 5. Par les formules de la fiche ») ; Consommation mesurée : compter par (Jours (les derniers jours) ou Relevés (les derniers de chaque type)) ; Consommation mesurée : moyenne des derniers (jours) ; Consommation mesurée : derniers relevés (de chaque type) ; Alerte Délaissée : jours sans aller au poignet ; Maximum de jours sans usage ; Prévision : limite (%) ; Copie des documents dans la base (Selon la montre et le fichier, Tous les fichiers, Aucun fichier). En dessous, la note expliquant la limite par montre, les cinq moteurs et la copie (et, en rouge, l\'avertissement que le config.php définit encore DOCUMENTOS_COPIA_BANCO, qui ne vaut plus, le cas échéant).',
        'Telas: Abrir o relógio na página Hoje (Ao lado da lista; Numa janela flutuante, grande); Destaque no alto da página Hoje; Próximos dias e Plano: mostrar até (dias); Idioma padrão da coleção; Endereço do sistema (a âncora {link}: só o master muda; para os outros, o texto).' => 'Écrans : Ouvrir la montre sur la page Aujourd\'hui (À côté de la liste ; Dans une grande fenêtre flottante) ; Mise en avant en haut de la page Aujourd\'hui ; Prochains jours et Plan : afficher jusqu\'à (jours) ; Langue par défaut de la collection ; Adresse du système (l\'ancre {link} : seul le master la change ; pour les autres, le texte).',
        'Cron: "Cron rodando: última execução às HH:MM." (nota) ou, em âmbar, "O cron ainda não rodou" / "O cron não roda desde ..." com a linha do crontab em código; o erro guardado numa caixa; o link "Ver todas as execuções do cron" e o registro da última rodada (o master vê o do sistema; os outros, o da coleção).' => 'Cron : « Cron en marche : dernière exécution à HH:MM. » (note) ou, en ambre, « Le cron n\'a pas encore tourné » / « Le cron ne tourne plus depuis ... » avec la ligne du crontab en code ; l\'erreur enregistrée dans une boîte ; le lien « Voir toutes les exécutions du cron » et le journal de la dernière tournée (le master voit celui du système ; les autres, celui de la collection).',
        'Sorteios (só leitura): de onde vêm os números (RANDOM.ORG, ANU QRNG, o gerador seguro do PHP) e o último lote.' => 'Tirages (lecture seule) : d\'où viennent les nombres (RANDOM.ORG, ANU QRNG, le générateur sûr de PHP) et le dernier lot.',
        'Avisos, lembretes e mensagens' => 'Alertes, rappels et messages',
        'Um quadro pequeno na grade: "N lembretes · N destinos · N agendas" e a nota "Os avisos dos relógios, os lembretes (os eventos personalizados) e para onde eles vão ficam juntos na página Avisos." (o link). O endereço antigo de um lembrete (?evento=<id> ou #personalizados) leva para a página Avisos.' => 'Un petit cadre dans la grille : « N rappels · N destinations · N agendas » et la note « Les alertes des montres, les rappels (les événements personnalisés) et où ils vont sont réunis dans la page Alertes. » (le lien). L\'ancienne adresse d\'un rappel (?evento=<id> ou #personalizados) mène à la page Alertes.',
        'A barra de salvar no pé: "As mudanças desta página valem depois de salvar." e o botão "Salvar configuração" (config salvar).' => 'La barre d\'enregistrement au pied : « Les modifications de cette page s\'appliquent après l\'enregistrement. » et le bouton « Enregistrer la configuration » (config salvar).',
        'Cópia de segurança (no fim da página; só o master)' => 'Sauvegarde (en bas de la page ; seulement le master)',
        'Título "Cópia de segurança". Com a pasta: a nota "Uma cópia do banco inteiro por dia, na rodada da noite, guardando as N mais novas, sem (ou com) o conteúdo dos documentos... Última: DD/MM/AAAA HH:MM."; sem a pasta, em âmbar, o aviso de que falta a BACKUP_PASTA.' => 'Titre « Sauvegarde ». Avec le dossier : la note « Une copie de toute la base par jour, dans la tournée du soir, en gardant les N plus récentes, sans (ou avec) le contenu des documents... Dernière : DD/MM/AAAA HH:MM. » ; sans le dossier, en ambre, l\'avis qu\'il manque la BACKUP_PASTA.',
        'A tabela compacta das cópias (da mais nova para a mais velha): Cópia (o nome do arquivo em fonte fixa), Feita em, Tamanho, Documentos (com/sem) e, à direita, "Baixar" e "Restaurar" (confirma antes). Com BACKUP_ATIVO = false, a seção inteira não aparece.' => 'Le tableau compact des copies (de la plus récente à la plus ancienne) : Copie (le nom du fichier en police fixe), Faite le, Taille, Documents (avec/sans) et, à droite, « Télécharger » et « Restaurer » (confirme d\'abord). Avec BACKUP_ATIVO = false, toute la section n\'apparaît pas.',
        'criterios.php?escopo=<"", g:<grupo> ou r:<relógio>>; ?relogio=<id> abre a conta dele' => 'criterios.php?escopo=<"", g:<groupe> ou r:<montre>> ; ?relogio=<id> ouvre son calcul',
        'criterios: todas as ações' => 'criterios : toutes les actions',
        'Explicações' => 'Explications',
        'h1 "Critérios de escolha do relógio". Cartão "Como a nota funciona" (lugar, conjunto, parâmetro, subparâmetro, faixas, peso efetivo e nota final, em negrito os termos). Cartão "Como a nota vira escolha": as quatro formas com a explicação, a tabela Modo de rodízio / Forma de escolha ("(o modo atual)") e a garantia de rodízio.' => 'h1 « Critères de choix de la montre ». Carte « Comment fonctionne la note » (endroit, ensemble, paramètre, sous-paramètre, tranches, poids effectif et note finale, les termes en gras). Carte « Comment la note devient un choix » : les quatre façons avec l\'explication, le tableau Mode de rotation / Méthode de choix (« (le mode actuel) ») et la garantie de rotation.',
        'Onde há critérios' => 'Où il y a des critères',
        'Tabela Lugar, Parâmetros (quantos), Usado por ("N relógios" e os nomes em cinza) e o link "editar". Em vermelho: "Há relógios sem conjunto nenhum (nota neutra, 50): ..."' => 'Tableau Endroit, Paramètres (combien), Utilisé par (« N montres » et les noms en gris) et le lien « modifier ». En rouge : « Il y a des montres sans aucun ensemble (note neutre, 50) : ... »',
        'O conjunto do lugar escolhido' => 'L\'ensemble de l\'endroit choisi',
        '"Editar os critérios de" com a lista de todos os lugares ("Todos os relógios", "Grupo: <caminho>", "Relógio: <nome>"; "— com critérios próprios" nos que têm) e "Abrir". Sem critérios próprios: "<Lugar> não tem critérios próprios: usa os de <lugar de cima>." e os botões "Criar critérios próprios, copiando os de <lugar>" e "Criar vazio" (leve).' => '« Modifier les critères de » avec la liste de tous les endroits (« Toutes les montres », « Groupe : <chemin> », « Montre : <nom> » ; « — avec ses propres critères » pour ceux qui en ont) et « Ouvrir ». Sans critères propres : « <Endroit> n\'a pas de critères propres : il utilise ceux de <endroit du dessus>. » et les boutons « Créer des critères propres, en copiant ceux de <endroit> » et « Créer vide » (léger).',
        'Com critérios: "Critérios de <lugar>", "Usado por N relógios: ..." e a tabela Parâmetro (o nome editável), Peso no conjunto (campo curto e "%"), Subparâmetros (link para a seção; "(fora da conta)" em vermelho se nenhum), e ↑ ↓ Excluir; no rodapé "Soma" com a soma ao vivo e "fecha 100%" ou, em vermelho, "faltam N%" / "passa N%"; botão "Salvar parâmetros". Excluir confirma mostrando como o peso se divide entre os que ficam. Linha de inclusão: Novo parâmetro, Peso (%), "Incluir". Embaixo, "Excluir os critérios próprios de <lugar>" (discreto, confirma).' => 'Avec des critères : « Critères de <endroit> », « Utilisé par N montres : ... » et le tableau Paramètre (le nom modifiable), Poids dans l\'ensemble (champ court et « % »), Sous-paramètres (lien vers la section ; « (hors du calcul) » en rouge s\'il n\'y en a aucun), et ↑ ↓ Supprimer ; au pied « Somme » avec la somme en direct et « fait 100 % » ou, en rouge, « il manque N % » / « dépasse de N % » ; bouton « Enregistrer les paramètres ». Supprimer confirme en montrant comment le poids se répartit entre ceux qui restent. Ligne d\'ajout : Nouveau paramètre, Poids (%), « Ajouter ». En dessous, « Supprimer les critères propres de <endroit> » (discret, confirme).',
        'Cada parâmetro' => 'Chaque paramètre',
        'Um cartão por parâmetro: "<nome> <peso> do conjunto de <lugar>"; a tabela Subparâmetro, Mede, Peso no parâmetro, Peso efetivo no conjunto (atualizado ao digitar), ↑ ↓ Excluir, com a soma no rodapé e "Salvar subparâmetros".' => 'Une carte par paramètre : « <nom> <poids> de l\'ensemble de <endroit> » ; le tableau Sous-paramètre, Mesure, Poids dans le paramètre, Poids effectif dans l\'ensemble (mis à jour à la saisie), ↑ ↓ Supprimer, avec la somme au pied et « Enregistrer les sous-paramètres ».',
        'Para cada subparâmetro, "Faixas de <nome>" (abre e fecha, com quantas faixas e o que mede): numa medida numérica, a tabela De, Até, Nota, Apagar; numa de categoria, Categoria (lista), Nota, Apagar; sempre uma linha em branco para incluir, o botão "+ faixa" (mais uma linha) e "Salvar faixas"; a regra das faixas em nota. Embaixo, "Trocar a medida para" (confirma: as faixas recomeçam) e "Mover para o parâmetro".' => 'Pour chaque sous-paramètre, « Tranches de <nom> » (s\'ouvre et se ferme, avec combien de tranches et ce qu\'il mesure) : pour une mesure numérique, le tableau De, À, Note, Effacer ; pour une de catégorie, Catégorie (liste), Note, Effacer ; toujours une ligne vide pour ajouter, le bouton « + tranche » (une ligne de plus) et « Enregistrer les tranches » ; la règle des tranches en note. En dessous, « Changer la mesure pour » (confirme : les tranches recommencent) et « Déplacer vers le paramètre ».',
        'Linha de inclusão: Novo subparâmetro, Mede (lista das medidas), Peso (%), "Incluir". Sem subparâmetros, em vermelho: "Sem subparâmetros: este parâmetro não entra na conta até ganhar um."' => 'Ligne d\'ajout : Nouveau sous-paramètre, Mesure (liste des mesures), Poids (%), « Ajouter ». Sans sous-paramètres, en rouge : « Sans sous-paramètres : ce paramètre n\'entre pas dans le calcul tant qu\'il n\'en a pas un. »',
        'A nota de cada relógio agora' => 'La note de chaque montre maintenant',
        'Um quadro que abre e fecha por relógio disponível, da maior nota para a menor: o nome em negrito, "<grupo> · critérios de <lugar>" e a nota à direita; aberto, a tabela Parâmetro, Subparâmetro, Valor medido, Faixa, Nota, Peso efetivo, Pontos, com a nota final no rodapé, e os links "editar os critérios de <lugar>" e "critérios só deste relógio". Por fim, o cartão "Restaurar os critérios iniciais" com o botão leve "Restaurar" (confirma).' => 'Un cadre qui s\'ouvre et se ferme par montre disponible, de la meilleure note à la plus basse : le nom en gras, « <groupe> · critères de <endroit> » et la note à droite ; ouvert, le tableau Paramètre, Sous-paramètre, Valeur mesurée, Tranche, Note, Poids effectif, Points, avec la note finale au pied, et les liens « modifier les critères de <endroit> » et « critères de cette montre seulement ». Enfin, la carte « Restaurer les critères initiaux » avec le bouton léger « Restaurer » (confirme).',
        'Grupos de relógios' => 'Groupes de montres',
        'arvore: novo, renomear, mover, ordem, excluir, relogios' => 'arvore : novo, renomear, mover, ordem, excluir, relogios',
        'Árvore' => 'Arbre',
        'A explicação; a árvore como lista com recuo por nível. Cada grupo: o nome num campo com "Renomear" (discreto), "N relógios" ("· critérios próprios" com link), ↑ ↓ e Excluir (confirma dizendo para onde vão os subgrupos, os relógios e o que acontece com os critérios); os relógios dele em cinza embaixo; e "subgrupo e mover" (abre e fecha): Novo subgrupo + "Criar", Mover para dentro de (só onde não forma ciclo) + "Mover". No fim: linha de inclusão "Novo grupo", "dentro de" e "Criar". Sem grupos: "Nenhum grupo ainda."' => 'L\'explication ; l\'arbre comme liste avec un retrait par niveau. Chaque groupe : le nom dans un champ avec « Renommer » (discret), « N montres » (« · critères propres » avec lien), ↑ ↓ et Supprimer (confirme en disant où vont les sous-groupes, les montres et ce qui arrive aux critères) ; ses montres en gris en dessous ; et « sous-groupe et déplacer » (s\'ouvre et se ferme) : Nouveau sous-groupe + « Créer », Déplacer dans (seulement là où cela ne forme pas de cycle) + « Déplacer ». À la fin : ligne d\'ajout « Nouveau groupe », « dans » et « Créer ». Sans groupes : « Aucun groupe pour l\'instant. »',
        'O grupo de cada relógio' => 'Le groupe de chaque montre',
        'Tabela Relógio ("(indisponível)" em cinza) e Grupo (lista com "(na raiz)" e os caminhos), e o botão "Salvar grupos" (arvore relogios, todos de uma vez).' => 'Tableau Montre (« (indisponible) » en gris) et Groupe (liste avec « (à la racine) » et les chemins), et le bouton « Enregistrer les groupes » (arvore relogios, tous d\'un coup).',
        'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina= (os filtros no endereço)' => 'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina= (les filtres dans l\'adresse)',
        'Título com "Última execução: DD/MM/AAAA HH:MM:SS". Filtros num cartão: De, Até (padrão: os últimos 7 dias), Situação (Com atividade (padrão), Com erro, Sem atividade, Todas), Texto no registro, Por página (25, 50, 100, 200), "Filtrar" e os atalhos hoje, 7 dias, 30 dias, erros do último ano.' => 'Titre avec « Dernière exécution : JJ/MM/AAAA HH:MM:SS ». Filtres dans une carte : De, À (par défaut : les 7 derniers jours), Statut (Avec activité (par défaut), Avec erreur, Sans activité, Toutes), Texte dans le journal, Par page (25, 50, 100, 200), « Filtrer » et les raccourcis aujourd\'hui, 7 jours, 30 jours, erreurs de la dernière année.',
        'Resumo em 4 caixas: execuções no período, com atividade, com erro (vermelho se houver), a mais lenta. A nota com quantas e a retenção. Tabela Início (data e a hora em negrito embaixo), Duração ("850 ms" ou "1,5 s"), Situação (etiqueta erro / atividade / sem atividade), Registro (o texto em fonte fixa, ou "nada a fazer neste minuto"); linha com erro em vermelho claro. Paginação: « primeira, ‹ anterior, até 3 números de cada lado, próxima ›, última ».' => 'Résumé en 4 cases : exécutions sur la période, avec activité, avec erreur (rouge s\'il y en a), la plus lente. La note avec combien et la rétention. Tableau Début (date et l\'heure en gras en dessous), Durée (« 850 ms » ou « 1,5 s »), Statut (étiquette erreur / activité / sans activité), Journal (le texte en police fixe, ou « rien à faire cette minute ») ; ligne avec erreur en rouge clair. Pagination : « première, ‹ précédente, jusqu\'à 3 numéros de chaque côté, suivante ›, dernière ».',
        'Histórico — <relógio>' => 'Historique — <montre>',
        'Cabeça com a foto, "Histórico · <tipo> · código N", o nome em h1 e "<n> registros desde ...". Filtros num cartão: De, Até, Estado (Todos, Em uso, Fora do rodízio, cada tipo de sessão, Em repouso, Marcações), Por página (25, 50, 100, Todos), "Filtrar" e os atalhos 7 dias, 30 dias, desde o começo.' => 'Tête avec la photo, « Historique · <type> · code N », le nom en h1 et « <n> enregistrements depuis ... ». Filtres dans une carte : De, À, État (Tous, En usage, Hors rotation, chaque type de session, Au repos, Marques), Par page (25, 50, 100, Tous), « Filtrer » et les raccourcis 7 jours, 30 jours, depuis le début.',
        'Resumo em caixas: o tempo em cada estado ("5d 7h" e "em uso · 13%") e a contagem de cada marcação. A nota de quantos e de como ler os trechos. Tabela Início, Fim, Duração, Estado (etiqueta verde para uso, vermelha para repouso, laranja para as outras sessões; marcação em cinza, só o texto; "em andamento: o fim é o momento desta consulta"). Paginação: « mais recentes, ‹ anterior, números, próxima ›, mais antigos » e "ver tudo".' => 'Résumé en cases : le temps dans chaque état (« 5j 7h » et « en usage · 13 % ») et le compte de chaque marque. La note de combien et de comment lire les périodes. Tableau Début, Fin, Durée, État (étiquette verte pour l\'usage, rouge pour le repos, orange pour les autres sessions ; marque en gris, seulement le texte ; « en cours : la fin est le moment de cette consultation »). Pagination : « plus récents, ‹ précédent, numéros, suivante ›, plus anciens » et « tout voir ».',
        'documentos.php?relogio=<id>&cat=<categoria> (sem relógio: de todos)' => 'documentos.php?relogio=<id>&cat=<catégorie> (sans montre : de toutes)',
        'recurso=documento (cada arquivo)' => 'recurso=documento (chaque fichier)',
        'documentos: enviar, alterar, excluir' => 'documentos : enviar, alterar, excluir',
        'relogio: salvar (a cópia no banco do relógio)' => 'relogio : salvar (la copie dans la base de la montre)',
        'Cabeça' => 'Tête',
        'h1 "Documentos do <relógio>" (ou "de todos os relógios"); a lista "Relógio" (Todos e cada um, com "(N)") e "Abrir a ficha do relógio". A situação da cópia no banco (quem decide: o config.php, o relógio, com o botão "Guardar todos os dele no banco" / "Só os marcados"). Sem a pasta: o motivo em âmbar.' => 'h1 « Documents de la <montre> » (ou « de toutes les montres ») ; la liste « Montre » (Tous et chacune, avec « (N) ») et « Ouvrir la fiche de la montre ». La situation de la copie dans la base (qui décide : config.php, la montre, avec le bouton « Tout garder dans la base » / « Seulement ceux cochés »). Sans le dossier : le motif en ambre.',
        'Enviar arquivos (abre e fecha; aberto quando não há nenhum; só com um relógio escolhido)' => 'Envoyer des fichiers (s\'ouvre et se ferme ; ouvert quand il n\'y en a aucun ; seulement avec une montre choisie)',
        'Categoria (com o que ela aceita), Título ("vazio: o nome do arquivo"), Data, Descrição, Arquivos (vários; o seletor só deixa os tipos da categoria), "Guardar a cópia destes arquivos também no banco" (só quando cabe ao arquivo decidir), o limite de tamanho, "Enviar" e o andamento ("Enviando 2 de 5: foto.jpg — 40%"). Um arquivo por vez, cada foto com a miniatura feita no navegador (480px, JPEG 80%). No fim: "N documentos guardados." e os erros.' => 'Catégorie (avec ce qu\'elle accepte), Titre (« vide : le nom du fichier »), Date, Description, Fichiers (plusieurs ; le sélecteur ne laisse que les types de la catégorie), « Garder la copie de ces fichiers aussi dans la base de données » (seulement quand c\'est au fichier de décider), la limite de taille, « Envoyer » et la progression (« Envoi de 2 sur 5 : foto.jpg — 40 % »). Un fichier à la fois, chaque photo avec la miniature faite dans le navigateur (480px, JPEG 80 %). À la fin : « N documents enregistrés. » et les erreurs.',
        'Abas e conteúdo' => 'Onglets et contenu',
        'Abas "Todos (N)" e cada categoria "(N)". Fotos: a galeria (quadrados de 140px, 100px no celular, com o título e a data) e o botão "▶ Apresentação"; tocar numa foto abre o visor em tela cheia (fundo #080b0f): "N de M", "▶ Apresentação" / "❚❚ Parar" (troca a cada 4 s), "Baixar", "×"; ‹ e › nos lados, setas do teclado, deslizar o dedo, Esc fecha, espaço liga a apresentação; a legenda embaixo.' => 'Onglets « Tous (N) » et chaque catégorie « (N) ». Photos : la galerie (carrés de 140px, 100px sur le téléphone, avec le titre et la date) et le bouton « ▶ Diaporama » ; toucher une photo ouvre la visionneuse en plein écran (fond #080b0f) : « N sur M », « ▶ Diaporama » / « ❚❚ Arrêter » (change toutes les 4 s), « Télécharger », « × » ; ‹ et › sur les côtés, flèches du clavier, glisser le doigt, Échap ferme, espace lance le diaporama ; la légende en dessous.',
        'Vídeos: o player e a lista para marcar e ordenar (↑ ↓), "▶ Assistir os marcados" (tocam em sequência; "‹ Anterior", "Próximo ›", "Fechar"). Arquivos: um cartão por arquivo com o título, a data, a categoria em etiqueta, a descrição, o nome, o tamanho e onde está guardado; PDF: "Ver aqui" (abre embutido), "Abrir noutra aba", "Baixar"; XML de NF-e: a tabela Emitente, Nota, Valor, Produto(s), Chave e "Baixar o XML"; áudio: o player; o resto: "Baixar".' => 'Vidéos : le lecteur et la liste pour cocher et ordonner (↑ ↓), « ▶ Regarder celles cochées » (elles se lisent à la suite ; « ‹ Précédent », « Suivant › », « Fermer »). Fichiers : une carte par fichier avec le titre, la date, la catégorie en étiquette, la description, le nom, la taille et où il est conservé ; PDF : « Voir ici » (s\'ouvre intégré), « Ouvrir dans un autre onglet », « Télécharger » ; XML de NF-e : le tableau Émetteur, Note, Montant, Produit(s), Clé et « Télécharger le XML » ; audio : le lecteur ; le reste : « Télécharger ».',
        'Cada foto (no canto de cima da miniatura), cada vídeo da lista, cada cartão de arquivo e o visor das fotos têm o botão redondo "⋮" (a dica "Abrir, baixar, editar ou excluir"): ele abre o menu Abrir (a foto no visor, o vídeo no player, o PDF e o resto noutra aba; não aparece no visor), Baixar, Editar e Excluir (em vermelho). Um menu aberto de cada vez; um clique fora ou Esc fecha. Editar abre uma janela por cima da página ("Editar <título>", o nome do arquivo, e Título, Data, Categoria, Descrição, a cópia no banco quando cabe, "Salvar" e "Cancelar"); com ela aberta, as setas e o espaço do visor não agem. Excluir mostra o que sai junto ("Sai junto: o arquivo no disco (6 KB).") e pede a confirmação; excluiu no visor, o visor fecha.' => 'Chaque photo (dans le coin supérieur de la miniature), chaque vidéo de la liste, chaque carte de fichier et la visionneuse de photos ont le bouton rond « ⋮ » (l\'infobulle « Ouvrir, télécharger, modifier ou supprimer ») : il ouvre le menu Ouvrir (la photo dans la visionneuse, la vidéo dans le lecteur, le PDF et le reste dans un autre onglet ; il n\'apparaît pas dans la visionneuse), Télécharger, Modifier et Supprimer (en rouge). Un seul menu ouvert à la fois ; un clic dehors ou Échap le ferme. Modifier ouvre une fenêtre au-dessus de la page (« Modifier <título> », le nom du fichier, et Titre, Date, Catégorie, Description, la copie dans la base quand elle s\'applique, « Enregistrer » et « Annuler ») ; tant qu\'elle est ouverte, les flèches et l\'espace de la visionneuse n\'agissent pas. Supprimer montre ce qui part avec (« Part avec : le fichier sur le disque (6 KB). ») et demande la confirmation ; supprimé dans la visionneuse, la visionneuse se ferme.',
        'modos.php; ?editar=<id>#form abre um modo para alterar' => 'modos.php ; ?editar=<id>#form ouvre un mode à modifier',
        'recurso=cadastros (os modos, os grupos e os relógios)' => 'recurso=cadastros (les modes, les groupes et les montres)',
        'modos: novo, alterar, ativar, excluir' => 'modos: novo, alterar, ativar, excluir',
        'Os modos' => 'Les modes',
        'h1 "Modos de rodízio" e um cartão: a explicação, a tabela e o formulário ("Novo modo" ou "Alterar ...", botão "Criar" / "Salvar" e "cancelar"). Gravou: o recado no alto e a edição acaba; recusado: o que foi digitado fica e os erros aparecem no topo.' => 'h1 « Modes de rotation » et une carte : l\'explication, le tableau et le formulaire (« Nouveau mode » ou « Modifier ... », bouton « Créer » / « Enregistrer » et « annuler »). Enregistré : le message en haut et l\'édition se termine ; refusé : ce qui a été saisi reste et les erreurs apparaissent en haut.',
        'Tabela Modo ("(ativo)"), Forma de escolha ("· com ciclo"), Blocos (nome e dias), ações (Editar; nos outros: Ativar e Excluir). Formulário: Nome, Planejamento (sorteio pelos blocos; escala inteligente de 7 dias, 30 dias, 60 dias, 6 meses, 1 ano, 2 anos), Forma de escolha, a caixa "ciclo", e a tabela dos blocos (os que existem e duas linhas vazias): Bloco (nome), Dias (caixas seg a dom), Sortear de, Um por (um por dia; um por bloco (na semana)), Relógio fixo ("— sorteia —" e os relógios). Bloco sem dia marcado sai.' => 'Tableau Mode (« (actif) »), Méthode de choix (« · avec cycle »), Blocs (nom et jours), actions (Modifier ; sur les autres : Activer et Supprimer). Formulaire : Nom, Planification (tirage par blocs ; planning intelligent de 7 jours, 30 jours, 60 jours, 6 mois, 1 an, 2 ans), Méthode de choix, la case « cycle », et le tableau des blocs (ceux qui existent et deux lignes vides) : Bloc (nom), Jours (cases lun à dim), Tirer parmi, Une par (une par jour ; une par bloc (dans la semaine)), Montre fixe (« — tirée au sort — » et les montres). Un bloc sans jour coché est retiré.',
        'cadastros.php?aba=<campos|lancamentos|formulas|documentos>&editar=<id>#form (o ?aba=avisos antigo leva para a página Avisos; o ?aba=modos, para a página Modos de rodízio)' => 'cadastros.php?aba=<campos|lancamentos|formulas|modos|documentos>&editar=<id>#form (l\'ancien ?aba=avisos mène à la page Alertes ; le ?aba=modos, à la page Modes de rotation)',
        'recurso=calcular (o testar)' => 'recurso=calcular (le tester)',
        'campos, lancamento_tipos, formulas, documento_categorias' => 'campos, lancamento_tipos, formulas, documento_categorias',
        'Em todas as abas' => 'Dans tous les onglets',
        'h1 "Cadastros" e as abas Campos, Tipos de lançamento, Fórmulas, Categorias de documentos. Cada aba é um cartão: o título, a explicação, a tabela com "Editar" (link que abre o formulário embaixo com os dados, no #form) e Excluir em cada linha, e o formulário ("Novo ..." ou "Alterar ...", botão "Criar" / "Salvar" e "cancelar"). Gravou: o recado no alto e a edição acaba; recusado: o que foi digitado fica e os erros aparecem no topo.' => 'h1 « Définitions » et les onglets Champs, Types de saisie, Formules, Catégories de documents. Chaque onglet est une carte : le titre, l\'explication, le tableau avec « Modifier » (lien qui ouvre le formulaire en dessous avec les données, sur le #form) et Supprimer sur chaque ligne, et le formulaire (« Nouveau ... » ou « Modifier ... », bouton « Créer » / « Enregistrer » et « annuler »). Enregistré : le message en haut et la modification se termine ; refusé : ce qui a été saisi reste et les erreurs apparaissent en haut.',
        'Tabela Campo ("(unidade)"), Identificador (fonte fixa), Tipo, Vale para, Padrão, ações (Editar, ↑, ↓, Excluir com confirmação "Excluir o campo <nome> e os valores dele?"). Formulário: Nome (até 120), Identificador (a-z, 0-9 e _; começa com letra; até 40), Tipo (Número inteiro, Número decimal, Sim ou não, Data, Lista de opções, Texto), Unidade (até 20), Valor padrão, Vale para ("todos os relógios" e os grupos), Opções (lista: uma por linha).' => 'Tableau Champ (« (unité) »), Identifiant (police fixe), Type, Vaut pour, Par défaut, actions (Modifier, ↑, ↓, Supprimer avec confirmation « Supprimer le champ <nom> et ses valeurs ? »). Formulaire : Nom (jusqu\'à 120), Identifiant (a-z, 0-9 et _ ; commence par une lettre ; jusqu\'à 40), Type (Nombre entier, Nombre décimal, Oui ou non, Date, Liste d\'options, Texte), Unité (jusqu\'à 20), Valeur par défaut, Vaut pour (« toutes les montres » et les groupes), Options (liste : une par ligne).',
        'Tipos de lançamento' => 'Types de saisie',
        'Tabela Tipo, Identificador, Formato (com a unidade), Fecha sozinho às, Exclusiva, Mede o gasto, Vale quando (fonte fixa), Vale para, Lançamentos (quantos), ações. Formulário: Nome, Identificador, Formato (Instantâneo; Instantâneo com valor; Sessão, com início e fim), Unidade (com valor), Fecha sozinho às (hora; vazio: não fecha), Vale para, Vale quando (fórmula), as caixas "sessão exclusiva (o relógio num lugar só)" e "mede o gasto".' => 'Tableau Type, Identifiant, Format (avec l\'unité), Se ferme seule à, Exclusive, Mesure la consommation, Vaut quand (police fixe), Vaut pour, Saisies (combien), actions. Formulaire : Nom, Identifiant, Format (Instantané ; Instantané avec valeur ; Session, avec début et fin), Unité (avec valeur), Se ferme seule à (heure ; vide : ne se ferme pas), Vaut pour, Vaut quand (formule), les cases « session exclusive (la montre à un seul endroit) » et « mesure la consommation ».',
        'Fórmulas' => 'Formules',
        'Tabela Fórmula (o nome e o identificador com a unidade), Versão para, Cálculo (fonte fixa), ações. Formulário: Identificador (só na nova), Nome, Unidade, Versão para, Cálculo (textarea, fonte fixa). "Testar uma fórmula (sem gravar)": o texto da fórmula e "Testar em todos os relógios" (recurso=calcular): a tabela Relógio, Resultado, As partes da conta, ou os erros. "As funções do motor" (abre e fecha): cada função em negrito e a explicação.' => 'Tableau Formule (le nom et l\'identifiant avec l\'unité), Version pour, Calcul (police fixe), actions. Formulaire : Identifiant (seulement pour la nouvelle), Nom, Unité, Version pour, Calcul (textarea, police fixe). « Tester une formule (sans enregistrer) » : le texte de la formule et « Tester sur toutes les montres » (recurso=calcular) : le tableau Montre, Résultat, Les parties du calcul, ou les erreurs. « Les fonctions du moteur » (s\'ouvre et se ferme) : chaque fonction en gras et l\'explication.',
        'Categorias de documentos' => 'Catégories de documents',
        'Tabela Categoria, Identificador, Aceita ("qualquer arquivo" ou as famílias), Ordem, Documentos, ações (Excluir só sem documentos). Formulário: Nome, Identificador (na nova), Ordem ("vazio: no fim"), Aceita (caixas imagens, vídeos, áudios, PDF, XML).' => 'Tableau Catégorie, Identifiant, Accepte (« n\'importe quel fichier » ou les familles), Ordre, Documents, actions (Supprimer seulement sans documents). Formulaire : Nom, Identifiant (sur la nouvelle), Ordre (« vide : à la fin »), Accepte (cases images, vidéos, audios, PDF, XML).',
        'usuarios: salvar, alterar, oficializar, prorrogar, voltar_demo, bloquear, transferir, dar_acesso, excluir' => 'usuarios: salvar, alterar, oficializar, prorrogar, voltar_demo, bloquear, transferir, dar_acesso, excluir',
        'O painel do master' => 'Le panneau du master',
        'h1 "Usuários". Cartão "Contas (N)": a tabela Login (com os selos "master" em azul, "demo" e "bloqueada" e "você"), E-mail, Criada em, Último acesso, Vence (a data e "(N dias)", ou "não vence"), Coleções (cada uma com "(N relógios)"), Vê também (as coleções de outros e "tudo de <dono>") e, à direita, "Ações", que abre: "Ver como <login>" (grava o cookie como e abre o Hoje como ele), "Tornar oficial" (na demo) ou "Voltar a demo (dias)", "Prorrogar (dias)", "Bloquear"/"Desbloquear", o quadro Alterar (Login, E-mail, Idioma, Papel, "Salvar"), a senha nova com "Trocar a senha", "Transferir a coleção" (a coleção e o novo dono), "Dar acesso" (uma coleção de outro ou "Tudo de <dono>") e "Excluir" (mostra o que sai junto: as coleções, os relógios, os arquivos).' => 'h1 « Utilisateurs ». Carte « Comptes (N) » : le tableau Identifiant (avec les badges « master » en bleu, « démo » et « bloqué » et « vous »), E-mail, Créé le, Dernier accès, Expire (la date et « (N jours) », ou « n\'expire pas »), Collections (chacune avec « (N montres) »), Voit aussi (les collections des autres et « tout de <dono> ») et, à droite, « Actions », qui ouvre : « Voir en tant que <login> » (enregistre le cookie como et ouvre Aujourd\'hui en tant que lui), « Rendre officiel » (sur la démo) ou « Revenir en démo (jours) », « Prolonger (jours) », « Bloquer »/« Débloquer », le cadre Modifier (Identifiant, E-mail, Langue, Rôle, « Enregistrer »), le nouveau mot de passe avec « Changer le mot de passe », « Transférer la collection » (la collection et le nouveau propriétaire), « Donner l\'accès » (une collection d\'un autre ou « Tout de <dono> ») et « Supprimer » (montre ce qui part avec : les collections, les montres, les fichiers).',
        'Cartão "Criar conta": Login, Senha (pelo menos 6 caracteres), E-mail, Coleção (uma com o conjunto inicial; uma vazia; nenhuma), a nota "A conta criada aqui é oficial (não vence). Se o login já existir, só a senha dele é trocada." e "Criar conta".' => 'Carte « Créer un compte » : Identifiant, Mot de passe (au moins 6 caractères), E-mail, Collection (une avec l\'ensemble initial ; une vide ; aucune), la note « Le compte créé ici est officiel (il n\'expire pas). Si l\'identifiant existe déjà, seul son mot de passe est changé. » et « Créer un compte ».',
        'Quem não é o master vê só "Só o administrador (master) cuida das contas. As suas coisas ficam em Minha conta.".' => 'Qui n\'est pas le master ne voit que « Seul l\'administrateur (master) s\'occupe des comptes. Vos affaires sont dans Mon compte. ».',
        'conta.php; ?convite=<token> aceita o convite ao abrir' => 'conta.php ; ?convite=<token> accepte l\'invitation à l\'ouverture',
        'recurso=conta' => 'recurso=conta',
        'recurso=cadastro (a lista das coleções e dos donos)' => 'recurso=cadastro (la liste des collections et des propriétaires)',
        'conta: alterar, token_criar, token_revogar, aparelho_lembrar, aparelho_esquecer, push_inscrever, push_cancelar, push_testar, email_testar, vapid_gerar, excluir' => 'conta: alterar, token_criar, token_revogar, aparelho_lembrar, aparelho_esquecer, push_inscrever, push_cancelar, push_testar, email_testar, vapid_gerar, excluir',
        'colecoes: criar, renomear, excluir, arvore_copiar, arvore_renomear, arvore_excluir' => 'colecoes: criar, renomear, excluir, arvore_copiar, arvore_renomear, arvore_excluir',
        'pedidos: pedir, cancelar' => 'pedidos: pedir, cancelar',
        'acessos: sair' => 'acessos: sair',
        'convites: aceitar' => 'convites: aceitar',
        'Coleções' => 'Collections',
        'Tabela Coleção, Código (o id, que o dono passa a quem quer pedir acesso), Dono, Você é (sua, membro, master) e as ações: "Abrir" (grava o cookie colecao) ou "aberta"; nas suas, "Renomear" (abre o nome e "Salvar") e "Excluir" (mostra o que sai junto); nas dos outros, "Sair". Sem nenhuma: o aviso âmbar "Você ainda não vê nenhuma coleção: crie uma aqui embaixo, ou peça acesso à de alguém (e espere a aprovação)." Embaixo da tabela, a nota "Para alguém pedir acesso a uma coleção sua, passe o código dela...". Depois, "Nova coleção": Nome, Começa (com o conjunto inicial; vazia; com uma árvore minha que já existe, que abre a escolha da Árvore) e "Criar coleção" (a nova passa a ser a do menu).' => 'Tableau Collection, Code (l\'id, que le propriétaire donne à qui veut demander l\'accès), Propriétaire, Vous êtes (la vôtre, membre, master) et les actions : « Ouvrir » (enregistre le cookie colecao) ou « ouverte » ; sur les vôtres, « Renommer » (ouvre le nom et « Enregistrer ») et « Supprimer » (montre ce qui part avec) ; sur celles des autres, « Quitter ». Sans aucune : l\'avis ambre « Vous ne voyez encore aucune collection : créez-en une ci-dessous, ou demandez l\'accès à celle de quelqu\'un (et attendez l\'approbation). » Sous le tableau, la note « Pour que quelqu\'un demande l\'accès à une de vos collections, donnez-lui son code... ». Ensuite, « Nouvelle collection » : Nom, Commence (avec l\'ensemble initial ; vide ; avec un de mes arbres qui existe déjà, ce qui ouvre le choix de l\'Arbre) et « Créer la collection » (la nouvelle devient celle du menu).',
        'Árvores de grupos' => 'Arbres de groupes',
        'Só quando há: a explicação ("A árvore guarda os grupos e o cadastro deles... Uma árvore pode servir a várias coleções suas: o que muda nela vale para todas.") e a tabela Árvore, Grupos, Usada por, com "Renomear ou copiar" (o nome e "Renomear"; "Cópia de <nome>" e "Copiar") e "Excluir" (mostra as coleções que saem junto).' => 'Seulement quand il y en a : l\'explication (« L\'arbre garde les groupes et leurs définitions... Un arbre peut servir à plusieurs de vos collections : ce qui change en lui vaut pour toutes. ») et le tableau Arbre, Groupes, Utilisé par, avec « Renommer ou copier » (le nom et « Renommer » ; « Copie de <nome> » et « Copier ») et « Supprimer » (montre les collections qui partent avec).',
        'Pedir acesso' => 'Demander l\'accès',
        'Os pedidos esperando (O quê, Pedido em, Vence em, "Cancelar"), quantos convites há para o seu e-mail ("aceite pelo link que chegou nele"), e o formulário: Acesso a ("uma coleção (o código da coleção)" ou "todas as coleções de um dono (o código do dono)"), Código (número), o quadro recolhido "Como pedir acesso (e por que pelo código)" (uma lista numerada: por que o código, como pedir o código ao dono e onde ele o encontra, o que preencher, o que acontece depois), Recado para o dono e "Pedir acesso". Nenhuma lista de contas nem de coleções; os pedidos esperando mostram só o código ("a coleção de código 7") até a aprovação. A nota "O dono (ou o administrador) aprova...".' => 'Les demandes en attente (Quoi, Demandé le, Expire le, « Annuler »), combien d\'invitations il y a pour votre e-mail (« acceptez par le lien qui y est arrivé »), et le formulaire : Accès à (« une collection (le code de la collection) » ou « toutes les collections d\'un propriétaire (le code du propriétaire) »), Code (un nombre), le cadre replié « Comment demander l\'accès (et pourquoi par le code) » (une liste numérotée : pourquoi le code, comment demander le code au propriétaire et où il le trouve, quoi remplir, ce qui se passe ensuite), Mot pour le propriétaire et « Demander l\'accès ». Aucune liste de comptes ni de collections ; les demandes en attente ne montrent que le code (« la collection de code 7 ») jusqu\'à l\'approbation. La note « Le propriétaire (ou l\'administrateur) approuve... ».',
        'Seus dados' => 'Vos données',
        'Login, os selos master e demonstração, desde quando e "seu código: N" (o id, para pedirem acesso a todas as suas coleções), e a nota "Alguém quer ver as suas coleções? Passe o seu código..." (como passar o código e o que acontece depois); na demonstração, o aviso âmbar "Conta de demonstração: vence em N dias (data)..."; o formulário E-mail, Idioma (O da coleção e os seis), Senha atual (só para trocar a senha), Senha nova, a nota e "Salvar".' => 'Identifiant, les badges master et démonstration, depuis quand et « votre code : N » (l\'id, pour qu\'on demande l\'accès à toutes vos collections), et la note « Quelqu\'un veut voir vos collections ? Donnez-lui votre code... » (comment donner le code et ce qui se passe ensuite) ; en démonstration, l\'avis ambre « Compte de démonstration : expire dans N jours (date)... » ; le formulaire E-mail, Langue (Celle de la collection et les six), Mot de passe actuel (seulement pour changer le mot de passe), Nouveau mot de passe, la note et « Enregistrer ».',
        'Aplicativo no celular' => 'Application sur le téléphone',
        'A nota ("O sistema vira um aplicativo no seu celular ou tablet: um ícone na tela inicial, abrindo em tela cheia, entrando sem pedir a senha e recebendo as notificações. Três passos...") e a lista numerada: 1. Lembrar este aparelho (o botão, com o nome do aparelho montado do navegador: "Android Chrome", "iPhone Safari"; lembrado, "Este aparelho está lembrado desde DD/MM/AAAA: o aplicativo (e este navegador) entra sem pedir a senha." e "Esquecer este aparelho"); 2. Instalar (dentro do aplicativo, "Você já está no aplicativo."; com o pedido de instalação do navegador guardado pelo api.js (beforeinstallprompt), o botão "Instalar o aplicativo"; no iPhone e no iPad, o caminho do Safari (Compartilhar, Adicionar à Tela de Início); senão, o do menu do navegador); 3. Ligar as notificações (o link para o quadro Notificações neste aparelho; no iPhone, só de dentro do aplicativo). Embaixo, com algum, "Os aparelhos lembrados (trocar a senha esquece todos):" e a tabela Aparelho lembrado (com "(este)" no deste navegador), Desde, Último uso e "Esquecer".' => 'La note (« Le système devient une application sur votre téléphone ou votre tablette : une icône sur l\'écran d\'accueil, ouvrant en plein écran, entrant sans demander le mot de passe et recevant les notifications. Trois étapes... ») et la liste numérotée : 1. Mémoriser cet appareil (le bouton, avec le nom de l\'appareil construit depuis le navigateur : « Android Chrome », « iPhone Safari » ; mémorisé, « Cet appareil est mémorisé depuis JJ/MM/AAAA : l\'application (et ce navigateur) entre sans demander le mot de passe. » et « Oublier cet appareil ») ; 2. Installer (dans l\'application, « Vous êtes déjà dans l\'application. » ; avec la demande d\'installation du navigateur gardée par api.js (beforeinstallprompt), le bouton « Installer l\'application » ; sur l\'iPhone et l\'iPad, le chemin de Safari (Partager, Sur l\'écran d\'accueil) ; sinon celui du menu du navigateur) ; 3. Activer les notifications (le lien vers le cadre Notifications sur cet appareil ; sur l\'iPhone, seulement depuis l\'application). En dessous, s\'il y en a, « Les appareils mémorisés (changer le mot de passe les oublie tous) : » et le tableau Appareil mémorisé (avec « (celui-ci) » sur celui de ce navigateur), Depuis, Dernier usage et « Oublier ».',
        'Tokens de API' => 'Jetons d\'API',
        'A explicação (cabeçalho X-Api-Token; vale como o seu login; só aparece ao criar); o token recém-criado numa caixa tracejada em fonte fixa (para copiar); a tabela Nome, Criado em, Último uso e "Revogar"; o formulário com o nome ("onde vai usar") e "Criar token".' => 'L\'explication (en-tête X-Api-Token ; il vaut comme votre identifiant ; il n\'apparaît qu\'à la création) ; le jeton qui vient d\'être créé dans une boîte en pointillés en police fixe (pour le copier) ; le tableau Nom, Créé le, Dernière utilisation et « Révoquer » ; le formulaire avec le nom (« où vous allez l\'utiliser ») et « Créer un jeton ».',
        'Notificações neste aparelho (Web Push)' => 'Notifications sur cet appareil (Web Push)',
        'Sem as chaves no servidor, o aviso âmbar; sem suporte no navegador, a nota (no iPhone, adicionar à tela de início); senão "Receber notificações neste aparelho" (pede a permissão, registra o service worker (api.php?recurso=sw) e inscreve). A tabela dos aparelhos (Aparelho, Desde, "Desligar") e "Mandar uma notificação de teste". Para o master, "Chaves do Web Push (master)": "Gerar chaves" mostra as duas linhas para o config.php.' => 'Sans les clés sur le serveur, l\'avis ambre ; sans prise en charge par le navigateur, la note (sur l\'iPhone, ajouter à l\'écran d\'accueil) ; sinon « Recevoir les notifications sur cet appareil » (demande l\'autorisation, enregistre le service worker (api.php?recurso=sw) et s\'inscrit). Le tableau des appareils (Appareil, Depuis, « Désactiver ») et « Envoyer une notification de test ». Pour le master, « Clés du Web Push (master) » : « Générer les clés » montre les deux lignes pour le config.php.',
        'Servidor de e-mail (só o master)' => 'Serveur d\'e-mail (seulement le master)',
        'A nota (de onde o sistema tira o e-mail e para que ele serve), a tabela Parte | O que o sistema leu do config.php (Método: SMTP, mail() ou "desligado" em negrito; Remetente; SMTP (envio): host:porta, a segurança, o usuário, "senha definida" ou "sem senha"; IMAP (cópia em Enviados) e POP (só o teste da conta): o mesmo, ou "não configurado (opcional)"), o aviso âmbar "Para corrigir no config.php:" com a lista dos problemas (se houver) e, com o envio ligado, "Testar as conexões (sem mandar nada)", o formulário "para quem" + "Mandar um e-mail de teste" e a nota do que o teste faz. Depois de um teste, a página para nele: "Resultado do teste", cada parte (SMTP, IMAP, POP, E-mail de teste) com o selo "ok" (verde) ou "falhou" (vermelho) e o erro, e "Conversa com os servidores" aberta, em fonte fixa (o que vai com ">", o que volta com "<", a senha e o usuário em base64 trocados pela descrição).' => 'La note (d\'où le système tire l\'e-mail et à quoi il sert), le tableau Partie | Ce que le système a lu du config.php (Méthode : SMTP, mail() ou « désactivé » en gras ; Expéditeur ; SMTP (envoi) : host:port, la sécurité, l\'utilisateur, « mot de passe défini » ou « sans mot de passe » ; IMAP (copie dans Envoyés) et POP (seulement le test du compte) : la même chose, ou « non configuré (facultatif) »), l\'avis ambre « À corriger dans le config.php : » avec la liste des problèmes (s\'il y en a) et, avec l\'envoi activé, « Tester les connexions (sans rien envoyer) », le formulaire « à qui » + « Envoyer un e-mail de test » et la note sur ce que fait le test. Après un test, la page s\'arrête dessus : « Résultat du test », chaque partie (SMTP, IMAP, POP, E-mail de test) avec le badge « ok » (vert) ou « échec » (rouge) et l\'erreur, et « Conversation avec les serveurs » ouverte, en police fixe (ce qui part avec « > », ce qui revient avec « < », le mot de passe et l\'utilisateur en base64 remplacés par la description).',
        'Excluir a conta' => 'Supprimer le compte',
        'A explicação do que sai e "Excluir a minha conta" (botão vermelho; a API mostra tudo o que sai junto e pede a confirmação; depois, vai para o cadastro).' => 'L\'explication de ce qui part et « Supprimer mon compte » (bouton rouge ; l\'API montre tout ce qui part avec et demande la confirmation ; ensuite, elle va à l\'inscription).',
        'Aprovações e convites' => 'Approbations et invitations',
        'aprovacoes.php' => 'aprovacoes.php',
        'recurso=aprovacoes' => 'recurso=aprovacoes',
        'recurso=conta, parte=menu (o seu login)' => 'recurso=conta, parte=menu (votre identifiant)',
        'pedidos: aprovar, recusar' => 'pedidos: aprovar, recusar',
        'convites: convidar, aprovar, recusar, reenviar, cancelar' => 'convites: convidar, aprovar, recusar, reenviar, cancelar',
        'acessos: remover' => 'acessos: remover',
        'Tudo' => 'Tout',
        'h1 "Aprovações e convites". "Pedidos de acesso": Quem (o login e o e-mail), Pede, Recado, Vence em, "Aprovar" e "Recusar" (ou "Nenhum pedido esperando."). "Convites esperando a sua aprovação" (só quando há): E-mail, Quem convidou, Para, Vence em, "Aprovar e enviar", "Recusar". "Convidar": a explicação (o link vale N dias; quem não tem conta cria pelo link; o convite de um membro espera o dono), sem e-mail no servidor o aviso âmbar (o link aparece aqui, numa caixa para copiar), E-mail, Para ver (as coleções que você vê e "Tudo meu") e "Convidar". "Convites que você fez": E-mail, Para, Situação (enviado, esperando o dono), Vence em, "Reenviar" e "Cancelar". "Quem vê as suas coleções": Quem, Vê, Desde e "Tirar o acesso" (confirma) ou "Só você.".' => 'h1 « Approbations et invitations ». « Demandes d\'accès » : Qui (l\'identifiant et l\'e-mail), Demande, Mot, Expire le, « Approuver » et « Refuser » (ou « Aucune demande en attente. »). « Invitations qui attendent votre approbation » (seulement quand il y en a) : E-mail, Qui a invité, Pour, Expire le, « Approuver et envoyer », « Refuser ». « Inviter » : l\'explication (le lien vaut N jours ; qui n\'a pas de compte le crée par le lien ; l\'invitation d\'un membre attend le propriétaire), sans e-mail sur le serveur l\'avis ambre (le lien apparaît ici, dans une boîte à copier), E-mail, Pour voir (les collections que vous voyez et « Tout ce qui est à moi ») et « Inviter ». « Invitations que vous avez faites » : E-mail, Pour, Situation (envoyée, attend le propriétaire), Expire le, « Renvoyer » et « Annuler ». « Qui voit vos collections » : Qui, Voit, Depuis et « Retirer l\'accès » (confirme) ou « Vous seul. ».',
        'Criar conta' => 'Créer un compte',
        'cadastro.php; ?convite=<token> (o convite); ?senha=<token> (a senha nova)' => 'cadastro.php ; ?convite=<token> (l\'invitation) ; ?senha=<token> (le nouveau mot de passe)',
        'recurso=cadastro (sem login)' => 'recurso=cadastro (sans identifiant)',
        'cadastro: criar_conta, esqueci_senha, nova_senha' => 'cadastro: criar_conta, esqueci_senha, nova_senha',
        'A página pública: sem menu (só o idioma), sem login. Normal: h1 "Criar conta", o formulário Login (sem dois-pontos), Senha, E-mail (largo), Idioma, "Para começar" (Uma coleção minha, com o conjunto inicial; Uma coleção minha, vazia; Pedir acesso à coleção de alguém, que abre Acesso a, Código, o quadro "Como pedir acesso (e por que pelo código)" já aberto e Recado, como em Minha conta: pelo código que o dono passou, sem nenhuma lista de contas), a nota da demonstração ("A conta nova é de demonstração por N dias...") e "Criar conta"; "Já tem conta? Entrar"; e "Esqueci a senha" (o e-mail ou o login e "Mandar o link"; sem e-mail no servidor, a nota). Cadastro fechado: o aviso âmbar. Com convite: "Você foi convidado para ver <alvo>.", "Já tem conta? Entre e aceite o convite" (conta.php?convite=...) e, se o e-mail não tem conta, o formulário com o e-mail já preenchido e a caixa "Criar também uma coleção minha". Com o link da senha: "Senha nova" e "Trocar a senha". Depois de criar ou trocar: "Pronto", a mensagem e o botão "Entrar".' => 'La page publique : sans menu (seulement la langue), sans identifiant. Normale : h1 « Créer un compte », le formulaire Identifiant (sans deux-points), Mot de passe, E-mail (large), Langue, « Pour commencer » (Une collection à moi, avec l\'ensemble initial ; Une collection à moi, vide ; Demander l\'accès à la collection de quelqu\'un, ce qui ouvre Accès à, Code, le cadre « Comment demander l\'accès (et pourquoi par le code) » déjà ouvert et Mot, comme dans Mon compte : par le code donné par le propriétaire, sans aucune liste de comptes), la note de la démonstration (« Le nouveau compte est en démonstration pendant N jours... ») et « Créer un compte » ; « Vous avez déjà un compte ? Se connecter » ; et « Mot de passe oublié » (l\'e-mail ou l\'identifiant et « Envoyer le lien » ; sans e-mail sur le serveur, la note). Inscription fermée : l\'avis ambre. Avec invitation : « Vous avez été invité à voir <alvo>. », « Vous avez déjà un compte ? Connectez-vous et acceptez l\'invitation » (conta.php?convite=...) et, si l\'e-mail n\'a pas de compte, le formulaire avec l\'e-mail déjà rempli et la case « Créer aussi une collection à moi ». Avec le lien du mot de passe : « Nouveau mot de passe » et « Changer le mot de passe ». Après la création ou le changement : « C\'est fait », le message et le bouton « Se connecter ».',
        'Destinos' => 'Destinations',
        'destinos.php#destino-<id>' => 'destinos.php#destino-<id>',
        'recurso=destinos' => 'recurso=destinos',
        'destinos: salvar, testar, excluir' => 'destinos: salvar, testar, excluir',
        'h1 "Destinos das mensagens", os links "← Configuração" e "Agendas" e a explicação. Cada destino num cartão (id destino-<id>): Nome, Ligado, Idioma (O da coleção e os seis), o que é do tipo (o webhook: Método, Endereço, A mensagem vai (na URL, como formulário, como JSON), a tabela dos Campos com duas linhas vazias, o Corpo JSON, a tabela dos Cabeçalhos, com o valor escondido ("(guardado; vazio mantém)"); o e-mail: Para, e o aviso âmbar sem e-mail no servidor; o Web Push: Para os aparelhos de (quem vê a coleção), quantos aparelhos, o link para Minha conta, e o aviso âmbar sem as chaves), a Mensagem padrão com "Inserir âncora", "O que recebe" (a tabela Recebe, Aviso, Quando, Texto: a caixa de cada tipo e o "Personalizar" que abre o texto próprio com "Inserir âncora"), "Salvar", "Mandar um teste", "Mandar a da manhã agora", "Mandar a da noite agora", "Excluir", e "Como sai hoje" (De manhã, À noite, o texto em fonte fixa ou "(nada a enviar)"). No fim, "Novo destino": o tipo e o nome, "Criar".' => 'h1 « Destinations des messages », les liens « ← Configuration » et « Agendas » et l\'explication. Chaque destination dans une carte (id destino-<id>) : Nom, Active, Langue (Celle de la collection et les six), ce qui est propre au type (le webhook : Méthode, Adresse, Le message part (dans l\'URL, comme formulaire, comme JSON), le tableau des Champs avec deux lignes vides, le Corps JSON, le tableau des En-têtes, avec la valeur cachée (« (enregistré ; vide le conserve) ») ; l\'e-mail : Pour, et l\'avis ambre sans e-mail sur le serveur ; le Web Push : Pour les appareils de (qui voit la collection), combien d\'appareils, le lien vers Mon compte, et l\'avis ambre sans les clés), le Message par défaut avec « Insérer un repère », « Ce qu\'il reçoit » (le tableau Reçoit, Alerte, Quand, Texte : la case de chaque type et le « Personnaliser » qui ouvre le texte propre avec « Insérer un repère »), « Enregistrer », « Envoyer un test », « Envoyer celui du matin maintenant », « Envoyer celui du soir maintenant », « Supprimer », et « Ce qui part aujourd\'hui » (Le matin, Le soir, le texte en police fixe ou « (rien à envoyer) »). À la fin, « Nouvelle destination » : le type et le nom, « Créer ».',
        'Agendas' => 'Agendas',
        'agendas.php#agenda-<id>; ?recado=<texto> (a volta da Microsoft)' => 'agendas.php#agenda-<id> ; ?recado=<texto> (le retour de Microsoft)',
        'recurso=agendas' => 'recurso=agendas',
        'agendas: salvar, sincronizar, teste_criar, teste_remover, novo_link, outlook_conectar, excluir' => 'agendas: salvar, sincronizar, teste_criar, teste_remover, novo_link, outlook_conectar, excluir',
        'h1 "Agendas", os links "← Configuração" e "Destinos" e a explicação ("...O cron sincroniza de manhã e à noite; o link ICS o app de agenda lê quando quiser."). Cada agenda num cartão: Nome, Ligada, Eventos até quantos dias à frente, Idioma, o que é do tipo (Google: ID da agenda e a chave, o JSON colado; o caminho no servidor só o master; CalDAV: Endereço do calendário, Usuário, Senha, com a dica do Nextcloud, do iCloud e do Fastmail; Outlook: a conta conectada ou não, o calendário, "Conectar ao Outlook" (vai para a Microsoft e volta com o recado), e sem o aplicativo no servidor o aviso âmbar; link ICS: o link para assinar, com as dicas do Google, do Outlook e do iPhone, e "Trocar o link", que confirma), o Modelo do evento com "Inserir âncora" ("A primeira linha é o título do evento; o resto, a descrição."), "O que recebe", "Salvar", "Sincronizar agora", "Criar evento de teste" / "Remover evento de teste", "Excluir", e "O que tem de estar nela agora" (a data, a hora, o título e a descrição dos primeiros eventos, ou "Nada previsto no período."). No fim, "Nova agenda": o tipo e o nome, "Criar".' => 'h1 « Agendas », les liens « ← Configuration » et « Destinations » et l\'explication (« ...Le cron synchronise le matin et le soir ; le lien ICS, l\'application d\'agenda le lit quand elle veut. »). Chaque agenda dans une carte : Nom, Active, Événements jusqu\'à combien de jours à l\'avance, Langue, ce qui est propre au type (Google : ID de l\'agenda et la clé, le JSON collé ; le chemin sur le serveur seulement le master ; CalDAV : Adresse du calendrier, Utilisateur, Mot de passe, avec l\'astuce pour Nextcloud, iCloud et Fastmail ; Outlook : le compte connecté ou non, le calendrier, « Se connecter à Outlook » (va chez Microsoft et revient avec le message), et sans l\'application sur le serveur l\'avis ambre ; lien ICS : le lien pour s\'abonner, avec les astuces pour Google, Outlook et l\'iPhone, et « Changer le lien », qui confirme), le Modèle de l\'événement avec « Insérer un repère » (« La première ligne est le titre de l\'événement ; le reste, la description. »), « Ce qu\'il reçoit », « Enregistrer », « Synchroniser maintenant », « Créer un événement de test » / « Supprimer l\'événement de test », « Supprimer », et « Ce qui doit y être maintenant » (la date, l\'heure, le titre et la description des premiers événements, ou « Rien de prévu sur la période. »). À la fin, « Nouvel agenda » : le type et le nom, « Créer ».',
        'ajuda.php#<âncora>' => 'ajuda.php#<ancre>',
        'recurso=manual (o HTML e o sumário)' => 'recurso=manual (le HTML et le sommaire)',
        'h1 "Ajuda"; "Nesta página": o sumário com os títulos de nível 2 e 3 (recuados), cada um link para a sua âncora; depois o manual em HTML, com as tabelas que rolam de lado no celular, as imagens com borda e cantos, o código em fonte fixa. Abrindo com uma âncora no endereço, a página vai direto para ela.' => 'h1 « Aide » ; « Sur cette page » : le sommaire avec les titres de niveau 2 et 3 (en retrait), chacun lien vers son ancre ; ensuite le manuel en HTML, avec les tableaux qui défilent de côté sur le téléphone, les images avec bordure et coins, le code en police fixe. Ouvert avec une ancre dans l\'adresse, la page va directement à elle.',
        'a página Hoje no computador, com o painel ao lado' => 'la page Aujourd\'hui sur l\'ordinateur, avec le panneau à côté',
        'a tabela dos relógios com as 12 colunas e os filtros' => 'le tableau des montres avec les 12 colonnes et les filtres',
        'o histórico de um relógio' => 'l\'historique d\'une montre',
        'a aba Campos dos Cadastros' => 'l\'onglet Champs des Définitions',
        'no celular: a Hoje, os cartões dos relógios e o painel em tela cheia' => 'sur le téléphone : Aujourd\'hui, les cartes des montres et le panneau en plein écran',
        'a base de todas as páginas: topo() (antes de tudo, o login: pagina_login(); depois o head, o menu e o título) e rodape() (os scripts, com a data do arquivo na URL)' => 'la base de toutes les pages : topo() (avant tout, la connexion : pagina_login() ; ensuite le head, le menu et le titre) et rodape() (les scripts, avec la date du fichier dans l\'URL)',
        'o estilo de todas as páginas: as cores, as letras, os controles, os componentes e os tamanhos de tela' => 'le style de toutes les pages : les couleurs, les caractères, les contrôles, les composants et les tailles d\'écran',
        'a base do JavaScript das páginas: os textos no idioma (t(), com o dicionário de recurso=textos), ler e gravar pela API, os formatos do idioma (número, dinheiro, data, hora), o login, os formulários que gravam, as tabelas que viram fichas no celular' => 'la base du JavaScript des pages : les textes dans la langue (t(), avec le dictionnaire de recurso=textos), lire et enregistrer par l\'API, les formats de la langue (nombre, argent, date, heure), l\'identifiant, les formulaires qui enregistrent, les tableaux qui deviennent des fiches sur le téléphone',
        'os idiomas: a lista (LINGUAS: o nome, o código curto do menu, o locale e os formatos da data e dos números), o idioma do pedido, t() e os formatos no PHP' => 'les langues : la liste (LINGUAS : le nom, le code court du menu, le locale et les formats de la date et des nombres), la langue de la requête, t() et les formats en PHP',
        'o arquivo de um idioma (en, zh-CN, hi, es, fr): o texto em português => a tradução, por parte (telas, api, ajuda, manual, reconstrucao), gerado e conferido por testes/textos.php; o que falta sai em português, ou para com erro no modo estrito (TEXTOS_ESTRITO)' => 'le fichier d\'une langue (en, zh-CN, hi, es, fr) : le texte en portugais => la traduction, par partie (telas, api, ajuda, manual, reconstrucao), généré et vérifié par testes/textos.php ; ce qui manque sort en portugais, ou s\'arrête avec une erreur en mode strict (TEXTOS_ESTRITO)',
        'o esqueleto da página Hoje (o meio, a tabela dos relógios com os títulos e os filtros, e o painel)' => 'le squelette de la page Aujourd\'hui (le milieu, le tableau des montres avec les titres et les filtres, et le panneau)',
        'a página Hoje: o relógio do dia, os avisos de hoje, os próximos dias, o modo de rodízio e as linhas da tabela dos relógios' => 'la page Aujourd\'hui : la montre du jour, les alertes d\'aujourd\'hui, les prochains jours, le mode de rotation et les lignes du tableau des montres',
        'a tabela dos relógios: ordenar, filtrar e virar cartões quando as 12 colunas não cabem' => 'le tableau des montres : trier, filtrer et devenir des cartes quand les 12 colonnes ne tiennent pas',
        'o painel do relógio (na página Hoje e na Ficha): os quadros, o Marcar, o Editar cadastro, o gráfico da carga, os dados e o histórico' => 'le panneau de la montre (sur la page Aujourd\'hui et sur la Fiche) : les cadres, Marquer, Modifier la fiche, le graphique de la charge, les données et l\'historique',
        'a foto reduzida no navegador antes de enviar (1200 px, JPEG 85%), com a prévia' => 'la photo réduite dans le navigateur avant l\'envoi (1200 px, JPEG 85 %), avec l\'aperçu',
        'a página Ficha do relógio: o painel do relógio numa página própria' => 'la page Fiche de la montre : le panneau de la montre sur une page propre',
        'o esqueleto da página Plano' => 'le squelette de la page Plan',
        'a página Plano: o resumo do período e o dia a dia, mês a mês' => 'la page Plan : le résumé de la période et le jour par jour, mois par mois',
        'o esqueleto da página Configuração' => 'le squelette de la page Configuration',
        'a página Configuração: o banco desatualizado, os quadros das opções, o resumo dos avisos e das mensagens (o caminho para a página Avisos) e a cópia de segurança' => 'la page Configuration : la base pas à jour, les cadres des options, le résumé des alertes et des messages (le chemin vers la page Alertes) et la sauvegarde',
        'o esqueleto da página Avisos' => 'le squelette de la page Alertes',
        'a página Avisos: os avisos dos relógios (o cadastro), os lembretes (os eventos personalizados) e para onde vão (os destinos e as agendas)' => 'la page Alertes : les alertes des montres (la définition), les rappels (les événements personnalisés) et où ils vont (les destinations et les agendas)',
        'o esqueleto da página Critérios' => 'le squelette de la page Critères',
        'a página Critérios: as explicações, os lugares, os parâmetros, os subparâmetros, as faixas e a nota de cada relógio' => 'la page Critères : les explications, les endroits, les paramètres, les sous-paramètres, les tranches et la note de chaque montre',
        'o esqueleto da página Grupos' => 'le squelette de la page Groupes',
        'a página Grupos: a árvore e o grupo de cada relógio' => 'la page Groupes : l\'arbre et le groupe de chaque montre',
        'o esqueleto da página Execuções do cron' => 'le squelette de la page Exécutions du cron',
        'a página Execuções do cron: os filtros, o resumo, a tabela e a paginação' => 'la page Exécutions du cron : les filtres, le résumé, le tableau et la pagination',
        'o esqueleto da página Desejos' => 'le squelette de la page Envies',
        'a página Desejos: a lista de desejos (com o Comprei) e os relógios fora da coleção' => 'la page Envies : la liste d\'envies (avec Achetée) et les montres hors de la collection',
        'o esqueleto da página Estatísticas' => 'le squelette de la page Statistiques',
        'o esqueleto da página Hora certa' => 'le squelette de la page Heure exacte',
        'o esqueleto da página Acessórios' => 'le squelette de la page Accessoires',
        'o esqueleto da página Galeria' => 'le squelette de la page Galerie',
        'a página Galeria: a coleção em fotos, por grupo, para ver e imprimir' => 'la page Galerie : la collection en photos, par groupe, pour voir et imprimer',
        'o esqueleto da página Passaporte do relógio' => 'le squelette de la page Passeport de la montre',
        'a página Passaporte: a ficha de um relógio para imprimir ou guardar em PDF' => 'la page Passeport : la fiche d\'une montre à imprimer ou à garder en PDF',
        'a página Acessórios: o filtro por relógio, a lista com Editar e Excluir e o cadastro' => 'la page Accessoires : le filtre par montre, la liste avec Modifier et Supprimer et la fiche',
        'a página Hora certa: o mostrador e a hora digital andando, acertados pela API, e os quadros do fuso, do calendário e da lua' => 'la page Heure exacte : le cadran et l\'heure numérique qui avancent, réglés par l\'API, et les cadres du fuseau, du calendrier et de la lune',
        'a página Estatísticas: o período, o resumo, cada relógio, os gráficos em SVG e a coleção' => 'la page Statistiques : la période, le résumé, chaque montre, les graphiques en SVG et la collection',
        'o esqueleto da página Histórico' => 'le squelette de la page Historique',
        'a página Histórico de um relógio: os filtros, o resumo do tempo e a linha do tempo' => 'la page Historique d\'une montre : les filtres, le résumé du temps et la chronologie',
        'o esqueleto da página Documentos' => 'le squelette de la page Documents',
        'a página Documentos: o envio, as abas, a galeria com o visor, os vídeos, os PDFs, as NF-e e a edição' => 'la page Documents : l\'envoi, les onglets, la galerie avec la visionneuse, les vidéos, les PDF, les NF-e et la modification',
        'o esqueleto da página Cadastros' => 'le squelette de la page Définitions',
        'a página Cadastros: as abas Campos, Tipos de lançamento, Fórmulas e Categorias de documentos (os avisos ficam na página Avisos; os modos, na página Modos de rodízio)' => 'la page Définitions : les onglets Champs, Types de saisie, Formules et Catégories de documents (les alertes sont dans la page Alertes ; les modes, dans la page Modes de rotation)',
        'o esqueleto da página Modos de rodízio' => 'le squelette de la page Modes de rotation',
        'a página Modos de rodízio: os modos da coleção, com os blocos de cada um, o ativo e o formulário' => 'la page Modes de rotation : les modes de la collection, avec les blocs de chacun, l\'actif et le formulaire',
        'o esqueleto da página Usuários' => 'le squelette de la page Utilisateurs',
        'a página Usuários: o painel do master (cada conta com o que tem e as ações: ver como, oficializar, prorrogar, voltar a demo, bloquear, alterar, trocar a senha, transferir, dar acesso, excluir) e criar conta' => 'la page Utilisateurs : le panneau du master (chaque compte avec ce qu\'il a et les actions : voir en tant que, rendre officiel, prolonger, revenir en démo, bloquer, modifier, changer le mot de passe, transférer, donner l\'accès, supprimer) et créer un compte',
        'o esqueleto da página Minha conta' => 'le squelette de la page Mon compte',
        'a página Minha conta: as coleções, as árvores, pedir acesso, os dados, os tokens, as notificações deste aparelho, o servidor de e-mail (master) e excluir a conta' => 'la page Mon compte : les collections, les arbres, demander l\'accès, les données, les jetons, les notifications de cet appareil, le serveur d\'e-mail (master) et supprimer le compte',
        'o esqueleto da página Aprovações' => 'le squelette de la page Approbations',
        'a página Aprovações: os pedidos, os convites a aprovar, convidar, os convites feitos e quem vê as suas coleções' => 'la page Approbations : les demandes, les invitations à approuver, inviter, les invitations faites et qui voit vos collections',
        'o esqueleto da página pública Criar conta (sem menu, sem login)' => 'le squelette de la page publique Créer un compte (sans menu, sans identifiant)',
        'a página Criar conta: o cadastro aberto, o convite, o esqueci a senha e a senha nova' => 'la page Créer un compte : l\'inscription ouverte, l\'invitation, le mot de passe oublié et le nouveau mot de passe',
        'o esqueleto da página Destinos' => 'le squelette de la page Destinations',
        'a página Destinos: cada destino das mensagens (webhook, e-mail, Web Push), o que recebe, o teste e como sai hoje' => 'la page Destinations : chaque destination des messages (webhook, e-mail, Web Push), ce qu\'elle reçoit, le test et ce qui part aujourd\'hui',
        'o esqueleto da página Agendas' => 'le squelette de la page Agendas',
        'a página Agendas: cada agenda (Google, CalDAV, Outlook, link ICS), o que recebe, a sincronização, o evento de teste e o que tem de estar nela' => 'la page Agendas : chaque agenda (Google, CalDAV, Outlook, lien ICS), ce qu\'elle reçoit, la synchronisation, l\'événement de test et ce qui doit y être',
        'o service worker do aplicativo no celular (PWA), entregue por api.php?recurso=sw com a versão e a lista dos arquivos na frente: guarda os arquivos das telas (nunca a API), entrega a página sem conexão quando a rede cai e mostra as notificações do Web Push (no clique, abre o sistema)' => 'le service worker de l\'application sur le téléphone (PWA), servi par api.php?recurso=sw avec la version et la liste des fichiers devant : garde les fichiers des écrans (jamais l\'API), sert la page sans connexion quand le réseau tombe et affiche les notifications du Web Push (au clic, ouvre le système)',
        'a página "sem conexão" do aplicativo (estática, nos seis idiomas): o service worker a entrega quando a rede cai' => 'la page « sans connexion » de l\'application (statique, dans les six langues) : le service worker la sert quand le réseau tombe',
        'o ícone do aplicativo (192 px: o manifesto, o favicon e as notificações)' => 'l\'icône de l\'application (192 px : le manifeste, le favicon et les notifications)',
        'o ícone do aplicativo (512 px: o manifesto, também como maskable)' => 'l\'icône de l\'application (512 px : le manifeste, aussi en maskable)',
        'o ícone do aplicativo no iPhone (o apple-touch-icon)' => 'l\'icône de l\'application sur l\'iPhone (l\'apple-touch-icon)',
        'o esqueleto da página Ajuda' => 'le squelette de la page Aide',
        'a página Ajuda: o sumário e o manual em HTML (recurso=manual)' => 'la page Aide : le sommaire et le manuel en HTML (recurso=manual)',
        'a API, a porta única: a autenticação, o formato, a ordem dos recursos (cada um no seu arquivo da pasta api/, ou ali mesmo, os pequenos), os filtros, o JSON e o XML, e no cabeçalho a documentação inteira' => 'l\'API, la porte unique : l\'authentification, le format, l\'ordre des ressources (chacune dans son fichier du dossier api/, ou là même, les petites), les filtres, le JSON et le XML, et dans l\'en-tête la documentation entière',
        'as funções que só a API usa (o XML, os textos legíveis do tempo, do plano, dos eventos e da agenda, os filtros das listas e a resposta) e o tratamento dos erros' => 'les fonctions que seule l\'API utilise (le XML, les textes lisibles du temps, du plan, des événements et de l\'agenda, les filtres des listes et la réponse) et le traitement des erreurs',
        'api.php sem recurso: tudo o que está guardado' => 'api.php sans ressource : tout ce qui est conservé',
        'recurso=hoje: tudo o que a página Hoje mostra' => 'recurso=hoje : tout ce que montre la page Aujourd\'hui',
        'recurso=ficha: tudo o que o painel de um relógio mostra (ou o cadastro de um novo)' => 'recurso=ficha : tout ce que montre le panneau d\'une montre (ou la fiche d\'une nouvelle)',
        'recurso=config: a Configuração inteira' => 'recurso=config : la Configuration entière',
        'recurso=destinos: os destinos das mensagens da coleção, o que cada um recebe e a prévia de hoje' => 'recurso=destinos : les destinations des messages de la collection, ce que chacune reçoit et l\'aperçu du jour',
        'recurso=agendas: as agendas da coleção, o que cada uma recebe e o que tem de estar nela agora' => 'recurso=agendas : les agendas de la collection, ce que chacune reçoit et ce qui doit y être maintenant',
        'recurso=desejos: a lista de desejos e os relógios fora da coleção' => 'recurso=desejos : la liste d\'envies et les montres hors de la collection',
        'recurso=passaporte: a ficha de um relógio para imprimir, tudo já em texto' => 'recurso=passaporte : la fiche d\'une montre à imprimer, tout déjà en texte',
        'recurso=galeria: a coleção em fotos, por grupo' => 'recurso=galeria : la collection en photos, par groupe',
        'recurso=hora_certa: a hora do servidor, o fuso, o UTC, a letra militar, o calendário e a lua (sem banco)' => 'recurso=hora_certa : l\'heure du serveur, le fuseau, l\'UTC, la lettre militaire, le calendrier et la lune (sans base)',
        'recurso=estatisticas: o uso da coleção num período, por relógio, dia da semana e mês, e a distribuição da coleção' => 'recurso=estatisticas : l\'usage de la collection sur une période, par montre, jour de la semaine et mois, et la répartition de la collection',
        'recurso=historico: a linha do tempo de um relógio, com os filtros e o resumo' => 'recurso=historico : la chronologie d\'une montre, avec les filtres et le résumé',
        'recurso=plano: o plano dia a dia, o resumo por relógio e as páginas' => 'recurso=plano : le plan jour par jour, le résumé par montre et les pages',
        'recurso=cron: as execuções do cron, com os filtros, o resumo e as páginas' => 'recurso=cron : les exécutions du cron, avec les filtres, le résumé et les pages',
        'recurso=arvore: a árvore dos grupos e o grupo de cada relógio' => 'recurso=arvore : l\'arbre des groupes et le groupe de chaque montre',
        'recurso=cadastros: os campos, os tipos de lançamento, as fórmulas, os avisos, os modos e as categorias' => 'recurso=cadastros : les champs, les types de saisie, les formules, les alertes, les modes et les catégories',
        'recurso=calcular: o resultado de uma fórmula para um relógio (ou para todos)' => 'recurso=calcular : le résultat d\'une formule pour une montre (ou pour toutes)',
        'recurso=documentos: os documentos de um relógio (ou de todos), as categorias e o limite' => 'recurso=documentos : les documents d\'une montre (ou de toutes), les catégories et la limite',
        'recurso=documento: um arquivo de um documento (o original, a miniatura, a página de um PDF)' => 'recurso=documento : un fichier d\'un document (l\'original, la miniature, la page d\'un PDF)',
        'recurso=backup: as cópias de segurança da pasta, e uma cópia para baixar (arquivo=)' => 'recurso=backup : les sauvegardes du dossier, et une copie à télécharger (arquivo=)',
        'recurso=migracoes: as migrações pendentes do banco (a leitura) e aplicar (a escrita)' => 'recurso=migracoes : les migrations en attente de la base (la lecture) et appliquer (l\'écriture)',
        'recurso=codigo: o código do sistema como está agora, arquivo por arquivo' => 'recurso=codigo : le code du système tel qu\'il est maintenant, fichier par fichier',
        'recurso=ajuda: a documentação da API (cada consulta, cada escrita e o dicionário dos campos, a fonte única dele)' => 'recurso=ajuda : la documentation de l\'API (chaque consultation, chaque écriture et le dictionnaire des champs, sa source unique)',
        'as escritas (POST): cada recurso e ação vai para a função dele no operacoes.php, que valida, grava e responde' => 'les écritures (POST) : chaque ressource et action va vers sa fonction dans operacoes.php, qui valide, enregistre et répond',
        'o núcleo: o token, o login, a árvore, os campos, os lançamentos, o motor das fórmulas, os avisos, os critérios, o rodízio, a escala e as listas do código' => 'le noyau : le jeton, l\'identifiant, l\'arbre, les champs, les saisies, le moteur des formules, les alertes, les critères, la rotation, le planning et les listes du code',
        'as escritas: cada ação valida, grava e devolve ok, mensagem e erros (a API chama estas funções)' => 'les écritures : chaque action valide, enregistre et renvoie ok, message et erreurs (l\'API appelle ces fonctions)',
        'as coleções no núcleo: a coleção do pedido, os ids da raiz, o modelo.json (a árvore e a coleção novas), os segredos cifrados, a tabela sistema, a migração v25, o usuário do pedido, as coleções que cada um vê, excluir com os arquivos, a limpeza das contas e o impacto das exclusões' => 'les collections dans le noyau : la collection de la requête, les ids de la racine, le modelo.json (le nouvel arbre et la nouvelle collection), les secrets chiffrés, la table sistema, la migration v25, l\'utilisateur de la requête, les collections que chacun voit, supprimer avec les fichiers, le nettoyage des comptes et l\'impact des suppressions',
        'os alertas: o pedido HTTP (e a conferência dos endereços de fora), os destinos (webhook, e-mail por SMTP/IMAP/POP, Web Push com VAPID), as mensagens da manhã e da noite, as agendas (Google, CalDAV, Outlook, o link ICS) e a sincronização' => 'les alertes : la requête HTTP (et la vérification des adresses extérieures), les destinations (webhook, e-mail par SMTP/IMAP/POP, Web Push avec VAPID), les messages du matin et du soir, les agendas (Google, CalDAV, Outlook, le lien ICS) et la synchronisation',
        'as contas: o cadastro aberto, Minha conta, as coleções e as árvores (copiar, transferir), os acessos, os convites, os pedidos, os tokens pessoais, o Vendo como e o painel do master' => 'les comptes : l\'inscription ouverte, Mon compte, les collections et les arbres (copier, transférer), les accès, les invitations, les demandes, les jetons personnels, le Vue en tant que et le panneau du master',
        'o conjunto inicial de uma coleção nova, sem códigos fixos (os grupos por apelido): os grupos, os campos, os tipos, as fórmulas, os avisos, os critérios, as categorias, os modos, a configuração e as mensagens padrão, em português' => 'l\'ensemble initial d\'une nouvelle collection, sans codes fixes (les groupes par surnom) : les groupes, les champs, les types, les formules, les alertes, les critères, les catégories, les modes, la configuration et les messages par défaut, en portugais',
        'o banco: MySQL/MariaDB, PostgreSQL, SQLite ou Firebird, o SQL escrito uma vez só e traduzido para cada um, e o catálogo do modelo' => 'la base : MySQL/MariaDB, PostgreSQL, SQLite ou Firebird, le SQL écrit une seule fois et traduit pour chacune, et le catalogue du modèle',
        'a reconstrução (recurso=reconstrucao): as regras de cada parte, a especificação das telas e esta lista do código' => 'la reconstruction (recurso=reconstrucao) : les règles de chaque partie, la spécification des écrans et cette liste du code',
        'o cron, a cada minuto: as mensagens, o pulso sozinho, a agenda, a manutenção dos documentos, sempre mudo e registrado no banco' => 'le cron, chaque minute : les messages, le poignet tout seul, l\'agenda, l\'entretien des documents, toujours silencieux et consigné dans la base',
        'a instalação pelo servidor (a mesma do POST recurso=instalacao)' => 'l\'installation par le serveur (la même que le POST recurso=instalacao)',
        'a importação do sistema antigo pelo servidor (a mesma do POST recurso=importacao)' => 'l\'importation de l\'ancien système par le serveur (la même que le POST recurso=importacao)',
        'criar um usuário ou trocar a senha pelo servidor (o mesmo do POST recurso=usuarios, acao=salvar)' => 'créer un utilisateur ou changer le mot de passe par le serveur (le même que le POST recurso=usuarios, acao=salvar)',
        'a estrutura do banco (no dialeto do MySQL, traduzida para os outros): as tabelas, as chaves e as regras, sem dados' => 'la structure de la base (dans le dialecte de MySQL, traduite pour les autres) : les tables, les clés et les règles, sans données',
        'o modelo do config.php, com cada constante explicada (o config.php de verdade não sai: veja nao_mostrados)' => 'le modèle de config.php, avec chaque constante expliquée (le vrai config.php ne sort pas : voir nao_mostrados)',
        'o Apache: o que abre pelo navegador e o que fica bloqueado' => 'Apache : ce qui s\'ouvre par le navigateur et ce qui reste bloqué',
        'o nginx: o mesmo bloqueio do .htaccess' => 'nginx : le même blocage que le .htaccess',
        'o roteiro de aceitação: faz pela API o que uma pessoa faz e tira a fotografia de tudo o que a API devolve' => 'le scénario de recette : il fait par l\'API ce qu\'une personne fait et prend la photographie de tout ce que l\'API renvoie',
        'compara duas fotografias do cenário (os quatro bancos, ou a reescrita com a versão atual)' => 'compare deux photographies du scénario (les quatre bases de données, ou la réécriture avec la version actuelle)',
        'o teste de paridade com um comando: os quatro bancos ao mesmo tempo, numa pasta temporária, e a comparação' => 'le test de parité avec une commande : les quatre bases de données en même temps, dans un dossier temporaire, et la comparaison',
        'o config dos testes (o acesso aos bancos pelo ambiente), apontado por RELOGIOS_CONFIG: o config.php de verdade fica intocado' => 'le config des tests (l\'accès aux bases de données par l\'environnement), indiqué par RELOGIOS_CONFIG : le vrai config.php reste intact',
        'gera o dicionário dos campos do cabeçalho do api.php a partir do da ajuda (a fonte única), e confere que batem' => 'génère le dictionnaire des champs de l\'en-tête de api.php à partir de celui de l\'aide (la source unique), et vérifie qu\'ils correspondent',
        'confere que todo campo das respostas da API está explicado no dicionário da ajuda' => 'vérifie que tout champ des réponses de l\'API est expliqué dans le dictionnaire de l\'aide',
        'confere que uma conta não vê nem muda o que é de outra pelo token pessoal (todos os recursos, com os ids da outra) e que o pedido de acesso pelo código não mostra login nem nome de coleção' => 'vérifie qu\'un compte ne voit ni ne modifie ce qui appartient à un autre par le jeton personnel (toutes les ressources, avec les ids de l\'autre) et que la demande d\'accès par code ne montre ni identifiant ni nom de collection',
        'a conferência do layout: todas as telas num navegador, em 15 tamanhos, com dados de estresse, procurando o que quebra' => 'la vérification de la mise en page : tous les écrans dans un navigateur, en 15 tailles, avec des données de stress, à la recherche de ce qui casse',
        'como rodar o teste de paridade e a conferência do layout' => 'comment lancer le test de parité et la vérification de la mise en page',
        'o manual inteiro: para quem usa, a instalação, a API e como é por dentro' => 'le manuel entier : pour qui utilise le système, l\'installation, l\'API et comment c\'est fait à l\'intérieur',
        'o que o sistema antigo fazia e onde está no novo' => 'ce que faisait l\'ancien système et où cela se trouve dans le nouveau',
        'a licença' => 'la licence',
        'o que nunca entra no repositório (a configuração, as chaves, os bancos)' => 'ce qui n\'entre jamais dans le dépôt (la configuration, les clés, les bases de données)',
        'as quebras de linha (LF em tudo) e os binários' => 'les fins de ligne (LF partout) et les binaires',
        'os testes no GitHub a cada push no main: a paridade nos bancos (com a documentação da API) e o layout das telas' => 'les tests sur GitHub à chaque push sur main : la parité sur les bases de données (avec la documentation de l\'API) et la mise en page des écrans',
        'confere os dicionários dos idiomas com o código (o texto que falta, o que sobra, o parâmetro diferente) e a origem de cada manual traduzido; junta traduções novas (--juntar)' => 'compare les dictionnaires des langues au code (le texte qui manque, celui en trop, le paramètre différent) et l\'origine de chaque manuel traduit ; fusionne les nouvelles traductions (--juntar)',
        'a conferência da arquitetura: as páginas sem banco, a rede das telas só pela API, o banco só no núcleo, na API e no cron, os scripts de linha de comando como atalhos da API, a guarda do api/, o bloqueio pela web, a API e o config.php documentados, as migrações e o repositório' => 'la vérification de l\'architecture : les pages sans base, le réseau des écrans seulement par l\'API, la base seulement dans le noyau, l\'API et le cron, les scripts en ligne de commande comme raccourcis de l\'API, la garde de api/, le blocage par le web, l\'API et le config.php documentés, les migrations et le dépôt',
        'monta o README de cada idioma (README.<idioma>.md) a partir do manual traduzido e do resto traduzido, e confere que estão em dia (--conferir)' => 'assemble le README de chaque langue (README.<idioma>.md) à partir du manuel traduit et du reste traduit, et vérifie qu\'ils sont à jour (--conferir)',
        'o dicionário do idioma {1}: o texto em português => a tradução, por parte (telas, api, cadastro, ajuda, reconstrucao)' => 'le dictionnaire de la langue {1} : le texte en portugais => la traduction, par partie (telas, api, cadastro, ajuda, reconstrucao)',
        'o manual da página Ajuda no idioma {1} (as seções do README para quem usa), com a origem na primeira linha' => 'le manuel de la page Aide dans la langue {1} (les sections du README pour les utilisateurs), avec l\'origine sur la première ligne',
        'o resto do README no idioma {1} (o que não está no manual), com a origem na primeira linha' => 'le reste du README dans la langue {1} (ce qui n\'est pas dans le manuel), avec l\'origine sur la première ligne',
        'o README no idioma {1}, montado por testes/readme.php (não editar à mão)' => 'le README dans la langue {1}, assemblé par testes/readme.php (ne pas modifier à la main)',
        'tem as senhas do banco e o API_TOKEN' => 'contient les mots de passe de la base de données et l\'API_TOKEN',
        'o config.exemplo.php (o modelo, com cada constante explicada) e listas.config_php no recurso=reconstrucao' => 'le config.exemplo.php (le modèle, avec chaque constante expliquée) et listas.config_php dans recurso=reconstrucao',
        'a chave JSON do Google (google-conta-servico.json ou o caminho da Configuração)' => 'la clé JSON de Google (google-conta-servico.json ou le chemin de la Configuration)',
        'é uma credencial' => 'c\'est un identifiant d\'authentification',
        'a seção mensagens do recurso=reconstrucao e o README (Google Agenda): como criar a conta de serviço e a chave' => 'la section messages de recurso=reconstrucao et le README (Google Agenda) : comment créer le compte de service et la clé',
        'o banco de dados (o servidor MySQL/PostgreSQL/Firebird, ou o arquivo do SQLite)' => 'la base de données (le serveur MySQL/PostgreSQL/Firebird, ou le fichier de SQLite)',
        'são os dados, não o código' => 'ce sont les données, pas le code',
        'o modelo em modelo_de_dados (recurso=reconstrucao) e os dados pela própria API (api.php sem recurso: tudo o que está guardado)' => 'le modèle dans modelo_de_dados (recurso=reconstrucao) et les données par l\'API elle-même (api.php sans recurso : tout ce qui est gardé)',
        'a pasta dos documentos (DOCUMENTOS_PASTA)' => 'le dossier des documents (DOCUMENTOS_PASTA)',
        'são os arquivos de cada relógio, não o código' => 'ce sont les fichiers de chaque montre, pas le code',
        'recurso=documentos (a lista) e recurso=documento (cada arquivo)' => 'recurso=documentos (la liste) et recurso=documento (chaque fichier)',
        'as senhas dos usuários' => 'les mots de passe des utilisateurs',
        'não existem no sistema: só o hash' => 'ils n\'existent pas dans le système : seulement le hash',
        'recurso=usuarios (o login e o hash) e senhas na ajuda (como conferir e migrar)' => 'recurso=usuarios (l\'identifiant et le hash) et senhas dans l\'aide (comment vérifier et migrer)',
        'a migração ' => 'la migration ',
        'a captura de tela: ' => 'la capture d\'écran : ',
        'text/plain; charset=utf-8' => 'text/plain; charset=utf-8',
        'O código do sistema como está agora, lido do disco na hora: cada arquivo com a camada, o que ele é, o tamanho e o SHA-256. Um arquivo: arquivo=<nome> (o conteúdo como está, em conteudo; a imagem em conteudo_base64); com cru=1, o arquivo puro, sem JSON (texto como text/plain, para ler no navegador). Numa página, html traz o HTML que o navegador recebe, já montado (html=1 com cru=1: só ele), e usa, os arquivos que ela carrega. Todos de uma vez: conteudo=1 (com os filtros: f[arquivos][camada]=tela traz o HTML, o CSS e o JavaScript das telas). O que fica de fora de propósito está em nao_mostrados, com o que ver no lugar.' => 'Le code du système tel qu\'il est maintenant, lu sur le disque au moment même : chaque fichier avec la couche, ce qu\'il est, la taille et le SHA-256. Un fichier : arquivo=<nom> (le contenu tel quel, dans conteudo ; l\'image dans conteudo_base64) ; avec cru=1, le fichier pur, sans JSON (texte en text/plain, pour le lire dans le navigateur). Pour une page, html apporte le HTML que le navigateur reçoit, déjà monté (html=1 avec cru=1 : lui seul), et usa, les fichiers qu\'elle charge. Tous d\'un coup : conteudo=1 (avec les filtres : f[arquivos][camada]=tela apporte le HTML, le CSS et le JavaScript des écrans). Ce qui reste dehors exprès est dans nao_mostrados, avec quoi voir à la place.',
        'as páginas: o esqueleto em PHP, o estilo e o JavaScript que lê a API e monta a tela' => 'les pages : le squelette en PHP, le style et le JavaScript qui lit l\'API et monte l\'écran',
        'o back-end: a API e o que ela usa (o núcleo, as escritas, o banco, a reconstrução)' => 'le back-end : l\'API et ce qu\'elle utilise (le noyau, les écritures, la base de données, la reconstruction)',
        'o cron e os scripts do servidor' => 'le cron et les scripts du serveur',
        'o banco inicial e as migrações' => 'la base de données initiale et les migrations',
        'a configuração do servidor web e o modelo do config.php' => 'la configuration du serveur web et le modèle du config.php',
        'o roteiro de aceitação e a comparação' => 'le scénario de recette et la comparaison',
        'o README e os outros textos' => 'le README et les autres textes',
        'os arquivos do git' => 'les fichiers de git',
        'as capturas das telas' => 'les captures des écrans',
        ' ou mais' => ' ou plus',
        'O Relojoeiro (Relógios 2) planeja o rodízio de uma coleção de relógios: escolhe o relógio de cada dia pela nota de cada um (critérios com pesos) e pelas regras do modo de rodízio, acompanha a energia de cada um (bateria, reserva de marcha, carga de luz, vida da pilha) pelas fórmulas do cadastro e pelo histórico de lançamentos, avisa o que fazer (carregar, dar corda, pôr no sol, trocar a pilha, revisão) pelos destinos das mensagens (Telegram e outros webhooks, e-mail, Web Push) e pelas agendas (Google, CalDAV, Outlook, link ICS), mede o gasto real da bateria pelas leituras e guarda os documentos de cada relógio. Esta resposta é o roteiro para reescrever o sistema inteiro do zero e chegar ao mesmo comportamento. Várias pessoas usam o mesmo sistema: cada conta tem as suas coleções (cada uma com os relógios, o histórico, o plano, as mensagens e as agendas), numa árvore de grupos que pode servir a várias coleções do mesmo dono, e pode ver as coleções de outros, por convite ou por pedido aprovado.' => 'Le Relojoeiro (Relógios 2) planifie la rotation d\'une collection de montres : il choisit la montre de chaque jour selon la note de chacune (critères pondérés) et les règles du mode de rotation, suit l\'énergie de chacune (batterie, réserve de marche, charge lumineuse, durée de vie de la pile) par les formules des définitions et l\'historique des saisies, avertit de ce qu\'il faut faire (charger, remonter, mettre au soleil, changer la pile, révision) par les destinations des messages (Telegram et autres webhooks, e-mail, Web Push) et par les agendas (Google, CalDAV, Outlook, lien ICS), mesure la dépense réelle de la batterie par les lectures et garde les documents de chaque montre. Cette réponse est la feuille de route pour réécrire tout le système depuis zéro et arriver au même comportement. Plusieurs personnes utilisent le même système : chaque compte a ses collections (chacune avec les montres, l\'historique, le plan, les messages et les agendas), dans un arbre de groupes qui peut servir à plusieurs collections du même propriétaire, et peut voir les collections des autres, sur invitation ou par demande approuvée.',
        'Leia as seções na ordem: os princípios e a arquitetura, a ordem de construção, e cada módulo com as suas regras.' => 'Lisez les sections dans l\'ordre : les principes et l\'architecture, l\'ordre de construction, et chaque module avec ses règles.',
        'O modelo de dados (modelo_de_dados) é o do banco em uso agora, lido dele: tabelas, colunas, chaves, índices e regras de validação. Os tipos vêm no dialeto desse banco; o dialeto de referência (MySQL) está no schema.sql.' => 'Le modèle de données (modelo_de_dados) est celui de la base de données en usage maintenant, lu sur elle : tables, colonnes, clés, index et règles de validation. Les types viennent dans le dialecte de cette base ; le dialecte de référence (MySQL) est dans schema.sql.',
        'O contrato da API (cada consulta com parâmetros e exemplo, cada escrita com ações e campos, e o significado de cada campo das respostas) está em api.php?recurso=ajuda: a reescrita deve responder igual, para as telas, os scripts e quem integra continuarem funcionando.' => 'Le contrat de l\'API (chaque consultation avec paramètres et exemple, chaque écriture avec actions et champs, et le sens de chaque champ des réponses) est dans api.php?recurso=ajuda : la réécriture doit répondre pareil, pour que les écrans, les scripts et qui intègre continuent de fonctionner.',
        'O conhecimento sobre relógios não está no código: está no modelo.json (o conjunto inicial de uma coleção nova: os grupos, os campos, os tipos de lançamento, as fórmulas, os avisos, os critérios dos grupos, as categorias, os modos, a configuração e as mensagens padrão, sem nenhum código fixo: os grupos se citam por apelido). O schema.sql só tem a estrutura. Leia também por recurso=cadastros e recurso=criterios. A reescrita traz esse cadastro como dado, não como código, no idioma de quem cria a coleção.' => 'La connaissance des montres n\'est pas dans le code : elle est dans le modelo.json (l\'ensemble initial d\'une nouvelle collection : les groupes, les champs, les types de saisie, les formules, les alertes, les critères des groupes, les catégories, les modes, la configuration et les messages par défaut, sans aucun code fixe : les groupes se citent par surnom). Le schema.sql n\'a que la structure. Lisez-le aussi par recurso=cadastros et recurso=criterios. La réécriture apporte ces définitions comme des données, pas comme du code, dans la langue de qui crée la collection.',
        'As telas (telas) são a especificação visual: o visual com os valores exatos, o menu e cada página, parte por parte, com cada tabela, campo, botão e mensagem, palavra por palavra. A reescrita reproduz a mesma interface, não uma parecida: o que está lá existe, e o que não está não existe. As capturas em docs/telas/ mostram o resultado.' => 'Les écrans (telas) sont la spécification visuelle : le visuel avec les valeurs exactes, le menu et chaque page, partie par partie, avec chaque tableau, champ, bouton et message, mot pour mot. La réécriture reproduit la même interface, pas une ressemblante : ce qui est là existe, et ce qui n\'y est pas n\'existe pas. Les captures dans docs/telas/ montrent le résultat.',
        'O código de verdade, como está agora, sai pelo recurso=codigo (a lista em codigo, abaixo): o CSS, o JavaScript, cada página e o HTML que ela entrega ao navegador, a API, o banco e o resto, lido do disco na hora (arquivo=<nome>; cru=1 para o arquivo puro). Cada página em telas diz os arquivos dela (codigo). O que não sai (o config.php, as chaves, os dados) está em codigo.nao_mostrados, com o que ver no lugar.' => 'Le vrai code, tel qu\'il est maintenant, sort par recurso=codigo (la liste dans codigo, ci-dessous) : le CSS, le JavaScript, chaque page et le HTML qu\'elle livre au navigateur, l\'API, la base de données et le reste, lu sur le disque au moment même (arquivo=<nom> ; cru=1 pour le fichier pur). Chaque page dans telas indique ses fichiers (codigo). Ce qui ne sort pas (le config.php, les clés, les données) est dans codigo.nao_mostrados, avec quoi voir à la place.',
        'O README.md explica cada tela e cada opção para quem usa (as seções para quem usa saem também pela API, em recurso=manual: o texto da página Ajuda); o testes/cenario.php é o roteiro de aceitação (veja a seção testes).' => 'Le README.md explique chaque écran et chaque option pour qui utilise le système (les sections pour qui l\'utilise sortent aussi par l\'API, dans recurso=manual : le texte de la page Aide) ; testes/cenario.php est le scénario de recette (voyez la section testes).',
        'Os princípios (não negociáveis)' => 'Les principes (non négociables)',
        'O sistema não sabe nada de relógios: o código tem só mecanismos (árvore, campos, tipos de lançamento, fórmulas, avisos, critérios, modos). Que um automático tem reserva de marcha, ou que um solar carrega no sol, está escrito em fórmulas cadastradas, que o usuário lê, edita e testa pela tela. Mudar uma regra de relógio é mudar cadastro (com uma migração), não código.' => 'Le système ne sait rien des montres : le code n\'a que des mécanismes (arbre, champs, types de saisie, formules, alertes, critères, modes). Qu\'une automatique a une réserve de marche, ou qu\'une solaire se charge au soleil, est écrit dans des formules enregistrées, que l\'utilisateur lit, modifie et teste par l\'écran. Changer une règle de montre, c\'est changer les définitions (avec une migration), pas le code.',
        'Tudo pela API: as páginas só desenham; toda leitura e toda gravação passa pela API, a mesma que um script usa. Nenhuma regra de negócio no navegador além de mostrar e esconder campos.' => 'Tout par l\'API : les pages ne font que dessiner ; toute lecture et toute écriture passent par l\'API, la même qu\'un script utilise. Aucune règle de métier dans le navigateur hormis montrer et cacher des champs.',
        'Falha segura: sem token válido, com o fuso inválido ou com o banco desatualizado (migração pendente), o sistema para e diz o motivo (a API responde 500 ou 503, o cron registra e não faz nada), em vez de rodar pela metade.' => 'Défaillance sûre : sans jeton valide, avec le fuseau invalide ou avec la base de données pas à jour (migration en attente), le système s\'arrête et dit pourquoi (l\'API répond 500 ou 503, le cron enregistre et ne fait rien), au lieu de tourner à moitié.',
        'O banco se defende: relacional e normalizado, toda ligação é chave estrangeira (obrigatória: some junto, ON DELETE CASCADE; opcional: a ligação se desfaz, SET NULL), nenhuma lista guardada como texto, e regras de validação (CHECK, NOT NULL, UNIQUE) iguais às da tela. Uma gravação errada é recusada pelo banco venha de onde vier (a API responde 409 com a regra quebrada).' => 'La base de données se défend : relationnelle et normalisée, tout lien est une clé étrangère (obligatoire : disparaît avec, ON DELETE CASCADE ; facultatif : le lien se défait, SET NULL), aucune liste gardée comme texte, et des règles de validation (CHECK, NOT NULL, UNIQUE) identiques à celles de l\'écran. Une écriture erronée est refusée par la base d\'où qu\'elle vienne (l\'API répond 409 avec la règle cassée).',
        'Cada coisa é de alguém: a coleção tem um dono, a árvore de grupos tem um dono, e tudo o que se lê ou se grava vale na coleção do pedido. A separação é do núcleo, não de cada consulta: a camada do banco reescreve cada comando para enxergar só a coleção (e a árvore dela), e quem não vê uma coleção recebe 404, como se ela não existisse.' => 'Chaque chose appartient à quelqu\'un : la collection a un propriétaire, l\'arbre de groupes a un propriétaire, et tout ce qui se lit ou s\'enregistre vaut dans la collection de la requête. La séparation est l\'affaire du noyau, pas de chaque requête : la couche de la base réécrit chaque commande pour ne voir que la collection (et son arbre), et qui ne voit pas une collection reçoit 404, comme si elle n\'existait pas.',
        'Nada some sem aviso: toda exclusão mostra antes o que sai junto (seguindo o banco em cascata, no banco inteiro: uma árvore serve a várias coleções) e só apaga com a confirmação; os arquivos do disco saem junto, na hora.' => 'Rien ne disparaît sans avertissement : toute suppression montre d\'abord ce qui part avec (en suivant la cascade de la base, dans toute la base : un arbre sert à plusieurs collections) et n\'efface qu\'avec la confirmation ; les fichiers du disque partent avec, aussitôt.',
        'Os mesmos resultados em MySQL/MariaDB, PostgreSQL, SQLite e Firebird: o SQL do sistema é escrito uma vez só; o que muda de banco para banco fica numa camada de tradução. Maiúsculas e acentos não contam nos textos curtos ("Relógio" = "RELOGIO"), em todos; no MySQL/MariaDB, toda tabela em utf8mb4_unicode_ci (a utf8mb4_general_ci, padrão do MariaDB, ordena diferente); no Firebird, a collation UNICODE_CI_AI.' => 'Les mêmes résultats sous MySQL/MariaDB, PostgreSQL, SQLite et Firebird : le SQL du système est écrit une seule fois ; ce qui change d\'une base à l\'autre reste dans une couche de traduction. Majuscules et accents ne comptent pas dans les textes courts (« Relógio » = « RELOGIO »), dans toutes ; sous MySQL/MariaDB, chaque table en utf8mb4_unicode_ci (utf8mb4_general_ci, le défaut de MariaDB, trie autrement) ; sous Firebird, la collation UNICODE_CI_AI.',
        'Datas e horas no fuso do sistema (FUSO). Nas fórmulas, o tempo é contado em dias no horário local: a meia-noite local de qualquer data é um número inteiro e a fração é a hora do dia; assim uma data e o agora entram na mesma conta sem o fuso aparecer.' => 'Dates et heures dans le fuseau du système (FUSO). Dans les formules, le temps se compte en jours à l\'heure locale : le minuit local de n\'importe quelle date est un nombre entier et la fraction est l\'heure du jour ; ainsi une date et le maintenant entrent dans le même calcul sans que le fuseau apparaisse.',
        'O cron é mudo e rastreável: roda a cada minuto, não escreve na saída, e registra no banco o que fez.' => 'Le cron est muet et traçable : il tourne chaque minute, n\'écrit rien sur la sortie, et enregistre dans la base de données ce qu\'il a fait.',
        'Mensagens que explicam o que fazer ("Dê um nome ao relógio (até 120 caracteres)."), em seis idiomas: português (o original), inglês, chinês simplificado, hindi, espanhol e francês. Nenhum texto fixo: todo texto que alguém lê passa por t("o texto em português", parâmetros), com o português como chave (como no gettext) e os parâmetros entre chaves ({1}, {nome}) trocados depois da tradução; cada idioma tem o seu dicionário (o texto em português => a tradução), e o que falta sai em português. O idioma de cada pessoa é dela (o seletor do menu, guardado no navegador); quem não escolheu vê o padrão da instalação (config.idioma), senão o do navegador, senão português. As datas e os números seguem o idioma. Os nomes cadastrados ficam como foram escritos.' => 'Des messages qui expliquent quoi faire (« Donnez un nom à la montre (jusqu\'à 120 caractères). »), en six langues : portugais (l\'original), anglais, chinois simplifié, hindi, espagnol et français. Aucun texte fixe : tout texte que quelqu\'un lit passe par t("o texto em português", paramètres), le portugais servant de clé (comme dans gettext) et les paramètres entre accolades ({1}, {nome}) remplacés après la traduction ; chaque langue a son dictionnaire (le texte en portugais => la traduction), et ce qui manque sort en portugais. La langue de chaque personne est la sienne (le sélecteur du menu, conservé dans le navigateur) ; qui n\'a pas choisi voit le défaut de l\'installation (config.idioma), sinon celle du navigateur, sinon le portugais. Les dates et les nombres suivent la langue. Les noms enregistrés restent tels qu\'ils ont été écrits.',
        'A arquitetura' => 'L\'architecture',
        'Um back-end único, a API (api.php): GET lê (recurso=...), POST grava (recurso=... e acao=...). Responde JSON (ou XML com formato=xml). O api.php faz a porta (a autenticação, o formato, a ordem dos recursos, os filtros e a resposta); cada recurso grande fica num arquivo da pasta api/ (api/hoje.php, api/ficha.php, api/ajuda.php...), que roda dentro dele, com as mesmas variáveis. Autenticação em todo pedido: o token (cabeçalho X-Api-Token ou parâmetro token, igual ao API_TOKEN) ou o login do site (HTTP Basic com usuário e senha da tabela usuario, senha com password_hash).' => 'Un back-end unique, l\'API (api.php) : GET lit (recurso=...), POST écrit (recurso=... et acao=...). Répond en JSON (ou en XML avec formato=xml). api.php fait la porte (l\'authentification, le format, l\'ordre des ressources, les filtres et la réponse) ; chaque grande ressource est dans un fichier du dossier api/ (api/hoje.php, api/ficha.php, api/ajuda.php...), qui tourne à l\'intérieur, avec les mêmes variables. Authentification à chaque requête : le jeton (en-tête X-Api-Token ou paramètre token, égal à API_TOKEN) ou la connexion du site (HTTP Basic avec l\'utilisateur et le mot de passe de la table usuario, mot de passe avec password_hash).',
        'Um núcleo (lib.php): o motor das fórmulas, as variáveis de cada relógio, os avisos, as notas, o plano, a escala, a previsão, o gasto medido, o pulso sozinho, a linha do tempo e os documentos; o colecoes.php (o escopo da coleção, o modelo.json, os segredos cifrados, a configuração do sistema, a migração v25, o impacto das exclusões); o alertas.php (os destinos das mensagens: webhook, e-mail por SMTP com cópia por IMAP, Web Push com VAPID; as agendas: Google, CalDAV, Outlook, ICS); o contas.php (o cadastro aberto, a conta, as coleções e as árvores, os convites, os pedidos, os tokens e o painel do master).' => 'Un noyau (lib.php) : le moteur des formules, les variables de chaque montre, les alertes, les notes, le plan, le planning, la prévision, la dépense mesurée, le poignet automatique, la chronologie et les documents ; le colecoes.php (la portée de la collection, le modelo.json, les secrets chiffrés, la configuration du système, la migration v25, l\'impact des suppressions) ; l\'alertas.php (les destinations des messages : webhook, e-mail par SMTP avec copie par IMAP, Web Push avec VAPID ; les agendas : Google, CalDAV, Outlook, ICS) ; le contas.php (l\'inscription ouverte, le compte, les collections et les arbres, les invitations, les demandes, les jetons et le panneau du master).',
        'As gravações (operacoes.php e, as das contas, contas.php): uma função por recurso (op_relogio, op_lancamento, op_campos, op_conta, op_colecoes...), que valida tudo, grava e devolve {ok, mensagem, erros[], ...}. A tela e a API chamam as mesmas.' => 'Les écritures (operacoes.php et, celles des comptes, contas.php) : une fonction par ressource (op_relogio, op_lancamento, op_campos, op_conta, op_colecoes...), qui valide tout, enregistre et renvoie {ok, mensagem, erros[], ...}. L\'écran et l\'API appellent les mêmes.',
        'O banco (banco.php): a conexão com as extensões do PHP (mysqli, pgsql, sqlite3, pdo_firebird), parâmetros sempre por ? (nunca texto colado no SQL), e a tradução do dialeto do MySQL para os outros: AUTO_INCREMENT, ENUM (vira CHECK ... IN), TINYINT, DATETIME, os INDEX dentro do CREATE TABLE, AFTER, MODIFY COLUMN (o SQLite refaz a tabela), INSERT IGNORE, REPLACE INTO, NOW(), <=>, LIKE sem diferenciar maiúsculas; no Firebird, também LIMIT/OFFSET (OFFSET ... ROWS FETCH NEXT ... ROWS ONLY), DATE(x) (CAST AS DATE), CONCAT (||), LENGTH/LEAST/GREATEST (OCTET_LENGTH/MINVALUE/MAXVALUE), o SELECT sem FROM (FROM RDB$DATABASE), o INSERT de várias linhas (um por linha), a tabela no (palavra reservada: "NO"), nomes de índice e de regra com até 31 letras, o TEXT como VARCHAR(8191) e a chave única de várias colunas com coluna vazia como índice único de uma expressão; e três comandos próprios das migrações: ALTER FOREIGN KEY, DROP COLUMN e ADD CONSTRAINT ... CHECK (trocando a regra sem perder a anterior se os dados não cumprem a nova).' => 'La base de données (banco.php) : la connexion avec les extensions de PHP (mysqli, pgsql, sqlite3, pdo_firebird), paramètres toujours par ? (jamais de texte collé dans le SQL), et la traduction du dialecte MySQL vers les autres : AUTO_INCREMENT, ENUM (devient CHECK ... IN), TINYINT, DATETIME, les INDEX dans le CREATE TABLE, AFTER, MODIFY COLUMN (SQLite refait la table), INSERT IGNORE, REPLACE INTO, NOW(), <=>, LIKE sans distinguer les majuscules ; sous Firebird, aussi LIMIT/OFFSET (OFFSET ... ROWS FETCH NEXT ... ROWS ONLY), DATE(x) (CAST AS DATE), CONCAT (||), LENGTH/LEAST/GREATEST (OCTET_LENGTH/MINVALUE/MAXVALUE), le SELECT sans FROM (FROM RDB$DATABASE), l\'INSERT de plusieurs lignes (une par ligne), la table no (mot réservé : « NO »), noms d\'index et de règle d\'au plus 31 lettres, le TEXT en VARCHAR(8191) et la clé unique de plusieurs colonnes avec une colonne vide comme index unique d\'une expression ; et trois commandes propres aux migrations : ALTER FOREIGN KEY, DROP COLUMN et ADD CONSTRAINT ... CHECK (en remplaçant la règle sans perdre la précédente si les données ne respectent pas la nouvelle).',
        'As páginas (index.php, plano.php, desejos.php, estatisticas.php, hora.php, acessorios.php, galeria.php, passaporte.php, ficha.php, documentos.php, historico.php, avisos.php, configuracao.php, modos.php, criterios.php, grupos.php, cadastros.php, execucoes.php, conta.php, aprovacoes.php, usuarios.php, destinos.php, agendas.php, ajuda.php, e a pública cadastro.php) só entregam o esqueleto, sem conferir nem o login; o JavaScript de cada uma (hoje.js, painel.js, configuracao.js, ajuda.js...) chama a API e monta a tela, sem fazer conta: resumos, porcentagens e situações (o resumo do plano, a porcentagem de cada estado no histórico, o peso efetivo dos critérios, a situação do cron, o manual em HTML) vêm prontos da API. Formulários com data-recurso gravam pela API e a página se remonta com a resposta.' => 'Les pages (index.php, plano.php, desejos.php, estatisticas.php, hora.php, acessorios.php, galeria.php, passaporte.php, ficha.php, documentos.php, historico.php, avisos.php, configuracao.php, modos.php, criterios.php, grupos.php, cadastros.php, execucoes.php, conta.php, aprovacoes.php, usuarios.php, destinos.php, agendas.php, ajuda.php, et la page publique cadastro.php) ne livrent que le squelette, sans même vérifier l\'identifiant ; le JavaScript de chacune (hoje.js, painel.js, configuracao.js, ajuda.js...) appelle l\'API et monte l\'écran, sans faire de calcul : résumés, pourcentages et situations (le résumé du plan, le pourcentage de chaque état dans l\'historique, le poids effectif des critères, la situation du cron, le manuel en HTML) viennent tout prêts de l\'API. Les formulaires avec data-recurso enregistrent par l\'API et la page se remonte avec la réponse.',
        'A API faz tudo, inclusive o que vem antes das telas: a instalação do banco vazio (recurso=instalacao, pelo token), o primeiro usuário (recurso=usuarios pelo token), a importação do sistema anterior (recurso=importacao) e o login das páginas (recurso=entrar: a página sem login recebe 401 da API, o api.js manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e a API devolve para a página). Os scripts de linha de comando (instalar.php, criar_usuario.php, importar.php) só chamam as mesmas operações.' => 'L\'API fait tout, y compris ce qui vient avant les écrans : l\'installation de la base vide (recurso=instalacao, par le jeton), le premier utilisateur (recurso=usuarios par le jeton), l\'importation du système précédent (recurso=importacao) et la connexion des pages (recurso=entrar : la page sans identifiant reçoit 401 de l\'API, api.js envoie vers api.php?recurso=entrar&volta=<la page>, le navigateur demande l\'utilisateur et le mot de passe et l\'API renvoie vers la page). Les scripts de ligne de commande (instalar.php, criar_usuario.php, importar.php) ne font qu\'appeler les mêmes opérations.',
        'Fora da API, só o cron (cron.php), a cada minuto pela linha de comando, com as mesmas funções que a API usa; o que ele fez sai em recurso=cron.' => 'Hors de l\'API, seulement le cron (cron.php), chaque minute par la ligne de commande, avec les mêmes fonctions que l\'API utilise ; ce qu\'il a fait sort dans recurso=cron.',
        'Sem framework e sem dependências: PHP 8.1+ e JavaScript puro. A reescrita pode usar outra pilha, desde que mantenha o contrato da API, o modelo de dados e as regras.' => 'Sans framework et sans dépendances : PHP 8.1+ et JavaScript pur. La réécriture peut utiliser une autre pile logicielle, dès lors qu\'elle garde le contrat de l\'API, le modèle de données et les règles.',
        'A ordem de construção' => 'L\'ordre de construction',
        '1. O banco: as tabelas do modelo_de_dados, com as chaves e as regras; a instalação (o schema inteiro num banco vazio) e as migrações (uma lista ordenada; cada uma com o SQL, um passo opcional em programa, e uma marca de aplicada: uma tabela, uma coluna ou uma linha da tabela sistema; com alguma pendente, o sistema para e a Configuração mostra o botão de aplicar). A v25 refaz o banco inteiro: copia tudo para um arquivo, cria a estrutura nova e devolve os registros na forma nova, com os mesmos ids.' => '1. La base : les tables du modelo_de_dados, avec les clés et les règles ; l\'installation (tout le schema dans une base vide) et les migrations (une liste ordonnée ; chacune avec le SQL, une étape facultative en programme, et une marque d\'application : une table, une colonne ou une ligne de la table sistema ; s\'il y en a une en attente, le système s\'arrête et la Configuration montre le bouton pour appliquer). La v25 refait toute la base : elle copie tout dans un fichier, crée la nouvelle structure et remet les enregistrements sous la nouvelle forme, avec les mêmes ids.',
        '2. O conjunto inicial (modelo.json: a árvore Smartwatch / Tradicional › Mecânico › Automático e Corda manual / Tradicional › Quartzo › Pilha e Solar, os campos, os tipos de lançamento, as fórmulas, os avisos, os critérios, as categorias e os modos) como dados, entrando no idioma de quem cria a coleção.' => '2. L\'ensemble initial (modelo.json : l\'arbre Smartwatch / Tradicional › Mecânico › Automático et Corda manual / Tradicional › Quartzo › Pilha et Solar, les champs, les types de saisie, les formules, les alertes, les critères, les catégories et les modes) comme données, arrivant dans la langue de qui crée la collection.',
        '3. As contas e a autenticação (o login HTTP Basic, o token pessoal, o token do servidor), a coleção do pedido e o escopo dela no banco, e o esqueleto da API: os formatos, os erros (400, 401, 403, 404, 409, 413, 500, 503) e os filtros genéricos de qualquer consulta (incluir, excluir, f[], busca, ordem, limite, pagina, mostrar).' => '3. Les comptes et l\'authentification (l\'identifiant HTTP Basic, le jeton personnel, le jeton du serveur), la collection de la requête et sa portée dans la base, et le squelette de l\'API : les formats, les erreurs (400, 401, 403, 404, 409, 413, 500, 503) et les filtres génériques de toute requête (incluir, excluir, f[], busca, ordem, limite, pagina, mostrar).',
        '4. A árvore, os campos (com a validação do valor pelo tipo), os relógios e as fotos.' => '4. L\'arbre, les champs (avec la validation de la valeur selon le type), les montres et les photos.',
        '5. Os tipos de lançamento e os lançamentos (instantâneo, com valor, sessão; sessão exclusiva fecha as outras exclusivas no mesmo instante; sem sobreposição de sessões do mesmo tipo), e a linha do tempo.' => '5. Les types de saisie et les saisies (instantané, avec valeur, session ; une session exclusive ferme les autres exclusives au même instant ; pas de chevauchement de sessions du même type), et la ligne du temps.',
        '6. O motor das fórmulas (abaixo), as variáveis de um relógio e o botão Testar.' => '6. Le moteur des formules (ci-dessous), les variables d\'une montre et le bouton Tester.',
        '7. Os avisos, a visão de cada relógio (agora, carga, situação, próxima manutenção) e a página Hoje.' => '7. Les alertes, la vue de chaque montre (maintenant, charge, situation, prochain entretien) et la page Aujourd\'hui.',
        '8. O gasto medido pelas leituras e a previsão da energia (autonomia).' => '8. La consommation mesurée par les lectures et la prévision de l\'énergie (autonomie).',
        '9. Os critérios e a nota; os modos de rodízio, o plano, a garantia de rodízio, trocar o dia, sortear de novo; a escala inteligente.' => '9. Les critères et la note ; les modes de rotation, le plan, la garantie de rotation, changer le jour, tirer à nouveau ; le planning intelligent.',
        '10. O pulso sozinho e as sessões esquecidas; o cron.' => '10. Le poignet tout seul et les sessions oubliées ; le cron.',
        '11. Os destinos das mensagens (webhook, e-mail, Web Push), as agendas (Google, CalDAV, Outlook, link ICS) e os eventos personalizados, cada um com o que recebe e o seu modelo.' => '11. Les destinations des messages (webhook, e-mail, Web Push), les agendas (Google, CalDAV, Outlook, lien ICS) et les événements personnalisés, chacun avec ce qu\'il reçoit et son modèle.',
        '12. Os documentos (pasta, cópia no banco em três níveis, galeria, vídeos, PDF, NF-e) e a manutenção deles no cron.' => '12. Les documents (dossier, copie dans la base de données à trois niveaux, galerie, vidéos, PDF, NF-e) et leur entretien dans le cron.',
        '13. As telas, as contas (o cadastro aberto, Minha conta, as Aprovações, o painel do master), as execuções do cron, a ajuda (o README dentro do sistema: os mesmos trechos que recurso=manual devolve) e a importação do sistema anterior.' => '13. Les écrans, les comptes (l\'inscription ouverte, Mon compte, les Approbations, le panneau du master), les exécutions du cron, l\'aide (le README dans le système : les mêmes extraits que renvoie recurso=manual) et l\'importation du système précédent.',
        '14. A aceitação: o roteiro de testes nos quatro bancos dá as mesmas respostas (seção testes).' => '14. La recette : le scénario de tests sur les quatre bases de données donne les mêmes réponses (section testes).',
        'A árvore, os campos e os relógios' => 'L\'arbre, les champs et les montres',
        'A árvore de grupos tem quantos níveis o usuário quiser; um relógio fica num grupo só (ou na raiz). Tudo o que se cadastra num grupo (campos, tipos de lançamento, fórmulas, avisos, critérios, a origem de um bloco de modo) vale para ele e para tudo abaixo dele.' => 'L\'arbre des groupes a autant de niveaux que l\'utilisateur veut ; une montre est dans un seul groupe (ou à la racine). Tout ce qu\'on enregistre dans un groupe (champs, types de saisie, formules, alertes, critères, l\'origine d\'un bloc de mode) vaut pour lui et pour tout ce qui est en dessous.',
        'O mesmo nome pode se repetir em ramos diferentes, mas não entre irmãos. Mover um grupo para dentro dele mesmo (ou de um de dentro) é recusado. Excluir um grupo pela tela passa antes o que era dele para o grupo de cima (os de dentro, os relógios, os campos, os tipos, as fórmulas, os avisos e os blocos que sorteavam dele); versões de fórmula e de aviso que o grupo de cima já tem saem.' => 'Le même nom peut se répéter dans des branches différentes, mais pas entre frères. Déplacer un groupe à l\'intérieur de lui-même (ou d\'un qui est dedans) est refusé. Supprimer un groupe par l\'écran passe d\'abord ce qui était à lui vers le groupe du dessus (ceux de l\'intérieur, les montres, les champs, les types, les formules, les alertes et les blocs qui tiraient au sort à partir de lui) ; les versions de formule et d\'alerte que le groupe du dessus a déjà sortent.',
        'Campos: identificador (minúsculas, números e _, começando por letra, até 40; único entre campos e fórmulas, porque é o nome nas fórmulas; não muda se alguma fórmula usa), nome, tipo (listas.tipos_de_campo), unidade, valor padrão, o grupo, a ordem e a marca só nos desejados (so_desejado). Os campos de um relógio são os de todos e os de cada grupo da cadeia dele (os só nos desejados, só no desejado).' => 'Champs : identifiant (minuscules, chiffres et _, commençant par une lettre, jusqu\'à 40 ; unique parmi les champs et les formules, parce que c\'est le nom dans les formules ; il ne change pas si une formule l\'utilise), nom, type (listas.tipos_de_campo), unité, valeur par défaut, le groupe, l\'ordre et la marque seulement pour les envies (so_desejado). Les champs d\'une montre sont ceux de tous et ceux de chaque groupe de sa chaîne (ceux seulement pour les envies, seulement sur une désirée).',
        'O valor de um campo é conferido e normalizado pelo tipo: inteiro; decimal (aceita 1.079,99, 1079,99 e 1079.99, grava com ponto); sim/não (1, sim, s, true; 0, não, nao, n, false); data AAAA-MM-DD; lista (uma das opções); texto (até 1000). Vazio apaga. O valor usado nas contas é o informado, senão o padrão do campo.' => 'La valeur d\'un champ est vérifiée et normalisée selon le type : entier ; décimal (accepte 1.079,99, 1079,99 et 1079.99, enregistre avec un point) ; oui/non (1, sim, s, true ; 0, não, nao, n, false) ; date AAAA-MM-JJ ; liste (l\'une des options) ; texte (jusqu\'à 1000). Vide efface. La valeur utilisée dans les calculs est celle saisie, sinon la valeur par défaut du champ.',
        'A situação na coleção de cada relógio (posse): colecao (o padrão), desejado (a lista de desejos), emprestado, vendido ou arquivado. Só o que está na coleção entra no rodízio: nas outras, o relógio fica indisponível (o banco garante, ck_relogio_posse_disponivel; a gravação força disponivel=0 e diz isso na mensagem), e por isso sai do sorteio, da escala e dos avisos sem regra a mais. Saindo da coleção, as sessões abertas dele fecham agora (com a nota "Fechei agora: ..."), os dias dele no plano de amanhã em diante saem e são sorteados de novo (com escala, gerar_escala de amanhã; sem, garantir_plano); hoje fica, mas a sessão do dia (o pulso sozinho) não abre para um relógio fora da coleção. Voltando para a coleção sem dizer o disponível, ele fica disponível. Da coleção (contam na tabela da página Hoje e no valor): na coleção e emprestado (o estado do emprestado parado é "Emprestado"); desejado, vendido e arquivado vão para fora_da_colecao (recurso=hoje) e para a página Desejos. Um campo com so_desejado=1 (o preço-alvo, a prioridade) vale só no desejado: campos_do_relogio o deixa de fora nos outros, e a gravação dos valores também. A lista de desejos (recurso=desejos) vem da prioridade mais alta para a mais baixa (a ordem das opções do campo prioridade_desejo; sem prioridade, no fim), depois pelo nome, com a soma dos preços-alvo; no painel do desejado, o quadro Desejo e os documentos tomam o lugar dos do dia a dia.' => 'Le statut dans la collection de chaque montre (posse) : colecao (le défaut), desejado (la liste d\'envies), emprestado, vendido ou arquivado. Seul ce qui est dans la collection entre dans la rotation : dans les autres, la montre devient indisponible (la base de données le garantit, ck_relogio_posse_disponivel ; l\'enregistrement force disponivel=0 et le dit dans le message), et elle sort donc du tirage, du planning et des alertes sans règle supplémentaire. En sortant de la collection, ses sessions ouvertes se ferment maintenant (avec la note « Fermé maintenant : ... »), ses jours dans le plan à partir de demain sortent et sont tirés au sort de nouveau (avec planning, gerar_escala à partir de demain ; sans, garantir_plano) ; aujourd\'hui reste, mais la session du jour (le poignet tout seul) ne s\'ouvre pas pour une montre hors de la collection. En revenant dans la collection sans préciser le disponible, elle devient disponible. Comptent dans la collection (elles comptent dans le tableau de la page Aujourd\'hui et dans le montant) : dans la collection et prêtée (l\'état de la prêtée à l\'arrêt est « Prêtée ») ; désirée, vendue et archivée vont dans fora_da_colecao (recurso=hoje) et sur la page Envies. Un champ avec so_desejado=1 (le prix cible, la priorité) ne vaut que sur une désirée : campos_do_relogio le laisse de côté sur les autres, et l\'enregistrement des valeurs aussi. La liste d\'envies (recurso=desejos) va de la priorité la plus haute à la plus basse (l\'ordre des options du champ prioridade_desejo ; sans priorité, à la fin), puis par le nom, avec la somme des prix cibles ; dans le panneau de la désirée, le cadre Envie et les documents prennent la place de ceux du quotidien.',
        'Acessórios (tabela acessorio): nome (até 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro), o relógio de que ele é (opcional: sem ele, solto; excluir o relógio deixa solto, ON DELETE SET NULL), observação (até 1000) e quando foi cadastrado. A lista vem pelo tipo e pelo nome; a ficha traz os do relógio.' => 'Accessoires (table acessorio) : nom (jusqu\'à 120), type (pulseira, caixa, estojo, ferramenta, carregador, peca, outro), la montre à laquelle il appartient (facultatif : sans elle, libre ; supprimer la montre le laisse libre, ON DELETE SET NULL), observation (jusqu\'à 1000) et quand il a été enregistré. La liste vient par le type et par le nom ; la fiche apporte ceux de la montre.',
        'Relógio: nome (até 120), grupo, situação na coleção, disponível (fora do rodízio e dos avisos quando não), a marca da cópia no banco dos documentos, a foto (JPEG, PNG ou WebP até 4 MB; o navegador reduz para 1200 px antes de enviar). Excluir apaga junto os valores, a foto, os documentos (e os arquivos), os lançamentos, o plano e os critérios próprios.' => 'Montre : nom (jusqu\'à 120), groupe, statut dans la collection, disponible (hors de la rotation et des alertes quand elle ne l\'est pas), la marque de la copie dans la base des documents, la photo (JPEG, PNG ou WebP jusqu\'à 4 Mo ; le navigateur réduit à 1200 px avant d\'envoyer). Supprimer efface en même temps les valeurs, la photo, les documents (et les fichiers), les saisies, le plan et les critères propres.',
        'Os tipos de lançamento, os lançamentos e a linha do tempo' => 'Les types de saisie, les saisies et la ligne du temps',
        'Formatos (listas.formatos_de_lancamento): instantâneo (corda, troca de pilha), com valor (a leitura de carga, com unidade) e sessão, com início e fim (no pulso, no winder, no sol). Só a sessão tem "fecha às" (a hora em que a esquecida aberta fecha sozinha) e pode ser exclusiva (abrir uma exclusiva fecha as outras exclusivas abertas no mesmo instante: o relógio fica num lugar só). Só o com valor pode medir o gasto. A condição ("vale quando") é uma fórmula: o tipo só vale para os relógios em que ela dá verdadeiro.' => 'Formats (listas.formatos_de_lancamento) : instantané (remontage, changement de pile), avec valeur (la lecture de charge, avec unité) et session, avec début et fin (au poignet, sur le remontoir, au soleil). Seule la session a « se ferme à » (l\'heure à laquelle l\'oubliée ouverte se ferme toute seule) et peut être exclusive (en ouvrir une exclusive ferme les autres exclusives ouvertes au même instant : la montre reste à un seul endroit). Seul celui avec valeur peut mesurer la consommation. La condition (« vaut quand ») est une formule : le type ne vaut que pour les montres sur lesquelles elle donne vrai.',
        'Lançar: lancar (instantâneo ou com valor, num instante até agora), iniciar e encerrar (uma sessão; encerrar não antes do início), alternar (a sessão aberta se fecha, a fechada se abre: um botão só num atalho de celular), periodo (uma sessão inteira que já passou, sem sobrepor outra exclusiva), alterar e excluir (corrigir uma marcação). Em todas, relogio_id=hoje é o relógio do dia pelo plano. O formato de um tipo não muda depois de ter lançamentos; um tipo com lançamentos não é excluído.' => 'Saisir : lancar (instantané ou avec valeur, à un instant jusqu\'à maintenant), iniciar et encerrar (une session ; encerrar pas avant le début), alternar (la session ouverte se ferme, la fermée s\'ouvre : un seul bouton dans un raccourci de téléphone), periodo (une session entière déjà passée, sans chevaucher une autre exclusive), alterar et excluir (corriger une marque). Dans toutes, relogio_id=hoje est la montre du jour selon le plan. Le format d\'un type ne change pas après qu\'il a des saisies ; un type avec des saisies n\'est pas supprimé.',
        'A origem: manual (pela tela ou pela API), rodizio (a sessão no pulso do relógio do dia, aberta pelo sistema ou pelo Pôs no relógio do dia) e importado.' => 'L\'origine : manual (par l\'écran ou par l\'API), rodizio (la session au poignet de la montre du jour, ouverte par le système ou par « Mise » sur la montre du jour) et importado.',
        'A linha do tempo de um relógio divide o histórico em trechos contínuos: em uso pelo rodízio, no pulso fora do rodízio, em cada tipo de sessão (no winder, no sol...) e em repouso (o que sobra); e as marcações (corda, carga, pilha, revisão) como pontos, sem duração. O resumo dá o tempo e a porcentagem em cada estado.' => 'La ligne du temps d\'une montre divise l\'historique en périodes continues : en usage par la rotation, au poignet hors de la rotation, dans chaque type de session (sur le remontoir, au soleil...) et au repos (ce qui reste) ; et les marques (remontage, charge, pile, révision) comme des points, sans durée. Le résumé donne le temps et le pourcentage dans chaque état.',
        'O estado de agora de um relógio: em uso (uma sessão no pulso aberta), numa sessão (outra sessão aberta: o estado é o nome do tipo, "No sol", "No winder", "No carregador"; duas juntas, "No sol · No winder") ou em repouso; na tabela da página Hoje, o indisponível em repouso aparece como indisponível. Com o desde quando: o começo da sessão no pulso, o da sessão mais recente, ou o fim da última no pulso ("Em repouso desde 21:40"). A sessão esquecida aberta conta só até o "fecha às" dela. O pulso é o único tipo que o código conhece pelo identificador; os outros entram pelo nome.' => 'L\'état actuel d\'une montre : en usage (une session au poignet ouverte), dans une session (une autre session ouverte : l\'état est le nom du type, « Au soleil », « Sur le remontoir », « Sur le chargeur » ; deux ensemble, « Au soleil · Sur le remontoir ») ou au repos ; dans le tableau de la page Aujourd\'hui, l\'indisponible au repos apparaît comme indisponible. Avec le depuis quand : le début de la session au poignet, celui de la session la plus récente, ou la fin de la dernière au poignet (« Au repos depuis 21:40 »). La session oubliée ouverte ne compte que jusqu\'à son « se ferme à ». Le poignet est le seul type que le code connaît par l\'identifiant ; les autres entrent par le nom.',
        'O motor das fórmulas' => 'Le moteur des formules',
        'A sintaxe é a de uma planilha: números com vírgula ou ponto, textos entre aspas, ; separando os argumentos, + - * / ^ (a potência associa à direita), as comparações = <> < <= > >= (dão 1 ou 0), o sinal, os parênteses, as variáveis e as funções (listas.funcoes_das_formulas). A precedência, da mais fraca para a mais forte: comparação, soma, produto, potência, sinal.' => 'La syntaxe est celle d\'un tableur : nombres avec virgule ou point, textes entre guillemets, ; séparant les arguments, + - * / ^ (la puissance s\'associe à droite), les comparaisons = <> < <= > >= (donnent 1 ou 0), le signe, les parenthèses, les variables et les fonctions (listas.funcoes_das_formulas). La précédence, de la plus faible à la plus forte : comparaison, somme, produit, puissance, signe.',
        'Um valor vazio se propaga pela conta (vazio + 1 = vazio); a divisão por zero dá vazio. MIN e MAX ignoram os vazios. PADRAO(x; outro) troca o vazio. Um erro de escrita diz a posição ("falta fechar as aspas", "\\";\\" sobrando na posição 12").' => 'Une valeur vide se propage dans le calcul (vide + 1 = vide) ; la division par zéro donne vide. MIN et MAX ignorent les vides. PADRAO(x; autre) remplace le vide. Une erreur d\'écriture indique la position (« il manque de fermer les guillemets », « \\";\\" en trop à la position 12 »).',
        'As variáveis de um relógio: os campos (o valor usado), as fórmulas (pelo identificador; uma fórmula pode usar outra, sem ciclo) e as que o sistema dá. Cada fórmula pode ter uma versão por grupo; vale a do grupo mais perto do relógio (a dele, senão a de cima, ... senão a de todos). Uma fórmula que não tem versão para o relógio fica vazia nele.' => 'Les variables d\'une montre : les champs (la valeur utilisée), les formules (par l\'identifiant ; une formule peut en utiliser une autre, sans cycle) et celles que le système fournit. Chaque formule peut avoir une version par groupe ; celle du groupe le plus proche de la montre s\'applique (la sienne, sinon celle du dessus, ... sinon celle de tous). Une formule qui n\'a pas de version pour la montre reste vide sur elle.',
        'As funções de histórico leem os lançamentos do relógio até o instante da conta (o primeiro argumento é o identificador do tipo, entre aspas). ACUMULA percorre o histórico como um saldo: começa no início, perde por hora, ganha por hora em cada sessão da lista, passa a valer o efeito num instantâneo da lista, sempre entre 0 e o máximo. É ela que faz a reserva de marcha e a carga de luz.' => 'Les fonctions d\'historique lisent les saisies de la montre jusqu\'à l\'instant du calcul (le premier argument est l\'identifiant du type, entre guillemets). ACUMULA parcourt l\'historique comme un solde : elle commence au début, perd par heure, gagne par heure dans chaque session de la liste, prend la valeur de l\'effet lors d\'un instantané de la liste, toujours entre 0 et le maximum. C\'est elle qui fait la réserve de marche et la charge de lumière.',
        'Testar: a mesma fórmula calculada em todos os relógios (ou nos escolhidos), sem gravar, com o caminho da conta (rastro). Antes de gravar uma fórmula, o sistema a lê (erro de escrita) e confere as variáveis e os tipos que ela usa. Renomear ou excluir um campo, um tipo ou uma fórmula que outra fórmula usa é recusado, com a lista de quem usa.' => 'Tester : la même formule calculée sur toutes les montres (ou sur celles choisies), sans enregistrer, avec le chemin du calcul (rastro). Avant d\'enregistrer une formule, le système la lit (erreur d\'écriture) et vérifie les variables et les types qu\'elle utilise. Renommer ou supprimer un champ, un type ou une formule qu\'une autre formule utilise est refusé, avec la liste de qui l\'utilise.',
        'O tempo nas contas é em dias: HOJE() é a meia-noite local de hoje, AGORA() o instante, e as datas dos campos viram dias pelo mesmo relógio. As horas viram dias dividindo por 24.' => 'Le temps dans les calculs est en jours : HOJE() est le minuit local d\'aujourd\'hui, AGORA() l\'instant, et les dates des champs deviennent des jours par la même horloge. Les heures deviennent des jours en divisant par 24.',
        'Os avisos e a visão de cada relógio' => 'Les alertes et la vue de chaque montre',
        'Um aviso tem uma fórmula que dá a data prevista (expressao, em dias), uma condição (vale quando), a antecedência (0 a 3650 dias), o texto (até 300, com {relogio}, {data}, {quando} e {limite}), o tipo de lançamento que resolve (o botão na tela Hoje), se está ativo, uma versão por grupo (como as fórmulas), e como a escala simula a solução (escala: nao, uso ou sempre; o valor ou as horas simuladas) e se entra na agenda só dentro da janela de antecedência ou sempre.' => 'Une alerte a une formule qui donne la date prévue (expressao, en jours), une condition (vaut quand), l\'anticipation (0 à 3650 jours), le texte (jusqu\'à 300, avec {relogio}, {data}, {quando} et {limite}), le type de saisie qui la résout (le bouton sur l\'écran Aujourd\'hui), si elle est active, une version par groupe (comme les formules), et comment le planning simule la solution (escala : nao, uso ou sempre ; la valeur ou les heures simulées) et si elle entre dans l\'agenda seulement dans la fenêtre d\'anticipation ou toujours.',
        'Um relógio fora da coleção (desejado, vendido, arquivado) não tem aviso nenhum (o emprestado tem). O aviso vale para um relógio disponível quando a condição dá verdadeiro e a data prevista existe; sai hoje quando a data menos a antecedência já chegou. Estado: atrasado (a data passou) ou em breve. O aviso de um relógio com uma sessão aberta à mão (carregando, no sol) não vai para a agenda enquanto ela estiver aberta: a data andaria a cada conta.' => 'Une montre hors de la collection (désirée, vendue, archivée) n\'a aucune alerte (la prêtée en a). L\'alerte vaut pour une montre disponible quand la condition donne vrai et que la date prévue existe ; elle sort aujourd\'hui quand la date moins l\'anticipation est déjà arrivée. État : en retard (la date est passée) ou bientôt. L\'alerte d\'une montre avec une session ouverte à la main (en charge, au soleil) ne va pas dans l\'agenda tant qu\'elle est ouverte : la date bougerait à chaque calcul.',
        'Os avisos de carga usam o limite de carga: o do relógio (campo carga_minima), senão o geral da Configuração (carga_limiar); o solar usa sol_limiar. A data do Carregar é pelo gasto do estado de agora (no pulso, o de uso; guardado, o de guardado); no carregador, o Carregar some e vale o Tirar do carregador (carregado: vence quando a bateria enche no carregador).' => 'Les alertes de charge utilisent la limite de charge : celle de la montre (champ carga_minima), sinon la générale de la Configuration (carga_limiar) ; la solaire utilise sol_limiar. La date de Charger est selon la consommation de l\'état actuel (au poignet, celle d\'usage ; rangée, celle du rangement) ; sur le chargeur, Charger disparaît et Retirer du chargeur s\'applique (chargée : elle arrive à échéance quand la batterie se remplit sur le chargeur).',
        'Um aviso pode ser "na hora" (na_hora): além do alerta da manhã, o cron manda pelos destinos que o recebem no minuto em que ele vence, uma vez, e guarda quais já foram (config.na_hora_enviados, relogio_id:identificador); um aviso sai da lista quando deixa de vencer. O botão do aviso na página Hoje vem da API (resolve.acao e resolve.botao): a sessão que resolve, aberta, se encerra ("Tirou do carregador"); fechada, se inicia ("Pôs no sol"); a leitura se informa.' => 'Une alerte peut être « à l\'heure » (na_hora) : en plus de l\'alerte du matin, le cron l\'envoie par les destinations qui la reçoivent à la minute où elle échoit, une fois, et garde lesquelles sont déjà parties (config.na_hora_enviados, relogio_id:identificador) ; une alerte sort de la liste quand elle cesse d\'échoir. Le bouton de l\'alerte sur la page Aujourd\'hui vient de l\'API (resolve.acao et resolve.botao) : la session qui la résout, ouverte, se termine (« Retirée du chargeur ») ; fermée, elle commence (« Mise au soleil ») ; la lecture se saisit.',
        'O aviso Encostado (encostado, de todos os relógios, resolve com o pulso) é só cadastro: a data prevista é PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias") (a Configuração, padrão 30), antecedência 0; sem nunca ter ido ao pulso nem data da compra, não avisa. Não entra na próxima manutenção nem no "O que fazer": a tabela da coleção tem a coluna Encostado, o cartão do dia mostra a falta quando já venceu, e o quadro Agora do painel também.' => 'L\'alerte Délaissée (encostado, pour toutes les montres, se résout avec le poignet) n\'est que des définitions : la date prévue est PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias") (la Configuration, 30 par défaut), anticipation 0 ; sans jamais être allée au poignet ni date d\'achat, elle n\'alerte pas. Elle n\'entre pas dans le prochain entretien ni dans « Que faire » : le tableau de la collection a la colonne Délaissée, la carte du jour montre le retard quand c\'est déjà échu, et le cadre Maintenant du panneau aussi.',
        'A visão de cada relógio (a tabela da página Hoje e o painel): em uso ou em repouso desde quando, a carga estimada agora e de onde vem (a fórmula energia e a origem), a situação (frases curtas: autonomia restante, reserva...), a próxima manutenção (o aviso mais perto, sem o Encostado), o que fazer e a coluna Encostado.' => 'La vue de chaque montre (le tableau de la page Aujourd\'hui et le panneau) : en usage ou au repos depuis quand, la charge estimée maintenant et d\'où elle vient (la formule energia et l\'origine), le statut (phrases courtes : autonomie restante, réserve...), le prochain entretien (l\'alerte la plus proche, sans la Délaissée), que faire et la colonne Délaissée.',
        'O gasto medido pelas leituras e a autonomia' => 'La consommation mesurée par les lectures et l\'autonomie',
        'Cada leitura de carga de um tipo que mede o gasto é comparada com a anterior do mesmo relógio: o intervalo vira uma medição, com a queda, as horas no pulso e as horas fora do pulso no intervalo (o horário de uso conta como pulso sozinho quando o pulso sozinho está ligado; as marcações Pôs e Tirou mandam) e a marcação das duas leituras (lancamento.estado: uso ou repouso, gravada na leitura; a leitura sem marcação, de antes ou de um script que não diz, vale o que o pulso registrado dizia naquele instante). Uma subida é recarga: novo ponto de partida, sem medir. Só entram intervalos de 1 hora ou mais. Um intervalo com outra sessão no meio (o carregador) não mede: a medição só separa pulso e guardado. Ao lançar uma leitura marcada ao contrário do pulso registrado naquele instante, a API responde confirmar: true com a pergunta, e só grava de novo com confirmar=1 (vale o que a pessoa marcou; nada é impedido e o pulso registrado não muda).' => 'Chaque relevé de charge d\'un type qui mesure la consommation est comparé au précédent de la même montre : l\'intervalle devient une mesure, avec la baisse, les heures au poignet et les heures hors du poignet dans l\'intervalle (les heures d\'usage comptent comme poignet d\'elles-mêmes quand le poignet automatique est activé ; les marquages Mis et Retiré font foi) et le marquage des deux relevés (lancamento.estado : uso ou repouso, enregistré dans le relevé ; le relevé sans marquage, d\'avant ou d\'un script qui ne dit rien, prend ce que le poignet enregistré disait à cet instant). Une hausse est une recharge : nouveau point de départ, sans mesurer. Seuls les intervalles de 1 heure ou plus entrent. Un intervalle avec une autre session au milieu (le chargeur) ne mesure pas : la mesure ne sépare que poignet et rangé. En saisissant un relevé marqué à l\'inverse du poignet enregistré à cet instant, l\'API répond confirmar: true avec la question, et n\'enregistre qu\'au renvoi avec confirmar=1 (ce que la personne a marqué fait foi ; rien n\'est bloqué et le poignet enregistré ne change pas).',
        'Cinco motores transformam as medições nos dois gastos (GASTO_MOTORES: horas, robusto, marcacao, cadastro, formulas), e a pessoa escolhe em três níveis, o de cima valendo sobre os de baixo (gasto_motor_de: a chave gasto_motor da Configuração da coleção; senão o valor do campo gasto_motor no relógio (uma lista com os cinco, na raiz do cadastro inicial); senão o padrão desse campo, na versão dele mais perto do relógio na árvore (o grupo); senão horas). A ficha diz o motor e de onde veio (previsao.gasto.motor, motor_nome, motor_de). Quais medições entram é outra chave, medicao_base: dias (as dos últimos medicao_janela_dias, padrão 90) ou leituras (as últimas medicao_janela_leituras de cada tipo, em uso e em repouso, padrão 20); sem nenhuma na janela, as de antes (medicoes_janela).' => 'Cinq moteurs transforment les mesures en les deux consommations (GASTO_MOTORES : horas, robusto, marcacao, cadastro, formulas), et la personne choisit à trois niveaux, celui du haut primant sur ceux du bas (gasto_motor_de : la clé gasto_motor de la Configuration de la collection ; sinon la valeur du champ gasto_motor dans la montre (une liste avec les cinq, à la racine de la fiche initiale) ; sinon la valeur par défaut de ce champ, dans sa version la plus proche de la montre dans l\'arbre (le groupe) ; sinon horas). La fiche dit le moteur et d\'où il vient (previsao.gasto.motor, motor_nome, motor_de). Quelles mesures entrent est une autre clé, medicao_base : dias (celles des derniers medicao_janela_dias, par défaut 90) ou leituras (les derniers medicao_janela_leituras de chaque type, en usage et au repos, par défaut 20) ; sans aucune dans la fenêtre, celles d\'avant (medicoes_janela).',
        '1. horas (gasto_medido_horas, o original): cada medição dividida pelas marcações de pulso minuto a minuto (horas_pulso, horas_guardado), e os dois gastos saem juntos por mínimos quadrados nas quedas, cada medição pesando as horas que cobre (peso_horas); sem separar os dois, a média de cada lado. 2. robusto (gasto_medido_desde): a conta é feita nas LEITURAS: entre duas recargas, leitura = carga do começo − gasto em uso × dias de uso − gasto guardado × dias guardado + erro. Medições seguidas (o fim de uma é o começo da outra) formam um trecho, cada trecho com a carga do começo dele (desconhecida; sai da conta tirando a média de cada trecho), e os dois gastos valem para todos. Mínimos quadrados com o mesmo peso para todas as leituras (o erro é o do mostrador e do medidor, o mesmo em 2 horas ou 2 semanas), repesados por Huber (peso 1 até 1,345 σ do desvio; depois 1,345 σ ÷ |desvio|; σ = 1,4826 × a mediana dos desvios, no mínimo 0,5 ponto), até os pesos pararem de mudar. O gasto do cadastro (taxa_uso e taxa_repouso sem as medições, gasto_prior) entra como média a priori, com desvio padrão de metade do valor (no mínimo 2% por dia de uso e 0,5% por dia guardado): a conta é a média a posteriori, (XᵀWX/σ² + Λ)β = XᵀWy/σ² + Λβ0, nunca negativa; a incerteza (uso_dp, repouso_dp) é a raiz da diagonal da inversa. De cada medição, a leitura dela que pesa menos (a do começo ou a do fim) dá o peso, o erro (em pontos) e o valor; pesando menos da metade, ela não bate com as outras (fora).' => '1. horas (gasto_medido_horas, l\'original) : chaque mesure divisée par les marquages de poignet minute par minute (horas_pulso, horas_guardado), et les deux consommations sortent ensemble par moindres carrés sur les baisses, chaque mesure pesant les heures qu\'elle couvre (peso_horas) ; sans pouvoir séparer les deux, la moyenne de chaque côté. 2. robusto (gasto_medido_desde) : le calcul se fait sur les RELEVÉS : entre deux recharges, relevé = charge du début − consommation en usage × jours d\'usage − consommation rangé × jours rangé + erreur. Des mesures consécutives (la fin de l\'une est le début de l\'autre) forment un tronçon, chaque tronçon avec sa charge de début (inconnue ; elle sort du calcul en soustrayant la moyenne de chaque tronçon), et les deux consommations valent pour tous. Moindres carrés avec le même poids pour tous les relevés (l\'erreur est celle de l\'affichage et du capteur, la même sur 2 heures ou 2 semaines), repondérés par Huber (poids 1 jusqu\'à 1,345 σ du résidu ; ensuite 1,345 σ ÷ |résidu| ; σ = 1,4826 × la médiane des résidus, au minimum 0,5 point), jusqu\'à ce que les poids cessent de changer. La consommation de la fiche (taxa_uso et taxa_repouso sans les mesures, gasto_prior) entre comme moyenne a priori, avec un écart-type de la moitié de la valeur (au minimum 2 % par jour d\'usage et 0,5 % par jour rangé) : le calcul est la moyenne a posteriori, (XᵀWX/σ² + Λ)β = XᵀWy/σ² + Λβ0, jamais négative ; l\'incertitude (uso_dp, repouso_dp) est la racine de la diagonale de l\'inverse. De chaque mesure, le relevé qui pèse le moins (celui du début ou celui de la fin) donne le poids, l\'erreur (en points) et la valeur ; pesant moins de la moitié, il ne colle pas avec les autres (fora).',
        '3. marcacao (medicoes_da_conta por marcação + gasto_medido_desde): só as medições cujas duas leituras têm a mesma marcação; a marcada em uso mede o gasto em uso com o tempo inteiro do intervalo como dias de uso (as horas de um dia de uso são as do horário de uso), e a marcada em repouso mede o gasto fora com o intervalo inteiro em dias guardados; as duas contas nunca se cruzam (o pulso registrado não entra), cada uma robusta como a 2, com a incerteza. 4. cadastro: MEDIDO dá vazio e valem só o decaimento e a autonomia do cadastro; as medições continuam sendo feitas e ficam no histórico. 5. formulas: vale o que as fórmulas taxa_uso e taxa_repouso derem; nelas MEDIDO é a conta 3, e as funções LEITURAS, QUEDA, DIAS_MEDIDOS, MEDIA_TAXA, MEDIANA_TAXA (todas com "uso" ou "repouso" e, opcional, os últimos N dias; sem N ou 0, a janela da Configuração) e ULTIMA_TAXA dão as peças das medições pela marcação. Nos outros motores as fórmulas também valem (é delas que sai o gasto que vale). A pessoa também tira ou põe uma medição na conta (lancamento medicao, usada 0 ou 1), sem apagar nada; vale nos motores 1, 2, 3 e 5. O resultado também é dado na janela anterior, para comparar (a bateria envelhecendo).' => '3. marcacao (medicoes_da_conta par marquage + gasto_medido_desde) : seulement les mesures dont les deux relevés ont le même marquage ; celle marquée en usage mesure la consommation en usage avec l\'intervalle entier comme jours d\'usage (les heures d\'un jour d\'usage sont celles des heures d\'usage), et celle marquée au repos mesure la consommation hors du poignet avec l\'intervalle entier en jours rangé ; les deux calculs ne se croisent jamais (le poignet enregistré n\'entre pas), chacun robuste comme le 2, avec l\'incertitude. 4. cadastro : MEDIDO donne vide et seuls la décroissance et l\'autonomie de la fiche valent ; les mesures continuent d\'être faites et restent dans l\'historique. 5. formulas : ce que donnent les formules taxa_uso et taxa_repouso vaut ; dans celles-ci MEDIDO est le calcul 3, et les fonctions LEITURAS, QUEDA, DIAS_MEDIDOS, MEDIA_TAXA, MEDIANA_TAXA (toutes avec « uso » ou « repouso » et, en option, les N derniers jours ; sans N ou avec 0, la fenêtre de la Configuration) et ULTIMA_TAXA donnent les pièces des mesures par marquage. Dans les autres moteurs les formules valent aussi (c\'est d\'elles que sort la consommation qui vaut). La personne retire aussi une mesure du calcul ou l\'y remet (lancamento medicao, usada 0 ou 1), sans rien effacer ; cela vaut dans les moteurs 1, 2, 3 et 5. Le résultat est aussi donné sur la fenêtre précédente, pour comparer (la batterie qui vieillit).',
        'MEDIDO("uso") e MEDIDO("repouso") dão esses gastos às fórmulas; corrigir uma marcação de pulso (ou a marcação de uma leitura) recalcula as horas das medições que cobrem aquele trecho.' => 'MEDIDO("uso") et MEDIDO("repouso") donnent ces consommations aux formules ; corriger un marquage de poignet (ou le marquage d\'un relevé) recalcule les heures des mesures qui couvrent ce tronçon.',
        'A autonomia: cheio pelo cadastro e pela conta (com o gasto medido), quando acaba seguindo o plano (simulando os dias do plano), quanto dura no pulso sem tirar e guardado; e a previsão do smartwatch (a carga dia a dia, até o limite).' => 'L\'autonomie : pleine selon la fiche et selon le calcul (avec la consommation mesurée), quand elle s\'épuise en suivant le plan (en simulant les jours du plan), combien elle dure au poignet sans la retirer et rangée ; et la prévision de la smartwatch (la charge jour après jour, jusqu\'à la limite).',
        'Os critérios e a nota' => 'Les critères et la note',
        'Um conjunto de critérios por lugar: todos os relógios, um grupo ou um relógio. O relógio usa o conjunto mais perto dele, inteiro (o dele, senão o do grupo, senão o de cima, ..., senão o de todos).' => 'Un ensemble de critères par endroit : toutes les montres, un groupe ou une montre. La montre utilise l\'ensemble le plus proche d\'elle, entier (le sien, sinon celui du groupe, sinon celui du dessus, ..., sinon celui de tous).',
        'O conjunto tem parâmetros com peso (somam 100%); cada parâmetro tem subparâmetros com peso (somam 100% dentro dele); cada subparâmetro lê uma variável (um campo ou uma fórmula) e transforma o valor em nota (0 a 100) pelas faixas: de um número até outro (a primeira começa em 0, sem buracos nem sobreposição, só a última sem limite) ou por categoria (campo de lista ou texto).' => 'L\'ensemble a des paramètres avec un poids (ils totalisent 100 %) ; chaque paramètre a des sous-paramètres avec un poids (ils totalisent 100 % à l\'intérieur) ; chaque sous-paramètre lit une variable (un champ ou une formule) et transforme la valeur en note (0 à 100) par les plages : d\'un nombre jusqu\'à un autre (la première commence à 0, sans trous ni chevauchement, seule la dernière sans limite) ou par catégorie (champ de liste ou texte).',
        'A nota do parâmetro é a média das notas dos subparâmetros, pelo peso; a nota do relógio, a média dos parâmetros, pelo peso. Um subparâmetro sem valor (campo vazio, valor fora de toda faixa) sai da conta e os outros dividem o peso dele. A conta inteira de cada nota é mostrada (cada faixa, cada peso, cada ponto).' => 'La note du paramètre est la moyenne des notes des sous-paramètres, selon le poids ; la note de la montre, la moyenne des paramètres, selon le poids. Un sous-paramètre sans valeur (champ vide, valeur hors de toute plage) sort du calcul et les autres se partagent son poids. Le calcul entier de chaque note est montré (chaque plage, chaque poids, chaque point).',
        'Restaurar os critérios iniciais apaga os de todos os lugares e volta aos do cadastro inicial.' => 'Restaurer les critères initiaux efface ceux de tous les endroits et revient à ceux des définitions initiales.',
        'Os modos de rodízio, o plano e a escala inteligente' => 'Les modes de rotation, le plan et le planning intelligent',
        'Hoje sem relógio (rodizio sem_relogio): o plano de hoje sai e hoje vira um dia livre; a sessão do rodízio de hoje que já começou fecha agora (o tempo dela conta como uso), a que ainda não começou sai; a sessão do dia (o pulso sozinho) não abre num dia sem plano, e o garantir_plano não põe de volta como plano de hoje o relógio que esteve no pulso pelo rodízio num dia livre. Os outros dias não mudam. Desfaz: trocar_dia (ou usando) de hoje, ou resortear_hoje.' => 'Aujourd\'hui sans montre (rodizio sem_relogio) : le plan d\'aujourd\'hui sort et aujourd\'hui devient un jour libre ; la session de rotation d\'aujourd\'hui déjà commencée se ferme maintenant (son temps compte comme usage), celle qui n\'a pas encore commencé sort ; la session du jour (le poignet tout seul) ne s\'ouvre pas un jour sans plan, et garantir_plano ne remet pas comme plan d\'aujourd\'hui la montre qui a été au poignet par la rotation un jour libre. Les autres jours ne changent pas. Annuler : trocar_dia (ou usando) d\'aujourd\'hui, ou resortear_hoje.',
        'Um modo é feito de blocos de dias da semana (cada dia em um bloco só). Cada bloco diz de onde escolher (um grupo, a coleção toda ou um relógio fixo) e se é um relógio por dia ou um para o bloco inteiro. A forma de escolha do modo: inteligente (a maior nota), ponderado (sorteio com a nota como chance), aleatório ou fifo (quem espera há mais tempo). Com o ciclo ligado, um relógio só volta depois que todos os disponíveis do bloco passaram. No máximo um modo em uso.' => 'Un mode est fait de blocs de jours de la semaine (chaque jour dans un seul bloc). Chaque bloc dit d\'où choisir (un groupe, toute la collection ou une montre fixe) et si c\'est une montre par jour ou une pour le bloc entier. La façon de choisir du mode : inteligente (la meilleure note), ponderado (tirage avec la note comme chance), aleatorio ou fifo (celle qui attend depuis le plus longtemps). Avec le cycle activé, une montre ne revient qu\'après que toutes les disponibles du bloc sont passées. Au plus un mode en usage.',
        'A garantia de rodízio (max_sem_uso, padrão 21) vale antes da nota: candidato além desse limite de dias sem uso ganha direto, o mais parado primeiro. Os dias sem uso de um relógio nunca usado contam desde a compra (sem data de compra: 9999).' => 'La garantie de rotation (max_sem_uso, 21 par défaut) vaut avant la note : un candidat au-delà de cette limite de jours sans usage gagne directement, le plus longtemps à l\'arrêt en premier. Les jours sans usage d\'une montre jamais portée comptent depuis l\'achat (sans date d\'achat : 9999).',
        'O plano guarda o relógio de cada dia, o bloco, a origem (sorteio ou manual), a ação do dia e o motivo, numa frase ("Garantia de rodízio: ...", "Sorteio pela nota, entre 5 candidatos: nota 70,2, 16,4% de chance", "Escolhido à mão"). O cron monta o dia que falta (à 0h da segunda, a semana nova); trocar o relógio de um dia o marca como manual; sortear de novo refaz o período; usando hoje põe outro relógio no período atual e refaz o plano.' => 'Le plan garde la montre de chaque jour, le bloc, l\'origine (tirage ou manuelle), l\'action du jour et le motif, en une phrase (« Garantie de rotation : ... », « Tirage par la note, parmi 5 candidats : note 70,2, 16,4 % de chance », « Choisi à la main »). Le cron construit le jour qui manque (à 0 h du lundi, la semaine nouvelle) ; changer la montre d\'un jour le marque comme manuel ; tirer de nouveau refait la période ; usando aujourd\'hui met une autre montre dans la période actuelle et refait le plan.',
        'Um período escolhido à mão (rodizio, acao=periodo): de, até (de hoje até 2 anos), os relógios na ordem e quantos dias seguidos cada (dias_cada): cada dia do período fica manual, com o relógio da vez (depois do último, volta ao primeiro; hoje, ele passa a ser o do pulso a partir de agora); na escala, ela é refeita a partir do começo do período. De amanhã em diante: periodo_sortear apaga o que o período tem (à mão, sorteado ou livre) e sorteia de novo; periodo_livre apaga e deixa os dias livres (a tabela plano_livre: sem relógio e sem sorteio; o sorteio e a escala pulam esses dias, e a escala não estica um bloco sobre eles). Escolher um relógio para um dia livre (trocar_dia, periodo, usando) o tira de plano_livre; trocar_dia 0 também (volta ao sorteio). Os dias manuais e os livres de amanhã em diante ficam quando se sorteia de novo ou se monta a próxima semana (hoje, o sortear de novo sorteia); trocar de modo refaz os sorteados. A API dá os dias livres em plano.livres e hoje.livres (as telas os põem entre os dias do plano, como "livre: escolha à mão").' => 'Une période choisie à la main (rodizio, acao=periodo) : de, até (d\'aujourd\'hui jusqu\'à 2 ans), les montres dans l\'ordre et combien de jours de suite chacune (dias_cada) : chaque jour de la période reste manuel, avec la montre du tour (après la dernière, on revient à la première ; aujourd\'hui, elle devient celle du poignet à partir de maintenant) ; dans le planning, il est refait à partir du début de la période. À partir de demain : periodo_sortear efface ce que la période a (à la main, tiré au sort ou libre) et tire au sort de nouveau ; periodo_livre efface et laisse les jours libres (la table plano_livre : sans montre et sans tirage ; le tirage et le planning sautent ces jours, et le planning n\'étire pas un bloc par-dessus). Choisir une montre pour un jour libre (trocar_dia, periodo, usando) le retire de plano_livre ; trocar_dia 0 aussi (retour au tirage). Les jours manuels et les libres à partir de demain restent quand on tire au sort de nouveau ou qu\'on construit la semaine suivante (aujourd\'hui, le tirer de nouveau tire au sort) ; changer de mode refait les tirés au sort. L\'API donne les jours libres dans plano.livres et hoje.livres (les écrans les placent parmi les jours du plan, comme « libre : choisissez à la main »).',
        'O Rodízio manual (a última opção da lista Modo de rodízio da página Hoje; não é um modo: fora do período vale o modo ativo): de e até (de hoje até 2 anos); recurso=rodizio_manual dá os dias de 7 em 7 (pagina), cada um com o que o plano tem e a escolha de partida do seletor: o relógio escolhido à mão, livre (dia livre) ou auto (Decida por mim: o dia sorteado ou sem relógio). rodizio acao=manual grava o período inteiro: dias[data] = o id, auto ou livre (hoje não); o dia que não vem fica com a escolha de partida. Os dias com relógio ficam manual ("Escolhido à mão no rodízio manual de DD/MM a DD/MM."); os livres vão para plano_livre; hoje com outro relógio passa a ser o do pulso a partir de agora (hoje em auto continua o que está); na escala, ela é refeita a partir do começo. O Decida por mim decide ao gravar e grava manual, com o motivo ("Decida por mim: a maior nota (62,9), entre 4 candidatos. O de ontem (X) ficou de fora." ou "Decida por mim, pela garantia de rodízio: parado há 33 dias, além do limite de 15 dias sem uso, ..."): de hoje até o fim do período, dia a dia, cada dia vira uma sessão simulada no pulso (os do plano antes do período, os escolhidos e os decididos), e no dia auto: os disponíveis, menos o de ontem e o escolhido para amanhã (se sobrar outro); a garantia de rodízio na frente (o mais tempo parado além de max_sem_uso); senão a maior nota no começo do uso do dia; empate: o menor id. A resposta diz quantos dias foram escolhidos, decididos, livres e quantos ficaram como já estavam.' => 'La Rotation manuelle (la dernière option de la liste Mode de rotation de la page Aujourd\'hui ; ce n\'est pas un mode : hors de la période vaut le mode actif) : de et até (d\'aujourd\'hui jusqu\'à 2 ans) ; recurso=rodizio_manual donne les jours 7 par 7 (pagina), chacun avec ce que le plan a et le choix de départ du sélecteur : la montre choisie à la main, libre (jour libre) ou auto (Décider pour moi : le jour tiré au sort ou sans montre). rodizio acao=manual enregistre la période entière : dias[data] = l\'id, auto ou libre (pas aujourd\'hui) ; le jour qui n\'est pas transmis garde le choix de départ. Les jours avec une montre restent manuels (« Choisi à la main dans la rotation manuelle du JJ/MM au JJ/MM. ») ; les libres vont dans plano_livre ; aujourd\'hui avec une autre montre devient celle du poignet à partir de maintenant (aujourd\'hui en auto continue ce qui est en place) ; dans le planning, il est refait à partir du début. Le Décider pour moi décide à l\'enregistrement et enregistre en manuel, avec le motif (« Décider pour moi : la meilleure note (62,9), parmi 4 candidats. Celle d\'hier (X) a été laissée de côté. » ou « Décider pour moi, par la garantie de rotation : à l\'arrêt depuis 33 jours, au-delà de la limite de 15 jours sans usage, ... ») : d\'aujourd\'hui jusqu\'à la fin de la période, jour après jour, chaque jour devient une session simulée au poignet (ceux du plan avant la période, les choisis et les décidés), et le jour auto : les disponibles, moins celle d\'hier et celle choisie pour demain (s\'il en reste une autre) ; la garantie de rotation devant (la plus longtemps à l\'arrêt au-delà de max_sem_uso) ; sinon la meilleure note au début de l\'usage du jour ; égalité : le plus petit id. La réponse dit combien de jours ont été choisis, décidés, libres et combien sont restés comme ils étaient.',
        'Apagar a programação (página Plano e quadro Modo de rodízio): apagar um período (periodo_sortear: os dias dele, de amanhã em diante, saem da tabela plano e o modo monta esses dias de novo; sem o de, de amanhã; sem o ate, até o último dia do plano; periodo_livre, só pela API: sai tudo e os dias ficam livres) e apagar tudo (rodizio apagar_tudo: sai toda a programação de amanhã em diante, à mão, sorteada e livre; com hoje=1, "Excluindo hoje", de hoje em diante; depois o modo ativo monta o plano de novo, gerar_escala na escala e garantir_plano até domingo no sorteio; hoje, se mudar, o novo vai para o pulso a partir de agora, como no resortear_hoje).' => 'Effacer la programmation (page Plan et cadre Mode de rotation) : effacer une période (periodo_sortear : ses jours, à partir de demain, quittent la table plano et le mode refait ces jours ; sans de, à partir de demain ; sans ate, jusqu\'au dernier jour du plan ; periodo_livre, seulement par l\'API : tout part et les jours deviennent libres) et tout effacer (rodizio apagar_tudo : toute la programmation à partir de demain part, à la main, tirée au sort et libre ; avec hoje=1, « Y compris aujourd\'hui », à partir d\'aujourd\'hui ; ensuite le mode actif refait le plan, gerar_escala dans le planning et garantir_plano jusqu\'à dimanche dans le tirage ; aujourd\'hui, s\'il change, le nouveau passe au poignet à partir de maintenant, comme dans resortear_hoje).',
        'As listas longas de dias vêm da API uma página por vez (plano_pagina): os Próximos dias (hoje.proximos e recurso=proximos, de hoje até o fim do plano) e o dia a dia da página Plano (plano.dia_a_dia, com o filtro relogio), com os dias livres no meio (origem livre; sem eles no filtro de relógio), cada dia com o dia da semana (dia_semana 1 a 7, dia_semana_curto); o tamanho da página é o Mostrar até da Configuração (config proximos_por_pagina, padrão 7; plano_por_pagina, padrão 31; 1 a 366; por_pagina no pedido vale por cima), e o recurso=config devolve os dois já com o padrão (mostrar_ate).' => 'Les longues listes de jours viennent de l\'API une page à la fois (plano_pagina) : les Prochains jours (hoje.proximos et recurso=proximos, d\'aujourd\'hui jusqu\'à la fin du plan) et le jour par jour de la page Plan (plano.dia_a_dia, avec le filtre relogio), avec les jours libres au milieu (origine libre ; sans eux dans le filtre de montre), chaque jour avec le jour de la semaine (dia_semana 1 à 7, dia_semana_curto) ; la taille de la page est le Afficher jusqu\'à de la Configuration (config proximos_por_pagina, 7 par défaut ; plano_por_pagina, 31 par défaut ; 1 à 366 ; por_pagina dans la requête l\'emporte), et recurso=config renvoie les deux déjà avec le défaut (mostrar_ate).',
        'A escala inteligente (um modo com escala_dias de 7 a 730) planeja tudo de uma vez simulando dia a dia: a nota de cada relógio com o estado simulado daquele dia; a escolha (o smartwatch fica os dias que a bateria aguenta, até 7); a sessão no pulso no horário de uso e o efeito dela em todos; os avisos (se o escolhido vai precisar de carga ou corda, anota a ação no dia e simula o lançamento que resolve). Toda manhã o cron refaz a escala a partir do estado real. Notas iguais na maior (o empate exato) se desempatam por sorteio, e o motivo diz "Empatado na nota com N outros: saiu no sorteio (<fonte>)."' => 'Le planning intelligent (un mode avec escala_dias de 7 à 730) planifie tout d\'un coup en simulant jour après jour : la note de chaque montre avec l\'état simulé de ce jour ; le choix (la smartwatch reste les jours que la batterie tient, jusqu\'à 7) ; la session au poignet pendant l\'horaire d\'usage et son effet sur toutes ; les alertes (si la choisie va avoir besoin de charge ou de remontage, note l\'action du jour et simule la saisie qui résout). Chaque matin le cron refait le planning à partir de l\'état réel. Des notes égales à la plus haute (l\'égalité exacte) se départagent par tirage, et le motif dit « À égalité de note avec N autres : sortie au tirage (<source>). ».',
        'O sorteio (sorteio(min, max): o modo aleatório, o sorteio pela nota e o desempate da escala) usa números aleatórios de fora, nesta ordem: RANDOM.ORG (www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new: ruído atmosférico); senão o ANU QRNG (qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16, o endereço antigo, sem chave: {"success": true, "data": [...]}; quântico); senão o gerador seguro do PHP (random_int). Um lote de 64 números de 16 bits por pedido, na memória do pedido; cada sorteio junta quantos pedaços de 16 bits precisar e descarta o valor que passa do último múltiplo inteiro da faixa (sem viés). Cada serviço tem 4 segundos; a resposta tem de vir completa e dentro da faixa, senão vale como falha. Se os dois falham, a config aleatorio_fora guarda quando, e por 10 minutos o sistema nem tenta (usa o do PHP); a config aleatorio_ultima guarda a fonte do último lote e quando (recurso=config: aleatorio.ultimo_lote, aleatorio.fora_desde; a Configuração mostra no quadro Sorteios). O motivo de cada dia sorteado termina com a fonte entre parênteses ("... todos com a mesma chance (RANDOM.ORG)."). Com RELOGIOS_SEMENTE (os testes), mt_rand com a semente, sem rede (a fonte: "semente de teste"). O que é segredo (o sal das senhas, os nomes dos arquivos dos documentos) fica no gerador do PHP: número que viaja pela internet não serve para segredo.' => 'Le tirage (sorteio(min, max) : le mode aléatoire, le tirage par la note et le départage du planning) utilise des nombres aléatoires de l\'extérieur, dans cet ordre : RANDOM.ORG (www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new : bruit atmosphérique) ; sinon l\'ANU QRNG (qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16, l\'ancienne adresse, sans clé : {"success": true, "data": [...]} ; quantique) ; sinon le générateur sûr de PHP (random_int). Un lot de 64 nombres de 16 bits par requête, dans la mémoire de la requête ; chaque tirage assemble autant de morceaux de 16 bits qu\'il lui faut et écarte la valeur qui dépasse le dernier multiple entier de la plage (sans biais). Chaque service a 4 secondes ; la réponse doit arriver complète et dans la plage, sinon cela compte comme un échec. Si les deux échouent, la config aleatorio_fora garde quand, et pendant 10 minutes le système n\'essaie même pas (il utilise celui de PHP) ; la config aleatorio_ultima garde la source du dernier lot et quand (recurso=config : aleatorio.ultimo_lote, aleatorio.fora_desde ; la Configuration le montre dans le cadre Tirages). Le motif de chaque jour tiré au sort se termine par la source entre parenthèses (« ... tous avec la même chance (RANDOM.ORG). »). Avec RELOGIOS_SEMENTE (les tests), mt_rand avec la graine, sans réseau (la source : « graine de test »). Ce qui est secret (le sel des mots de passe, les noms des fichiers des documents) reste dans le générateur de PHP : un nombre qui voyage par Internet ne sert pas de secret.',
        'O pulso sozinho e as sessões esquecidas' => 'Le poignet tout seul et les sessions oubliées',
        'O horário de uso (uso_inicio e uso_fim) diz quando o relógio do dia está no pulso. Pôr sozinho (pulso_auto_inicio): no início do horário, o cron abre a sessão no pulso do relógio do dia (origem rodizio). Tirar sozinho (pulso_auto_fim): o "fecha às" do tipo No pulso segue o fim do horário. Desligados, só as marcações Pôs e Tirou contam; o que foi marcado sempre vale. Com o relógio do dia noutra sessão exclusiva aberta (no carregador, no sol, no winder), o pôr sozinho espera; se ele saiu de uma depois do início do horário, a sessão no pulso começa quando ele saiu.' => 'L\'horaire d\'usage (uso_inicio et uso_fim) dit quand la montre du jour est au poignet. Mettre au poignet tout seul (pulso_auto_inicio) : au début de l\'horaire, le cron ouvre la session au poignet de la montre du jour (origine rodizio). Retirer du poignet tout seul (pulso_auto_fim) : le « se ferme à » du type Au poignet suit la fin de l\'horaire. Désactivés, seules les marques Mise et Retirée comptent ; ce qui a été marqué vaut toujours. Avec la montre du jour dans une autre session exclusive ouverte (sur le chargeur, au soleil, sur le remontoir), le mettre tout seul attend ; si elle est sortie d\'une après le début de l\'horaire, la session au poignet commence quand elle en est sortie.',
        'Toda sessão esquecida aberta fecha sozinha no "fecha às" do tipo dela (a do sol, em sol_fim).' => 'Toute session oubliée ouverte se ferme toute seule au « se ferme à » de son type (celle du soleil, à sol_fim).',
        'O cron' => 'Le cron',
        'A cada minuto: confere o token, o fuso e as migrações (pendente: registra e para); apaga execuções antigas (sem atividade, 7 dias; com atividade ou erro, 1 ano); monta o dia do plano que falta; fecha as sessões esquecidas; abre a sessão no pulso do dia; dispara os eventos personalizados no minuto marcado (depois de uma parada de até 7 dias, sai uma vez só, sem repetir); a manutenção dos documentos.' => 'Chaque minute : vérifie le jeton, le fuseau et les migrations (en attente : enregistre et s\'arrête) ; efface les exécutions anciennes (sans activité, 7 jours ; avec activité ou erreur, 1 an) ; construit le jour du plan qui manque ; ferme les sessions oubliées ; ouvre la session au poignet du jour ; déclenche les événements personnalisés à la minute marquée (après un arrêt d\'au plus 7 jours, part une seule fois, sans répéter) ; l\'entretien des documents.',
        'Por coleção, na hora da manhã dela (horario_manha), uma vez por dia: refaz a escala a partir do estado real, manda a mensagem do dia (o relógio de hoje e os avisos) por cada destino ligado e sincroniza as agendas. Na hora da noite (horario_noite): a da véspera (o relógio de amanhã e o que preparar) e a sincronização; conta os documentos. O sistema inteiro, a cada minuto: a limpeza das contas (o aviso de vencimento da demonstração, 7 dias e 1 dia antes, por e-mail; a conta vencida sai com tudo; os convites, os pedidos e os links de senha vencidos saem; a conta comum sem nada sai), a manutenção dos documentos e, depois das 20h, uma vez por dia, a cópia de segurança.' => 'Par collection, à son heure du matin (horario_manha), une fois par jour : il refait le planning à partir de l\'état réel, envoie le message du jour (la montre du jour et les alertes) par chaque destination active et synchronise les agendas. À l\'heure du soir (horario_noite) : celui de la veille (la montre de demain et ce qu\'il faut préparer) et la synchronisation ; il compte les documents. Tout le système, chaque minute : le nettoyage des comptes (l\'avis d\'expiration de la démonstration, 7 jours et 1 jour avant, par e-mail ; le compte expiré part avec tout ; les invitations, les demandes et les liens de mot de passe expirés partent ; le compte ordinaire sans rien part), la maintenance des documents et, après 20h, une fois par jour, la sauvegarde.',
        'Os avisos na hora, a cada minuto, em cada coleção: os vencidos agora que ainda não foram vão pelos destinos que os recebem.' => 'Les alertes à l\'heure, chaque minute, dans chaque collection : celles qui échoient maintenant et ne sont pas encore parties vont par les destinations qui les reçoivent.',
        'A cópia de segurança: um arquivo relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz na BACKUP_PASTA (fora da pasta publicada: dentro dela, recusada), JSON Lines comprimido, o mesmo nos quatro bancos: a primeira linha é o cabeçalho (relojoeiro_copia 1, criada, banco, versao: a última migração, documentos, tabelas); depois, para cada tabela, uma linha {tabela, colunas, binarias} e uma linha por registro com a lista dos valores (binários em base64). As tabelas vêm na ordem em que voltam (a citada antes da que cita; a que cita a si mesma, a árvore, volta em rodadas). Ficam as BACKUP_MANTER mais novas (padrão 7). O conteúdo dos documentos (documento_parte) só com BACKUP_DOCUMENTOS = true. Restaurar: só da mesma versão; antes, uma cópia do que está agora; depois, numa transação, apaga tudo (na ordem inversa) e grava a cópia; sem o conteúdo dos documentos, documento.no_banco volta a 0.' => 'La copie de sauvegarde : un fichier relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz dans BACKUP_PASTA (hors du dossier publié : à l\'intérieur, refusée), JSON Lines compressé, le même sur les quatre bases : la première ligne est l\'en-tête (relojoeiro_copia 1, criada, banco, versao : la dernière migration, documentos, tabelas) ; ensuite, pour chaque table, une ligne {tabela, colunas, binarias} et une ligne par enregistrement avec la liste des valeurs (binaires en base64). Les tables viennent dans l\'ordre où elles reviennent (celle citée avant celle qui cite ; celle qui se cite elle-même, l\'arbre, revient par tours). Restent les BACKUP_MANTER les plus récentes (7 par défaut). Le contenu des documents (documento_parte) seulement avec BACKUP_DOCUMENTOS = true. Restaurer : seulement de la même version ; avant, une copie de ce qui est là maintenant ; ensuite, dans une transaction, efface tout (dans l\'ordre inverse) et enregistre la copie ; sans le contenu des documents, documento.no_banco revient à 0.',
        'Com BACKUP_ATIVO = false no config.php, o cron não faz a cópia de segurança e a escrita fazer é recusada.' => 'Avec BACKUP_ATIVO = false dans le config.php, le cron ne fait pas la sauvegarde et l\'écriture fazer est refusée.',
        'Mudo: avisos do PHP e erros entram no registro, nunca na saída. Grava em cron_execucao o que fez o sistema (só quando fez algo, ou deu erro) e em cron_execucao_colecao o de cada coleção; o último erro em sistema.cron_erro (sai na primeira execução sem erro) e a última rodada com atividade em sistema.cron_registro. Erro fatal sem banco vai para um arquivo na pasta temporária.' => 'Silencieux : les avertissements de PHP et les erreurs vont dans le journal, jamais dans la sortie. Il enregistre dans cron_execucao ce que le système a fait (seulement quand il a fait quelque chose, ou en cas d\'erreur) et dans cron_execucao_colecao ce de chaque collection ; la dernière erreur dans sistema.cron_erro (effacée à la première exécution sans erreur) et la dernière tournée avec activité dans sistema.cron_registro. Une erreur fatale sans base va dans un fichier du dossier temporaire.',
        'As mensagens, as agendas e os eventos personalizados' => 'Les messages, les agendas et les événements personnalisés',
        'Os destinos (listas.tipos_de_destino) de cada coleção: webhook (um pedido HTTP GET, POST ou PUT, com a mensagem na URL, como formulário ou como JSON, os campos e os cabeçalhos, estes cifrados; o Telegram é um webhook), e-mail (pelo SMTP do config.php, com STARTTLS ou TLS, e a cópia em Enviados por IMAP) e Web Push (os aparelhos de um usuário que vê a coleção; aes128gcm e VAPID ES256). Cada um tem a mensagem padrão (o modelo, com as âncoras) e o idioma, e escolhe o que recebe: o relógio do dia, a véspera, cada aviso e cada evento personalizado, cada um com o texto próprio opcional. Os itens do mesmo horário vão juntos; o webhook manda em partes de até 3000 caracteres.' => 'Les destinations (listas.tipos_de_destino) de chaque collection : webhook (une requête HTTP GET, POST ou PUT, avec le message dans l\'URL, comme formulaire ou comme JSON, les champs et les en-têtes, ces derniers chiffrés ; Telegram est un webhook), e-mail (par le SMTP du config.php, avec STARTTLS ou TLS, et la copie dans Envoyés par IMAP) et Web Push (les appareils d\'un utilisateur qui voit la collection ; aes128gcm et VAPID ES256). Chacune a le message par défaut (le modèle, avec les ancres) et la langue, et choisit ce qu\'elle reçoit : la montre du jour, la veille, chaque alerte et chaque événement personnalisé, chacun avec un texte propre facultatif. Les éléments du même horaire partent ensemble ; le webhook envoie par parties de 3000 caractères au plus.',
        'As agendas (listas.tipos_de_agenda): Google Agenda (uma conta de serviço; token por JWT RS256), CalDAV (Nextcloud, iCloud com senha de app, Fastmail: um PUT de um .ics por evento), Outlook (o Microsoft Graph, com a conta conectada pelo OAuth do aplicativo registrado) e o link ICS (um calendário que o app de agenda assina; sem login, pela chave secreta do link). O sistema calcula o que tem de estar em cada uma (de hoje até janela_dias: os avisos marcados para ela, no horário da manhã do dia previsto; o relógio do dia e a véspera, pelo plano; os eventos personalizados) e deixa a agenda igual: cria o que falta, atualiza o que mudou (a assinatura do título e da descrição) e apaga o que deixou de valer; o que já passou fica, como histórico.' => 'Les agendas (listas.tipos_de_agenda) : Google Agenda (un compte de service ; jeton par JWT RS256), CalDAV (Nextcloud, iCloud avec un mot de passe d\'application, Fastmail : un PUT d\'un .ics par événement), Outlook (Microsoft Graph, avec le compte connecté par l\'OAuth de l\'application enregistrée) et le lien ICS (un calendrier auquel l\'application d\'agenda s\'abonne ; sans identifiant, par la clé secrète du lien). Le système calcule ce qui doit être dans chacune (d\'aujourd\'hui jusqu\'à janela_dias : les alertes cochées pour elle, à l\'heure du matin du jour prévu ; la montre du jour et la veille, d\'après le plan ; les événements personnalisés) et met l\'agenda en accord : il crée ce qui manque, met à jour ce qui a changé (la signature du titre et de la description) et efface ce qui ne vaut plus ; ce qui est déjà passé reste, comme historique.',
        'Os segredos (senhas, chaves, tokens, cabeçalhos) ficam cifrados no banco (AES-256-GCM, com a SEGREDO_CHAVE do config.php; sem ela, o API_TOKEN) e nunca voltam para a tela: a resposta diz só se estão preenchidos. Fora das coleções do master, os endereços que o usuário escreve (webhook, CalDAV, Web Push) têm de ser da internet: nada da rede do servidor.' => 'Les secrets (mots de passe, clés, jetons, en-têtes) restent chiffrés dans la base (AES-256-GCM, avec la SEGREDO_CHAVE du config.php ; sans elle, l\'API_TOKEN) et ne reviennent jamais à l\'écran : la réponse dit seulement s\'ils sont remplis. Hors des collections du master, les adresses que l\'utilisateur saisit (webhook, CalDAV, Web Push) doivent être sur internet : rien du réseau du serveur.',
        'Evento personalizado: nome, ativo, repetição (listas.repeticoes), data (uma vez; a cada N dias: a partir dela), hora, dias da semana, dia do mês (1 a 31; mês sem o dia, o último), intervalo (1 a 3650), relógio opcional (com ele, as âncoras do relógio funcionam). Só o que a repetição usa fica gravado. O evento novo vai para todos os destinos da coleção; cada disparo fica gravado, para não disparar duas vezes.' => 'Événement personnalisé : nom, actif, répétition (listas.repeticoes), date (une fois ; tous les N jours : à partir d\'elle), heure, jours de la semaine, jour du mois (1 à 31 ; un mois sans ce jour, le dernier), intervalle (1 à 3650), montre facultative (avec elle, les ancres de la montre fonctionnent). Seul ce que la répétition utilise est enregistré. Le nouvel événement va vers toutes les destinations de la collection ; chaque déclenchement est enregistré, pour ne pas se déclencher deux fois.',
        'As contas, as coleções e o acesso' => 'Les comptes, les collections et l\'accès',
        'Contas: o login (sem dois-pontos), o e-mail, a senha (o hash), o papel (master: cuida do sistema inteiro, vê todas as coleções e o painel das contas; comum), o idioma, e o vencimento da conta de demonstração. O primeiro usuário é o master. A conta criada pelo cadastro aberto (cadastro.php, CADASTRO_ABERTO) é de demonstração por DEMO_DIAS dias, com aviso por e-mail 7 dias e 1 dia antes; vencida, o cron a apaga com tudo. O master oficializa, prorroga, volta a demonstração, bloqueia, transfere uma coleção, dá acesso, exclui e vê o sistema como outro usuário (Vendo como).' => 'Comptes : l\'identifiant (sans deux-points), l\'e-mail, le mot de passe (le hash), le rôle (master : s\'occupe de tout le système, voit toutes les collections et le panneau des comptes ; comum), la langue, et l\'expiration du compte de démonstration. Le premier utilisateur est le master. Le compte créé par l\'inscription ouverte (cadastro.php, CADASTRO_ABERTO) est en démonstration pendant DEMO_DIAS jours, avec un avis par e-mail 7 jours et 1 jour avant ; expiré, le cron l\'efface avec tout. Le master rend officiel, prolonge, remet en démonstration, bloque, transfère une collection, donne l\'accès, supprime et voit le système en tant qu\'un autre utilisateur (Vue en tant que).',
        'Coleções e árvores: cada coleção tem um dono e usa uma árvore de grupos do mesmo dono; uma árvore pode servir a várias coleções, e o cadastro dela (campos, tipos, fórmulas, avisos, categorias, critérios dos grupos) vale em todas. A coleção nova nasce com o conjunto inicial (numa árvore nova), vazia (só a raiz) ou numa árvore que já existe. Transferir uma coleção leva a árvore junto quando só ela a usa; senão, o novo dono ganha uma cópia da árvore e a coleção passa para a cópia (os relógios, os valores, os lançamentos, os documentos e os blocos dos modos acompanham os ids novos).' => 'Collections et arbres : chaque collection a un propriétaire et utilise un arbre de groupes du même propriétaire ; un arbre peut servir à plusieurs collections, et ses définitions (champs, types, formules, alertes, catégories, critères des groupes) valent dans toutes. La nouvelle collection naît avec l\'ensemble initial (dans un nouvel arbre), vide (seulement la racine) ou dans un arbre qui existe déjà. Transférer une collection emporte l\'arbre quand elle seule l\'utilise ; sinon, le nouveau propriétaire reçoit une copie de l\'arbre et la collection passe à la copie (les montres, les valeurs, les saisies, les documents et les blocs des modes suivent les nouveaux ids).',
        'O acesso: o dono vê as suas; um membro vê uma coleção (colecao_usuario); quem tem tudo de um dono vê todas as dele, também as que vierem (acesso_dono). Entra-se por convite (o dono, ou o master, convida por e-mail com um link de token; o convite de um membro espera o dono aprovar; quem não tem conta cria pelo link) ou por pedido (o pedido espera o dono, ou o master, aprovar; aprovado ou recusado, a pessoa recebe um e-mail). Convites e pedidos vencem em CONVITE_DIAS dias. A conta comum que fica sem nada (sem coleção, sem acesso, sem pedido nem convite) sai.' => 'L\'accès : le propriétaire voit les siennes ; un membre voit une collection (colecao_usuario) ; qui a tout d\'un propriétaire voit toutes les siennes, aussi celles à venir (acesso_dono). On entre par invitation (le propriétaire, ou le master, invite par e-mail avec un lien à jeton ; l\'invitation d\'un membre attend l\'approbation du propriétaire ; qui n\'a pas de compte le crée par le lien) ou par demande (la demande attend l\'approbation du propriétaire, ou du master ; approuvée ou refusée, la personne reçoit un e-mail). Invitations et demandes expirent en CONVITE_DIAS jours. Le compte ordinaire qui se retrouve sans rien (sans collection, sans accès, sans demande ni invitation) part.',
        'O escopo: a coleção do pedido (colecao=, o cookie do seletor do menu, ou a primeira) decide tudo o que se lê e se grava: a camada do banco reescreve cada SELECT, UPDATE e DELETE para enxergar só as linhas da coleção e da árvore dela (a raiz da árvore não aparece, e as colunas que a citam leem vazio, como no tempo de uma pessoa só). A configuração é por coleção; os valores do sistema inteiro (o cron, a cópia de segurança, o aleatório, as migrações, o endereço do sistema) ficam na tabela sistema.' => 'La portée : la collection de la requête (colecao=, le cookie du sélecteur du menu, ou la première) décide de tout ce qui se lit et s\'enregistre : la couche de la base réécrit chaque SELECT, UPDATE et DELETE pour ne voir que les lignes de la collection et de son arbre (la racine de l\'arbre n\'apparaît pas, et les colonnes qui la citent se lisent vides, comme à l\'époque d\'une seule personne). La configuration est par collection ; les valeurs de tout le système (le cron, la sauvegarde, l\'aléatoire, les migrations, l\'adresse du système) sont dans la table sistema.',
        'Os tokens pessoais (Minha conta) valem como o login do dono; o token do servidor (API_TOKEN) vale como o master mais antigo. O Esqueci a senha manda um link de token (2 horas) por e-mail.' => 'Les jetons personnels (Mon compte) valent comme l\'identifiant du propriétaire ; le jeton du serveur (API_TOKEN) vaut comme le master le plus ancien. Mot de passe oublié envoie un lien à jeton (2 heures) par e-mail.',
        'Os documentos de cada relógio' => 'Les documents de chaque montre',
        'Qualquer arquivo, cada um numa categoria (as que aceitam só algumas famílias recusam as outras), com título, data e descrição. O tipo vem do conteúdo do arquivo; quando o conteúdo diz pouco (texto, binário genérico, zip), da extensão. A família decide como abre: imagem (galeria com visor em tela cheia e apresentação, com a miniatura feita no navegador), vídeo (player, em sequência na ordem escolhida), PDF (visualizador), XML (o resumo da NF-e: emitente, número, série, data, valor, chave e produtos; lido sem baixar nada de fora), o resto para baixar. Inline só o que o navegador mostra sem rodar nada (HTML, SVG e XML sempre como download); atende pedido de pedaço (Range).' => 'N\'importe quel fichier, chacun dans une catégorie (celles qui n\'acceptent que certaines familles refusent les autres), avec titre, date et description. Le type vient du contenu du fichier ; quand le contenu dit peu (texte, binaire générique, zip), de l\'extension. La famille décide comment il s\'ouvre : image (galerie avec visionneuse plein écran et diaporama, avec la miniature faite dans le navigateur), vidéo (lecteur, en séquence dans l\'ordre choisi), PDF (visionneuse), XML (le résumé de la NF-e : émetteur, numéro, série, date, montant, clé et produits ; lu sans rien télécharger de l\'extérieur), le reste à télécharger. Inline seulement ce que le navigateur montre sans rien exécuter (HTML, SVG et XML toujours en téléchargement) ; répond à une demande de fragment (Range).',
        'Os arquivos ficam numa pasta fora da publicada (DOCUMENTOS_PASTA), em r<id do relógio>/ com nome aleatório. Limite por arquivo: DOCUMENTOS_LIMITE (padrão 100 MB) e os do PHP e do servidor web.' => 'Les fichiers restent dans un dossier hors du publié (DOCUMENTOS_PASTA), dans r<id de la montre>/ avec un nom aléatoire. Limite par fichier : DOCUMENTOS_LIMITE (100 Mo par défaut) et celles de PHP et du serveur web.',
        'A cópia no banco (documento_parte, pedaços de 4 MB, com o SHA-256): três níveis, e o de cima vale sobre os de baixo. A coleção (a chave documentos_copia da Configuração: todos; nenhum; vazia, decidem os de baixo; o DOCUMENTOS_COPIA_BANCO do config.php, que valia para o servidor inteiro, não vale mais, e a Configuração avisa se ele ainda está definido), o relógio (copia_banco: todos os dele) e o arquivo (copia_banco: só ele). A tela só mostra a escolha de quem decide. A cópia entra na hora no envio e em editar; pelo relógio, o cron copia aos poucos; quando ninguém mais pede, sai, mas só se o arquivo da pasta confere com ela (o documento nunca fica sem as duas).' => 'La copie dans la base (documento_parte, morceaux de 4 Mo, avec le SHA-256) : trois niveaux, et celui du haut prime sur ceux du bas. La collection (la clé documentos_copia de la Configuration : todos ; nenhum ; vide, ceux du bas décident ; le DOCUMENTOS_COPIA_BANCO du config.php, qui valait pour tout le serveur, ne vaut plus, et la Configuration avertit s\'il est encore défini), la montre (copia_banco : tous les siens) et le fichier (copia_banco : lui seul). L\'écran ne montre que le choix de celui qui décide. La copie entre aussitôt à l\'envoi et à la modification ; par la montre, le cron copie petit à petit ; quand plus personne ne la demande, elle sort, mais seulement si le fichier du dossier lui correspond (le document ne reste jamais sans les deux).',
        'A manutenção (o cron, a cada minuto, até 256 MB por rodada): o arquivo que sumiu da pasta volta da cópia (conferindo o SHA-256); a cópia pedida que falta é feita; a que ninguém pede sai; a pasta de um relógio que não existe mais sai inteira; o arquivo que não é de nenhum documento sai (só depois de 10 minutos: um envio pode estar no meio). Os perdidos (sem arquivo e sem cópia) são contados à noite.' => 'L\'entretien (le cron, chaque minute, jusqu\'à 256 Mo par tour) : le fichier qui a disparu du dossier revient de la copie (en vérifiant le SHA-256) ; la copie demandée qui manque est faite ; celle que personne ne demande sort ; le dossier d\'une montre qui n\'existe plus sort entier ; le fichier qui n\'appartient à aucun document sort (seulement après 10 minutes : un envoi peut être en cours). Les perdus (sans fichier et sans copie) sont comptés le soir.',
        'O aplicativo no celular (PWA)' => 'L\'application sur le téléphone (PWA)',
        'O sistema se instala como aplicativo no celular e no tablet sem loja nenhuma: toda página aponta o manifesto (<link rel="manifest" href="api.php?recurso=manifest" crossorigin="use-credentials">, com o ícone e as marcas que o iPhone lê fora dele: apple-touch-icon, apple-mobile-web-app-capable, apple-mobile-web-app-title) e o api.js registra o service worker (navigator.serviceWorker.register("api.php?recurso=sw")) e guarda o beforeinstallprompt para o botão "Instalar o aplicativo" de Minha conta. O manifesto (app_manifesto, no lib.php): id e scope ./, start_url index.php, display standalone, as cores do tema (#e4e8ec e #1c2530), os ícones 192 e 512 (o 512 também maskable). Os dois recursos respondem sem login.' => 'Le système s\'installe comme application sur le téléphone et la tablette sans aucun magasin : chaque page pointe le manifeste (<link rel="manifest" href="api.php?recurso=manifest" crossorigin="use-credentials">, avec l\'icône et les balises que l\'iPhone lit en dehors : apple-touch-icon, apple-mobile-web-app-capable, apple-mobile-web-app-title) et api.js enregistre le service worker (navigator.serviceWorker.register("api.php?recurso=sw")) et garde le beforeinstallprompt pour le bouton « Installer l\'application » de Mon compte. Le manifeste (app_manifesto, dans lib.php) : id et scope ./, start_url index.php, display standalone, les couleurs du thème (#e4e8ec et #1c2530), les icônes 192 et 512 (la 512 aussi en maskable). Les deux ressources répondent sans login.',
        'O service worker (sw.js, entregue pela API com VERSAO e ARQUIVOS na frente, app_service_worker): na instalação guarda o estilo, os scripts, os ícones e a página sem conexão (com o ?v= das páginas) num cache com o nome da versão (o sha1 dos nomes, datas e tamanhos desses arquivos: qualquer mudança neles é um service worker novo, e o cache antigo sai ao ativar); o estilo, os scripts, as imagens e os textos do idioma (api.php?recurso=textos&formato=js) saem do cache quando já estão nele, senão da rede (e entram); as páginas vêm sempre da rede, e sem rede sai a offline.html; a API nunca fica em cache. O push e o notificationclick do Web Push ficam nele (o push.js de antes).' => 'Le service worker (sw.js, servi par l\'API avec VERSAO et ARQUIVOS devant, app_service_worker) : à l\'installation il garde le style, les scripts, les icônes et la page sans connexion (avec le ?v= des pages) dans un cache au nom de la version (le sha1 des noms, dates et tailles de ces fichiers : tout changement est un nouveau service worker, et l\'ancien cache sort à l\'activation) ; le style, les scripts, les images et les textes de la langue (api.php?recurso=textos&formato=js) sortent du cache quand ils y sont déjà, sinon du réseau (et y entrent) ; les pages viennent toujours du réseau, et sans réseau sort offline.html ; l\'API n\'est jamais mise en cache. Le push et le notificationclick du Web Push y vivent (l\'ancien push.js).',
        'Entrar sem a senha: "Lembrar este aparelho" (recurso=conta, acao=aparelho_lembrar) cria uma chave (24 bytes aleatórios em base64url), grava o hash dela (sha256 com o prefixo do sistema, como os tokens) na tabela usuario_aparelho (usuario_id, nome, chave_hash, criado, ultimo_uso) e a chave num cookie aparelho (HttpOnly, SameSite=Lax, Secure no https, um ano, na pasta do sistema). O pedido que chega sem o login do site e com o cookie entra como o dono da chave (usuario_por_aparelho, em usuario_autenticado; a conta bloqueada ou vencida não entra; ultimo_uso no máximo uma vez por minuto). "Esquecer" (aparelho_esquecer, id ou o deste pedido) apaga a linha e o cookie; trocar a senha apaga todos. O manifesto pedido com o cookie leva a chave no start_url (index.php?aparelho=...): o aplicativo instalado abre por ela, pagina_login grava o cookie no navegador do aplicativo (no iPhone ele não compartilha os cookies do Safari) e abre a página de novo sem a chave na barra.' => 'Entrer sans le mot de passe : « Mémoriser cet appareil » (recurso=conta, acao=aparelho_lembrar) crée une clé (24 octets aléatoires en base64url), enregistre son hash (sha256 avec le préfixe du système, comme les jetons) dans la table usuario_aparelho (usuario_id, nome, chave_hash, criado, ultimo_uso) et la clé dans un cookie aparelho (HttpOnly, SameSite=Lax, Secure en https, un an, dans le dossier du système). La requête qui arrive sans le login du site et avec le cookie entre comme le propriétaire de la clé (usuario_por_aparelho, dans usuario_autenticado ; le compte bloqué ou expiré n\'entre pas ; ultimo_uso au plus une fois par minute). « Oublier » (aparelho_esquecer, id ou celui de cette requête) efface la ligne et le cookie ; changer le mot de passe les efface tous. Le manifeste demandé avec le cookie porte la clé dans le start_url (index.php?aparelho=...) : l\'application installée s\'ouvre par elle, pagina_login enregistre le cookie dans le navigateur de l\'application (sur l\'iPhone il ne partage pas les cookies de Safari) et rouvre la page sans la clé dans la barre.',
        'As estatísticas' => 'Les statistiques',
        'recurso=estatisticas conta o tempo no pulso de cada relógio em cada dia do período (as sessões do tipo pulso partidas na meia-noite, a aberta até agora; as marcações antigas no pulso contam o dia, sem horas). Dela saem: os dias de uso e as horas de cada relógio, a parte de cada um, a barra (comparada com o mais usado), a tendência (a segunda metade do período contra a primeira: até 20% ou menos de 1 h de diferença é estável; menos de 1 h no total ou período de menos de 14 dias, poucos dados), o uso por dia da semana e por mês (com a média por dia e a barra comparada com o maior) e o resumo. O custo por uso e os dias de uso desde sempre são as fórmulas custo_por_uso e dias_de_uso. A coleção (na coleção e emprestados) é dividida por grupo, marca, ano da compra, situação e cada campo de lista (menos os só dos desejados). Período padrão: os últimos 90 dias; até hoje; no máximo 3661 dias; de=tudo: desde o primeiro uso.' => 'recurso=estatisticas compte le temps au poignet de chaque montre chaque jour de la période (les sessions du type pulso coupées à minuit, l\'ouverte jusqu\'à maintenant ; les anciennes marques au poignet comptent le jour, sans heures). Il en sort : les jours d\'usage et les heures de chaque montre, la part de chacune, la barre (comparée à la plus portée), la tendance (la seconde moitié de la période contre la première : jusqu\'à 20 % ou moins de 1 h de différence est stable ; moins de 1 h au total ou période de moins de 14 jours, peu de données), l\'usage par jour de la semaine et par mois (avec la moyenne par jour et la barre comparée à la plus grande) et le résumé. Le coût par port et les jours d\'usage depuis toujours sont les formules custo_por_uso et dias_de_uso. La collection (dans la collection et prêtées) est divisée par groupe, marque, année d\'achat, statut et chaque champ de liste (sauf ceux seulement des envies). Période par défaut : les 90 derniers jours ; jusqu\'à aujourd\'hui ; au plus 3661 jours ; de=tudo : depuis le premier usage.',
        'A hora certa' => 'L\'heure exacte',
        'recurso=hora_certa não usa o banco: a hora do servidor (microtime) no fuso do sistema e em UTC; a letra militar do fuso pelo deslocamento em horas cheias (A a M sem J a leste, N a Y a oeste, Z no UTC; fora da hora cheia, nenhuma); o grupo data-hora DDHHMM + letra + mês em inglês + ano com dois dígitos; o calendário pelo formato de datas (z, L, W, o); o dia juliano = segundos / 86400 + 2440587,5; a lua pela idade no ciclo sinódico médio de 29,530588853 dias a partir da lua nova de 06/01/2000 18:14 UTC (dia juliano 2451550,1), a parte iluminada (1 - cos(2π idade/ciclo)) / 2 e a fase pelos oitavos do ciclo (os limites 1,85; 5,54; 9,23; 12,92; 16,61; 20,30; 23,99; 27,68 dias).' => 'recurso=hora_certa n\'utilise pas la base : l\'heure du serveur (microtime) dans le fuseau du système et en UTC ; la lettre militaire du fuseau par le décalage en heures pleines (A à M sans J à l\'est, N à Y à l\'ouest, Z en UTC ; hors de l\'heure pleine, aucune) ; le groupe date-heure DDHHMM + lettre + mois en anglais + année sur deux chiffres ; le calendrier par le format de dates (z, L, W, o) ; le jour julien = secondes / 86400 + 2440587,5 ; la lune par l\'âge dans le cycle synodique moyen de 29,530588853 jours à partir de la nouvelle lune du 06/01/2000 18:14 UTC (jour julien 2451550,1), la partie éclairée (1 - cos(2π âge/cycle)) / 2 et la phase par les huitièmes du cycle (les limites 1,85 ; 5,54 ; 9,23 ; 12,92 ; 16,61 ; 20,30 ; 23,99 ; 27,68 jours).',
        'As telas' => 'Les écrans',
        'A especificação completa, tela por tela, está em telas (abaixo): o visual com os valores exatos (cores, letras, controles, componentes, larguras), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem com cada tabela, campo, botão e mensagem. Aqui, o resumo.' => 'La spécification complète, écran par écran, est dans telas (ci-dessous) : le visuel avec les valeurs exactes (couleurs, lettres, contrôles, composants, largeurs), le menu, et chaque page avec l\'adresse, ce qu\'elle lit et enregistre dans l\'API, et les parties dans l\'ordre avec chaque tableau, champ, bouton et message. Ici, le résumé.',
        'Hoje: no alto, o destaque: o relógio do dia ou, com destaque_hoje = pulso, o que está no pulso agora (a API escolhe: destaque.relogio_id) (com o Pôs e o Tirou), "Hoje é dia de" (os avisos com o botão que resolve), os próximos dias com o motivo e o trocar por…, o modo de rodízio (troca ali mesmo), e a tabela da coleção com filtros e ordenação; clicar num relógio abre o painel dele, ao lado da lista ou numa janela flutuante (painel_modo).' => 'Aujourd\'hui : en haut, la mise en avant : la montre du jour ou, avec destaque_hoje = pulso, ce qui est au poignet maintenant (l\'API choisit : destaque.relogio_id) (avec la Mise et la Retirée), « Aujourd\'hui, c\'est le jour de » (les alertes avec le bouton qui résout), les prochains jours avec le motif et le remplacer par…, le mode de rotation (on le change là même), et le tableau de la collection avec filtres et tri ; cliquer sur une montre ouvre son panneau, à côté de la liste ou dans une fenêtre flottante (painel_modo).',
        'O painel (e a ficha, a mesma coisa numa página): a cabeça (foto, grupo, nome, marcas), quadros alinhados numa grade (Agora, Previsão, Gasto da bateria, Autonomia, Rodízio, Compra, Documentos, Próximas manutenções), cada um com rótulo e valor em duas colunas; o quadro Marcar (um menu só, "O que você quer marcar?", e embaixo só os campos daquilo); Editar cadastro; o gráfico da carga com as medições; os dados do relógio (o cadastro com a origem de cada valor e o resultado de cada fórmula com a versão); o histórico recente.' => 'Le panneau (et la fiche, la même chose sur une page) : la tête (photo, groupe, nom, marques), cadres alignés dans une grille (Maintenant, Prévision, Consommation de la batterie, Autonomie, Rotation, Achat, Documents, Prochains entretiens), chacun avec libellé et valeur en deux colonnes ; le cadre Marquer (un seul menu, « Que voulez-vous marquer ? », et en dessous seulement les champs de cela) ; Modifier la fiche ; le graphique de la charge avec les mesures ; les données de la montre (la fiche avec l\'origine de chaque valeur et le résultat de chaque formule avec la version) ; l\'historique récent.',
        'Plano, Histórico, Documentos (com o menu ⋮ em cada arquivo), Avisos, Configuração (quadros com uma opção por linha e a barra de salvar presa no pé), Destinos, Agendas, Modos de rodízio, Critérios, Grupos, Cadastros, Execuções do cron, Minha conta, Aprovações, Usuários (o painel do master), Ajuda (as seções do README) e o cadastro aberto.' => 'Plan, Historique, Documents (avec le menu ⋮ sur chaque fichier), Alertes, Configuration (cadres avec une option par ligne et la barre d\'enregistrement fixée en bas), Destinations, Agendas, Modes de rotation, Critères, Groupes, Définitions, Exécutions du cron, Mon compte, Approbations, Utilisateurs (le panneau du master), Aide (les sections du README) et l\'inscription ouverte.',
        'Três tamanhos com o mesmo sistema visual: até 900 px (celular e tablet de pé) o menu fica recolhido, as tabelas viram cartões e o relógio abre em tela cheia (o voltar do aparelho fecha); de 901 a 1199 px o painel ao lado desliza por cima, pela direita. A mesma informação em todos os tamanhos: nenhuma coluna, filtro ou dia é escondido por falta de espaço. A tabela dos relógios tem sempre as 12 colunas; quando a tabela inteira não cabe na largura que tem (medida com os dados, com ou sem o painel aberto), cada relógio vira um cartão com os mesmos 12 campos na mesma ordem, cada um com o nome da coluna em cima (2 colunas no celular, 5 no tablet), os títulos viram botões de ordenar e os 11 filtros ficam todos. Campos com letra de 16 px no celular (o iPhone não aproxima a tela).' => 'Trois tailles avec le même système visuel : jusqu\'à 900 px (téléphone et tablette debout) le menu reste replié, les tableaux deviennent des cartes et la montre s\'ouvre en plein écran (le retour de l\'appareil ferme) ; de 901 à 1199 px le panneau à côté glisse par-dessus, par la droite. La même information dans toutes les tailles : aucune colonne, aucun filtre ni jour n\'est caché par manque de place. Le tableau des montres a toujours les 12 colonnes ; quand le tableau entier ne tient pas dans la largeur qu\'il a (mesurée avec les données, avec ou sans le panneau ouvert), chaque montre devient une carte avec les mêmes 12 champs dans le même ordre, chacun avec le nom de la colonne au-dessus (2 colonnes sur le téléphone, 5 sur la tablette), les titres deviennent des boutons de tri et les 11 filtres restent tous. Champs avec une lettre de 16 px sur le téléphone (l\'iPhone n\'agrandit pas la page).',
        'Segurança' => 'Sécurité',
        'Todo pedido da API exige autenticação (o login do site, um token pessoal, a chave de um aparelho lembrado no cookie, ou o token do servidor), menos o cadastro aberto, o link ICS, os textos das telas, o manifesto e o service worker do aplicativo; as páginas são só o esqueleto, sem dado nenhum, e quem chega sem login vai para o login da API. Cada pedido só vê a coleção dele (o escopo é do banco), e a coleção que ele não vê responde 404. A cópia de segurança e as migrações são só do master. O cron e os scripts só pela linha de comando. Os arquivos internos (núcleo, banco, configuração, scripts, testes, dados, os que começam com ponto) ficam bloqueados no servidor web (.htaccess e nginx).' => 'Toute requête à l\'API exige une authentification (l\'identifiant du site, un jeton personnel, la clé d\'un appareil mémorisé dans le cookie, ou le jeton du serveur), sauf l\'inscription ouverte, le lien ICS, les textes des écrans, le manifeste et le service worker de l\'application ; les pages ne sont que le squelette, sans aucune donnée, et qui arrive sans identifiant va à l\'identification de l\'API. Chaque requête ne voit que sa collection (la portée est l\'affaire de la base), et la collection qu\'elle ne voit pas répond 404. La sauvegarde et les migrations sont réservées au master. Le cron et les scripts seulement par la ligne de commande. Les fichiers internes (noyau, base, configuration, scripts, tests, données, ceux qui commencent par un point) sont bloqués sur le serveur web (.htaccess et nginx).',
        'SQL sempre com parâmetros; textos escapados no HTML; XML da NF-e lido sem entidades nem rede; arquivos servidos inline só dos tipos seguros; senhas com password_hash; o token comparado em tempo constante.' => 'SQL toujours avec des paramètres ; textes échappés dans le HTML ; XML de la NF-e lu sans entités ni réseau ; fichiers servis en inline seulement des types sûrs ; mots de passe avec password_hash ; le jeton comparé en temps constant.',
        'Senhas: só o hash, pelo password_hash do PHP (bcrypt, $2y$<custo>$<sal de 22><resultado de 31>); o login confere com o password_verify (o bcrypt da senha digitada com o sal e o custo do hash). A API entrega o login e o hash de cada usuário (recurso=usuarios: senha_hash, senha_algoritmo, senha_custo) e aceita criar um usuário pelo hash de outro sistema (usuarios/salvar com senha_hash; bcrypt $2y$, $2b$ ou $2a$, ou argon2; o $2b$ guardado como $2y$, o mesmo cálculo). A reescrita tem de conferir pelo mesmo bcrypt, para os usuários migrarem com a mesma senha. Os arquivos dos documentos só pelo recurso=documento.' => 'Mots de passe : seulement le hash, par le password_hash de PHP (bcrypt, $2y$<coût>$<sel de 22><résultat de 31>) ; la connexion vérifie avec password_verify (le bcrypt du mot de passe saisi avec le sel et le coût du hash). L\'API livre l\'identifiant et le hash de chaque utilisateur (recurso=usuarios : senha_hash, senha_algoritmo, senha_custo) et accepte de créer un utilisateur par le hash d\'un autre système (usuarios/salvar avec senha_hash ; bcrypt $2y$, $2b$ ou $2a$, ou argon2 ; le $2b$ gardé comme $2y$, le même calcul). La réécriture doit vérifier par le même bcrypt, pour que les utilisateurs migrent avec le même mot de passe. Les fichiers des documents seulement par recurso=documento.',
        'Os testes e a aceitação' => 'Les tests et la recette',
        'testes/cenario.php faz pela API o que uma pessoa faz (cadastra relógios de cada tipo, lança cordas, cargas, sol, winder e pilha, monta a escala, mexe nos critérios, nos eventos e nas fotos, roda o cron) e tira a fotografia de tudo o que a API devolve; testes/comparar.php compara duas fotografias. Com RELOGIOS_SEMENTE (o sorteio fica previsível), o roteiro rodado em MySQL, PostgreSQL, SQLite e Firebird, num banco recém-instalado, tem de dar as mesmas respostas; e a reescrita, as mesmas da versão atual. testes/paridade.sh faz tudo com um comando (os bancos recriados, a instalação, o usuário, os servidores, o roteiro e a comparação), com o config de teste apontado pela variável de ambiente RELOGIOS_CONFIG (o núcleo carrega o arquivo que ela diz; sem ela, o config.php).' => 'testes/cenario.php fait par l\'API ce qu\'une personne fait (enregistre des montres de chaque type, saisit des remontages, des charges, du soleil, du remontoir et de la pile, construit le planning, touche aux critères, aux événements et aux photos, lance le cron) et prend la photographie de tout ce que l\'API renvoie ; testes/comparar.php compare deux photographies. Avec RELOGIOS_SEMENTE (le tirage devient prévisible), le scénario lancé sur MySQL, PostgreSQL, SQLite et Firebird, sur une base fraîchement installée, doit donner les mêmes réponses ; et la réécriture, les mêmes que la version actuelle. testes/paridade.sh fait tout avec une commande (les bases recréées, l\'installation, l\'utilisateur, les serveurs, le scénario et la comparaison), avec le config de test indiqué par la variable d\'environnement RELOGIOS_CONFIG (le noyau charge le fichier qu\'elle dit ; sans elle, le config.php).',
        'Além disso: nenhuma escrita do roteiro recusada; o dicionário da ajuda explica todos os campos das respostas; as telas sem erro de JavaScript e sem rolagem lateral no celular, no tablet e no computador.' => 'En plus : aucune écriture du scénario refusée ; le dictionnaire de l\'aide explique tous les champs des réponses ; les écrans sans erreur de JavaScript et sans défilement latéral sur le téléphone, la tablette et l\'ordinateur.',
        'A documentação da API tem uma fonte só: o dicionário dos campos da ajuda (recurso=ajuda, campos); o do cabeçalho do api.php é gerado dele (testes/dicionario.php --gravar; sem o --gravar, confere). testes/campos.php confere que todo campo das respostas está explicado. Os dois rodam no testes/paridade.sh.' => 'La documentation de l\'API a une seule source : le dictionnaire des champs de l\'aide (recurso=ajuda, campos) ; celui de l\'en-tête de api.php est généré à partir de lui (testes/dicionario.php --gravar ; sans le --gravar, il vérifie). testes/campos.php vérifie que tout champ des réponses est expliqué. Les deux tournent dans testes/paridade.sh.',
        'testes/layout.cjs abre todas as telas (com os quadros recolhidos abertos e cada opção dos menus que mostram partes) num navegador, em 15 tamanhos de 320 a 1920px, e mede o que quebra: a página que rola de lado, o elemento que sai da caixa em que está, a etiqueta partida, o texto cortado, o botão com o texto em duas linhas e o que fica por cima de outro. O esperado: 0 problemas.' => 'testes/layout.cjs ouvre tous les écrans (avec les cadres repliés ouverts et chaque option des menus qui montrent des parties) dans un navigateur, en 15 tailles de 320 à 1920px, et mesure ce qui casse : la page qui défile de côté, l\'élément qui sort de la boîte où il est, l\'étiquette coupée, le texte coupé, le bouton avec le texte sur deux lignes et ce qui reste par-dessus un autre. L\'attendu : 0 problème.',
        'Cada tabela com as colunas (nome, tipo no dialeto do banco em uso, se aceita vazio, o padrão), a chave primária, as chaves estrangeiras (a coluna, a tabela.coluna de referência e o que acontece ao apagar a linha de cima: CASCADE some junto, SET NULL desfaz a ligação), as chaves únicas, os índices e as regras de validação (CHECK). As colunas de texto curto não diferenciam maiúsculas nem acentos. Três referências ficam pelo nome, de propósito: as fórmulas e os critérios citam campos e fórmulas pelo identificador, e destino_aviso.tipo_aviso e agenda_aviso.tipo_aviso citam o aviso pelo identificador (vale para todas as versões dele).' => 'Chaque table avec les colonnes (nom, type dans le dialecte de la base utilisée, si elle accepte le vide, la valeur par défaut), la clé primaire, les clés étrangères (la colonne, la table.colonne de référence et ce qui se passe à la suppression de la ligne parente : CASCADE disparaît avec, SET NULL défait le lien), les clés uniques, les index et les règles de validation (CHECK). Les colonnes de texte court ne distinguent ni majuscules ni accents. Trois références passent par le nom, exprès : les formules et les critères citent champs et formules par l\'identifiant, et destino_aviso.tipo_aviso et agenda_aviso.tipo_aviso citent l\'alerte par l\'identifiant (valable pour toutes ses versions).',
    ],
];
